/* ÇEVİRİ az · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("az","olay",{
"OLAYLAR:1299-01:0":{"b": ["Osmanlı Bəyliyinin qurulması", "9f0b7c0a"], "d": ["Qayı boyundan Osman Qazinin Söyüd-Domaniç ətrafında müstəqil hərəkət etməyə başlaması Osmanlı Dövlətinin qurulması üçün ənənəviləşmiş başlanğıc sayılır; bəzi tarixçilər 1302-ci il Bapheus qələbəsini əsl dönüş nöqtəsi hesab edir. Bəylik Bizansın sərhəd bölgəsindəki mövqeyi sayəsində qazi basqınları ilə sürətlə güc topladı. Səlcuq irsinin dağıldığı bu mühitdə Osman Qazi ətrafına əxiləri, qazıları və köçəri türkmənləri topladı; Şeyx Ədəbali ilə qurduğu bağ bəyliyin mənəvi legitimliyinin əsası sayılır. Eyni tarixdə qatılan digər yerlər: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Bursanın fəthi", "98c727fa"], "d": ["İllərlə blokada altında saxlanılan Bursa mühasirənin son mərhələsini idarə edən Orxan Qaziyə təslim oldu; şəhər bəyliyin ilk böyük paytaxtı edildi. Fəth xəbərinin ölüm döşəyindəki Osman Qaziyə çatdırıldığı rəvayət edilir; Osman Qazi vəsiyyəti üzərinə Bursada dəfn edildi. Şəhər qısa müddətdə məscid, imarət və mədrəsələrlə təchiz edilərək erkən Osmanlı şəhərsalmasının modelinə çevrildi.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["İznikin fəthi", "a846a811"], "d": ["Bizansın Anadoludakı ən mühüm mərkəzlərindən İznik (Nikaia) 1329-cu il Pelekanon qələbəsindən sonra müqavimət ümidini itirərək Orxan Qaziyə təslim oldu. İlk Osmanlı mədrəsəsi burada quruldu və Davud-i Qeysəri kimi alimlər dərs verməyə başladı; şəhər erkən dövrün elm mərkəzi oldu. Ayasofya kilsəsi məscidə çevrilərək fəth ənənəsinin erkən bir nümunəsi nümayiş etdirildi.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["İzmitin fəthi", "06a35035"], "d": ["İzmitin (Nikomedia) süqutu ilə Bizansın Anadolu yakasındakı son mühüm qalası da Osmanlı idarəsinə keçdi; İstanbulun qarşı sahilinə qədər bütün Kocaeli yarımadası Osmanlı torpağı oldu. Beləliklə bəylik Mərmərənin cənub və şərq sahillərinin hamısına hakim olaraq Rumeliyə keçidin infrastrukturunu hazırladı.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Çimpe qalası — Rumeliyə keçid", "c2f0a07d"], "d": ["Orxan Qazinin oğlu Süleyman Paşa Bizans vətəndaş müharibəsində verilən Çimpe qalasını 1352-ci ildə baza etmişdi; 1354-cü ilin Mart ayında Gəlibolunu dağıdan böyük zəlzələdən sonra boşalan qalalar sürətlə möhkəmləndirilərək yarımada daimi Osmanlı körpübaşına çevrilmişdi. Anadoludan gətirilən türkmən əhalinin yerləşdirilməsi ilə dəstəklənən bu addım Osmanlıların Avropa qitəsində 550 ildən çox davam edəcək mövcudluğunun başlanğıcıdır.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Ədirnənin fəthi", "2f54ebb0"], "d": ["Frakiyanın açar şəhəri Ədirnənin (Adrianopolis) alınması Balkan fəthlərinin əsas bazasını və istiqamətini müəyyən etdi; fəth tarixi mənbələrdə 1361 ilə 1369 arasında mübahisəlidir. Şəhər qısa müddət sonra paytaxt edilərək dövlətin ağırlıq mərkəzinin Rumeliyə keçdiyini elan etdi; İstanbulun fəthinə qədər təxminən 90 il paytaxt qaldı.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["I Murad taxta çıxdı", "f8d48a26"], "d": ["Orxan Qazinin ölümü ilə taxta keçən I Murad (Hüdavəndigar) 27 illik səltənətində dövləti bir sərhəd bəyliyindən imperiya skeletinə daşıdı. Pəncik sistemi ilə Yeniçəri Ocağının təməli atıldı, timar qaydası yayıldı, Rumeli Bəylərbəyiliyi quruldu və vəzirlik institutu gücləndirildi. Balkan fəthləri onun dövründə sistemli dövlət siyasətinə çevrildi.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["I Kosovo döyüşü — I Muradın şəhid olması", "10b8ddc9"], "d": ["Knyaz Lazarın rəhbərlik etdiyi Balkan ittifaqı Kosovo düzündə qəti məğlubiyyətə uğradıldı; Serbiya Osmanlı ali hakimiyyətinə keçdi. Döyüş meydanını gəzən I Murad Serb əsilzadəsi Miloš Obilić tərəfindən xəncərlənərək şəhid edildi — döyüş meydanında ölən yeganə Osmanlı padşahıdır. Yerinə ordugahda Yıldırım Bəyazid keçirildi; qardaşı Yaqub Çələbi boğdurulub öldürüldü və bu, qardaş qətli tətbiqinin məlum ilk nümunələrindən oldu.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Nikopol qələbəsi", "75716e96"], "d": ["Macar kralı Sigismundun çağırışı ilə toplanan və Fransız-Burqundiya cəngavərlərinin də qatıldığı böyük Səlib ordusu Dunay sahilindəki Nikopol önündə Yıldırım Bəyazid tərəfindən ağır məğlubiyyətə uğradıldı. Qələbə Bolqarıstan üzərindəki Osmanlı hakimiyyətini qətiləşdirdi; Avropada bir nəsil boyunca böyük Səlib yürüşü təşkil edilə bilmədi.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Ankara döyüşü — Fətrət Dövrü başladı", "b4a99d96"], "d": ["Teymurun ordusu qarşısında Çubuk düzündə alınan ağır məğlubiyyətdə Yıldırım Bəyazid əsir düşdü və bir neçə ay sonra əsirlikdə öldü. Teymur Anadolu bəyliklərini yenidən dirçəltdi; Osmanlı torpaqları Bəyazidin oğulları arasında parçalandı və 11 il davam edəcək taxt mübarizəsi (Fətrət Dövrü) başladı. Dövlətin qurulduğu gündən bəri yaşadığı ən ağır böhran olan bu dövr mərkəziyyətçi quruluşun əhəmiyyətini Osmanlı yaddaşına həkk etdi. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çələbi Mehmed birliyi yenidən qurdu", "03413dfd"], "d": ["Qardaşlar arasındakı son hesablaşmada Musa Çələbini Çamurluda məğlub edən I Mehmed ölkə torpaqlarını vahid idarə altında birləşdirdi; buna görə 'dövlətin ikinci qurucusu' sayılır. Səltənətində yıpranmış dövlət quruluşu bərpa edildi, Anadolu bəylikləri ilə münasibətlər tarazlandı və Rumelidə ehtiyatlı sülh siyasəti izlənildi.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Şeyx Bədrəddin üsyanı", "e0a072ca"], "d": ["Fətrət Dövründə qazaskərlik etmiş böyük fəqih və mütəsəvvüf Şeyx Bədrəddinin ətrafında inkişaf edən dini-ictimai hərəkat Karaburunda Börklücə Mustafa və Manisada Torlak Kamalın üsyanları ilə eyni vaxtda başladı. Üsyanlar qanlı şəkildə yatırıldı; Bədrəddin Deliormanda yaxalanaraq Serezdə edam edildi. Hadisə Osmanlı tarixindəki ən erkən böyük ictimai-mehdiçi üsyan kimi ədəbiyyatda və tarixşünaslıqda dərin iz buraxdı.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Varna qələbəsi", "f739eedc"], "d": ["Szeged müqaviləsini pozaraq cənuba enən Macar-Leh Səlib ordusu taxtdan çəkilmişkən ordunun başına qayıdan II Murad tərəfindən Varnada məhv edildi; gənc kral III Ladislas döyüş meydanında öldü. Qələbə Balkanlardakı Osmanlı mövcudluğunu ləğv etməyə yönəlik son böyük xarici müdaxilə şansını aradan qaldırdı və İstanbulun fəthinə gedən yolu təmin etdi.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["II Kosovo döyüşü", "ebe0b662"], "d": ["Varnanın qisasını almaq istəyən Hunyadi Yanoşun ordusu üç gün davam edən çətin döyüşdə II Murad tərəfindən qəti məğlubiyyətə uğradıldı. Bu, Səlibçilərin Balkanlarda Osmanlıya qarşı girişdiyi son böyük meydan döyüşüdür; qələbə ilə Dunayın cənubundakı Osmanlı hakimiyyəti artıq geri qaytarıla bilməyəcək şəkildə yerləşdi.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["İstanbulun Fəthi", "583d5e3e"], "d": ["Əlli dörd gün (6 Aprel–29 May 1453) davam edən mühasirədən sonra 29 May səhəri divarları aşan Osmanlı ordusu şəhərə girdi; son imperator XI Konstantinos döyüşlərdə öldü və 1100 illik Şərqi Roma İmperiyası tarixə qarışdı. Gənc padşah 'Fatih' titulunu aldı, şəhəri paytaxt edərək Ayasofyanı məscidə çevirdi; şəhər qısa müddətdə məskunlaşdırma və abadlıqla yenidən canlandırıldı. TDV-yə görə Silivri ilə Vize ancaq 1453-də qəti olaraq fəth edilmişdir; TDV Limni maddəsinə görə ada fəthdən dərhal sonra Osmanlı idarəsinə girdi və xərac şərti ilə Gattilusio ailəsinə buraxıldı. Atlasda Silivri, Vize və Limni bu gündən Bizansdan Osmanlıya (Limni xəracgüzar) yazılıdır. Nəhəng topların tökdürülməsi, gəmilərin quru ilə yeridilməsi və divarların önündəki mühasirə qaydası dövrün hərbi mühəndisliyinin zirvəsi sayılır. Fəth Avropa tarixşünaslığında Orta Əsrlərin bitişinin rəmzi tarixlərindən biri hesab olunur.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Trabzonun fəthi", "15f52403"], "d": ["Fatihin ordu və donanma ilə eyni vaxtda apardığı çətin Qara dəniz yürüşünün sonunda Trabzon Rum İmperiyası təslim oldu; Bizans dünyasının Anadoludakı bu son qalığının ləğvi ilə Qara dənizin cənub sahili bütövlükdə Osmanlı hakimiyyətinə keçdi. Komnenos sülaləsinə son verilməsi Fatihin 'iki dənizin və iki qitənin hökmdarı' iddiasını möhkəmləndirdi. Eyni tarixdə qatılan digər yerlər: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Silifkənin qəti fəthi — Qaramanoğullarının son müqavimətinin qırılması", "d988bee4"], "d": ["Silifkə qalası 1472-ci ildə bir dəfə Gedik Əhməd Paşaya təslim olmuş, lakin eyni il Qaramanoğlu Qasım bəy Aralıq dənizindəki Səlib donanmasının köməyi ilə qalanı geri almışdı. Otluqbeli qələbəsindən sonra Fatih oğlunu və Gedik Əhməd Paşanı bölgəni qəti olaraq ələ keçirməyə tapşırdı; köhnə Osmanlı topçularının köməyi ilə barıt anbarı alovlandırılaraq qala sürətlə süqut etdirildi. Beləliklə Qaramanoğullarının Taşeli-İçel dağlarındakı son müqaviməti qırıldı; bəyliyin ləğvi 1474-də tamamlanacaqdı.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Otluqbeli döyüşü", "42c7194e"], "d": ["Şərqdə böyük güc halına gələn və Venesiya ilə ittifaq quran Ağqoyunlu hökmdarı Uzun Həsən Otluqbelidə Fatihin odlu silahlarla təchiz edilmiş ordusu qarşısında ağır məğlubiyyətə uğradı. Qələbə Anadoluda Osmanlı üstünlüyünü qətiləşdirdi; klassik ordu qarşısında top və tüfəngdən istifadə edən mərkəzi ordunun üstünlüyünün də erkən sübutu oldu. TDV Gümüşhane maddəsinə görə şəhər 1467-dən bəri Ağqoyunlu hakimiyyətində idi; bu hakimiyyət Otluqbeli məğlubiyyəti ilə sona çatdı və Gümüşhane qəti olaraq Osmanlı hakimiyyətinə keçdi.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Krımın Osmanlı himayəsinə keçməsi", "44e3f7c8"], "d": ["Gedik Əhməd Paşanın komandanlığındakı donanma Cenovalıların əlindəki Kəfə başda olmaqla Krımın cənub sahil şəhərlərini fəth etdi; bu sahillər birbaşa Osmanlı sancağı edildi. Krım Xanlığı isə Mengli Girayla Osmanlı ali hakimiyyətini tanıyan imtiyazlı bir vassal dövlətə çevrildi və üç əsr boyunca şimal siyasətinin əsas daşı oldu; Qara dəniz artıq faktiki olaraq Osmanlının daxili dənizinə çevrildi. Eyni tarixdə qatılan digər yerlər: Bağçasaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Fatihin ölümü — Cem Sultan hadisəsi", "190ecf01"], "d": ["Fatihin yürüş yolunda qəfil ölümü üzərinə taxta II Bəyazid keçdi; qardaşı Cem Sultan səltənət iddiası ilə Bursada adına xütbə oxudub sikkə kəsdirdi. Məğlub olunca əvvəl Məmlüklərə, sonra Rodos cəngavərlərinə sığındı; cəngavərlərin və papalığın əlində Avropa diplomatiyasının sövdələşmə kartına çevrilən Cem 1495-də Neapolda öldü. Bu hadisə Osmanlı xarici siyasətini on beş il boyunca ehtiyatlı davranmağa məcbur etdi.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Çaldıran qələbəsi", "fea64ebb"], "d": ["Anadoluda Səfəvi təbliğatının yaratdığı təhlükəni kökündən həll etmək istəyən Yavuz Sultan Səlim Şah İsmayılın ordusunu Çaldıran düzündə top və tüfəng üstünlüyü ilə ağır məğlubiyyətə uğratdı. Təbrizə girildi; Şərqi və Cənub-Şərqi Anadolu ilə Mosul-Diyarbəkir xətti Osmanlı idarəsinə qatıldı. İdris-i Bitlisinin səyi ilə Kürd bəylərinin Osmanlıya bağlanması şərq sərhədinin əsrlərlə davam edəcək çərçivəsini qurdu.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Mərcidabıq qələbəsi", "07d254d3"], "d": ["Məmlük ordusu Hələbin şimalındakı Mərcidabıqda bir neçə saat ərzində dağıdıldı; yaşlı sultan Qansu Qavri döyüş zamanı öldü. Hələb və Dəməşq qapılarını taybatay açan qələbə ilə Suriya, Livan və Fələstin Osmanlı idarəsinə keçdi; Məmlük Dövlətinin sonunu gətirəcək Misir yürüşünün yolu açıldı.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniyyə — Misirin fəthi və xilafət", "caf378d6"], "d": ["Sina səhrasını sürətlə keçən Osmanlı ordusu Tomanbayın müdafiə xəttini Ridaniyyədə yararaq Qahirəyə girdi; müqavimətini davam etdirən Tomanbay yaxalanaraq edam edildi və Məmlük Dövləti tarixə qarışdı. Misir, Hicaz və müqəddəs şəhərlər Osmanlı idarəsinə girdi; Abbasi xəlifəsi və müqəddəs əmanətlər İstanbula aparıldı. Xilafətin Osmanlı sülaləsinə keçməsi ilə padşahlar İslam dünyasının rəhbərliyi iddiasını öz üzərinə götürdü; Ədviyyat Yolunun nəzarəti də imperiyaya böyük gəlir təmin etdi. Eyni tarixdə qatılan digər yerlər: Əkka, Maan, Sayda, Kərək.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Qanuni Sultan Süleyman taxta çıxdı", "f6512269"], "d": ["Yavuzun ölümü üzərinə yeganə oğlan övlad kimi taxta keçən I Süleymanın 46 illik səltənəti imperiyanın siyasi, hərbi, hüquqi və mədəni zirvəsi sayılır. Örfi hüququ sistemləşdirən qanunnamələr ona 'Qanuni' titulunu qazandırdı; Qərbdə 'Möhtəşəm' (Magnificent) deyə anıldı. Memar Sinanın əsərləri, divan ədəbiyyatının qızıl dövrü və donanmanın Aralıq dənizindəki üstünlüyü bu dövrün simvolları idi.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Belqradın fəthi", "59ef5cec"], "d": ["Fatihin 1456-da ələ keçirə bilmədiyi və 'Mərkəzi Avropanın kilidi' sayılan Belqrad Qanuninin ilk yürüşündə Dunay-Sava qovşağındakı mühasirə ilə süqut etdi. Macarıstanın cənub müdafiə xətti çökmüş oldu; beş il sonra Mohaça, iyirmi il sonra Budinin ilhaqına uzanan Mərkəzi Avropa əməliyyatının qapısı bu fəthlə açıldı.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Rodosun fəthi", "807bbb1e"], "d": ["Şərqi Aralıq dənizi dəniz yollarını və həcc marşrutunu təhdid edən Sent-Jan cəngavərlərinin bazası Rodos aylarla davam edən qanlı mühasirədən sonra aman şərtilə təslim oldu; cəngavərlərin adadan sərbəst ayrılmasına icazə verildi (sonradan Maltaya yerləşdilər). Anadolu sahillərinin təhlükəsizliyi təmin edildi və İstanbul-Misir dəniz xətti fasiləsiz Osmanlı nəzarətinə girdi.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Mohaç meydan döyüşü", "f3418b0d"], "d": ["Macar ordusu Mohaç düzündə təxminən iki saat ərzində top atəşi və manevr üstünlüyü ilə məhv edildi; Kral II Layoş qaçarkən bataqlıqda öldü. Osmanlı tarixinin ən sürətlə qazanılmış böyük meydan döyüşlərindən olan Mohaç müstəqil Macar krallığına faktiki olaraq son qoydu və Mərkəzi Avropada Osmanlı-Habsburq rəqabəti dövrünü açdı.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["I Vyana mühasirəsi", "dc49ea4f"], "d": ["Habsburqların Macar taxtına əl atmasına qarşı təşkil edilən yürüşdə Osmanlı ordusu Vyananı mühasirəyə aldı; ağır topların yolda buraxılması, erkən başlayan qış və ərzaq çətinliyi üzündən üç həftə sonra mühasirə qaldırıldı. Şəhər alınmasa da Macarıstan üzərindəki Osmanlı nüfuzu qorundu; Vyana önləri imperiyanın Mərkəzi Avropadakı logistik əlçatanlıq həddini göstərdi.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Bağdadın fəthi — İrakeyn yürüşü", "897092c3"], "d": ["'İki İraq' (İraqi-Ərəb və İraqi-Əcəm) üzərinə təşkil edilən yürüşdə əvvəl Təbrizə, sonra döyüşsüz şəkildə Bağdada girildi; Abbasilərin köhnə paytaxtının alınması Osmanlı hökmdarına İslam dünyasında böyük nüfuz qazandırdı. İmami-Əzəm Əbu Hənifənin türbəsi bərpa edildi; Bağdad və Bəsrənin qatılması ilə Osmanlı torpaqları Bəsrə körfəzinə çatdı. Eyni tarixdə qatılan digər yerlər: Kərkük, Kərbəla.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Preveze dəniz qələbəsi", "30dc0f97"], "d": ["Papanın başçılığı ilə qurulan Səlib donanması sayca üstün olmasına baxmayaraq Barbarosun küləyi və sahili ustalıqla istifadə edən taktikası ilə Preveze açıqlarında dağıdıldı; Andrea Doria döyüş meydanını tərk etdi. Qələbə Aralıq dənizində təxminən 33 il davam edəcək mübahisəsiz Osmanlı dəniz üstünlüyünü qurdu; Türk dənizçilik ənənəsində donanma gününün simvolik tarixidir. Eyni tarixdə qatılan digər yerlər: Ədən, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Budinin ilhaqı — Macarıstan Osmanlı əyaləti", "db53b244"], "d": ["Habsburqların Budini mühasirəyə alması üzərinə yürüşə çıxan Qanuni şəhəri xilas etdikdən sonra Mərkəzi Macarıstanı birbaşa Osmanlı idarəsinə alaraq Budin Bəylərbəyiliyini qurdu; Erdel isə Osmanlıya bağlı muxtar knyazlıq edildi. Macarıstanın bu üçə bölünmüş qaydası təxminən 150 il davam etdi və Osmanlının Mərkəzi Avropadakı daimi idarəetmə skeletini təşkil etdi.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Amasya Sazişi", "a5afe0d1"], "d": ["İllərlə davam edən Osmanlı-Səfəvi müharibələrini bitirən ilk rəsmi sülh sazişidir. Bağdad və İraq Osmanlıda qaldı, Şərqi Anadolu sərhədi ilk dəfə qarşılıqlı tanındı; Səfəvilər Osmanlı ölkəsindəki şiə təbliğatını dayandırmağı, Osmanlılar da İranlı həccaların keçid təhlükəsizliyini öhdələrinə götürdü. Saziş iki dövlət arasındakı münasibətlərin hüquqi çərçivəsinin ilk nümunəsi oldu.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Zigetvar — Qanuninin vəfatı", "e2917ed2"], "d": ["72 yaşındakı Qanuni on üçüncü yürüşündə mühasirəyə aldığı Zigetvar qalasının süqutundan bir neçə saat əvvəl otağında vəfat etdi; Sokullu Mehmed Paşa ordunun dağılmaması üçün ölümü həftələrlə gizlətdi. Qala alındı, lakin dövlət ən uzun səltənətli və ən təntənəli padşahını itirmişdi; taxta oğlu II Səlim keçdi və dövlət idarəçiliyində böyük vəzirlərin çəkisi artmağa başladı.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Kiprin fəthi", "e364a2b3"], "d": ["Venesiya idarəsindəki Kipr 1570-də desant çıxarıldı; Lefkoşa sürətlə süqut etdi, Maqosa isə ancaq on bir aylıq mühasirədən sonra Avqust 1571-də təslim oldu. Şərqi Aralıq dənizi ticarət və həcc yollarının təhlükəsizliyi baxımından kritik olan ada bir bəylərbəyilik kimi təşkil edildi və Anadoludan əhali yerləşdirildi; fəth İnəbəxtıya gedəcək böyük Səlib ittifaqının da əsası oldu.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["İnəbəxtı (Lepanto) məğlubiyyəti", "6a1d44a9"], "d": ["Kiprin fəthi üzərinə birləşən Səlib donanması Osmanlı donanmasını İnəbəxtı körfəzində yaxalayaraq böyük hissəsini məhv etdi; kapudan-i dərya Müəzzinzadə Əli Paşa şəhid düşdü, yalnız Uluc Əlinin donanması xilas oldu. Fəlakətdən sonra Sədrəzəm Sokullu Mehmed Paşa Uluc Əli Paşanı kapudan-i-daryalığa gətirib dağılmış donanmanı toplamaqla vəzifələndirdi və İstanbuldan Alanyaya qədər bütün gəmiqayırma zavodlarında yeni donanmanın inşasına başladı; lakin Aralıq dənizindəki mütləq üstünlük psixoloji olaraq sarsılmışdı.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Haçova meydan döyüşü", "da308ec5"], "d": ["Uzun Müharibənin (1593–1606) ən böyük meydan döyüşündə III Mehmedin şəxsən başında olduğu ordu dağılma nöqtəsinə gəldiyi anda Xoca Səadəddin Əfəndinin təlqini ilə toparlanaraq Habsburq ordusunu məğlubiyyətə uğratdı. Osmanlıların qazandığı son böyük klassik meydan döyüşü sayılır; lakin döyüşün ümumi gedişini dəyişdirməməsi hərbi sistemdəki yıpranmanın da əlaməti sayıldı.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Zitvatorok Müqaviləsi", "39c01142"], "d": ["On üç illik yıpradıcı müharibəni bitirən müqavilə ilə Habsburq hökmdarı ilk dəfə 'Roma İmperatoru' sifəti ilə padşahın bərabəri sayıldı və illik xərac ləğv edildi. Torpaq itkisi yox dərəcəsində az idi; lakin diplomatik dilin bu dəyişməsi Osmanlının Avropa qarşısındakı mütləq üstünlük iddiasının sona çatdığının rəmzi kimi oxunur.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Qəsri-Şirin Müqaviləsi", "c1acf3af"], "d": ["IV Muradın Bağdadı geri almasından (1638) sonra imzalanan müqavilə yüz ildən çox Osmanlı-Səfəvi müharibələrinə son verdi. Bağdad və İraq qəti olaraq Osmanlıda qaldı, İrəvan Səfəvilərə buraxıldı; çəkilən xətt kiçik dəyişikliklərlə bugünkü Türkiyə-İran sərhədinin əsası oldu və dünyanın ən uzunömürlü sərhədlərindən biri sayılır. Müqavilə Bədrə, Cəssan, Məndəli, Dərtəng və Dərnəni Osmanlıya buraxdı; sərhəddəki Zəncir qalası dağıdılacaq, qərbindəki kəndlər Osmanlıya, şərqindəkilər İrana qalacaqdı. Şəhrizor yaxınlığındakı Zalım qalası ətrafı və Qızılca qala Osmanlıda, Avroman və Mehriban İranda qaldı; Kotur, Maku və Məğazbərd qalaları hər iki tərəfdən dağıdılacaqdı.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Giritin fəthi tamamlandı", "e0d85604"], "d": ["1645-də başlayan Girit müharibəsinin son pərdəsi olan Kandiya mühasirəsi Fazıl Əhməd Paşanın üç illik qətiyyətli əməliyyatı ilə nəticələndi; Venesiya komandanı Morosini şəhəri müqavilə ilə təslim etdi. Təxminən çərək əsr davam edən mübarizə Osmanlı tarixinin ən uzun mühasirəsi kimi qeydə keçdi; Şərqi Aralıq dənizinin son böyük Latın qalası da Osmanlı idarəsinə girdi. Adanın şimal sahilindəki üç kiçik qayalıq qala — Suda, Spinalonqa və Qranbosa — hələ Venesiyada qaldı; bunlar ayrı adacıqlar üzərində qurulduğu üçün xəritədə Giritin qalan hissəsindən ayrı göstərilə bilməz.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Buçaş Müqaviləsi — ən geniş sərhədlər", "b17b6e5a"], "d": ["Leh yürüşündə Kamaniçenin fəthindən sonra imzalanan Buçaş Müqaviləsi ilə Podoliya Osmanlıya qatıldı və Ukraynanın bir hissəsi himayə altına alındı. İmperiya beləliklə Avropadakı ən geniş sərhədlərinə çatdı; bu nöqtə genişlənmə dövrünün zirvəsi və eyni zamanda son halqası sayılır.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["II Vyana mühasirəsi məğlubiyyəti", "7d889252"], "d": ["Mərzifonlu Qara Mustafa Paşanın iki ay davam edən Vyana mühasirəsi Leh kralı Yan Sobieskinin Kahlenberq təpələrindən endirdiyi qəfil zərbə ilə məğlubiyyətə çevrildi; ordu ağırlıqlarını buraxaraq geri çəkildi, Mərzifonlu Belqradda edam edildi. Qələbədən sonra qurulan Müqəddəs İttifaqla müharibə 16 il davam etdi; Osmanlı tarixində böyük gerilməsinin başlanğıc anı kimi bu məğlubiyyət göstərilir.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Qranbosa qalasının fəthi — Giritin Venesiyada qalan qayalıq qalalarından biri", "3ddf9eeb"], "d": ["1669-da Kandiyanın təslimi ilə Giritin fəthi böyük ölçüdə tamamlanmış sayılsa da adanın şimal-qərb ucundakı qayalıq ada-qala Qranbosa iyirmi üç il daha Venesiya əlində qaldı. 1692-də ələ keçirilməsi ilə Giritdəki üç Venesiya qalığından biri təmizləndi; Suda və Spinalonqa isə 1715 Moreya yürüşünü gözləyəcəkdi.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Karlovits Müqaviləsi — ilk böyük torpaq itkisi", "8f7e2546"], "d": ["On altı illik Müqəddəs İttifaq müharibələrini bitirən Karlovitslə Macarıstan və Erdel Avstriyaya, Podoliya Polşaya, Moreya və Dalmatiya sahilləri Venesiyaya buraxıldı. Osmanlı tarixində ilk dəfə bu miqyasda torpaq masa başında və daimi olaraq əldən çıxırdı; müqavilə imperiyanın Avropa qarşısında müdafiəyə keçdiyi yeni dövrün başlanğıc sənədi sayılır və Osmanlı diplomatiya tarixinin də dönüş nöqtəsidir. Eyni gün atlasda əldən-ələ keçən yaşayış məntəqələri: Kostajnica və Jasenovac (Osmanlıdan Habsburqa; müqavilə mətni Castanoviz-i imperatorun əlində buraxır, Jasenovacın təslim günü mənbədə yoxdur, müqavilə günü yazıldı) ilə Preveze (Venesiyadan Osmanlıya; TDV karlofca: 24 Rəcəb 1110 / 26 Yanvar 1699-da imzalanan müddəa uyarınca Venesiyanın İnəbəxtı körfəzi şimalındakı işğal yerləri geri qaytarıldı). Atlas ayrıca Kostayniçe (Kostajnica) və Jasenovaçı Habsburq tərəfə, Sağ Sahil Ukraynadakı Uman və Vinnitsanı Osmanlıdan Polşaya (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: 1672-99 Türk hakimiyyəti) və Dalmatiyadakı Nadini Venesiyaya yazır (yaşayış məntəqəsinə məxsus təslim günü mənbədə yoxdur, müqavilə günü yazıldı; Nadinin dövr uclar mənbə ilə doğrulanmadı — bəyanlı təqribilik). İnəbəxtı körfəzinin şimalındakı Vonitsa da Venesiyadan Osmanlıya qaytarılır (TDV karlofca); Dalmatiyada Vrana (Urana) Venesiyada qalan yerlər arasındadır (dövr ucu doğrulanmadı — bəyanlı).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Prut qələbəsi", "2583572f"], "d": ["Poltava məğlubiyyətindən sonra Osmanlıya sığınan İsveç kralı məsələsi üzündən çıxan müharibədə Çar I Petronun ordusu Prut sahilində mühasirəyə alınaraq təslim olmağa məcbur qaldı. İmzalanan müqavilə ilə Azak geri alındı; ordunun məhv edilməməsi və çarın sərbəst buraxılması isə o gündən bu günə qədər müzakirə edilən bir qərar kimi tarixə keçdi.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Suda və Spinalonqa qalalarının fəthi — Girit-də son Venesiya izinin silinməsi", "7261f7ba"], "d": ["Qranbosanın 1692-də süqutundan iyirmi üç il sonra Moreya yürüşünün bir yan qolu ilə Venesiyanın Giritdəki son iki dayağı olan Suda və Spinalonqa qalaları da fəth edildi. Beləliklə 1645-də başlayan Girit fəthi qırx altı ilin sonunda adanın son santimetrinə qədər tamamlanmış oldu.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Patrona Xəlil üsyanı", "100941a4"], "d": ["İran cəbhəsindəki uğursuzluq, vergilər və saray çevrəsinin lüksünə duyulan qəzəb hamam dəllakı Patrona Xəlilin rəhbərliyi ilə böyük bir üsyana çevrildi. Sədrəzəm İbrahim Paşa öldürüldü, III Əhməd taxtdan endirildi və Lalə Dövrü sona çatdı; üsyançıların aylarla şəhərə hakim olması mərkəzi hakimiyyətin kövrəkliyini təsirli şəkildə göstərdi.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Belqrad Müqaviləsi — Belqrad, Smederevo və şimali Serbiyanın geri alınması", "ba7f8e46"], "d": ["Avstriya və Rusiyaya qarşı iki cəbhədə aparılan müharibənin (1736–1739) sonunda Belqrad və Şimali Serbiya geri alındı; Rusiya Azakı silahsızlaşdırmağı və Qara dənizdə donanma saxlamamağı qəbul etdi. 18-ci əsr Osmanlı diplomatiyasının və ordusunun son böyük uğuru sayılan müqavilə imperiyaya çərək əsrlik bir sülh dövrü qazandırdı. Eyni gün atlasda Avstriyadan Osmanlıya qayıdan digər yaşayış məntəqələri: Hisarcık (Grocka) (Belqradın abi-mərkəz zənciri; TDV belgrad), Krayova (Craiova), Rimnik (Râmnicu Vâlcea) və Turnu Severin (Kiçik Eflakın Osmanlıya qayıdışı, Eflak vassallığına). Sava zolağındakı Bosna Brodu (Bosanski Brod) və Bosna Dubiçası (Bosanska Dubica) isə atlasda 28 Sentyabr 1739-da Osmanlıya qayıdır (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 Sentyabr 1739). Kiçik Eflakda Tırqu Jiu da eyni gün Osmanlıya qayıdır.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Çeşmə basqını", "840b30bd"], "d": ["İngilislərin dəstəyi ilə Aralıq dənizinə açılan Rus donanması Osmanlı donanmasını sığındığı Çeşmə limanında yanğın gəmiləri ilə basaraq demək olar ki, tamamilə yandırdı. Rusiya ilk dəfə Aralıq dənizində böyük dəniz gücü kimi göründü; fəlakət 1774 Küçük Kaynarcaya gedən müharibənin taleyini müəyyən edən zərbələrdən biri oldu və donanmanın köklü islahı ehtiyacını gözlər önünə sərdi.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Küçük Kaynarca Müqaviləsi", "2776dcdb"], "d": ["1768–1774 müharibəsini bitirən və Osmanlı tarixinin ən ağır müqavilələrindən sayılan Küçük Kaynarcayla Krım Xanlığına 'müstəqillik' verildi — faktiki olaraq Rus nüfuz sahəsi yaradılmış oldu. Rusiya Qara dəniz sahilinə yerləşdi, ticarət gəmilərinə Boğazlardan keçid hüququ və İstanbulda daimi səfirlik qazandı; Pravoslav təbəə üzərindəki qeyri-müəyyən himayə qeydi sonrakı əsrin müdaxilə əsaslarının qapısını aralı qoydu. İlk dəfə əhalisi müsəlman olan bir torpaq Osmanlı hakimiyyətindən çıxarılırdı.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Krımın Rusiyaya ilhaqı", "bdf6faa8"], "d": ["Küçük Kaynarcanın yaratdığı 'müstəqil' Krım son xan Şahin Giray dövründəki qarışıqlıqlar bəhanə edilərək II Yekaterinanın manifesti ilə Rusiyaya ilhaq edildi. Üç əsrlik Osmanlı-Krım ortaqlığı sona çatdı; şimal çöllərinin itirilməsi İstanbulun müdafiə dərinliyini aradan qaldırdı və on minlərlə Krım Tatarının Osmanlı torpaqlarına köçünün ilk böyük dalğasını başlatdı. Bu gün Krım yarımadası (Alušta, Kəfə, Sudak, Yalta, Balaklava, İnkerman, Mankup, Arabat) Rusiyaya qatıldı; Taman və Kuban da eyni ilhaqda Rusiyaya keçdi (TDV Krım: 8 Aprel 1783 Yulian = 19 Aprel Qriqori).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["III Səlim və Nizami-Cədid", "d53aec21"], "d": ["Müharibənin ortasında taxta çıxan III Səlim məğlubiyyətlərin struktur xarakterli olduğunu görərək 'Nizami-Cədid' (Yeni Nizam) adı ilə hərtərəfli islahat proqramı başlatdı: Avropa üsulu ilə təlim görmüş yeni ordu, bunu maliyyələşdirən ayrıca xəzinə (İradi-Cədid), mühəndisxanaların gücləndirilməsi və Avropa paytaxtlarında ilk daimi səfirliklər. Proqram müasir Türk islahat ənənəsinin başlanğıcı sayılır; lakin ocaqların və əyanların müqaviməti ilə 1807-də yıxılacaqdı.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Malta cəngavərlərinin ləğvi — Fransız donanmasının yoldakı dayanacağı", "d62f901d"], "d": ["Misirə gedən Fransız donanması yol üstündəki Maltaya uğradı; Sent-Jan (Malta) cəngavərləri çox müqavimət göstərmədən adanı təslim etdi. Rodosdan 1522-də qovularaq buraya yerləşən cəngavər ordeninin son qalası beləliklə sona çatdı. Malta iki il sonra İngiltərənin əlinə keçəcək, Napoleon isə adadan birbaşa İskəndəriyyəyə yönələcəkdi.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Napoleonun Misiri işğalı", "93fede5f"], "d": ["General Bonapartın ordusu İskəndəriyyəyə çıxaraq Misiri işğal etdi; İngiltərənin Hindistan yolunu hədəf alan bu yürüş bir Avropa gücünün Osmanlının mərkəz torpaqlarına ilk birbaşa hücumu idi. Nelsonun Əbukir basqını və Cəzzar Əhməd Paşanın Əkka müdafiəsi Fransız yürüşünü qırdı; işğal 1801-də sona çatdı, lakin buraxdığı boşluqda Qavalalı Məhəmməd Əli Paşanın yüksəlişi və 'Şərq Məsələsi' dövrü başladı.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sənədi-İttifaq", "cce49ef5"], "d": ["II Mahmudu taxta çıxaran Rusçuk əyanı Alemdar Mustafa Paşanın rəhbərliyi ilə saray ilə əyalətdəki güclü əyan ailələri arasında imzalanan sənəd; əyanlar padşaha bağlılıq və əsgər dəstəyi təəhhüd edərkən dövlət də onların varlıq və hüquqlarını tanıdı. Padşah hakimiyyətinin bir sənədlə məhdudlaşdırılmasının Osmanlı tarixindəki ilk nümunəsi olduğundan bəzi tarixçilər tərəfindən konstitusiya ənənəsinin uzaq başlanğıcı sayılır; faktiki olaraq bir neçə ay ərzində təsirsiz qaldı.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Yunan üsyanı başladı", "a7293715"], "d": ["Filiki Eterya təşkilatının hazırladığı üsyan əvvəl Eflakda, sonra əsas gücü ilə Moreyada başladı; Tepedelenli Əli Paşa məsələsi ilə məşğul olan dövlət ilk müdaxilədə gecikdi. Üsyan Avropa ictimai rəyindəki güclü Yunan simpatiyası (filhellenizm) sayəsində qısa müddətdə beynəlxalq bir məsələyə çevrildi; millətçilik dövrünün Osmanlı torpaqlarındakı ilk uğurlu müstəqillik hərəkatının fitili belə yandı. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Afina, Balyabadra (Patras), İstefe (Fiva), Livadiya, Eleusis (Attika), Missolonqi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Moreyada ilk silahlı üsyan", "77e6250f"], "d": ["Prut keçidindən sonra üsyan Moreyaya sıçradı: Kalavritada (Yulian 21 Mart) başlayan silahlı hərəkəti Patras, Kalamata və Manidəki hərəkatlar izlədi; Moreya qısa müddətdə ümumi üsyana çevrildi və Osmanlı idarəsi yarımadanın böyük hissəsini itirdi. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Afina, Balyabadra (Patras), İstefe (Fiva), Livadiya, Eleusis (Attika), Missolonqi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vəqayi-Xeyriyyə — Yeniçəri Ocağı ləğv edildi", "08c9372a"], "d": ["Yeni qurulan Əşkinci Ocağının təlimlərinə qarşı qazan çevirən yeniçərilər II Mahmudun əvvəlcədən hazırladığı sadiq birliklərin top atəşi ilə Etmeydanındakı kazarmalarında məhv edildi; ocaq bütün şöbələri və bağlı Bektaşi təkkələri ilə birlikdə ləğv edildi. 'Xeyirli hadisə' mənasındakı adı ilə tarixə keçən bu əməliyyat dörd əsrlik qurumu ləğv edərək Əsakiri-Mənsurəyi-Məhəmmədiyyə ordusunun və sonrakı bütün mərkəzləşdirmə islahatlarının önünü açdı.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Navarin basqını", "ee579e7f"], "d": ["Yunan üsyanını yatırmaqda olan Osmanlı-Misir donanması müharibə elanı olmadan limana girən İngilis-Fransız-Rus birləşmiş donanması tərəfindən Navarində yandırıldı; altmışa yaxın gəmi və minlərlə dənizçi itirildi. Avropa diplomatiyasında 'bədbəxt hadisə' deyə ötüşdürülən basqın Yunan müstəqilliyini faktiki olaraq təmin etdi və 1828–29 Osmanlı-Rus müharibəsinin yolunu açdı.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Tənzimat Fərmanı", "5042ce7b"], "d": ["Gülxanədə oxunan Xətti-Hümayunla din ayrımı gözlənilmədən bütün təbəənin can, mal və namus təhlükəsizliyi dövlət təminatına alındı; vergidə ədalət, hərbi xidmətdə qayda və mühakiməsiz cəza verilməməsi prinsipləri elan edildi. Mustafa Rəşid Paşanın əsəri olan fərman Osmanlı modernləşməsinin konstitusiya xarakterli ilk böyük sənədi sayılır və 'Tənzimat Dövrü' (1839–1876) islahat dövrünə adını vermişdir; idarəetmə, hüquq, təhsil və maliyyədə köklü yenidən qurulma bu çərçivədə aparıldı.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Krım müharibəsi başladı", "3b9ca3c8"], "d": ["Müqəddəs yerlər məsələsi və Rusiyanın Pravoslav təbəə üzərində himayə iddiası ilə başlayan böhran Osmanlının müharibə elanı ilə açıq toqquşmaya çevrildi; Sinop basqınından sonra İngiltərə və Fransa (sonra Pyemont) Osmanlı tərəfində müharibəyə girdi. Müttəfiq orduların Krıma çıxaraq Sevastopolu almasıyla müharibə 1856 Paris Müqaviləsi ilə qazanıldı; lakin müharibə illərində alınan ilk xarici borc (1854) imperiyanı yarım əsr davam edəcək maliyyə asılılığı çevrəsinə saldı.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["İslahat Fərmanı", "78ff234d"], "d": ["Paris sülh danışıqlarından əvvəl elan edilən fərman Tənzimat prinsiplərini genişləndirərək qeyri-müsəlman təbəəyə dövlət məmurluğu, hərbi xidmət və məktəb açmaq daxil geniş bərabərlik hüquqları tanıdı; icma təşkilatları yenidən nizamlandı. Ardınca imzalanan Paris Müqaviləsi ilə Osmanlı Dövləti rəsmən Avropa dövlətlər hüququ ailəsinə qəbul edildi və ərazi bütövlüyü böyük dövlətlərin ortaq zəmanətinə alındı — bu zəmanət praktikada müdaxilələrin yeni qapısı olacaqdı.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Qanuni-Əsasi — I Məşrutiyyət", "0fe052c1"], "d": ["Balkan böhranını müzakirə etmək üçün İstanbulda toplanan beynəlxalq konfransın açıldığı gün top atəşləri ilə ilk Osmanlı konstitusiyası elan edildi; Midhat Paşanın başçılıq etdiyi 'Yeni Osmanlılar' hərəkatının əsəri olan Qanuni-Əsasi ilə iki palatalı parlament quruldu. Məclisi-Məbusan Mart 1877-də açıldı; lakin II Əbdülhəmid 93 Müharibəsini əsas göstərərək Fevral 1878-də məclisi müddətsiz tətil etdi və konstitusiya otuz il asılı qaldı.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["93 Müharibəsi (1877–78 Osmanlı-Rus müharibəsi)", "5bd96af7"], "d": ["Rumi 1293-cü ilə təsadüf etdiyi üçün '93 Müharibəsi' deyə anılan müharibədə Rus orduları iki cəbhədən hücum etdi; Qazi Osman Paşanın Plevna müdafiəsi və Əhməd Muxtar Paşanın Qafqaz döyüşləri dastanlaşsa da cəbhə çökdü və Ruslar Yeşilköyə (Ayastefanos) qədər irəlilədi. Müharibə Balkanlardan və Qafqazdan İstanbula yönələn, təsirləri bu günə uzanan böyük müsəlman köç dalğalarını başlatdı; imperiyanın demoqrafik və maliyyə quruluşu bir daha köhnə halına qayıda bilmədi.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Berlin Müqaviləsi", "47f76a49"], "d": ["Ayastefanosun yaratdığı 'Böyük Bolqarıstanı' böyük dövlətlər balansı adına yenidən nəzərdən keçirən Berlin Konqresi yenə də ağır bir mənzərə buraxdı: Serbiya, Monteneqro və Rumıniya müstəqil oldu; muxtar Bolqarıstan Knyazlığı quruldu; Bosniya-Herseqovina Avstriya işğalına, Kipr Britaniya idarəsinə, Qars-Ərdahan-Batum Rusiyaya buraxıldı. Rumelidəki beş yüz illik Osmanlı nizamı böyük ölçüdə dağıldı; 'şərq məsələsi' Avropa diplomatiyasının daimi gündəminə çevrildi. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence. Rumıniya Bessarabiyanı Rusiyaya verməsinə qarşılıq Tulça (Tulcea) və Dobrucanı aldı: Şimali Dobrucadakı Tulça, Babadağ (Babadag), Maçin, İsakça (Isaccea), Hırsova (Hârșova) və Mankaliya (Mangalia) Rumıniyaya keçdi.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Tunisin işğalı və Düyuni-Ümumiyyə", "c7e25598"], "d": ["Fransa Əlcəzair sərhədindəki hadisələri bəhanə edərək Tunisi işğal etdi və Bardo Müqaviləsi ilə himayəsinə aldı; Osmanlının Şimali Afrikadakı mövcudluğu Tripolitaniyaya endi. Eyni il çıxarılan Məhərrəm Fərmanı ilə müflis olmuş xarici borcların idarəsi üçün kreditorların təmsil olunduğu Düyuni-Ümumiyyə İdarəsi quruldu: duz, tütün, ipək kimi əsas gəlirlər birbaşa bu xarici idarəyə bağlandı və maliyyə suverenliyi ağır şəkildə məhdudlaşdı. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Qeyrəvan, Qabis, Sfaks, Cerbə (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Misirin Britaniya işğalı", "f1269768"], "d": ["Misirdə maliyyə müflisliyinə və xarici nəzarətə qarşı yüksələn Urabi Paşa hərəkatı İskəndəriyyənin bombalanmasından sonra quruya çıxan Britaniya ordusunun Təl əl-Kəbir qələbəsi ilə əzildi və Qahirə işğal edildi. Misir hüquqən Osmanlıya bağlı qalmağa davam etsə də faktiki olaraq Britaniya idarəsinə girdi; Süveyş kanalının nəzarəti Britaniya imperiya strategiyasının mərkəzinə yerləşdi.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["II Məşrutiyyətin elanı", "95ee2fd2"], "d": ["İttihad və Tərəqqi Cəmiyyətinə bağlı zabitlərin Makedoniyada dağa çıxması ilə böyüyən hərəkat qarşısında II Əbdülhəmid Qanuni-Əsasini yenidən qüvvəyə mindirdi; 'azadlığın elanı' coşqu ilə qarşılandı və seçkilərə gedildi. Lakin sabitlik gəlmədi: 31 Mart Hadisəsi (Aprel 1909) yatırıldıqdan sonra Əbdülhəmid taxtdan endirildi; Bolqarıstanın müstəqilliyi, Bosniyanın ilhaqı və Giritin Yunanıstana yönəlməsi də bu çalxantılı aylarda baş verdi.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Tripolitaniya müharibəsi", "ed441994"], "d": ["Müstəmləkə axtarışındakı İtaliya Osmanlının Şimali Afrikadakı son torpağı Tripolitaniyaya müharibə elan edib sahilləri işğal etdi; donanması olmayan dövlət nizami ordu göndərə bilmədikdə Mustafa Kamal və Ənvər bəy kimi gənc zabitlər gizlicə bölgəyə keçərək Sənusi qəbilələri ilə təsirli bir müqavimət təşkil etdi. Balkan müharibəsinin başlaması üzərinə imzalanan Uşi Müqaviləsi ilə (18 Oktyabr 1912) Liviya İtaliyaya buraxıldı; İtaliya ayrıca Rodos və Onikiadanı işğal etdi.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["London Müqaviləsi — Rumelinin itirilməsi", "f3f976df"], "d": ["I Balkan müharibəsini bitirən London Müqaviləsi ilə Midye-Enez xəttinin qərbindəki bütün torpaqlar və Egey adaları itirildi; Albaniya müstəqil oldu. Beş yüz ildən çoxdur imperiyanın demoqrafik, iqtisadi və mədəni ağırlıq mərkəzi olan Rumelidən geriyə yalnız Şərqi Frakiya qalacaqdı (Ədirnə II Balkan müharibəsində geri alındı); itki İttihadçı idarənin müharibə və məskunlaşdırma siyasətini köklü şəkildə sərtləşdirdi. Midye-Enez xəttinin qərbində qalan bu yerlər əldən çıxdı: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Dibra), Prizren, Priştinə, Peç (Pejë), Yenipazar (Novi Pazar), Kosovo düzü (Kosovo Polje); Serez, Drama, Kavala, Petriç, Nevrokop, İskeçə, Gümülcinə, Dədəağac, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fəqih (Fakia), Malak Dərvənd (Lalkovo); Giritdə Xanya, Kandiya, Girit (Rəsmo), Sitiyə (Sitia) və İsfakiyə (Sfakia).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["I Dünya müharibəsinə giriş", "05a0252e"], "d": ["İngiltərədən qaçan Goeben və Breslau zirehliləri satın alınmış kimi göstərilərək Boğazdan içəri alınması dövləti addım-addım Almaniyanın yanına çəkdi; Admiral Souchonun komandanlığındakı donanmanın Rus limanlarını bombalaması ilə (29 Oktyabr) müharibə faktiki olaraq başladı və qarşılıqlı elanlar Noyabrın əvvəlində gəldi. Cihadi-Əkbər elanına baxmayaraq gözlənilən təsir yaranmadı; imperiya dörd il boyunca Qafqazdan Fələstinə beş ayrı cəbhədə varlıq müharibəsinə girdi.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Çanaqqala qələbəsi", "95d888e8"], "d": ["İstanbulu süquta uğradıb Rusiyaya çatmağı hədəfləyən müttəfiq armada 18 Martda mina xətləri və tabyaların atəşi ilə Boğazdan geri oturdu; Nüsrət mina gəmisinin düzdüyü xətt müharibənin taleyini müəyyən etdi. Aprelda başlayan Gəliboluda quru əməliyyatı da Anafartalar və Conkbayırında dayandırıldı; müttəfiqlər Yanvar 1916-da yarımadanı tamamilə boşaltdı. Podpolkovnik Mustafa Kamalın adı bu cəbhədə eşidildi; təxminən çərək milyon şəhid və itki ilə qazanılan qələbə Milli Mücadilə kadrlarının və ruhunun doğulduğu yer sayılır.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Şərif Hüseyn üsyanı", "75f7c58c"], "d": ["Məkkə Əmiri Şərif Hüseyn İngilislərlə apardığı gizli yazışmalardan sonra müstəqil Ərəb krallığı vədi ilə üsyan qaldırdı; Hicaz dəmir yolu basqınların hədəfinə çevrildi. Fəxrəddin Paşanın Mədinəni barışıqdan sonrasına qədər davam edən əfsanəvi müdafiəsi müqavimətin rəmzi olaraq qalsa da üsyan Fələstin cəbhəsindəki Britaniya irəliləyişi ilə birləşərək Ərəb vilayətlərindəki Osmanlı hakimiyyətinin dağılmasını sürətləndirdi. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Taif.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Mudros barışığı", "9e87c767"], "d": ["Bolqarıstanın çöküşü ilə cəbhələri bir-birindən qopan Osmanlı Dövləti Agamemnon zirehlisində imzalanan barışıqla müharibədən çəkildi. Boğazların açılması və xüsusilə təhlükəsizliyi təhdid olunan yerlərin işğal edilməsinə imkan verən 7-ci maddə qısa müddətdə faktiki bölüşdürmənin hüquqi örtüyü edildi: Mosul, İskəndərun, sonra İzmir və İstanbul işğal edildi. Barışıq imperiyanın faktiki sonunun sənədi sayılır. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Həma, Şam, Hims.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kamal Samsunda — Milli Mücadilə", "09a8f784"], "d": ["İzmirin işğalının yaratdığı üsyan mühitində 9-cu Ordu müfəttişi sifəti ilə Samsuna çıxan Mustafa Kamal Paşa rəsmi vəzifəsini Anadoludakı müqavimətin təşkilinə yönəltdi. Amasya Sirkulyarı ilə Ərzurum və Sivas qurultayları bu çıxışın davamıdır; 'millətin müstəqilliyini yenə millətin əzmi və qərarı xilas edəcək' prinsipi Milli Mücadilənin siyasi proqramının nüvəsi oldu.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["TBMM-in açılışı və Sevr", "2008feec"], "d": ["İstanbulun rəsmən işğalı və Məclisi-Məbusanın dağıdılması üzərinə 23 Aprel 1920-də Ankarada Böyük Millət Məclisi açıldı; fövqəladə səlahiyyətləri özündə toplayan məclis milli iradəyə əsaslanan yeni dövlətin nüvəsi oldu. Avqustda İstanbul hökumətinin imzaladığı Sevr Müqaviləsi Anadolunu bölüşdürürdü; TBMM müqaviləni imzalayanları vətən xaini elan etdi və Sevr heç vaxt tətbiq edilə bilmədi.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Sakarya meydan döyüşü", "f2f970a6"], "d": ["Ankaraya 50 kilometrə qədər yaxınlaşan Yunan hücumu baş komandanlıq səlahiyyətini öz üzərinə götürən Mustafa Kamal Paşanın 'müdafiə xətti yoxdur, müdafiə səthi var' əmri ilə aparılan 22 gün 22 gecəlik döyüşdə qırıldı. Yunan ordusu ilk dəfə strateji müdafiəyə keçdi; qələbə Mustafa Kamala qazilik və müşirlik (marşal rütbəsi) gətirdi, Fransa ilə Ankara Sazişinin və xarici tanınmanın qapısını açdı.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Böyük Hücum və İzmirin azad edilməsi", "172a50c4"], "d": ["26 Avqust səhəri Kocatəpədən başladılan hücum 30 Avqustda Dumlupınarda Baş Komandan Meydan Döyüşü ilə Yunan əsas qüvvələrinin məhvinə çatdı; 'Ordular, ilk hədəfiniz Aralıq dənizidir, irəli!' əmri ilə davam edən təqiblə 9 Sentyabrda İzmir azad edildi. Mudanya barışığı ilə (11 Oktyabr) Şərqi Frakiya döyüşsüz geri alındı; hərbi qələbə Lozannada qurulacaq yeni dövlətin masadakı gücünü müəyyən etdi.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Səltənətin ləğvi", "9f36a9f6"], "d": ["Lozanna danışıqlarına İstanbul hökumətinin də çağırılması üzərinə TBMM 1 Noyabr 1922-də səltənət ilə xilafəti ayıraraq səltənəti ləğv etdi; 623 illik Osmanlı sülalə idarəsi hüquqən sona çatdı. VI Mehmed Vahidəddin 17 Noyabrda bir Britaniya zirehlisi ilə ölkədən ayrıldı; xilafət məqamına TBMM qərarı ilə Əbdülməcid Əfəndi gətirildi və bu məqam da 3 Mart 1924-də ləğv ediləcəkdi.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Lozanna Müqaviləsi", "38c27f7d"], "d": ["Səkkiz ay davam edən çətin danışıqların sonunda imzalanan Lozanna Sülh Müqaviləsi ilə yeni Türk dövlətinin sərhədləri, tam müstəqilliyi və suverenliyi beynəlxalq arenada tanındı; kapitulyasiyalar ləğv edildi, Düyuni-Ümumiyyə ləğv prosesinə salındı, əhali mübadiləsi nizamlandı. Sevri faktiki olaraq qüvvədən salan Lozanna Milli Mücadilənin diplomatik qələbəsi və Respublikanın təsisedici xarici sənədi sayılır.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Respublikanın elanı", "d5bfcdfb"], "d": ["TBMM-in konstitusiya dəyişikliyi ilə 'Türkiyə Dövlətinin hökumət forması respublikadır' müddəasını qəbul etməsi ilə Respublika elan edildi; Mustafa Kamal Paşa ilk prezident seçildi. 1299-da bir sərhəd bəyliyi kimi başlayan 624 illik Osmanlı macərası beləliklə bağlanmış, suverenliyin qeyd-şərtsiz millətə məxsus olduğu yeni dövlət imperiyanın mirası üzərində qurulmuşdur.", "f5cabb8c"]},
"OLAYLAR_2S1019:0330-05-11:0":{"b": ["Konstantinopol Bizans (Şərqi Roma) paytaxtı olaraq açıldı", "9d155dd6"], "d": ["Konstantinin yenidən qurdurduğu Byzantion, günlərlə davam edən mərasimlərlə imperiyanın yeni paytaxtı olaraq açıldı. Atlasın Bizans (Şərqi Roma) qeydi Konstantinopolda bu gün ilə başlayır.", "c4468b48"]},
"OLAYLAR_2S1019:0969-07-06:0":{"b": ["Fatimilər Misiri aldı: Cövhər əs-Siqilli Fustata girdi, Qahirənin təməli qoyuldu", "500aef7a"], "d": ["Fatimi komandanı Cövhər əs-Siqilli Misirdəki İxşidi hakimiyyətinə son verib Fustata girdi və şimaldakı Mənahda yeni paytaxtın, Qahirənin sarayını və divarlarını qurdurdu.", "d9599f90"]},
"OLAYLAR_2S1019:0990-03-31:0":{"b": ["Uqeylilər Mosulu ələ keçirdi — Mosul Uqeyli sülaləsinin qurulması", "49eb93a6"], "d": ["Əbüzzəvvad, Əbu Tahir İbrahimi oğlu ilə birlikdə öldürüb Mosulu aldı; şəhərdə Büveyhilərə bağlı Uqeyli sülaləsi quruldu.", "affdc0ec"]},
"OLAYLAR_2S1019:1084-12-12:0":{"b": ["Qutalmışoğlu Süleyman şah Antakyanı Bizansdan aldı", "17d1c6f0"], "d": ["Bir əsrdən çox Bizansın əlində qalan Antakyanı Anadolu Səlcuqlu hökmdarı Süleyman şah aldı; müqavimət göstərən iç qala 12 yanvar 1085-də təslim oldu.", "a6f1f783"]},
"OLAYLAR_2S1019:1098-06-03:0":{"b": ["Səlibçilər Antakyanı aldı — Antakya knyazlığı quruldu", "c9f47942"], "d": ["Uzun mühasirəyə dözən Antakya, Yağısıyanın komandanı Firuzun xəyanəti ilə səlibçilərin əlinə keçdi. Qurulan Antakya knyazlığı İskəndəruna da əhatə etdi.", "f6409190"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["Qiyaseddin Keyxosrov Antalyanı fəth etdi — Səlcuqlular Aralıq dənizinə çatdı", "9812e629"], "d": ["Latınların Konstantinopolu almasından sonra italyan Aldobrandininin əlinə keçən Antalyanı, Latın idarəsindən razı qalmayan rumların da dəstəyi ilə Anadolu Səlcuqlu sultanı I Qiyaseddin Keyxosrov aldı.", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["İzzəddin Keykavus Antalyanı kiprlilərdən geri aldı", "ec2446f9"], "d": ["1212-də Kipr kralının dəstəyi ilə edilən üsyan nəticəsində əldən çıxan Antalyanı I İzzəddin Keykavus yenidən fəth etdi və valiliyini təkrar Mübarizəddin Ertokuşa verdi.", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["Baybars Yafanı səlibçilərdən aldı — Qüds krallığının Yafadakı hakimiyyəti sona çatdı", "c7629d70"], "d": ["Məmlük sultanı I Baybars Yafadakı səlibçi hakimiyyətinə son verdi, şəhəri dağıtdırdı; iç qalanın taxta və mərmərini Qahirədəki məscidinin inşasına göndərdi.", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["Baybars Antakyanı aldı — Antakya knyazlığının sonu", "da2b511a"], "d": ["Məmlük ordusu ümumi hücumla Antakya divarlarını aşdı; 170 illik səlibçi knyazlığı sona çatdı və İskəndərun da yenidən İslam torpaqlarına qatıldı.", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["Qaramanoğulları Konyanı Elxanilərdən geri aldı", "057ec073"], "d": ["Elxani Anadolu valisi Dəmirtaşın Misirə qaçmasından sonra Konya yenidən Qaramanoğullarının əlinə keçdi. Şəhər 1350-də Eretnaya keçəcəkdi.", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["Kastiliya kralı XI Alfonso Cəzirətülxəzranı (Algeciras) aldı: iyirmi aylıq mühasirədən sonra Mərini hakimiyyəti sona çatdı", "5de2a877"], "d": ["Kastiliya kralı XI Alfonsonun təxminən iyirmi ay davam edən mühasirəsinin ardınca 21 mart 1344-də başlayan danışıqlar sonunda Mərini hökmdarı Əbülhəsən müsəlmanlara şəhəri tərk etmələrini bildirdi; 26 martda Villa Nueva, ertəsi gün Villa Vieja boşaldıldı və kastiliyalılar şəhəri təhvil aldı. XI Alfonso 28 mart 1344-də (Xurma bazarı) təntənə ilə şəhərə girdi. Cəzirətülxəzra 1369-a qədər Kastiliyada qaldı.", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["Stefan Duşan Serezi Bizansdan aldı", "2cc79d36"], "d": ["Bizans vətəndaş müharibəsindən istifadə edən Serb kralı Stefan Duşan Serezi ələ keçirdi və şəhəri Serb imperiyasının paytaxtı etdi.", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["Feldkirch qraflığı Habsburq Avstriyasına satıldı", "fe4a0306"], "d": ["Montfort-Feldkirch qolunun sonuncu qrafı Rudolf, 1375-də bütün mülkünü Avstriya hersoqları Habsburqlara satdı; faktiki devir onun ölümü ilə (1390) tamamlandı. Feldkirch, Vorarlbergin Habsburq əlinə keçən ilk böyük parçası oldu.", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["Balçık və Dobruca sahili Osmanlı idarəsinə girdi", "dfd348b9"], "d": ["Kosovo qələbəsinin ardınca Dobruca sahilindəki Balçık Osmanlı idarəsinə girdi. Bölgəni dərhal ardınca Əflak voyvodası Mircea işğal edəcək, Osmanlı hakimiyyəti 1393-də yenidən qurulacaqdı.", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["Mər'aşi seyyidləri Mahaneserdə Teymura təslim oldu — Mazandaran Teymurilərə keçdi", "125dbed8"], "d": ["Beş illik yürüşündə Mazandarana girən Teymur, Qaratoğanda qarşısına çıxan Mər'aşiləri Mahaneser qalasına sıxışdırıb təslim aldı. Sari ilə Amulda böyük qətliam edildi; Sari Kiya Əfrasiyabın oğlu İskəndər Şeyxiyə verildi.", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["Şibenik yenidən Venesiya Respublikasının idarəsinə girdi", "9b7998bf"], "d": ["Neapollu Ladislasın Dalmatiya üzərindəki haqlarını 1409-da Venesiyaya satmasından sonra müqavimət göstərən Şibenik, 1412-də yenidən Venesiya idarəsinə girdi. Şəhər 1797-də Respublika yıxılana qədər Venesiyanın Dalmatiya mülkü olaraq qaldı.", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["Çələbi Mehmedin Candaroğulları yürüşü: Çankırı Osmanlı himayəsindəki Qasım bəyə verildi", "da03b919"], "d": ["Şeyx Bədrəddinin Əflaka keçməsinə kömək edən Candaroğlu İsfəndiyar bəyə qarşı yürüyən Çələbi Mehmed Kastamonuya irəlilədi və İsfəndiyarın çəkildiyi Sinopu mühasirəyə aldı. İsfəndiyar Osmanlı hökmranlığını tanıdı; Ilqaz dağı sərhəd qəbul edilərək Osmanlıya sığınmış oğlu Qasım bəyə Çankırı və ətrafı verildi.", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["Smederevonun alınması ilə Hisarcık (Grocka) da Osmanlıya keçdi", "ab724ec9"], "d": ["Üç aylıq mühasirədən sonra Smederevo alındı. Smederevodan 17 km yaxınlıqdakı Hisarcık (Grocka) atlasda ağa mərkəzi Smederevonun aqibətini izləyir və eyni gündə Serb despotluğundan Osmanlıya keçir (1444-də geri qaytarılacaqdır).", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["Bregenz qraflığının ilk yarısı Habsburq Avstriyasına satıldı", "3a9598db"], "d": ["Montfort-Bregenz varisi Hochberqli Elisabeth 1451-də Bregenz qraflığının yarısını Habsburqlara satdı; qalan yarı 1523-də alındı. Bregenz beləliklə Habsburq Vorarlbergin parçası oldu.", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["Gördüsün (Korinf) təslimi ilə Sikyon da Osmanlıya keçdi", "c7b0d22d"], "d": ["Fateh Mora yürüşündə üç aylıq mühasirədən sonra Gördüsü (Korinf) sülh yolu ilə aldı. Korinfə 17 km məsafədəki Sikyon atlasda ağa mərkəzi Gördüsün aqibətini izləyir və eyni gündə Osmanlıya keçir.", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["Smederevonun təslimi ilə Hisarcık (Grocka) da Osmanlıya keçdi", "e3d76f5c"], "d": ["Lazar Brankoviçin dul arvadı Helena Smederevo qalasını osmanlılara təslim etdi; Serb despotluğu sona çatdı. Smederevonun ağa mərkəzliyindəki Hisarcık (Grocka) eyni gündə Osmanlıya keçir.", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["Kəfənin təslimi və Krım xanının tabeliyi — Çərkəziyə sahili (Soçi, Tuapse, Maykop) boş himayə sahəsi kimi Krım xanlığına bağlandı", "e99eb8e8"], "d": ["Dörd günlük mühasirədən sonra Kəfə Əhməd paşaya təslim oldu, Mengli Giray Osmanlı sultanının tabeliyini qəbul etdi. Krım xanlarını metbu tanıyan Çərkəz tayfalarının yurdu olan Soçi, Tuapse və Maykop ətrafı atlasda bu tarixdən etibarən Krım xanlığına boş himayə olaraq bağlı göstərilir.", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["Moskva Bryanskı Litva Böyük Hersoqluğundan aldı", "fb1c3a61"], "d": ["1500-1503 Moskva-Litva müharibəsində Rus ordusu Bryanskı aldı və şəhər Moskva dövlətinə qatıldı; 1503 atəşkəsi bu qazancı tanıdı.", "8e507991"]},
"OLAYLAR_2S1019:1500-04-12:0":{"b": ["Sonuncu Görz qrafı Leonhard öldü — Lienz və Puster vadisi Habsburq Avstriyasına (Tirol) keçdi", "93331339"], "d": ["Görz (Gorizia) qraflarının sonuncu nümayəndəsi Leonhard 12 aprel 1500-də Lienzdə öldü. Əvvəlcədən edilən varislik razılaşmasına görə Lienz və Puster vadisini əhatə edən ön qraflıq I Maximiliana keçərək Tirola qatıldı.", "996079fc"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["Bıyıqlı Mehmed paşa Mosul, Sincar və İmadiyyəni Səfəvilərdən aldı", "3039d6af"], "d": ["Koçhisarda Qara xanı məğlub edən Bıyıqlı Mehmed paşa Mardini mühasirəyə alarkən ətrafdakı qalaları Səfəvilərdən aldı: Mosul, Ruha, Birecik və Sincar ələ keçirildi, İmadiyyə və digər kürd hakimləri Osmanlı tabeliyini qəbul etdi. Mardin qalası isə paşanın Mərcidabiqdən qayıdışından sonra təslim alınacaqdı.", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["Gustav Vasa Strängnäsdə kral seçildi — İsveç krallığı Kalmar ittifaqından ayrıldı", "a6e95f4c"], "d": ["Stokholm qan hamamından (1520) sonra Danimarka kralı II Christiana qarşı üsyan edən Gustav Eriksson Vasa, 1523-cü ilin mayında Strängnäsdə toplanan İsveç Riksdaqında 6 iyun 1523-də kral seçildi. İsveç və ona bağlı Finlandiya beləliklə 1397-dən bəri davam edən Kalmar ittifaqından qəti olaraq çıxdı və müstəqil İsveç krallığının Vasa dövrü başladı.", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["Silezya zümrələri I Ferdinandı kral tanıdı — Silezya Habsburq Avstriyasına keçdi", "a28e10c2"], "d": ["Mohaçda II Lajosun ölümü ilə boşalan Bohemiya tacına 1526-cı ilin oktyabrında seçilən Habsburq Ferdinandı, Yuxarı və Aşağı Silezya zümrələri ümumi toplantıda imtiyazlarının təsdiqi şərti ilə 5 dekabr 1526-da kral, arvadı Annanı kraliça tanıdı. Silezya hersoqluqları beləliklə Bohemiya tacı ilə birlikdə Habsburq idarəsinə girdi.", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["İsveç kralı Gustav Vasa Helsinkini qurdu", "43468b54"], "d": ["İsveç kralı Gustav Vasa 1550-də Vantaa çayının mənsəbində, Reval (Tallinn) ilə Baltik ticarətində rəqabət aparması üçün yeni ticarət şəhəri olaraq Helsinkini qurdurdu. Şəhər 1640-da bugünkü yerinə, dənizə doğru köçürüldü.", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["Ümman Ya'rubi imamı Nasir ibn Mürşid Cülfarı Portuqaliyadan aldı", "6ca9fb0c"], "d": ["Hörmüzün 1622-də süqutundan sonra da Cülfarda dayanan portuqallar, Ümman Ya'rubi imamı Nasir ibn Mürşidin 1633-dəki ələ keçirməsi ilə bölgədən çıxarıldı.", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["Sin (Sinj) qalasının Venesiyaya itirilməsi — Dalmatiya daxili bölgəsi", "3af8e103"], "d": ["Mora müharibəsi zamanı Venesiya qüvvələri 1686-da Dalmatiyanın daxili bölgəsindəki Sin (Sinj) qalasını Osmanlılardan aldı; qala 1715 Osmanlı mühasirəsinə də davam gətirdi və Venesiyada qaldı.", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["Varadin və Baçın Macarıstan krallığının (Habsburq tacı) əlinə keçməsi — Harşandan sonra Bačkadan çəkiliş", "6bc2b1ac"], "d": ["Harşan məğlubiyyətindən çəkilən Sarı Süleyman paşanın ordusu 1 sentyabr 1687-də Varadindən keçdi və qalanı Cəfər paşaya tərk etdi; qısa müddət sonra Varadin ilə Bačkadakı Baç müttəfiq Habsburq qüvvələrinin əlinə keçdi. Karlovitsada Sava sərhəd qəbul edilincə Varadin Avstriya tərəfində qaldı.", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["Öseki Macarıstan krallığının (Habsburq tacı) əlinə keçməsi — Slavoniyanın itkisi başladı", "7af97ffe"], "d": ["Harşan məğlubiyyətindən sonra Drava üzərindəki Ösek körpü qalası 26 sentyabr 1687-də Habsburq qüvvələrinə keçdi. Slavoniyadakı Osmanlı hərbi varlığı və türk əhalisi 1686-1688 arasında tədricən çəkildi; bölgə Habsburq idarəsinə girdi.", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["Herseknovinin Venesiyaya itirilməsi — Kotor körfəzinin ağzı", "b88046d8"], "d": ["Mora müharibəsi zamanı Venesiya donanması və müttəfiqləri 1687-də Kotor körfəzinin ağzındakı Herseknovi qalasını mühasirəyə alıb aldı; şəhər 1797-də Venesiya Respublikası yıxılanadək Venesiyada qaldı.", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["Korsikanın İngiltərə tacına bağlanması — Anglo-Korsika krallığı", "10f18bde"], "d": ["İnqilab Fransasına qarşı üsyan edən Paoli, ingilis donanmasının dəstəyi ilə adanı fransız qarnizonlarından təmizlədi; Cortedə toplanan konsultada Korsikanı ingilis krallığına bağlayan konstitusiya qəbul etdi. Ada iki il Anglo-Korsika krallığı olaraq ingilis general-qubernatoru Gilbert Elliotun idarəsində qaldı.", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["İngilislərin Korsikanı boşaltması — ada yenidən Fransanın", "c9f986fe"], "d": ["Bonapartın İtaliya qələbələri və İspaniyanın Fransa tərəfinə keçməsi ilə Aralıq dənizində sıxışan İngiltərə Korsikanı boşaltdı. Anglo-Korsika krallığı sona çatdı və ada yenidən Fransaya bağlandı.", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["Avstriya-Macarıstan ordusu müqaviməti qıraraq Bihaçı aldı", "ffec53e0"], "d": ["Berlin müqaviləsi ilə Bosniya-Herseqovinanı işğal hüququ alan Avstriya-Macarıstan, Bihaçda yerli müsəlman müqaviməti ilə qarşılaşdı. General Wilhelm von Reinländerin komandanlığı altındakı qüvvələr 18 sentyabr 1878-də şəhəri aldı; Una vadisindəki Ostrovica qarnizonu da eyni əməliyyatla Osmanlı əlindən çıxdı.", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["İngilislər Sokotonu işğal etdi — Sokoto xilafəti paytaxtını itirdi", "e744f986"], "d": ["Şimali Nigeriyanı 1900-də müstəmləkə elan edən İngiltərənin valisi Lugard əmirlikləri bir-bir aldıqdan sonra Sokoto ordusunu ağır məğlubiyyətə uğratdı və 15 mart 1903-də paytaxtı işğal etdi. Qaçan xəlifə Tahirin iyulda Burmidə öldürülməsi ilə xilafətin siyasi hakimiyyəti sona çatdı.", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["İbn Süud Rəşidi əmirini məğlub etdi — Qəsim Şəmmər əmirliyindən Süudilərə keçdi", "a32201dd"], "d": ["Riyadı 1902-də geri alan Əbdüləziz ibn Süud, 13 aprel 1906-da Rəşidi əmiri Əbdüləziz ibn Mut'ibi məğlub edib öldürdü. Bu döyüşün ardınca Qəsim bölgəsini (Buraydə, Uneyzə) ələ keçirdi; Rəşidilər bundan sonra yalnız Hail və ətrafında hökm sürdü.", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["Kəmaran adası ingilislər tərəfindən işğal edildi", "c514bb66"], "d": ["Qırmızı dənizdə Yəmən sahilindəki Kəmaran adası I Dünya müharibəsi zamanı 1915-də ingilislər tərəfindən işğal edildi və Ədəndən idarə olunmağa başladı.", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["Nablusun ingilislər tərəfindən işğalı — Fələstin cəbhəsinin çöküşü", "b5e85950"], "d": ["1918-in sentyabrında Allenbynin Fələstin cəbhəsindəki böyük hücumu Osmanlı 7 və 8-ci ordularını dağıtdı; Nablus ingilislərin əlinə keçdi və şəhərdə dörd əsrlik Osmanlı hakimiyyəti sona çatdı. Şəhər 1920-yə qədər ingilis hərbi idarəsində qaldı.", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["İngilislərin Mosula girişi — Mosul vilayətinin barışığa zidd işğalı", "ed5e8e33"], "d": ["Mudros barışığı imzalananda Mosul türk qüvvələrinin əlində idi. İngilislər barışığın 7-ci maddəsinə əsaslanaraq 8 (və ya 10) noyabr 1918-də şəhərə girdi və 15 noyabrda türk birlikləri vilayətdən çəkilməyə məcbur oldu. Mosul məsələsi Lozannada da həll olunmadı və 1926 Ankara müqaviləsinə qaldı.", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["Lozanna müqaviləsi — Patmos İtaliyaya tərk edildi, Egey adalarında Yunan suverenliyi təsdiq edildi", "185960b3"], "d": ["Lozannanın 15-ci maddəsi ilə Türkiyə, Batnoz (Patmos) daxil On İki Adaya (Dodecanese) aid bütün haq və titullarından İtaliya xeyrinə imtina etdi; adalar 1912-dən bəri faktiki italyan işğalı altında idi. 12-ci maddə isə Limni, Semadirək, Midilli, Sakız, Sisam və Nikariyanın Yunan suverenliyini təsdiq etdi. Bozbaba (Ay Strati) ilə Fornoz (Fourni) 1912-dən bəri Yunan əlində idi və Lozannadan sonra da Yunanıstanda qaldı; bu iki adın özü Lozannanın 12-ci maddəsində sayılmır.", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["Tunceli qanunu — Dərsim sancağı yerinə Tunceli vilayəti quruldu (mərkəz Kalan)", "1ae9ad50"], "d": ["2885 saylı qanunla Dərsim bölgəsində Tunceli adlı yeni vilayət qurulması qərara alındı; vilayətin inzibati mərkəzi Kalan yaşayış məntəqəsi oldu və yaşayış məntəqəsi sonradan Tunceli adını aldı. Bölgə Türkiyə Cümhuriyyəti daxilində qaldı; dəyişən şey inzibati statusu və adıdır.", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["Fasın müstəqilliyi: Fransız himayəsi sona çatdı, Salə və Rabat Fas krallığına qaldı", "a62a3fdb"], "d": ["2 mart 1956-da imzalanan müstəqillik müqaviləsi ilə 1912-dən bəri davam edən Fransız himayəsi sona çatdı; Salə və Rabat müstəqil Fas krallığının torpağı oldu. İspaniya Fasın müstəqilliyini 5 aprel 1956-da tanıdı.", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["Yeni Hebridlər müstəqil oldu: Vanuatu Respublikası quruldu", "cc93330f"], "d": ["Fransa ilə Birləşmiş Krallığın birgə suverenliyindəki Yeni Hebridlər kondominiumu 30 iyul 1980-də Vanuatu adı ilə müstəqil oldu. Efate adasındakı paytaxt Port Vila ilə Teouma yaşayış məntəqəsi kondominium idarəsindən Vanuatuya keçdi.", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["Cənubi Afrika Valvis körfəzini (Walvis Bay) Namibiyaya təhvil verdi", "96bb0184"], "d": ["Cənubi Afrika Respublikası 1 mart 1994-də Valvis körfəzi limanını və açıqdakı on iki adanı Namibiya hökumətinə təhvil verdi; səksən dörd illik Cənubi Afrika nəzarəti sona çatdı.", "fdd93117"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["II Konrad Alman kralı seçildi və Mainzda tac geydi — Salier sülaləsi başladı", "c88123e8"], "d": ["II Heinrichin ölümündən sonra Alman knyazları 4 sentyabr 1024-də Reynin sağ sahilindəki Kambada toplandı; seçimi Mainz baş yepiskopu Aribo idarə etdi. Yaşlı Konrad qardaşı oğlu gənc Konrada qarşı qalib gəldi və Məryəmin Doğuluşu bayramında (8 sentyabr) Mainzda Aribo tərəfindən kral olaraq tac geydirildi.", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["İmperator II Konrad Utrechtdə öldü", "f967406b"], "d": ["Salier sülaləsinin ilk imperatoru II Konrad 4 iyun 1039-da Utrechtdə qısa və ağrılı bir xəstəlikdən sonra öldü.", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["Worms konkordatı — İnvestitura çəkişməsi sona çatdı", "8073e4a0"], "d": ["Papalıq heyətinin vasitəçiliyi ilə imperator V Heinrich ilə papa II Calixtus arasındakı sülh 23 sentyabr 1122-də Wormsda (Lobwiesendə, şəhərin yanında) elan edildi. Heinrich üzük və əsa ilə investituradan vaz keçdi, yepiskop və baş rahiblərin kanonik seçimini qəbul etdi.", "a915c2e7"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["Zähringen nəslinin sönməsi ilə Bern azad imperiya şəhəri oldu", "1473c219"], "d": ["Zähringen sülaləsi 1218-də sönəndə Bern birbaşa imperiyaya bağlı azad şəhər oldu; 1353-də İsveçrə konfederasiyasına səkkizinci üzv olaraq girdi.", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["Hessen landqraflığı: Brabantlı I Heinrich ilk Hessen landqrafı oldu, Meißenlə sülh 1264", "57067f04"], "d": ["Hessenin müstəqil bir ölkə olaraq tarixi I Heinrich ('Uşaq') ilə başlayır; Meißenlə sülh 1264-də bağlandı. Heinrich Kasseldə qala tikdirdi və burası sonrakı illərdə adi iqamətgahı oldu; 1292-də imperiya knyazlığına (Reichsfürstenstand) alındı.", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["Schwerin qraflığı razılaşma ilə Mecklenburg hersoqu II Albrechtin əlinə keçdi", "013b6860"], "d": ["II Albrecht, 1 dekabr 1358 tarixli müqavilə ilə qraf Nicolausa 10.000 mark gümüş ödəyərək Schwerin qraflığını aldı; şəhər o tarixdən sonra Mecklenburg hersoqluğunun torpağı oldu (paytaxt olaraq yerləşməsi isə XVI əsrdə qalıcılaşdı).", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["Landqraf Philipp 'Səxavətli' Kasseldə öldü — Hessen dörd oğlu arasında bölündü", "c0cb27ed"], "d": ["Reformasiyanın siyasi öndərlərindən Hessen landqrafı I Philipp 31 mart 1567-də Kasseldə öldü. 1562 tarixli vəsiyyətinə görə ölkə Hessen-Kassel (Wilhelm IV), Hessen-Marburg (Ludwig IV), Hessen-Rheinfels (Philipp II) və Hessen-Darmstadt (Georg) olaraq dörd oğlu arasında bölüşdürüldü; birləşmiş Hessen landqraflığı beləliklə sona çatdı.", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["Sonuncu Pomeraniya hersoqu XIV Bogislaw Stettində öldü — Griffin sülaləsi sona çatdı", "ab96746a"], "d": ["Pomeraniyanın sonuncu hersoqu XIV Bogislaw 10 mart 1637-də Stettində öldü və onunla birlikdə yerli Pomeraniya sülaləsi sönmüşdür. Hersoqluğun faktiki bölüşdürülməsi (Brandenburq-İsveç) 1648 Vestfaliya sülhü ilə təsdiqləndi.", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["III Ferdinand Bremenə azad imperiya şəhəri imtiyazlarını verdi", "174142ee"], "d": ["İmperator III Ferdinand 1646-da Bremenə azad imperiya şəhəri imtiyazlarını tanıdı; İsveç buna qarşı çıxdı və 1666-da şəhəri silahla boyun əydirməyə çalışıb uğursuz oldu. Hannover seçicisi baş yepiskopluğu alınca (1720) Bremeni azad şəhər kimi tanıdı.", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["Bremen Fransa imperiyasına qatıldı — Weser mənsəbləri departamentinin mərkəzi oldu", "d5d149ae"], "d": ["Bremen 1806-da fransızlar tərəfindən ələ keçirilmiş, 1810-dan 1813-ə qədər Weser mənsəbləri (Bouches-du-Weser) departamentinin mərkəzi olmuşdur.", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["Napoleon Lübecki Fransa imperiyasına qatdı", "1ca78afe"], "d": ["Blücherin 1806-cı ilin noyabrında Lübeck yaxınlığında təslim olmasının ardınca şəhər fransızlar tərəfindən talan edilmiş, 1810-cu ilin dekabrında Napoleon şəhəri öz imperiyasına qatmışdır. Lübeck bu tarixədək 1226-dan bəri azad imperiya şəhəri idi.", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["Lübeck Fransa hakimiyyətinə qarşı üsyan edib azad şəhər statusunu geri aldı", "84e70d49"], "d": ["1813-də Fransa idarəsinə qarşı üsyan edən Lübeck, 1815-də Vyana konqresi tərəfindən Alman konfederasiyasının azad və Hansa şəhəri kimi tanınmışdır.", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["Fransa hakimiyyəti sona çatdı — Bremen azad şəhər statusunu geri aldı", "4afa71be"], "d": ["Bremenin Weser mənsəbləri departamenti mərkəzi olaraq Fransa idarəsində qalması 1813-də sona çatdı; şəhər 1815-də Vyana konqresi tərəfindən müstəqilliyinə qovuşdurulub Alman konfederasiyasına qatıldı.", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["Mecklenburg-Schwerin hersoqluğu böyük hersoqluq titulunu aldı", "3f5d05eb"], "d": ["Mecklenburg-Schwerin hersoqu Friedrich Franz I 1815-də böyük hersoqluq ('großherzogliche Würde') titulunu aldı; Mecklenburg hersoqluğu (1348-1815) künyəsi bu nöqtədə sona çatır, ölkə Alman konfederasiyası daxilində böyük hersoqluq olaraq davam edir.", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["Böyük Hamburq qanunu qüvvəyə mindi — Lübeckin müstəqil əyalət statusu sona çatdı", "6df2f92a"], "d": ["26 yanvar 1937-də qəbul edilən Böyük Hamburq qanunu 1 aprel 1937-də qüvvəyə mindi; Lübeck 700 ildən çox muxtariyyətini itirib Prussiyanın Schleswig-Holstein əyalətinə bağlandı, Hamburqun sərhədləri genişləndi.", "b96594d2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["Raetia və Noricum Romaya qatıldı: Tiberius və Drusus Alp aşırımını aldı", "be6f2a15"], "d": ["e.ə. 15-də Tiberius və Drusus Alp tayfalarını məğlub edib Raetianı (və Noricumun ilhaqını) tamamladı; Tunanın yuxarı sahili Roma sərhədi oldu.", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["Amyntasın ölümü ilə Galatiya Roma əyaləti oldu", "e4250ad7"], "d": ["Antoniusun təyin etdiyi qalat kralı Amyntas Kilikiyada öldürüləndə (e.ə. 25) Augustus Galatiyanı Roma əyalətinə çevirdi və Pisidiya, Lykaoniya ilə birləşdirdi. Paytaxt Ankyra (Ankara) oldu; Augustusun Res Gestae kitabəsi (Monumentum Ancyranum) burada yazıldı.", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["Octavianus \"Augustus\" titulunu aldı: Principat (imperiya) dövrü başladı", "310297b6"], "d": ["27-ci il 16 yanvarda Senat Octavianusa Augustus titulunu verdi; Octavianus əyalətlərin böyük hissəsinin komandanlığını (imperium) uzunmüddətli aldı. Bu tarix Roma imperiyasının başlanğıcı sayılır.", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["II Bocchus öldü; Mauretaniya Octavianusun nəzarətinə keçdi", "414fa36c"], "d": ["II Bocchus 33-də övladsız öldükdə Mauretaniya Octavianusun vəsiyyətlə təhvil almasıyla Roma idarəsinə girdi; bir müddət birbaşa Roma idarəsində qaldı və 25-də II Jubaya verildi.", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["Antonius Archelaosu Kappadokiya kralı etdi", "1e83e691"], "d": ["Antonius Şərqi yenidən təşkil edərkən Kappadokiya taxtını Archelaosa verdi; Archelaos b.e. 17-də Tiberius tərəfindən Romaya çağırılanadək idarə etdi. Kappadokiya b.e. 17-də Roma əyaləti oldu (bu hadisə xronologiyada ayrı maddədir).", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["Philippi: Octavianus və Antonius Brutus və Cassiusu məğlub etdi", "4386016f"], "d": ["42-ci ilin oktyabrında Philippi yaxınlığında iki ayrı döyüş keçirildi; Cassius və Brutus intihar etdi və respublikaçı güc aradan qalxdı. Triumvirlər Roma dünyasını aralarında bölüşdürdü.", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["Julius Caesar Korinfi Roma koloniyası kimi yenidən qurdurdu", "283a5daa"], "d": ["Caesara sui-qəsddən qısa müddət əvvəl Korinfdə Roma vətəndaşı koloniyaçılar (əksəriyyəti azadlıq almış) yerləşdirildi; şəhər Roma əyaləti Axaiyanın mühüm mərkəzlərindən biri oldu. Yenidən qurulma qərarı e.ə. 44 tarixlidir, yerləşdirmə e.ə. 44/43.", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["Burebista sui-qəsdə qurban getdi: Dak krallığı parçalandı", "9b9edb14"], "d": ["Strabon Burebistanın Caesarın ölümündən əvvəl daxili çevrilişlə öldürüldüyünü, krallığın isə beş, sonra dörd hissəyə bölündüyünü yazır. Dakiya birliyi Decebalusa (b.e. 87) qədər yenidən qurula bilmədi.", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["Caesar Mart İdasında (15 mart) Senatda öldürüldü", "18649074"], "d": ["Daimi diktator elan edilən Caesar 44-cü il 15 martda Pompeius Teatrında Senat iclasında bir qrup senator tərəfindən xəncərlə öldürüldü. Ölümü yeni vətəndaş müharibələrinin və Augustus hakimiyyətinin zəminini hazırladı.", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["Munda: Caesar Pompeiusun oğullarını məğlub etdi", "e1e93362"], "d": ["45-ci il 17 martda Mundada Caesar Gnaeus Pompeius və Sextus Pompeiusun ordusunu məğlub etdi; Hispaniya Caesarın əlində qaldı. Vətəndaş müharibəsinin son böyük döyüşüdür.", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["Thapsus: Caesar I Jubanı məğlub etdi; Şərqi Numidiya Africa Nova əyaləti oldu", "77b28c50"], "d": ["Caesar 46-cı ilin baharında Thapsusda Scipio və I Jubanın ordusunu darmadağın etdi; Juba intihar etdi. Numidiyanın şərq hissəsi Sallustiusun idarə etdiyi Africa Nova əyaləti oldu, qərb hissəsi Bocchus və Sittiusa verildi.", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["Zela: Caesar II Pharnakesi məğlub etdi (\"veni vidi vici\")", "11bf082a"], "d": ["Mithridatesin oğlu II Pharnakes vətəndaş müharibəsindən istifadə edib Pontusu geri almağa çalışdı; Caesar 47-də Zelada onu məğlub edərək Pontusu Roma nəzarətində yenidən təşkil etdi. Pharnakes Bosporosa qaçıb orada öldü.", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["Pharsalus: Caesar Pompeiusu məğlub etdi", "e821abe8"], "d": ["Caesar Dyrrhachiumdakı geri çəkilişdən sonra Pharsalusda Pompeiusun daha böyük ordusunu darmadağın etdi. Pompeius Misirə qaçıb öldürüldü; Şərq əyalətləri Caesara açıldı.", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["Alesia: Caesar Vercingetorixi mühasirəyə alıb məğlub etdi, Qalliyanın müqaviməti qırıldı", "d57cab9f"], "d": ["E.ə. 52-də Arverni Vercingetorixin rəhbərliyi ilə Qalliya üsyanı Caesarın Alesia mühasirəsi və mühasirə xətti müdafiəsi ilə yatırıldı; Vercingetorix təslim oldu. Qalliya növbəti il tamamilə Roma nəzarətinə girdi.", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["Caesarın Qalliya yürüşü başladı: Helvetii məğlub oldu", "1e594bb3"], "d": ["E.ə. 58-də Caesar Sisalp və Transalp Qalliyasının qubernatoru olaraq Helvetiinin köçünü Bibracte yaxınlığında dayandırdı; ardınca Ariovistusun germanlarını məğlub etdi. Yürüş səkkiz il davam edib Qalliyanı Romaya qatacaqdı.", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["VI Mithridates Pantikapaionda öldü; Bosporos Pharnakesə qaldı", "0831b871"], "d": ["Pompeiusdan qaçan Mithridates oğlu Pharnakesin üsyanı üzərinə Pantikapaion qalasında intihar etdi (63). Pharnakes Bosporosu Pompeiusa təslim etdi və Romanın dost kralı kimi tanındı.", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["Pompeius Bithyniya ilə Pontusun qərbini birləşdirib Bithynia et Pontus əyalətini qurdu", "b2865ea8"], "d": ["Pompeius Şərq nizamlaması zamanı (65-63) Bithyniyanı Pontusun qərb yarısı ilə birləşdirərək Bithynia et Pontus əyalətini yaratdı; şərqdəki Pontusun daxili bölgələri isə yerli şahzadələrə verildi.", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["Pompeius Kommageneni Romanın dostu və müttəfiqi kimi tanıdı", "a48ba55c"], "d": ["Pompeius Şərq nizamlamasında I Antiochosun krallığını və Seleukeia (Zeugma) bölgəsinin bir hissəsini təsdiq edərək Kommageneni Roma-Parfiya arasında müttəfiq bufer etdi. Krallıq b.e. 17-də və daimi olaraq b.e. 72-də Roma əyalətinə qatıldı (bu hadisələr xronologiyada ayrı maddələrdir).", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["Pompeius Mithridatesi məğlub etdi; Pontus Romaya bağlandı", "8f3f50a6"], "d": ["Pompeius 66-da Lykos düzənliyində Mithridatesin ordusunu gecə darmadağın etdi; Mithridates Kolxidadan Bosporosa qaçdı. Pontusun sahil şəhərləri Roma nəzarətinə girdi və 63-də Bithyniya ilə birləşdirilən əyalət yaradıldı.", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["I Antiochos Theos Kommagene taxtına çıxdı", "b1680d3f"], "d": ["Kommagene kralı I Antiochos Fars və Makedoniya nəslini birləşdirən Nemrut dağı məzar-məbədini tikdirdi. Krallıq Roma və Parfiya arasında bufer vəziyyətində idi.", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["Kirenaika Roma əyaləti edildi (Cyrenaica)", "f9993ffb"], "d": ["Ptolemaios Apionun krallığını Romaya vəsiyyət etməsindən (96) iyirmi il sonra Roma Cyrenaicanı əyalət nizamına saldı; 67-də Kritlə birləşdirildi.", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["IV Nikomedes krallığını Romaya vəsiyyət etdi", "e29d9fbc"], "d": ["IV Nikomedesin ölümü ilə (75/74) Bithyniya vəsiyyətlə Roma xalqına qaldı; VI Mithridates bunu qəbul etmədi və Üçüncü Mithridates müharibəsi başladı. Bithyniya Romanın birbaşa əyalətinə çevrildi.", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["Burebista Dak və Get tayfalarını birləşdirdi", "3648f92e"], "d": ["Strabona görə Burebista getləri və daklari tək krallıqda topladı, Tunanın cənubunda Frakiya və İlliriya sərhədlərinə qədər yürüşlər etdi. Krallıq Tuna boyunca Roma üçün təhlükə olmağa başladı.", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["Dardanos sülhü: Mithridates Asiya və Bithyniyadan çəkildi", "535818ed"], "d": ["Sulla ilə bağlanan Dardanos sülhündə Mithridates bütün fəthlərini (Asiya, Bithyniya, Kappadokiya, Paflaqoniya) boşaltmağı, 70 gəmi və 2000-3000 talant verməyi qəbul etdi. Lakin Romada Sullanın düşmənlərinin hakim olması İkinci Mithridates müharibəsinə yol açdı.", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["Mithridates Asiya əyalətini işğal etdi; Efes Vespers (80.000 romalının qırğını)", "3986833b"], "d": ["Birinci Mithridates müharibəsinin əvvəlində (89/88) Mithridates Bithyniya və Asiya əyalətini işğal etdi, Efesdə verdiyi əmrlə Roma vətəndaşları kütləvi şəkildə öldürüldü. Afina da Pontus tərəfinə keçdi (Aristion).", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia: Roma italyan müttəfiqlərə vətəndaşlıq verdi (Sosial müharibə)", "f72ba27d"], "d": ["Romanın italyan müttəfiqlərinin üsyanı (91-88) üzərinə Lex Iulia (90) və Lex Plautia Papiria (89) sadiq qalan və təslim olan müttəfiqlərə Roma vətəndaşlığı tanıdı. Beləliklə, Poya qədər İtaliya yarımadası vahid vətəndaş cəmiyyəti oldu.", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["Sulla Ariobarzanesi Kappadokiya taxtına oturtdu", "8bdd078c"], "d": ["VI Mithridatesin Kappadokiyanı uşaq kral vasitəsilə əlində saxlamasına qarşı Roma Sullanın Kilikiya qubernatorluğu zamanı Ariobarzanesi kral elan etdirdi. Kappadokiya sonrakı əsrdə Roma-Fars-Pontus çəkişmələrinin buferi oldu.", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["Ptolemaios Apion Kirenanı Romaya vəsiyyət etdi", "5edef477"], "d": ["Kirenanı idarə edən Ptolemaios Apion övladsız ölərkən krallığını Roma xalqına qoydu (96); Senat şəhərləri azad buraxdı, Roma əyalətə çevirmə işini 74-ə qədər gecikdirdi.", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["Bocchus Jugurthanı Romaya təhvil verdi; Numidiyanın qərbi Mauretaniyaya qatıldı", "7619ad15"], "d": ["Jugurthanın qayınatası Mauretaniya kralı I Bocchus Sullaya Jugurthanı təhvil verərək Romayla barışdı; müqabilində Numidiyanın qərb hissəsi ona buraxıldı. Jugurtha 104-də Romada həbsdə öldü.", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["V Pairisades krallığı VI Mithridatesə verdi: Bosporos Pontusa bağlandı", "835bbe74"], "d": ["İskit təzyiqi altındakı V Pairisades Mithridatesin komandanı Diophantosun köməyi ilə krallığı Mithridatesə devr etdi; Bosporos beləliklə Pontusun şimal uzantısı oldu. Qara dəniz taxıl ticarəti Mithridatesin mənbəyi olaraq bu tarixdə Pontusa keçdi.", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["Mithridatesin komandanı Diophantos Krımda İskitləri məğlub etdi", "d8d48c68"], "d": ["Diophantos İskit kralı Skilourosun oğlu Palakosun ordusunu məğlub etdi və Taurikada Neapolis ətrafını aldı; Bosporos ilə Xersonesos Pontusa bağlandı.", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["Jugurtha Cirtanı aldı: Roma Numidiya işlərinə müdaxilə etdi", "660eb34a"], "d": ["Jugurtha e.ə. 112-də Cirtanı mühasirəyə alıb Adherbalı öldürdü; şəhərdə öldürülən italyan tacirlər Romanı Jugurthaya müharibə elan etməyə sövq etdi. Müharibə 105-ə qədər davam etdi.", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["Narbo Martius quruldu: Cənubi Qalliya (Gallia Transalpina) Roma əyaləti oldu", "20c4bdfa"], "d": ["Massaliyanın kömək çağırışı ilə (125) Qalliyaya girən Roma Aquae Sextiae (122) və Allobroges qələbələri ilə Rhône vadisini aldı; e.ə. 118-də Narbo Martius ilk Roma koloniyası olaraq Qalliyada quruldu. Bölgə Gallia Transalpina əyaləti oldu.", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["VI Mithridates Eupator Pontus taxtına çıxdı", "c2d5fd41"], "d": ["V Mithridatesin ölümü ilə (120/119) uşaq yaşında taxta çıxan VI Mithridates bir neçə il himayədən sonra Pontusu Qara dəniz ətrafında Romaya rəqib gücə çıxardı.", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["Massaliyanın çağırışı ilə Roma Qalliyaya girdi", "eaf7eb0a"], "d": ["Salluvii və liqurların təzyiqi altındakı Massaliya Romadan kömək istəyəndə Roma 125-də Cənubi Qalliyaya ordu göndərdi. Bu müdaxilə Narbo Martiusun qurulmasına (118) və Gallia Transalpinanın alınmasına yol açdı.", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["Aristonikos məğlub oldu; Bergama torpaqlarından Asiya əyaləti quruldu", "7ccdc59e"], "d": ["III Eumenes adı ilə taxt iddia edən Aristonikos Roma ordusu tərəfindən məğlub edilib tutuldu (129); Manius Aquillius nizamlaması ilə keçmiş Bergama krallığı Asiya əyaləti oldu. Əyalətin vergi sistemi (publicani) Roma üçün böyük gəlir mənbəyi idi.", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["Numantia süqut etdi: Keltiberiya Romaya qatıldı", "ced07244"], "d": ["Scipio Aemilianus səkkiz aylıq mühasirədən sonra Numantianı aclıqla təslim aldı (133); şəhər dağıdıldı. Keltiber müharibələri sona çatdı və Hispania Citeriorun daxili bölgəsi Romaya qatıldı.", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["Axaiya müharibəsi: Axaiya Birliyi Romaya məğlub oldu, birliklər dağıdıldı", "e434cfe0"], "d": ["Sparta ilə sərhəd mübahisəsi üzündən Romaya qarşı qalxan Axaiya Birliyi 146-da Leukopetrada məğlub oldu; Korinf dağıdıldı və Birlik faktiki olaraq ləğv edildi, Yunanıstanın bir hissəsi Makedoniya əyalətinin nəzarətinə girdi.", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["Üçüncü Pun müharibəsi sona çatdı: Karfagen dağıdıldı, Africa əyaləti quruldu", "522515b4"], "d": ["Üç illik mühasirədən sonra P. Cornelius Scipio Aemilianus 146-cı ilin yazında Karfageni aldı; şəhər yandırılıb dağıdıldı, torpaqlar Romaya qatıldı. Karfagenin hinterlandı Africa əyaləti oldu; Masinissanın Numidiyası qərbdə qonşu qaldı.", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["Makedoniya Roma əyaləti oldu", "dc6d2352"], "d": ["Andriskos üsyanının (148) yatırılmasından sonra Makedoniyanın dörd bölgəsi tək Roma əyaləti olaraq birləşdirildi (146); əyalətin cənubunda Yunanıstanın nəzarəti də Makedoniya qubernatorunun nəzarətinə buraxıldı. Via Egnatia sonrakı illərdə Adriatikdən Salonikə qədər tikildi.", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["Andriskos üsyanı: Makedoniya krallığı qısa müddət yenidən quruldu, Metellus tərəfindən yatırıldı", "0119ff73"], "d": ["Perseusun oğlu olduğunu iddia edən Andriskos 150/149-da Makedoniyanı yenidən birləşdirdi, ilk Roma qüvvələrini məğlub etdi; 148-də Metellus Makedoniyanı geri aldı. Üsyan Makedoniyanın birbaşa Roma idarəsinə bağlanmasının səbəbi oldu.", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["Roma Karfagenə müharibə elan etdi: Üçüncü Pun müharibəsi başladı", "2e34c235"], "d": ["Masinissanın hücumlarına qarşı Karfagenin özünü müdafiə etməsi müqavilənin pozulması sayıldı; Roma 149-da müharibə elan edib Utikanı özünə bağladı. Karfagen şəhəri üç il boyunca mühasirə altında müqavimət göstərdi.", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["Masinissa Karfagen torpaqlarına hücum etdi: Numidiya-Karfagen müharibəsi", "b47559a5"], "d": ["Masinissanın Karfagen torpaqlarını ələ keçirməsi (151/150) üzərinə Karfagen müharibə elan etdi və Masinissaya məğlub oldu; Roma bunu müqavilənin pozulması sayıb 149-da müharibə elan etdi. Masinissa 148-də doxsan yaşında öldü.", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["Roma Rodosa Likiya və Kariyadakı valilərini geri çəkməyi əmr etdi; Likiya İttifaqı (Patara) Rodos hakimiyyətindən çıxdı", "6bbe2b54"], "d": ["III Makedoniya müharibəsindən sonra Roma Senatı Rodosa Likiya və Kariyadakı valilərini müəyyən bir günədək geri çəkməyi əmr etdi; Rodos bu itkiləri müharibə təhlükəsindən daha yüngül sayıb qəbul etdi. Likiya İttifaqı (mərkəzi Patara) beləliklə Rodos hakimiyyətindən çıxdı və Roma himayəsində Likiya İttifaqı kimi davam etdi.", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["Epir Roma tərəfindən talan edildi: yetmiş şəhər dağıdıldı", "456fb461"], "d": ["III Makedoniya müharibəsindən sonra Epirin Perseyə yaxın qalan Molossis şəhərləri Aemilius Paullusun əmri ilə talan edildi, təxminən 150.000 nəfər kölə edildi. Epir sonrakı əsrdə Roma hakimiyyəti altında yoxsul qaldı.", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["Makedoniya Roma tərəfindən dörd muxtar bölgəyə (meris) bölündü", "7a795ba0"], "d": ["Senatın qərarı ilə (e.ə. 167) Makedoniya krallığı Amphipolis, Thessalonike (Səlanik), Pella və Pelagonia mərkəzli dörd bölgəyə bölündü; bölgələr arasında evlilik və mülk əldə etmək qadağan edildi, mədən istismarı məhdudlaşdırıldı.", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["Roma Likiya və Kariyanı Rodosdan aldı; Delos azad liman elan edildi", "09c8143f"], "d": ["Üçüncü Makedoniya müharibəsində Rodosun Roma ilə Perseus arasında vasitəçilik cəhdi cəzalandırıldı: Senat Likiya və Kariyanı Rodosdan alıb azad elan etdi, Delosu Afinaya verib gömrüksüz limana çevirdi. Rodosun ticarət gəliri ağır düşdü.", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["Pydna: Aemilius Paullus Perseusu məğlub etdi; Antiqonid krallığı sona çatdı", "a59c5270"], "d": ["168-ci il iyunun 22-də Pydnada Roma legionları Makedon falanqasını məğlub edərək III Makedoniya müharibəsini bitirdi; Perseus Samothrakedə təslim oldu və Romada qələbə mərasiminə aparıldı. Antiqonid sülaləsi sona çatdı.", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["Apameia sülhü: II Eumenes Bergamaya Frakiya Xersonesini, Frigiya, Lidiya və Mysiyanın böyük hissəsini qazandı", "f25ed9af"], "d": ["Magnesiadakı məğlubiyyətdən sonra III Antiox 188-də Roma ilə sülh imzaladı: Toros dağlarının şimalını tərk etdi. Bu torpaqların çoxu müttəfiq II Eumenesin Bergamasına verildi (Frakiya Xersonesi, Böyük Frigiya, Lidiya, Mysiya, İoniyanın bir hissəsi).", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["Apameia sülhü: Rodos Likiya və Kariyanın cənubunu aldı", "aa5173c6"], "d": ["Magnesiadan sonra Roma müttəfiq Rodosa Likiyanı və Kariyanın Meander çayının cənubundakı hissəsini verdi. Rodos bu torpaqları 167-də itirdi.", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["Manlius Vulso Qalat tayfalarını məğlub etdi: Qalatların müstəqilliyi Romanın nəzarətinə keçdi", "30ae73d7"], "d": ["Magnesiadan sonra Cn. Manlius Vulso Qalat ölkəsinə soxularaq Olympos və Magabada Tolistoagii və Tektosagesi darmadağın etdi; müqavilə ilə Qalatlar qonşulara hücum etməməyi qəbul etdi. Qalatiya böyük ölçüdə müstəqil qaldı, lakin Roma-Bergama tarazlığına bağlandı.", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["Aitoliya Roma ilə sülh bağladı: Ambrakia və Oiniadaini itirdi, Romanın hökmranlığını tanıdı", "f332c6bf"], "d": ["Antiox müharibəsində Antioxun yanında yer alan Aitoliya, Fulvius Nobiliorun Ambrakia mühasirəsindən sonra Roma ilə sülh bağladı; Romanın \"əzəmətini\" tanıdı, təzminat ödədi və Ambrakia ilə Oiniadai kimi şəhərləri tərk etdi.", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["Magnesia ad Sipylum: Roma və Bergama III Antioxu məğlub etdi", "f650ef21"], "d": ["190/189-cu illərin qışında Magnesiada L. Scipio və II Eumenes III Antioxun ordusunu darmadağın etdi. Qələbədən sonra bağlanan Apameia sülhü (188) Antioxun Torosun şimalını tərk etməsinə səbəb oldu.", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["Sparta Axaia İttifaqına qatıldı: Philopoimen Nabisdən sonra Lakoniyanı ittifaqa bağladı", "2629b6e1"], "d": ["Spartalı tiran Nabisin öldürülməsindən (192) sonra Axaia strategosu Philopoimen Spartanı zorla Axaia İttifaqına qatdı. Sparta müstəqilliyini 188-də divarlarının yıxılması ilə tamamilə itirdi.", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["Flamininus İsthm oyunlarında yunanların azadlığını elan etdi", "3d850bf2"], "d": ["Kynoskephalaidən sonra Roma komandanı T. Quinctius Flamininus e.ə. 196-cı il İsthm oyunlarında Korinf, Xalkis və Demetriasdakı Makedon qarnizonlarının geri çəkiləcəyini və Yunan şəhərlərinin \"azad, vergisiz və öz qanunlarına tabe\" olduğunu elan etdi. Roma beləliklə Yunanıstana hakim kimi yerləşdi.", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["Kynoskephalai: Roma V Filippi məğlub etdi; Makedoniya Yunanıstandan çəkilməyə məcbur oldu", "9cb44ca6"], "d": ["197-ci ilin iyununda Flamininusun Roma legionları Kynoskephalaidə Makedon falanqasını darmadağın etdi. 196-cı il sülhündə Filipp Yunanıstandakı bütün mövqelərini (Demetrias, Xalkis, Korinf) tərk etdi, donanmasını təslim edib 1000 talant ödədi.", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["Hispaniyada iki Roma əyaləti yaradıldı: Citerior və Ulterior", "1baa8383"], "d": ["Hispaniyanın Karfagendən alınan torpaqları 197-də ilk dəfə ayrı iki əyalətə bölündü və hər biri bir pretor tərəfindən idarə olundu. Bu tarixdən sonra yarımadadakı Keltiber və Lusitan müharibələri Roma əyalət quruluşunu genişləndirmək üçün aparıldı.", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["Zamadan sonrakı sülh: Karfagen Hispaniyanı və Aralıq dənizi adalarını, donanmasını itirdi, 10.000 talant təzminat öhdəsinə götürdü", "8654422d"], "d": ["Zamadan (202) sonra Roma Karfageni Afrikadakı öz torpaqlarına sıxışdırdı: Hispaniyanı və Aralıq dənizi adalarını tərk etmə, donanmanı (10 gəmi istisna olmaqla) təslim etmə, 50 il ərzində 10.000 talant ödəmə və Romanın icazəsi olmadan müharibə açmama şərtləri qəbul edildi. Masinissanın Numidiyası müstəqil qonşu oldu.", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["Roma Masinissanı Syphaxın krallığı ilə mükafatlandırdı", "54ba7a64"], "d": ["Zama sülhündə Roma Masinissanı Syphaxın krallığına və Karfagendən alınan sərhəd torpaqlarına təyin etdi; Masinissanın \"Emporia\" bölgəsinə və Karfagen sərhədinə yönəlik tələbləri sonra müharibənin səbəbi oldu.", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["Zama: Scipio və Masinissa Hannibalı məğlub etdi", "52e188e6"], "d": ["Hannibalın Afrikaya çağırılmasından sonra baş verən Zama döyüşündə Scipionun legionları və Masinissanın Numidiya süvariləri Karfagen ordusunu məğlub etdi. İkinci Pun müharibəsi bu döyüşlə qəti şəkildə Roma xeyrinə bitdi.", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["Syphax məğlub edilib əsir alındı; Masinissa Numidiyanı birləşdirdi", "a42a3cb0"], "d": ["Scipio və Masinissa 203-də Syphaxın ordusunu məğlub edib Syphaxı əsir aldı; Masinissa Cirtanı və Syphaxın krallığını Romanın dəstəyi ilə ələ keçirdi. Numidiya şərq və qərb hissələrinin birləşməsi ilə güclü krallığa çevrildi.", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["Ilipa və Gades: Hispaniya Karfagendən Romaya keçdi", "31e5a50c"], "d": ["Scipio 206-da Ilipada Hasdrubal Gisgo və Maqonun ordusunu məğlub edib Hispaniyadakı Karfagen nəzarətinə son qoydu; Gades də qısa müddət sonra Romaya keçdi. Karfagen Hispaniya gümüş mədənlərini və əsgər ehtiyatını itirdi.", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["Fabius Maximus Tarenti Hannibaldan geri aldı", "bd605091"], "d": ["212-də Hannibala təslim olan Tarent 209-da xəyanət nəticəsində Q. Fabius Maximusa keçdi. Şəhərin süqutu ilə Hannibal Cənubi İtaliyadakı ən dəyərli limanını itirdi.", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["Capua Romaya düşdü: Hannibalın Kampaniya bazası itirildi", "cfcb9c9a"], "d": ["Cannaedən sonra Hannibala keçən Capuanı iki il mühasirədə saxlayan Roma, Hannibalın Romaya yürüş cəhdinə baxmayaraq şəhəri aldı və ağır cəzalandırdı; Capuanın muxtariyyəti ləğv edildi. Hannibal Cənubi İtaliyada müdafiəyə çəkildi.", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["Cannae: Hannibal Roma ordusunu mühasirəyə alıb məhv etdi; Cənubi İtaliya Karfagenin tərəfinə keçməyə başladı", "94f5110a"], "d": ["216-da Apuliyadakı Cannaedə Hannibalın mühasirə quruluşu təxminən yetmiş min nəfərlik Roma ordusunu məhv etdi. Capua, Tarent və Cənubi İtaliyanın bir çox şəhəri Karfagen tərəfinə keçdi.", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["Roma ordusu Hispaniyaya çıxdı: Emporionda ilk Roma bazası", "8cb47853"], "d": ["Hannibalın İtaliyaya yürüşündən sonra Cn. Cornelius Scipio e.ə. 218-də Emporiona çıxaraq Ebro boyunda Romanın Hispaniyadakı mövcudluğunu başlatdı; yarımada İkinci Pun müharibəsinin ikinci cəbhəsi oldu.", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["Hannibal Alp dağlarını aşıb İtaliyaya daxil oldu", "a1d3bf5a"], "d": ["Hannibal Ebronu, Pireneyləri və Rhône çayını keçib payızda Alp dağlarını aşdı və Şimali İtaliyaya endi; Ticinus və Trebiada Roma ordularını məğlub etdi. Karfagenin İtaliya müharibəsinin mərkəzi beləliklə Romanın içinə daşındı.", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["Hannibal Saguntumu aldı: İkinci Pun müharibəsinin fitili alovlandı", "a497a334"], "d": ["Hannibal səkkiz aylıq mühasirədən sonra Romanın müttəfiqi Saguntumu aldı (e.ə. 219); Roma elçi göndərib Hannibalın təslim edilməsini istədi və rədd edilincə müharibə elan edildi. Müharibə İtaliyada, Hispaniyada və Afrikada on yeddi il davam etdi.", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["Sellasia: Antigonos Doson Kleomenesi məğlub etdi, Sparta ilk dəfə xarici işğala məruz qaldı", "dc64a8db"], "d": ["222-ci ilin yayında Sellasiada Makedon-Axaia ittifaqı Kleomenesin Spartalı ordusunu məğlub etdi; Kleomenes Misirə qaçdı. Doson Spartaya girdi, onu Likurq quruluşuna qaytardı; Spartalılar tarixlərində ilk dəfə xarici ordunun işğalını yaşadılar.", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["Mediolanum (Milan) Romaya düşdü: İnsubreslər məğlub oldu, Şimali İtaliya Romaya açıldı", "d3ec639f"], "d": ["Telamonda (225) Qalliyalıları məğlub edən Roma, e.ə. 222-də Clastidiumda Marcellusun qələbəsi və Mediolanumun alınması ilə Po ovasının böyük hissəsini nəzarətə aldı. Bölgə Cisalpina Qalliyası kimi təşkil olundu.", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["Axaia İttifaqı Akrokorinthi Antigonos Dosona verdi: Korinf Makedoniyaya qayıtdı", "c8ec9d0c"], "d": ["III Kleomenesin təzyiqi altında olan Axaia İttifaqı, Aratos vasitəsilə Makedoniyadan kömək istəyərək Akrokorinthi və Korinfi Antigonos Dosona təslim etdi; Doson Hellen İttifaqını (Hellenikos symmachia) qurdu.", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["Ebro müqaviləsi: Karfagen Ebronun şimalına keçməməyi qəbul etdi", "a199de0b"], "d": ["Hamilkarın başlatdığı Hispaniya fəthini davam etdirən Hasdrubal Roma ilə Ebro müqaviləsini bağladı: Karfagen silahlı şəkildə Ebronu keçməyəcəkdi. Hannibalın 219-da Saguntuma hücum etməsi bu müqavilənin təfsirinə əsaslandırıldı.", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["Roma Sardiniya və Korsikanı Karfagendən aldı", "4f7295ee"], "d": ["Karfagenin Sardiniyadakı üsyançı muzdlu əsgərləri Romadan kömək istəyincə Roma adanı işğal etdi; Karfagen müharibə təhlükəsi üzərinə adaları tərk edib əlavə 1200 talant ödəməyə məcbur qaldı. Roma ikinci əyaləti (Sardinia et Corsica) yaratdı.", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["Aegates adaları: Karfagen donanması məhv edildi; Siciliya ilk Roma əyaləti oldu", "8bd16e8f"], "d": ["Lutatius Catulus 241-ci ilin martında Aegates qarşısında Hannonun Karfagen donanmasını darmadağın etdi; ardınca Lutatius sülhü ilə Karfagen Siciliyanı boşaltdı və 3200 talant müharibə təzminatı ödəməyi qəbul etdi. Siciliya (Hieronun Sirakuzası istisna olmaqla) Romanın ilk əyaləti oldu.", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["Aratos Akrokorinthə basqın etdi: Korinf Makedoniyadan Axaia İttifaqına keçdi", "a88dfda6"], "d": ["Sikyonlu Aratos gecə basqını ilə Antigonos Gonatasın Akrokorinth qarnizonunu zərərsizləşdirdi və Korinfi Axaia İttifaqına qatdı; Megara, Troizen və Epidauros da ittifaqa keçdi. Makedoniya Peloponnesosda açar qalasını itirdi.", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["Aratos Sikyonu Axaia İttifaqına qatdı", "6f413f9c"], "d": ["Gənc Aratos Sikyon tiranını devirib şəhəri Axaia İttifaqına bağladı; bu addım ittifaqı Korinf körfəzinin şimal və cənub sahillərinə yaydı və Aratosu strateqos seçilməyə apardı.", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["II Hieron Roma ilə ittifaq bağladı: Şərqi Siciliya Romanın müttəfiqi oldu", "5e95a134"], "d": ["Hieron Birinci Pun müharibəsinin əvvəllərində Messana məsələsi üzündən Romaya qarşı Karfagenlə ittifaq bağlamışdı; 263-də Roma ilə sülh və ittifaq qurdu və ömrü boyunca (215-ə qədər) Romanın sadiq müttəfiqi qaldı. Sirakuza Roma Siciliyasının əyalətdən kənarda qalan müttəfiq dövləti oldu.", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["I Nikomedes Nikomedeianı (İzmit) qurdu", "a89ed42a"], "d": ["Nikomedes Astakosun dağıdılmasından sonra körfəzin şərq ucunda Nikomedeianı qurdu; şəhər sonrakı əsrlərdə Bithyniyanın və Diokletian dövründə Roma şərq paytaxtının mərkəzi oldu.", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["Birinci Pun müharibəsi başladı: Appius Claudius Messanaya keçdi", "636e1533"], "d": ["Mamertinlərin Messanası Sirakuza kralı Hierona qarşı Karfagendən sonra Romadan da kömək istəyincə Roma konsulu Appius Claudius Caudex 264-də Siciliyaya keçib Messananı Karfagen qarnizonundan aldı. Beləliklə Roma ilk dəfə İtaliyadan kənarda müharibəyə girdi.", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["Volsinii süquta uğradı: Etruriyanın son müstəqil böyük şəhəri Romaya keçdi", "b6aed092"], "d": ["Kölə üsyanı üzündən Romanın köməyinə müraciət edən Volsiniini Roma 264-də ələ keçirdi, şəhərin sakinlərini yeni bir yerə köçürdü. Etruriya bundan sonra faktiki olaraq Roma hakimiyyətinə girdi.", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["Pyrrhos Argosda öldü", "2b4996fa"], "d": ["Peloponnesos yürüşündə Argos küçə döyüşündə Pyrrhos bir kirəmitlə yaralanıb öldü (272). Epir Makedoniyaya qarşı çəkisini itirdi və Roma ilə münasibətləri yenidən qurdu.", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["Tarent Romaya təslim oldu: Cənubi İtaliya Romaya qatıldı", "6e87c924"], "d": ["Pyrrhosun ayrılışından sonra Tarentin Epir qarnizonu geri çəkildi və şəhər Romaya təslim oldu (272). Bruttium və Lucania ilə birlikdə Cənubi İtaliya Yunan şəhərləri Romanın müttəfiqi oldu; beləliklə Roma Po ovasına qədər İtaliya yarımadasının hakimi oldu.", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["Maleventum (Beneventum): Pyrrhos İtaliyadan çəkildi", "ab67e9f5"], "d": ["Pyrrhosun Siciliya yürüşündən qayıdıb Romaya yenidən hücum etməsi Maleventumda Manius Curius Dentatusun qarşısında uğursuzluğa düçar oldu; Pyrrhos 275-də Epirə qayıtdı. Tarentdə kiçik bir qarnizon qoydu; Roma İtaliyada rəqibsiz qaldı.", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["I Antiox \"Fil döyüşü\"ndə Qalatları məğlub etdi", "1e88c2d0"], "d": ["I Antiox Qalatları filləri ilə məğlub edərək Soter (\"xilaskar\") ləqəbini aldı; Qalatlar Mərkəzi Anadoluda yerləşik xərac və basqın quruluşuna qayıtdı. Sonrakı əsrlərdə Pergamon və Bithyniya ilə toqquşmalar davam etdi.", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["Antigonos Gonatas Makedoniya kralı oldu: Antiqonid sülaləsi qalıcılaşdı", "4b907dd6"], "d": ["Gonatas 277-də Lysimakheiada Qalatları məğlub edərək şöhrət qazandı və 276-da Makedoniya taxtına yerləşdi. Sülalə 168-ə qədər Makedoniyanı idarə etdi; Yunanıstanda Korinf, Xalkis və Pire qalalarını əlində saxladı.", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["I Nikomedes Qalatları Anadoluya keçirdi", "9e5ab10b"], "d": ["Bithyniya kralı I Nikomedes qardaşı Zipoitesə və Selevk təzyiqinə qarşı Qalat (Kelt) tayfalarını Bosfordan keçirib xidmətinə aldı; Qalatlar sonradan Mərkəzi Anadoluya yerləşdi; Tektosages qolu Ankaranı (Ankyra) paytaxt etdi (TDV «Ankara»: «milattan önce 278-189 yılları arasında Trakya’dan gelen Galatlar’ın Tektosages kolunun başşehri oldu»). Keçid tarixi 278/277.", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["Aitoliya İttifaqı Qalat basqınına qarşı Delfi müdafiə etdi", "5488966a"], "d": ["Brennosun Qalat ordusu Thermopylaini aşıb Delfiyə doğru irəlilədi; Aitoliyalıların və Fokislilərin müqaviməti basqını dağıtdı. Aitoliyanın Delfi Amfiktioniyasındakı çəkisi bu qələbə ilə artdı.", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["Pyrrhos Tarentin köməyinə İtaliyaya keçdi; Herakleiada romalıları məğlub etdi", "55f18e85"], "d": ["Tarentin Romaya qarşı çağırışı ilə 280-də İtaliyaya çıxan Pyrrhos Herakleiada Valerius Laevinusun ordusunu fil və süvari ilə məğlub etdi, lakin ağır itki verdi. 279-da Asculumda yenidən qalib gəldi, 278-276-da Siciliyaya keçdi.", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["Axaia İttifaqı yenidən quruldu: Patrai, Dyme, Tritaia, Pharai", "81bba071"], "d": ["Antiqonidlərin nəzarətindəki Axaiada dörd şəhər (Dyme, Patrai, Tritaia, Pharai) e.ə. 280-də federal ittifaqı yenidən qurdu; sonrakı illərdə Aigion və digər şəhərlər qatıldı. İttifaq Aratosun rəhbərliyi altında Peloponnesosun böyük gücünə çevrildi.", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["Philetairos Korupedion döyüşündən sonra Selevkə keçdi; Bergama faktiki müstəqil sülalə qurdu", "ac6b3e31"], "d": ["Lysimaxın süqutundan sonra Philetairos xəzinə ilə birlikdə Selevkə bağlandı və Pergamonu qoruyub zənginləşdirdi; Selevkin ölümü ilə (281) faktiki müstəqilləşdi. Livius Attalid sülaləsinin Pergamonu 283-dən 129-a qədər idarə etdiyini verir.", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["Lysimax Pyrrhosu Makedoniyadan çıxardı və Makedoniyanın yeganə kralı oldu", "a83e6c64"], "d": ["Demetriosun Selevkə təslim olduğu 285-ci ilin qışından sonra Lysimax Pyrrhosu Makedoniyadan qovub ölkəni təkbaşına idarə etdi. Dövləti Frakiya, Makedoniya və Qərbi Anadolunu əhatə edən geniş bölgəyə çatdı.", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["Pyrrhos və Lysimax Makedoniyanı böldü; Demetrios Poliorketes devrildi", "63371ab8"], "d": ["287-ci ilin yayında Demetriosun Asiyaya keçməsi üzərinə Pyrrhos və Lysimax Makedoniyanı birgə iki bölgəyə ayırdı; Demetrios yıxıldı. Bu bölüşdürmə yalnız iki il davam etdi.", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["Samnium Romaya qatıldı: Üçüncü Samnit müharibəsi sona çatdı", "bede9942"], "d": ["Manius Curius Dentatus Samnitləri və Sabinləri qəti məğlubiyyətə uğratdı; Samnium Romanın müttəfiqi oldu. Roma Mərkəzi İtaliyanın hakimi oldu və Cənubi İtaliya Yunan şəhərləri (Tarent) ilə üz-üzə gəldi.", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["Demetrios Poliorketes Makedoniya kralı elan edildi", "a2b1eba3"], "d": ["Kassandros sülaləsindəki taxt çəkişməsindən istifadə edən Demetrios 294-cü ilin payızında ordu tərəfindən Makedoniya kralı elan edildi. Antigonos nəslinin Makedoniyadakı ilk hökmranlığıdır; 288-də çökdü, Gonatas 276-da onu qalıcı etdi.", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["Sentinum: Etrusklar, Umbriyalılar, Samnitlər və Qalliyalıların ittifaqı Romaya məğlub oldu", "b5affc1b"], "d": ["Üçüncü Samnit müharibəsində Sentinumdakı bu döyüş İtaliyadakı Roma əleyhdarı son böyük ittifaqı məhv etdi; Etrusk şəhərləri bir-bir Romanın müttəfiqliyinə məcbur edildi.", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["Pyrrhos Ptolemaiosun dəstəyi ilə Epir taxtına qayıtdı", "6288bf69"], "d": ["Ipsosdan sonra Misirdə girov qalan Pyrrhos, Ptolemaiosun köməyi ilə Epirə qayıdıb taxtı geri aldı. Epir bundan sonra Makedoniya və İtaliya məsələlərində söz sahibi oldu.", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["Lysimax xəzinəsini Bergamada yerləşdirdi; Philetairos qalanın qoruyucusu oldu", "e1b4ab77"], "d": ["Ipsosdan sonra Lysimax xəzinəsini təpədəki Pergamon qalasında saxlatdı və mühafizəni xədim Philetairosa verdi. Philetairos 281-də Selevkə keçib sülalənin təməlini qoydu.", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["I Mithridates Ktistes Pont sülaləsini qurdu", "490c338c"], "d": ["Antigonos Monophthalmosa yaxınlaşan Mithridates 302-də öldürülmək təhlükəsindən qaçıb Kappadokiya Pontosundakı dağlıq bölgədə Kimiataya sığındı, burada Pont krallığının nüvəsini yaratdı. Sülalə 63-ə qədər davam etdi.", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["Demetrios Poliorketesin Rodos mühasirəsi uğursuzluqla bitdi", "dae6f4d6"], "d": ["Antigonosa qarşı Ptolemaiosun yanında qalan Rodosu Demetrios 305-də nəhəng mühasirə maşınları ilə mühasirəyə aldı; Rodoslular bir il müqavimət göstərdi və 304-cü ilin yayında sülh əldə edildi. Şəhərdə Günəş tanrısı Heliosun Kolossosu bu qələbənin pulu ilə ucaldıldı.", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["Kipr Salamisdə Demetrios Ptolemaiosu məğlub etdi; Antigonos və Demetrios kral titulunu aldı", "cc308941"], "d": ["306-cı ilin yazında Demetrios Poliorketes Kipr qarşısında Ptolemaiosun donanmasını məğlub etdi və Kipri Antigonosun əlinə keçirdi; yay aylarında Antigonos və Demetrios kral titulunu aldı, digər Diadoxlar da qısa müddətdə eyni titulu üzərinə götürdü. Ptolemaios Kipri 294-də geri aldı.", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["Lysimax Lysimakheianı qurdu: Frakiya Xersonesində paytaxt", "83b83160"], "d": ["Lysimax Gelibolu yarımadasının boynunda qurduğu Lysimakheianı Frakiya krallığının paytaxtı etdi; Boğaz və Çanaqqala keçidi onun əlində cəmləşdi. Şəhər e.ə. III əsrdə zəlzələ ilə dağıldı.", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["Diadoxlar sülhü: Antigonos Asiyanın, Kassandros Avropanın, Ptolemaios Misirin idarəsini tanıdı", "811c80f0"], "d": ["311-ci ilin dekabrında imzalanan sülhdə Antigonos Asiyanın komandanı, Kassandros Avropanın strategosu, Lysimax Frakiyanın, Ptolemaios Misir və ətrafının idarəçisi kimi tanındı; Yunan şəhərlərinin azadlığı prinsipi keçdi. Selevkin Babili bu sülhün kənarında qaldı.", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["Tyr Antigonosa keçdi: Fenikiya Ptolemaiosdan alındı", "30f78257"], "d": ["Antigonos 315-də Suriyaya girib Fenikiyanı aldı və Tyri mühasirəyə aldı; şəhər 314-də süquta uğradı. Fenikiya sahili və Qəzzəyə qədər sahil onun əlinə keçdi (Qəzzə döyüşündə 312-də Ptolemaiosa geri verildi).", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["Kassandros Səlaniki qurdu", "7043bd8a"], "d": ["Kassandros Termaikos körfəzinin şimalındakı iyirmidən çox yaşayış məntəqəsini birləşdirib arvadı (II Filippin qızı) Thessalonike adına şəhər qurdu. Səlanik sonrakı min il Makedoniyanın ən mühüm limanı oldu.", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["Kassandros Thebaini yenidən qurdurdu", "0167e784"], "d": ["İskəndərin dağıtdığı Thebai, Kassandrosun dəstəyi ilə və Afina ilə Euboiadan gələn yardımlarla divarları təmir edilərək yenidən quruldu. Boiotiya İttifaqına yenidən mərkəz təmin edildi.", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["Gabiene: Antigonos Eumenesi məğlub etdi, İrana qədər uzanan Asiyanın hakimi oldu", "d2990dfd"], "d": ["316/5-ci illərin qışında Gabienedə Eumenesin ordusu darmadağın edildi, komandanı öz əsgərləri tərəfindən Antigonosa təslim edilib edam olundu. Antigonos Fars yaylasından Anadoluya uzanan geniş bölgənin yeganə hakimi oldu; Selevk Misirə qaçdı.", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["Triparadeisos nizamlaması: Antigonos Monophthalmos Asiya strategosu oldu", "69f6fafb"], "d": ["Perdikkasın Misirdə öldürülməsindən (may 320) sonra Antipatros Triparadeisosda satraplıqları yenidən payladı; Antigonos Asiya qüvvələrinin başına gətirildi, Selevk Babili aldı. Antigonos bu mövqedən öz imperiyasını qurmağa girişdi.", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["Krannon: Lamia müharibəsi uduzuldu; Afinaya Makedon qarnizonu girdi, demokratiya dayandırıldı", "6931c4f6"], "d": ["322-ci il sentyabrın 5-də Krannonda Yunan ittifaqı Antipatros və Krateroya məğlub oldu; Afina Mounykhiaya Makedon qarnizonu qəbul etməyi və vətəndaşlıq meyarını mülk sahibləri ilə məhdudlaşdırmağı qəbul etdi. Demosthenes intihar etdi; klassik Afina demokratiyası faktiki olaraq sona çatdı.", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["Lamia müharibəsi: Yunan şəhərləri İskəndərin ölümündən sonra Makedon hegemonluğuna qarşı qiyam qaldırdı", "c31c7da4"], "d": ["İskəndərin ölüm xəbəri ilə (iyun 323) Afina və Aitoliya İttifaqı Antipatrosa qarşı üsyan etdi; Antipatros Lamiada mühasirəyə alındı. Müharibə Krannonda (sentyabr 322) Makedoniya qələbəsi ilə bitdi, Korinf İttifaqı çərçivəsində Makedon üstünlüyü yenidən quruldu.", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["Hydaspes: Poros məğlub oldu; Pəncab İskəndərə bağlandı", "abab206b"], "d": ["326-cı ilin mayında Taksila rajası Ambhinin dəstəyi ilə İskəndər Jhelumu keçib Porosu məğlub etdi; Porosun krallığı İskəndərə vassal olaraq saxlanıldı. İskəndər bu nöqtədən şərqə doğru irəlilədi, lakin Hyphasisdə ordunun etirazı ilə dayandı.", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["Hyphasis (Beas) sahilində ordu irəliləməyi rədd etdi: İskəndərin şərq sərhədi", "17b23afc"], "d": ["Muson yağışları və yorğunluq üzündən Makedon ordusu Hyphasisin o tayına keçməyi rədd etdi; İskəndər on iki qurbangah ucaldıb geri qayıtmağa məcbur oldu. Hyphasis Makedon fəthlərinin Hindistandakı şərq ucu oldu.", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["Baktriya və Sogdiana İskəndərə boyun əydi; İskəndər Roksane ilə evləndi", "a050508d"], "d": ["329-327-ci illər arasında Oksus o tayı bölgə intensiv partizan mübarizəsi ilə alındı; Spitamenes öldürüldü, Sogdiana qayası və Xorienes qalası təslim oldu. İskəndər Baktriyalı şahzadə Roksane ilə evlənərək yerli əyanları idarəyə bağladı.", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["Qərbi Anadolu sahili İskəndərə keçdi: Efes, Miletos və Halikarnassos", "f67084a4"], "d": ["Efes demokratik rejimlə qapıları açdı, Miletos mühasirə sonunda (yay 334) alındı; Halikarnassosun mühasirəsi payızda şəhərin süqutu ilə nəticələndi və Kariya satraplığı Adaya verildi. İskəndər Fars donanmasının limanlarını quru yolla ələ keçirmək strategiyasını beləliklə tətbiq etdi.", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["Thebai İskəndərin əmri ilə dağıdıldı", "26c4193c"], "d": ["Filippin ölümü ilə üsyan qaldıran Thebaini İskəndər payızda ələ keçirdi; Kadmeiaya Makedon qarnizonu qoydu, şəhəri dağıtdırıb xalqını kölə etdi (Pindarosun evi istisna olmaqla). Boiotiya İttifaqı bu dağıntı ilə faktiki olaraq sona çatdı (316-da Kassandros yenidən qurdu).", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["II Filipp Aigaida öldürüldü; İskəndər taxta çıxdı", "417d909e"], "d": ["Qızı Kleopatranın toy şənliyində teatrda mühafizəçisi Pausanias tərəfindən öldürülən Filippin yerinə oğlu İskəndər ordu tərəfindən kral elan edildi. Fars yürüşü və Yunanıstanın nəzarəti İskəndərə qaldı.", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["Korinf İttifaqı quruldu: Yunan şəhərləri II Filippin hegemonluğu altında birləşdirildi", "c38074dc"], "d": ["Xaironeiadan sonra Filipp Yunan şəhərlərini ümumi sülh (koine eirene) və ümumi müdafiə andı altında Korinfdə topladı; Farsa qarşı yürüş üçün əsgər və hegemon komandanlığı qərara alındı. Yalnız Sparta qatılmadı.", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["Xaironeia: Filipp Afina və Thebai ordusunu məğlub edərək Yunanıstanın nəzarətini ələ aldı", "5e5d77e7"], "d": ["338-ci ilin avqustunda Xaironeia ovasında gənc İskəndərin komandanlıq etdiyi süvari hücumu ilə Afina–Thebai ordusu darmadağın edildi; Thebaiyə Makedon qarnizonu qoyuldu, Afina müsamihə ilə bağışlandı. Qələbə Yunan şəhərlərinin müstəqilliyinə son qoydu və Korinf İttifaqına gedən yolu açdı.", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["Latın İttifaqı dağıdıldı: Latium Romaya bağlandı", "58849f84"], "d": ["Latın müharibəsinin (340-338) sonunda Roma Latın İttifaqını ləğv etdi; şəhərlər Roma vətəndaşlığına qatıldı və ya tək-tək Romaya bağlandı, öz aralarındakı ittifaq qadağan edildi. Romanın İtaliyadakı genişlənmə modelinin təməli budur.", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["II Filipp skif kralı Ateası məğlub etdi", "e4dee658"], "d": ["Kral Ateasın İstros (Tuna) sahillərində Filipplə müharibəsi Ateasın öldürülməsi ilə bitdi; Filipp qayıdarkən Triballilərdən hücuma məruz qaldı. Skif gücü qərbdə Tunanın o tayına sürüşdü.", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["Filipp Frakiyanı Odris sülaləsi ilə birlikdə tabeliyinə aldı", "b543427a"], "d": ["Filipp e.ə. 342-341-ci il yürüşlərində Frakiyanın daxillərinə irəlilədi, Odris kralı Kersobleptesi xəracqoyma altına aldı və Philippoupolis (Filibe) kimi şəhərlər qurdu. Frakiya Makedoniyanın şərq uzantısı oldu.", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["Olynthosun dağıdılması: Xalkidiki İttifaqı Makedoniyaya keçdi", "89d77301"], "d": ["Olynthosun Afinadan kömək istəməsinə baxmayaraq Filipp şəhəri xəyanət yolu ilə ələ keçirib dağıtdı; Xalkidiki yarımadası Makedoniyaya qatıldı. Demosthenesin Olynthiaka nitqləri bu çağırışa əsaslanır.", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["Müttəfiqlər müharibəsi sona çatdı: Bizans, Xios, Rodos və Kos İkinci Afina İttifaqından ayrıldı", "856a9763"], "d": ["E.ə. 357-də başlayan üsyan, Afina komandanlarının Xiosda məğlub olması və Fars dəstəyinin Afinaya qarşı çıxması ilə Afinanın sülhü qəbul etməsi ilə bitdi; dörd mühüm üzv müstəqilliyini qazandı. İttifaq gücsüzləşdi və Makedoniya qarşısında müdafiəsiz qaldı.", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["Filipp Amphipolisi Afinadan aldı", "2c793bc6"], "d": ["Afinanın Strymon çayının mənsəbindəki Amphipolisini mühasirəyə alıb ələ keçirən Filipp, şəhərin qızıl-gümüş mədənlərinə və meşə mənbələrinə çatdığını görüb Frakiya sahilinə açıldı. Bu fəth Afina–Makedoniya münaqişəsini başlatdı.", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["II Filipp Makedoniya kralı oldu", "d557268d"], "d": ["III Perdikkasın İlliriyalılarla müharibədə ölməsi (e.ə. 360/359) üzərinə Filipp əvvəlcə vəkil, sonra kral oldu; İlliriya, Paionia və Frakiya təhlükələrini dəf edib ordu islahatını (sarissa falanqası) apardı. Makedoniyanın yüksəlişi bu krallıqla başlayır.", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["Mantineia: Epameinondas öldü, Boiotiya hegemonluğu sona çatdı", "94be8d5c"], "d": ["Thebai ordusu döyüşü qazandı, lakin Epameinondas yaralanıb öldü; Ksenofont \"qeyri-müəyyənlik və qarışıqlıq Yunanıstanda əvvəlkindən çox\" deyərək bitirir. Thebainin qısa hegemonluğu həmin il sona çatdı, Afina–Sparta–Thebai tarazlığı qorundu.", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["Arkadiya İttifaqı quruldu: Peloponnes İttifaqının bu hissəsi dağıldı", "42fdc676"], "d": ["Leuktradan sonra Arkadiya şəhərləri Thebai dəstəyi ilə federal ittifaq qurdu və yeni paytaxt Megalopolisi inşa etdi. Beləliklə Spartanın Peloponnes İttifaqı faktiki olaraq dağıldı; Sparta yalnız Lakoniyaya çəkildi.", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["Messeniya Spartadan ayrıldı; Messene quruldu", "e4ef9302"], "d": ["Epameinondasın Leuktradan sonrakı Peloponnesos yürüşündə (qış 370/69) Messeniya helotları azad edildi və İthome dağının ətəyində güclü divarlı Messene şəhəri quruldu. Sparta iqtisadi təməlini təşkil edən Messeniya torpaqlarını əsrlər sonra ilk dəfə itirdi.", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["Leuktra: Thebai ordusu Spartalıları məğlub etdi; Sparta quru üstünlüyünü itirdi", "e7829597"], "d": ["Epameinondasın dərin sağ cinah yığma quruluşu Kral Kleombrotosun Spartalı qüvvəsini Leuktrada məğlubiyyətə uğratdı; təxminən 400 Spartiatın ölümü ilə Sparta əhali itkisini kompensasiya edə bilməz hala gəldi. Thebai rəhbərliyi altında hegemonluq dövrü başladı.", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["İkinci Afina İttifaqı quruldu (Aristoteles fərmanı)", "0e5dcaf2"], "d": ["Afina Spartaya qarşı muxtariyyət və xərac almama prinsipi ilə Egey şəhərlərini ittifaqa çağırdı; fərman Aristotelesin təklifi ilə qəbul edildi və üzv şəhərlərin siyahısı daşa yazıldı. İttifaqın qurulması Afinanı yenidən dəniz gücü etdi.", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["Pelopidas Thebaini xilas etdi; Sparta qarnizonu Kadmeiadan qovuldu", "eb15a9d7"], "d": ["Spartanın e.ə. 382-də ələ keçirib qarnizon saxladığı Thebai Kadmeiası, sürgünlərin gecə basqını ilə geri alındı; Thebai yenidən Boiotiya İttifaqının mərkəzi oldu. Hadisə Sparta hegemonluğunun çözülməsinin başlanğıcıdır.", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["Allia: Qalliyalılar Roma ordusunu məğlub edib şəhəri talan etdi", "db864bc9"], "d": ["Tiberin qollarından Allia sahilində Senon Qalliyalılar Roma ordusunu darmadağın etdi; Roma Kapitolium xaric işğal edildi və talan olundu. Livius \"Allia günü\"nün (18 iyul) romalılar üçün uğursuz sayıldığını yazır.", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["Korinf Argosla birləşdi (Argos–Korinf isopolitiyası)", "135a3d3a"], "d": ["Korinf müharibəsi zamanı (e.ə. 395-387) Korinf Argosla ortaq vətəndaşlıq ittifaqı qurdu; Argoslu qarnizon Korinfdə qaldı. Sparta Kral sülhü (386) ilə bu birləşməni pozdurdu.", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["Veii Romaya düşdü: Etruriyanın cənubdakı ilk böyük şəhəri itirildi", "0d1c4fe4"], "d": ["On illik mühasirədən sonra Camillus Veiini aldı (ənənədə e.ə. 396); xalqı kölə edildi, torpaqları Romaya qatıldı və Romanın ager Romanusu təxminən iki qat artdı. Etrusk şəhərlərinin Tiberin cənubundakı gücü qırıldı.", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["Afina Spartaya təslim oldu; Afina dəniz imperiyası və Delos İttifaqı sona çatdı", "43f2ddf9"], "d": ["Aigospotamoida donanmasını itirən Afina aclıqdan təslim oldu; Uzun divarlar dağıdıldı, dəniz imperiyası dağıldı, şəhərdə Spartalıların qurdurduğu Otuzlar idarəsi gəldi. İttifaqın keçmiş üzvü olan adalarda və Frakiya sahillərində Lysandrosun qurduğu dekarxiya idarələri və Sparta qarnizonları yerləşdi.", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["I Dionysios Sirakuzada tiran oldu", "1ad10305"], "d": ["Karfagenin Akragas və Gelanı aldığı illərdə Dionysios 405-də Sirakuza strategosu və ardınca tiranı oldu; Karfagen ilə sülh bağlayıb (405) Siciliyanın Yunan şəhərlərini özünə bağladı. 38 il davam edəcək Dionysios hakimiyyəti Siciliyanı Aralıq dənizinin böyük güclərindən biri etdi.", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["Aigospotamoi: Afina donanması məhv edildi; Delos İttifaqı çöküşün astanasına gəldi", "ce62187c"], "d": ["405-ci ilin sentyabrında Lysandros Aigospotamoida lövbər salmış Afina donanmasını basqınla ələ keçirdi; donanmanın demək olar ki, hamısı və minlərlə əsir itirildi. Hellespontos yolu bağlandı və Afinanın taxıl təchizatı kəsildi; bir neçə ay sonra Afina təslim oldu.", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["Rodos şəhəri quruldu: Lindos, Ialysos və Kameiros birləşdi", "2de55901"], "d": ["E.ə. 408-də Rodos adasının üç şəhəri ortaq dövlət qurub yeni Rodos şəhərində birləşdi; Hippodamos planı ilə inşa edilən şəhər Hellenistik dünyanın ən mühüm dəniz bazası və ticarət mərkəzlərindən biri oldu.", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["Hannibal Mago Selinus və Himeranı dağıtdı: Karfagen qərbi Siciliyada məskunlaşdı", "358f4417"], "d": ["Segestanın kömək çağırışı ilə Siciliyaya çıxan Hannibal Mago e.ə. 409-da Selinusu və Himeranı aldı; bölgə Karfagenin epikratiası oldu. Karfagen–Sirakuza münaqişəsi iki əsr davam etdi.", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["Siciliya yürüşü fəlakətlə bitdi: Afina ordusu Sirakuza qarşısında məhv oldu", "b363df0d"], "d": ["Afinanın e.ə. 415-də başlatdığı Siciliya yürüşü, Sirakuzanın mühasirəyə alına bilməməsindən sonra Nikias və Demosthenesin geri çəkilişində Assinaros çayı sahilində təslimlə (e.ə. 413-cü ilin payızı) nəticələndi. Afina ordusunu və donanmasının böyük hissəsini itirdi.", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["Sitalkes Afina ilə ittifaq etdi: Odris krallığı Peloponnes müharibəsinə qatıldı", "4562f13d"], "d": ["Afina Sitalkesin oğlunu Afina vətəndaşı etdi və onunla ittifaq qurdu; Sitalkes 429-da Makedoniyaya hücum etdi. Odris gücü bu dövrdə zirvəyə çıxdı.", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["Peloponnes müharibəsi başladı: Peloponnes İttifaqı Afinaya qarşı səfərbər oldu", "2adee4a1"], "d": ["Thebainin Plataiaya gecə basqını ilə (yaz 431) sülh faktiki olaraq pozuldu; yay əvvəlində Kral Arxidamosun komandanlığı altındakı Peloponnes İttifaqı ordusu Attikanı işğal etdi. Müharibə Afinanın dəniz imperiyası ilə Spartanın quru ittifaqı arasında 27 il davam etdi.", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["Sybota: Korinf–Korkyra döyüşü Afinanı müdaxiləyə cəlb etdi", "dc07b0ac"], "d": ["Korinfin koloniyası Korkyra ilə Epidamnos üzündən girdiyi dəniz döyüşündə Afina Korkyranı dəstəklədi. Korinfin Afinaya qəzəbi Peloponnes müharibəsinin birbaşa səbəblərindən biri oldu.", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["Spartokos Bosporosda arxon oldu: Spartokidlər sülaləsi", "ddc76f79"], "d": ["Pantikapaiondakı Arxeanaktid sülaləsinin yerini Frakiya mənşəli Spartokos aldı (438/7); Spartokidlər sülaləsi Bosporos krallığını qurdu və Afinaya taxıl ixracını idarə etdi. Sülalə e.ə. 109-a qədər davam etdi.", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["Otuz illik sülh: Afina quru imperiyasını (Boiotiya, Megara, Axaia) itirdi", "4f33ff13"], "d": ["Boiotiyalıların Koroneiada Afina ordusunu məğlub etməsi (447), ardınca Euboia və Megara üsyanları və Spartanın Attika işğalından sonra Afina Otuz illik sülhü imzaladı. Afina Megaranı, Nisaianı, Pegainı və Peloponnesosdakı Troizen və Axaianı tərk etdi; yalnız dəniz imperiyasını qoruyub saxladı.", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["Teres Odris krallığını qurdu: Frakiyanın ilk böyük dövləti", "83caf189"], "d": ["Thukydides Teresin Frakiyada ilk böyük krallığı qurduğunu yazır; oğlu Sitalkes krallığı Tunadan Egeyə çatdırdı. Odris krallığı Afina, Makedoniya və Fars arasında tarazlıq siyasəti yürütdü.", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["İttifaq xəzinəsi Delosdan Afinaya daşındı", "173f2e5b"], "d": ["Misir yürüşündəki məğlubiyyət və Fars donanması qorxusu əsas gətirilərək ortaq xəzinə Delosdan Afinaya aparıldı; Afina ilahəsinə verilən \"altmışda bir\" payı siyahıları bu ildən başlayır. Bu addım ittifaqın praktikada Afina imperiyasına çevrildiyinin əlaməti kimi şərh olunur.", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["Thasos üsyanı yatırıldı; Delos İttifaqı üzvlərin ayrıla bilməyəcəyi bir imperiyaya çevrildi", "d24bd124"], "d": ["Thasos mədənlər üzündən Afina ilə toqquşub ittifaqdan ayrılmağa cəhd etdi; iki illik mühasirədən sonra (e.ə. 463) divarlarını yıxdı, donanmasını təslim etdi və Frakiya sahilindəki mədən bölgəsini itirdi. Hadisə ittifaq üzvlüyünün tərk edilə bilməyəcəyini göstərən ilk presedentdir.", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["Kyme (Cumae) dəniz döyüşü: Sirakuza Etrusk donanmasını məğlub etdi, Etrusk dəniz gücü qırıldı", "2e81670b"], "d": ["Kymenin kömək çağırışı üzərinə Sirakuza tiranı I Hieron Etrusk donanmasını Kyme qarşısında darmadağın etdi; Hieron qələbəni Delfiyə dəbilqə hədiyyəsi ilə qeyd etdi (Liviusun qeyd etdiyi Etrusk dəbilqəsi). Etrusklərin Kampaniya hakimiyyəti sarsıldı.", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["Delos İttifaqı quruldu: Afinanın başçılığı ilə Egey ittifaqı", "f0de153a"], "d": ["Pausaniasın idarə tərzindən sonra İoniya şəhərləri Afinadan rəhbərlik istədi; Aristeidesin müəyyən etdiyi xərac (460 talant) ilə Delosda ortaq xəzinə quruldu. İttifaq Afinaya Egey üzərində daimi donanma və vergi bazası təmin etdi.", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["Salamis (29 sentyabr 480) və Plataia: Fars işğalı geri oturduldu", "479b17e6"], "d": ["Kserks Afinanı ələ keçirib yandırdıqdan sonra Themistoklesin tələsi ilə Fars donanması Salamis boğazında darmadağın edildi (29 sentyabr 480); ertəsi il Plataiada Pausaniasın komandanlığı altındakı Yunan quru ordusu Mardonioşu məğlub edərək işğalı bitirdi. Beləliklə Egey Yunanıstanı Fars hakimiyyətindən qurtuldu.", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["Himera: Siciliya yunanları Karfagen ordusunu məğlub etdi", "ece09580"], "d": ["Gelon və Theronun ittifaqı Himera qarşısında Hamilkarın Karfagen ordusunu darmadağın etdi; Karfagen yarım əsr Siciliyaya yenidən böyük yürüş edə bilmədi. Herodot və Diodora görə eyni gün Salamis qazanıldı (ənənə).", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["Marathon: Afina Fars hücumunu dayandırdı", "0967ce7c"], "d": ["Miltiadesin komandanlığı altındakı Afina və Plataia hoplitləri Marathon ovasında Fars qüvvəsini məğlub edərək Attikaya çıxışın qarşısını aldı. Qələbə Afina demokratiyasının özgüvənini və ardınca Delos İttifaqına uzanan dəniz siyasətini bəslədi.", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["Mardonios Makedoniyanı Farsa tabe etdi", "7bde569c"], "d": ["Dareiosun kürəkəni Mardonios Frakiyanı keçib Makedoniyanı Fars hakimiyyəti altına saldı; Makedon kralı Farsa torpaq və su verdi. Makedoniya bu asılılığı Plataiadan sonra (479) atdı.", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum: Roma Latın İttifaqı ilə ittifaq bağladı", "56db407d"], "d": ["Spurius Cassiusun adını daşıyan müqavilə ilə Roma və Latın İttifaqı qarşılıqlı müdafiə, qənimət bölüşdürülməsi və ortaq ordu əsasında ittifaq qurdu. Bu müqavilə Latın müharibəsinə (340-338) qədər Roma-Latium münasibətlərinin çərçivəsidir.", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["Korinfin çəkilməsi ilə Peloponnes İttifaqının Afina yürüşü dağıldı", "b44adf6b"], "d": ["Sparta Kleisthenesin demokratik Afinasına qarşı Peloponnes İttifaqı ordusunu Attikaya yeritdi; Eleusisdə Korinf ordusunun çəkilməsi və iki Sparta kralının razılaşmazlığı yürüşü çökdürdü. Hadisə ittifaq məclisində müttəfiqlərin səs hüququnun işləməyə başladığı ilk məlum nümunə sayılır.", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["Kleisthenes islahatı: Afina demokratiyasının institusional təməli qoyuldu", "b2421c86"], "d": ["Hippiasın süqutundan sonra Kleisthenes vətəndaşları yaşayış vahidi olan demoslar və on yeni tayfa üzərindən təşkil etdi; Beşyüzlər Şurası bu quruluşun mərkəzi oldu. İsonomiya/demokratiya anlayışlarının doğduğu nizamlamadır.", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["Sonuncu kral Tarquinius Superbus qovuldu; krallıq sona çatdı, Respublika başladı", "5a4a9061"], "d": ["Liviusa görə Tarquinius Superbus və ailəsi e.ə. 509-da şəhərdən qovuldu və ilk konsullar (Brutus, Collatinus) seçildi. Polybios Roma-Karfagenin ilk müqaviləsini ilk konsulların ilinə bağlayır; tarix müasir tarixşünaslıqda \"ənənə\" sayılsa da e.ə. VI əsrin sonuna oturur.", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["Roma ilə Karfagen arasında ilk müqavilə (Polybios 3.22)", "cdef940f"], "d": ["Polybios ilk konsulların ilində Roma və Karfagen arasında bağlanan və Latium sahillərini Romaya, Karfageni qərbi Siciliya və Liviyaya ayıran müqaviləni mətni ilə nəql edir. Roma Latiumun hakimi kimi anılır.", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["Alalia dəniz döyüşü: Etrusklər və Karfagenlilər Fokaialıları Korsikadan çıxartdı", "25efbea8"], "d": ["Alaliada Fokaialı yunanlar kağız üzərində qələbə qazandı, lakin donanmasının çoxunu itirdi; Korsikanı tərk edib Cənubi İtaliyada Eleaya çəkildi. Adada Etrusk (Caere) hakimiyyəti quruldu.", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["Sparta–Tegea müqaviləsi: Peloponnes İttifaqının nüvəsi yarandı", "57098e47"], "d": ["Sparta Arkadiyadakı Tegeanı məğlub edib ona torpaqlarını pozmama müqabilində əbədi ittifaq (symmachia) qəbul etdirdi; eyni qəlib Peloponnesos şəhərlərinə yayıldı və Sparta başçılığı ilə Peloponnes İttifaqı doğuldu. İttifaq öz daxilində Sparta və müttəfiq məclisi (Sparta komandanlığı altında) şəklində fəaliyyət göstərdi.", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["Fokaialılar Massalianı (Marsel) qurdu", "5d46bdf2"], "d": ["Fokaialı koloniyaçılar e.ə. 600 civarında Rhône mənsəbində Massalianı qurdu; şəhər Qərbi Aralıq dənizində Yunan ticarətinin və Kelt dünyası ilə təmasın mərkəzi oldu.", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["Theralı Battos Kyrenenı qurdu", "67fd477f"], "d": ["Theradan gələn koloniyaçılar Delfi kahinliyinə əsasən Battosun rəhbərliyi ilə Kyrenenı qurdu; Battiadlar sülaləsi 440-a qədər idarə etdi. Livius qurulma tarixini \"c. 630\" olaraq verir.", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["Sparta Birinci Messeniya müharibəsini qazandı: Messeniya Spartaya qatıldı", "74ad461c"], "d": ["Pausaniasın nəql etdiyi ənənədə Birinci Messeniya müharibəsi iyirmi il davam etdi və Ithomenin süqutu ilə Messeniya ovası Spartaya keçdi; əhali helot statusuna endi. Bu fəth Spartanın əkinçilik gücünü və hərbi cəmiyyətini müəyyən edən əsas hadisə sayıldı.", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["Sirakuza korinfli Archias tərəfindən quruldu", "10217104"], "d": ["Thukydidesə görə Naxosdan bir il sonra korinfli Archias Sirakuzanı qurdu. Şəhər Siciliyanın ən böyük Yunan şəhəri oldu.", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["Karfagenin ənənəvi qurulması (Timaios: e.ə. 814/813)", "908099b5"], "d": ["Timaiosa görə Karfagen e.ə. 814/813-də Tyrli koloniyaçılar tərəfindən quruldu; Iustinus 825 verir. Arxeoloji qatlar e.ə. VIII əsrin sonuna işarə edir.", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["Mikena saray mərkəzləri dağıdıldı: Palatial quruluş Peloponnesosda çökdü", "d2c79152"], "d": ["Gec Hellas IIIB sonu / IIIC əvvəlində Pylos, Tiryns və Mikenadakı saray mərkəzləri dağıntı və ya tərk qatı verir; Linear B yazıya əsaslanan saray iqtisadiyyatı sona çatır. Dağıntının səbəbi (zəlzələ, daxili toqquşma, Dəniz xalqları, quraqlıq) mübahisəlidir; dağıntı qatları tək ilə deyil, bir neçə onilliyə yayılır.", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["Kritdə Minos saraylarının dağıdılması; Knossosda Mikena nəzarəti başladı", "1a7f7f2b"], "d": ["Gec Minos IB sonunda (e.ə. XV əsrin ortası) Kritdəki saray mərkəzləri və villalar dağıntıya uğrayır; Knossosda sonrakı mərhələdə Linear B lövhələri Yunan dilində yazılmış saray idarəsini, yəni Mikena nəzarətini göstərir. Beləliklə Minos hakimiyyəti Kritdə sona çatır.", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["Teutoburq meşəsi: Varusun üç legionu məhv edildi; Roma Elbe xəttini tərk etdi", "1684ae43"], "d": ["b.e. 9-da Arminiusun rəhbərliyindəki German koalisiyası P. Quinctilius Varusun XVII, XVIII və XIX legionlarını Teutoburq meşəsində məhv etdi. Avqust Reynin o tayındakı fəthlərdən vaz keçdi və Reyn sərhədi qalıcılaşdı.", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["Avqust öldü; Tiberius imperator oldu", "0221344d"], "d": ["Avqust 14-cü il avqustun 19-da Nolada öldü; Tiberius yerinə keçdi. Principatusda varislik prinsipi (ailədən övladlığa götürmə) beləliklə qalıcılaşdı.", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["Kral Ptolemaios Caligula tərəfindən öldürüldü; Mavretaniyanın müstəqilliyi sona çatdı", "11337627"], "d": ["II Jubanın oğlu Ptolemaios b.e. 40-da Lugdunumda Caligulanın əmri ilə öldürüldü; ardınca Mavretaniyada Aedemon üsyanı çıxdı və Claudius 44-də ölkəni Tingitana və Caesariensis adlı iki əyalətə ayırdı.", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["Claudius Britanniyanı işğal etdi", "f42ba7f7"], "d": ["B.e. 43-də Aulus Plautiusun komandanlığı altındakı dörd legion Kent sahilinə çıxdı; Camulodunum (Colchester) alındı və Claudius qısa müddət şəhərdə oldu. Britanniyanın cənubu yeni Roma əyaləti oldu.", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["Roma Frakiyanı əyalət etdi: Odris sülaləsi sona çatdı", "af2ba1b2"], "d": ["Frakiya kralı III Rhoemetalcesin arvadı tərəfindən öldürülməsi və ardınca yaranan qarışıqlıq üzərinə Claudius 46-da Frakiyanı Roma əyalətinə çevirdi. Balkanlarda Romanın şərqdəki əyalət quruluşunu tamamlayan son addımlardandır.", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["Trayan Dakiyanı fəth etdi: Sarmizegetusa süquta uğradı, Decebalus öldü, Dacia əyaləti quruldu", "a9277172"], "d": ["İkinci Dak müharibəsində (105-106) Trayan Sarmizegetusanı aldı; Decebalus əsir düşməmək üçün intihar etdi. Dakiya Roma əyaləti oldu və qızıl mədənləri Roma iqtisadiyyatına bağlandı Müharibənin əvvəlki mərhələləri (101-105) xronologiyada ayrı maddələrdədir..", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["Hadrian Britanniyada şimal sərhədində Divar tikintisinə başladı", "f4a886ec"], "d": ["Hadrian b.e. 122-də Britanniyaya səfərdən sonra Tyne-Solway xəttində sərhəd divarı tikdirdi. Divar Romanın müdafiəyə yönəlik sərhəd siyasətini simvolizə edir; irəliləmə Antoninus divarı (142) ilə sınaqdan keçirildi, lakin qalıcı olmadı.", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["Septimius Severus Mesopotamiyanı əyalət etdi; Ktesifon talan edildi", "df466924"], "d": ["Severus Part müharibəsində (195-198) Nisibisi alıb Ktesifonu talan etdi və Yuxarı Mesopotamiyanı Roma əyaləti kimi təşkil etdi. Əyalət Romanın ən şərq irəliləyişini III əsrə daşıdı.", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana: İmperiyadakı bütün azad sakinlərə Roma vətəndaşlığı verildi", "dd4e4024"], "d": ["Caracalla b.e. 212-də əyalətlərdəki azad sakinləri Roma vətəndaşı etdi; imperiyada vətəndaş-əcnəbi fərqi aradan qalxdı. Nizamlama vergi bazasını da genişləndirdi.", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["Postumus Qalliyada separatçı Qalliya imperiyasını qurdu", "4dcda41d"], "d": ["Valerianın Partlara əsir düşməsi (260) üzərinə Postumus Reyn orduları ilə Qalliyada imperiya elan etdi; Qalliya, Britanniya və Hispaniyanın böyük hissəsi 274-ə qədər Romadan qopdu. Gallienus ayrılığı aradan qaldıra bilmədi.", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["Aurelian Daciyanı boşaltdı: Tunanın şimalı tərk edildi", "db2ca714"], "d": ["Qotların təzyiqi üzündən Aurelian Dacia əyalətini boşaldıb legionları və mülki əhalini Tunanın cənubuna (Dacia Ripensis) çəkdi. Roma 165 il sonra Tunanın şimalındakı ilk böyük torpağını tərk etdi.", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["Aurelian Palmira imperiyasını məğlub etdi: Zenobianın Şərq torpaqları Romaya qayıtdı", "0a358790"], "d": ["Aurelian 272-də Antiokheia və Emesada Zenobianın ordusunu məğlub edib Palmiranı mühasirəyə aldı; Zenobia tutuldu. Suriya, Misir və Anadolunun cənubu yenidən Romaya bağlandı.", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["Aurelian Qalliya imperiyasını məğlub etdi: Roma yenidən birləşdi", "c1a6a642"], "d": ["Aurelian 274-də Catalaunumda Tetricusu məğlub etdi; Qalliya, Britanniya və Hispaniya Romaya qayıtdı. İmperiya 14 illik bölünmədən sonra bütövləşdi və Aurelian \"Restitutor Orbis\" (\"dünyanı yenidən quran\") titulunu aldı.", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["Julian Salian Franklarını Toxandriyaya Roma foederati kimi yerləşdirdi", "0fb618fe"], "d": ["Sezar Julian 358-də Salian Franklarını məğlub edərək Roma torpaqlarında Toxandriyada (bugünkü Hollandiya-Belçika sərhədi) məskunlaşmağa icazə verdi. Frank krallığının doğacağı bölgənin Roma himayəsində yerləşməsinin başlanğıcıdır.", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["Hunlar Donu keçib Alanlara və Ostqotlara hücum etdi: Böyük köçün başlanğıcı", "659eb875"], "d": ["Ammianusa görə Hunlar 375-də Donu keçib Alanları məğlub etdi, ardınca Ostqot kralı Ermanarikin krallığını yıxdı; Vizqot (Tervingi) xalqı bunun üzərinə Tunaya dayandı. Avropada Hunların hakimiyyət çağı beləliklə başladı.", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["Tervingi qotları Tunanı keçib Roma torpaqlarına yerləşdi", "3e9de0e6"], "d": ["Hunların təzyiqi ilə Fritigernin Tervingi qotları 376-da Valensdən Tunanı keçib Roma torpaqlarına yerləşmək üçün icazə aldı; təchizat və idarəetmə problemləri üsyana çevrildi. Nəticə 378-də Adrianopolis (Ədirnə) məğlubiyyəti oldu.", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["Vandallar, Alanlar və Süevlər Reyni keçərək Qalliyaya daxil oldu", "2b3354ba"], "d": ["Ənənəvi 31 dekabr 406 tarixində (donmuş Reyn üzərindən) Vandallar, Alanlar və Süevlər Roma Qalliyasına daxil oldu; Reyn müdafiəsi çökdü. Ardınca İspaniyaya keçmələri (409) Qərbi Romanın əsas əyalətlərini qopardı.", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["Vandallar, Alanlar və Süevlər İspaniyaya keçdi: Hispaniya bölüşdürüldü", "b7036608"], "d": ["409-cu ilin payızında Qalliyadan Pireneyləri keçən Vandal, Alan və Süev qrupları 411-də yarımadanı aralarında bölüşdürdü: Hasdinqlər və Süevlər Gallaeciyanı, Silinqlər Baeticanı, Alanlar Lusitaniya və Carthaginensisi aldı. Vizqotlar (416-418) Silinqləri və Alanları əzərək Vandalların Afrikaya keçişini hazırladı.", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["Roma Vizqotları Aquitania Secundaya yerləşdirdi: Tuluza mərkəzli Vizqot krallığı", "38a7699e"], "d": ["Constantiusun komandanlığı altındakı Roma, Walliyanın Vizqotlarını Hispaniyada Vandal-Alanlara qarşı istifadə etdikdən sonra 418-də Garonne vadisindəki Aquitania Secundaya foederati kimi yerləşdirdi. Tuluza mərkəzli Vizqot krallığı Roma torpağında ilk German krallığı sayılır.", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["Margus müqaviləsi: Hunlar Romadan illik 700 libre qızıl aldı", "833d8854"], "d": ["Hun kralı Ruanın ölümündən (433/4) sonra Attila və Bleda Margusda Şərqi Roma ilə müqavilə bağladı: illik xərac 350-dən 700 libre qızıla çıxarıldı, Hun sığınanları geri verildi. Hunlar Tuna sərhədində ticarət hüququ əldə etdi.", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["Hippo müqaviləsi: Roma Vandalları Numidiya və Mavretaniyanın bir hissəsində foederati kimi tanıdı", "f7dba59f"], "d": ["Vandal kralı Gaiseric 429-da Afrikaya keçdikdən sonra 435-də Roma ilə Hippo müqaviləsini bağladı; Vandallar Numidiyanın və Mavretaniyanın bir hissəsini foederati qismində saxladı. Müqavilə 439-da Karfagenin alınması ilə pozuldu.", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["Attila Tuna qalalarını aldı: Viminacium və Singidunum (Belqrad) Hunlara keçdi", "0abb2c54"], "d": ["Şərqi Roma ordusunun Siciliya və Vandal yürüşündə olması üzərinə Attila 441-də Tunanı keçdi; Margus, Viminacium və Singidunum alındı. Sirmium da bu yürüşlərdə süquta uğradı və Hunlar Balkanların daxillərinə çatdı.", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["Roma və Vandallar yeni müqavilə bağladı: Africa Proconsularis, Byzacena və Numidiyanın bir hissəsi Vandallara qaldı", "e5700ddc"], "d": ["Karfageni alan (439) Gaiseric, 442-də III Valentinianla bağladığı müqavilə ilə Africa Proconsularis, Byzacena, Abaritana və Numidiyanın bir hissəsini hüquqi olaraq Vandal torpağı etdi; Roma yalnız Mavretaniyanı və Numidiyanın qərbini əlində saxladı.", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["Anatolius sülhü: Tunanın cənubunda geniş bir zolaq Hunlara tərk edildi", "ee8ad838"], "d": ["Utusdakı Şərqi Roma məğlubiyyətindən sonra Anatolius 447-də Attila ilə sülh bağladı: Roma Tunanın cənubunda Singidunumdan Novaeyə uzanan beş günlük genişlikdə bir zolağı Hunlara tərk etdi, illik xərac 2100 libre qızıla çıxarıldı.", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["Catalaunum (Châlons) döyüşü: Aetius və I Theodorix Attilanı Qalliyadan çıxartdı", "80f10e32"], "d": ["451-də Attila Qalliyaya daxil olub Orléansı mühasirəyə aldı; Aetius və Vizqot kralı I Theodorixin koalisiyası onu Catalaunum ovasında geri çevirdi (Theodorix ölərkən). Hunların Qərbi Avropadakı irəliləyişi beləliklə dayandı.", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["Attila İtaliyaya daxil oldu; Aquileia dağıdıldı", "1349c67a"], "d": ["452-də Attila Alp dağlarının o tayından Şimali İtaliyaya daxil oldu, Aquileianı yerlə-yeksan etdi və Po ovasını talan etdi; xəstəlik və Şərqi Romanın əks hücumu ilə geri çəkildi. Aquileianın qaçqın əhalisi laqunlarda Venesiyanın nüvəsini yaratdı.", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["Attila öldü; Hun dövləti dağıldı", "47009384"], "d": ["Attila 453-də toy gecəsi öldü; oğulları arasındakı bölüşdürmə və German təbəələrin üsyanı bir il sonra Nedaoda (454) Hun üstünlüyünə son qoydu. Hunlar Şərqi Avropaya çəkildi.", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["Euricin Vizqot krallığı Romadan faktiki ayrıldı: Auvergne Vizqotlara tərk edildi", "4bbe7b0c"], "d": ["Euric 466-dan bəri Hispaniya və Qalliyada fəthlər edərək krallığını genişləndirdi; 475-də Julius Nepos Auvergneni tərk edərək onun müstəqil hökmranlığını faktiki tanıdı. Vizqot krallığı Loiredan Aralıq dənizinə qədər Qərbi Roma torpaqlarına nəzarət etdi.", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["Julius Nepos Dalmatiyada öldürüldü: Qərbi Romanın son qanuni imperatoru", "3b965f33"], "d": ["Romulusun devrilməsindən sonra Dalmatiyaya çəkilən Nepos 480-də öldürüldü; ölümündən sonra Qərbi Roma taxtına iddia edəcək kimsə qalmadı və Odoacer İtaliyadakı faktiki hakimiyyətini Zenonun adı ilə davam etdirdi.", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["Theodorix Ostqotları İtaliyaya soxdu: Isonzo və Veronada Odoacer məğlub oldu", "6a998bf8"], "d": ["Şərqi Roma imperatoru Zenonun təsdiqi ilə Theodorix 489-da İtaliyaya daxil oldu, Isonzo və Veronada Odoaceri məğlub etdi; Odoacer Ravennaya qapandı. Üç illik mühasirə 493-də Ravennanın təslimi ilə bitdi.", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["Theodorix Odoaceri Ravennada öldürtdü; İtaliya Ostqot krallığının oldu", "5a2db0ed"], "d": ["Odoacerin İtaliya krallığının sonu: bütün İtaliya (Genuya, Brindisi, Aricia kimi şəhərlər daxil olmaqla) Şərqi Qot (Ostqot) krallığına keçdi. Üç illik Ravenna mühasirəsindən sonra 493-cü ilin martında Odoacer və Theodorix birgə idarə üzərində razılaşdı; ardınca Theodorix Odoaceri bir ziyafətdə öldürdü. İtaliya Şərqi Romanın təsdiqi ilə Ostqot krallığı oldu və paytaxtı Ravennadır.", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["Samos Sülhü: Kush elçiləri Augustusdan sülh aldı; Roma Kushdan qoyduğu xərac vergisini ləğv etdi, sərhəd Aşağı Nubiyada (Hiera Sykaminos) çəkildi", "c3c4c20d"], "d": ["Kandakenin elçiləri Petroniusun yönləndirməsi ilə Augustusu tapdıqları Samosa getdi; Augustus onların bütün istəklərini qəbul etdi və Petroniusun Kusha qoyduğu xərancları da ləğv etdi. Sülh nəticəsində Roma-Kush sərhədi Philaenin cənubunda Hiera Sykaminos (Maharraqa) xəttinə oturdu və təxminən üç yüz il ciddi toqquşma olmadı.", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["Petronius Kusha qarşı yürüşə çıxıb Pselkis, Premnis və Napatanı aldı; İbrimə qarnizon yerləşdirdi", "4884ed51"], "d": ["Prefekt Petronius on minə yaxın piyada və səkkiz yüz atlı ilə otuz min Kush əsgərini məğlub etdi, Pselkisi aldı, Premnis (Qasr İbrim) qalasını ilk hücumda ələ keçirdi və Kandakenin sarayının yerləşdiyi Napatanı yerlə yeksan etdi. Daha irəli getməyi çətin sayıb qayıdarkən Premnisə iki illik ərzaqla dörd yüz nəfərlik qarnizon qoydu. Kandake Premnisi geri almağa çalışanda Petronius yetişib qalanı qorudu.", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["Kandakenin rəhbərliyi ilə Kush Elefantin, Syene və Philaeni aldı; Augustusun heykəllərini yıxdı", "aa665fad"], "d": ["Aelius Gallusun Ərəbistan yürüşü üçün Misirdəki Roma birliklərinin bir qismi çəkiləndə Kushlular Thebaisə girdi; Syenedəki üç kohortluq qarnizonu məğlub edib Syene, Elefantin və Philaeni aldı, əhalini əsir etdi və Caesar heykəllərini yıxdı. Strabon həmin dövrdə Kushu idarə edən kraliçanın 'Kandake' titullu, təkgözlü bir qadın olduğunu yazır.", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["Cornelius Gallus ilk Misir prefekti oldu; Heroonpolis və Fiva üsyanlarını yatırdı, Kushla sərhəd təmin edildi", "9f688855"], "d": ["Octavianus Misiri vergiyə bağlı xüsusi əyalət edib idarəsini senator deyil, atlı sinfindən olan prefektə tapşırdı; ilk prefekt Cornelius Gallus oldu. Strabon Gallusun Heroonpolisdə üsyan edən bir qəsəbəni az sayda əsgərlə aldığını və Fivada vergi üzündən çıxan qiyamı qısa müddətdə yatırdığını yazır. Philaedəki Gallus steləsi Kush hökmdarının elçilərinin burada qəbul edildiyini və Triakontaschoinos bölgəsinin himayə altına alındığını bildirir.", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["Octavianus İskəndəriyyəyə girdi; Ptolemaios dövləti sona çatdı, Misir Romaya keçdi", "553804ca"], "d": ["Antoniusun donanma və süvarisinin Octavianusa keçməsindən sonra Octavianus İskəndəriyyəyə girdi; Antonius özünü öldürdü, Kleopatra da qısa müddət sonra öldü. Octavianus İskəndəriyyə əhalisini bağışladı, 'bir kral görmək istədim, ölüləri deyil' deyərək Ptolemaioslar məzarlarını ziyarət etmədi və Misiri vergiyə bağlı bir ölkə kimi Cornelius Gallusa verdi. Bu tarixlə üç yüz illik Ptolemaios krallığı sona çatdı.", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["Aktion dəniz döyüşü: Octavianus Antonius və Kleopatranı məğlub etdi", "7e46cc73"], "d": ["Octavianusun donanması Aktionda Antonius və Kleopatranın donanmasını məğlub etdi; ikili Misirə çəkildi. Dio tarix verməkdən qaçınan müəllif olaraq bu günü xüsusi qeyd edir, çünki Octavianus bundan etibarən imperiyanı təkbaşına əlində saxladı və hakimiyyət illəri bu gündən hesablandı.", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["İskəndəriyyə Bəxşişləri: Antonius Kleopatranı və uşaqlarını şərq krallıqlarının hökmdarı elan etdi", "24e24981"], "d": ["Gymnasionda toplanan izdihama qızıl taxtlar qurdurmuş Antonius Kleopatranı Misir, Kipr, Liviya və Koile-Suriya kraliçası, Kaisarionu onunla birgə hökmdar, uşaqlarını isə Ermənistan, Mediya, Parfiya və Finikiya-Suriya-Kilikiya kralı elan etdi. Romada bu mərasim Antoniusun əleyhinə təbliğata çevrildi və vətəndaş müharibəsini sürətləndirdi.", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["Antonius Kleopatraya Kipr, Finikiya, Koile-Suriya və Kilikiyanın bir hissəsini hədiyyə etdi", "cf19a357"], "d": ["Plutarxosa görə Antonius Suriyaya gələndə Kleopatraya Finikiyanı, Koile-Suriyanı, Kiprı, Kilikiyanın böyük hissəsini, Yəhudiyyənin balzam verən tərəfini və Nabateyanın dənizə uzanan hissəsini verdi. Beləliklə, Ptolemaios dövləti III Ptolemaiosdan bəri ilk dəfə Şərqi Aralıq dənizində geniş bir sahəni (Romanın qəzəbinə baxmayaraq) nəzarətdə saxladı.", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["İskəndəriyyə müharibəsi: Caesar XIII Ptolemaiosu məğlub etdi, Misiri Kleopatraya tapşırdı", "96c9b516"], "d": ["Caesar İskəndəriyyəyə gəlib Kleopatra ilə XIII Ptolemaios arasında hakimlik etmək istəyəndə saray qüvvələri onu mühasirəyə aldı; qış boyu davam edən küçə döyüşlərində Caesara kömək gəldi və Nil döyüşündə XIII Ptolemaios boğuldu. Caesar Misiri Kleopatraya və kiçik qardaşı XIV Ptolemaiosa verdi; Roma legionları İskəndəriyyədə qaldı.", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["Gabinius XII Ptolemaiosu Roma ordusu ilə Misir taxtına qaytardı; İskəndəriyyədə Roma qarnizonu qaldı", "41d8f47d"], "d": ["Qovulmuş XII Ptolemaios (Auletes) Suriya qubernatoru Gabiniusa böyük rüşvət verərək Misirə girişi satın aldı; Gabinius Parfiya yürüşünü buraxıb Pelusiumdan Misirə girdi, Auletesi taxta qaytardı. Bu, Misirin müstəqilliyinin faktiki olaraq Roma təminatına bağlandığı andır. Gabinius sonradan Romada mühakimə olundu.", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["Roma Kiprı Ptolemaiosdan alıb ilhaq etdi; Cato adaya göndərildi", "678b2115"], "d": ["XII Ptolemaiosun qardaşı olan Kipr kralı Romanın Clodiusun təklifi ilə adanı almasına qarşı çıxmadı; Cato adanı təhvil almaq üçün göndərildi. Ptolemaios dövləti Kiprı itirdi və sahildəki son dəniz bazasını itirdi. Plutarxos Catonun 'Kipra göndərilməsini' Pompeiusun tərcümeyi-halında xatırladır.", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["«Eleusis Günü»: Roma elçisi Popilius Laenas IV Antiochosu Misirdən geri çəkilməyə məcbur etdi", "e6883e6a"], "d": ["Pydna döyüşündən (e.ə. 168-ci il 22 iyun) dərhal sonra Roma elçisi Gaius Popilius Laenas İskəndəriyyəni mühasirəyə alan Antiochosa Senatın müharibəni dayandırmaq əmrini çatdırdı; kralın cavabını düşünməsi üçün onun ətrafına bir dairə çəkdi. Antiochos geri çəkildi. Misir müstəqilliyini Romanın himayəsi ilə itirmədən davam etdirdi.", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["IV Antiochos Misirə hücum etdi; Altıncı Suriya müharibəsində Memphis və Naukratisə irəlilədi", "b85e6712"], "d": ["IV Antiochos VI Ptolemaiosun Koile-Suriyanı geri alma hazırlığına cavab olaraq Misirə girib Pelusiumdan Nilə endi; Koile-Suriya üzərində haqqını müdafiə etdi və Naukratisdə əhaliyə yaxşı davrandı. Müharibə Misiri dağıtmadan, lakin dövləti zəiflədərək Romanın araya girməsi ilə bir il sonra bitdi.", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["Fiva üsyanı yatırıldı: Komanos Yuxarı Misiri Ptolemaios hakimiyyətinə geri qaytardı", "4c0e4f10"], "d": ["Təxminən iyirmi illik separatçı idarədən sonra Ptolemaios komandanı Komanos Fivanı yerli fironu Ankhwenneferdən geri aldı və Yuxarı Misir yenidən Ptolemaios dövlətinə bağlandı.", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["Memphis sinodu Rosetta fərmanını verdi: V Ptolemaios məbədlərə vergi bəxşişi tanıdı", "5643b91f"], "d": ["Misir kahinlərinin Memphisdə topladığı sinod V Ptolemaiosun taxta çıxışını təsdiq edib kralın məbədlərə etdiyi vergi bəxşişlərini, üsyanların yatırılmasını və kral kultunun qurulmasını elan etdi. Fərman yunan, demotik və iyerogliflə yazıldı; Rosetta daşı bu üç dilli mətndir. Mətn eyni zamanda Deltadakı üsyançıların (Lykopolis) yatırıldığına işarə edir.", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["Panion döyüşü: III Antiochos Skopası məğlub etdi; Koile-Suriya Ptolemaioslardan Selevkilərə keçdi", "97e30e58"], "d": ["Beşinci Suriya müharibəsində III Antiochos Ptolemaios komandanı aitoliyalı Skopası Paneionda darmadağın etdi; Josephusa görə Antiochos Skopasın ələ keçirdiyi Koile-Suriya şəhərlərini geri alıb Samariyanı da aldı, yəhudilər öz razılıqları ilə Antiochosa qoşuldu. Koile-Suriya (Suriya-Fələstin) bundan sonra Selevki idarəsinə keçdi; Ptolemaios dövləti bölgədən çəkildi.", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["Fivada separatçı yerli fironlar çıxdı: Yuxarı Misir Ptolemaios hakimiyyətindən qopdu", "d10abb36"], "d": ["Raphia qələbəsindən sonra silahlandırılan yerli misirlilər Polybiosun ifadəsi ilə qələbədən şişib kralın əmrinə qulaq asmaz oldu; Delta və Yuxarı Misirdə üsyanlar baş verdi. Fivada yerli fironlar (Horwennefer, sonra Ankhwennefer) təxminən iyirmi il Ptolemaiosa qarşı Yuxarı Misiri əllərində saxladı.", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["Raphia döyüşü: IV Ptolemaios III Antiochosu məğlub etdi; Koile-Suriya Ptolemaiosda qaldı", "34362178"], "d": ["Raphiada IV Ptolemaiosun ordusu çoxlu sayda yerli misirli falanqs (hoplit) daxil olan tərkibi ilə III Antiochosun ordusunu məğlub etdi; Antiochos Koile-Suriyadan çəkildi və bölgə 200-ə qədər Ptolemaios əlində qaldı. Yerli misirlilərin silahlandırılması sonradan Yuxarı Misirdəki separatçı üsyanları qidalandırdı.", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["III Antiochos Seleukeia Pieriyanı Ptolemaioslardan geri aldı", "39ee3a52"], "d": ["III Antiochos Ptolemaios əlində olan Seleukeia Pieriyanı mühasirəyə alıb zabitlərə rüşvət verərək aldı; Polybios şəhərin III Ptolemaios zamanından bəri Misir krallarına aid qarnizon tərəfindən saxlandığını yazır. Bu qələbə ilə Selevkilər Antakya limanına qovuşub Koile-Suriyaya yürüşə hazırlaşdı (Dördüncü Suriya müharibəsi).", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["III Ptolemaios Laodike müharibəsində Suriyanı və Mesopotamiyanı işğal etdi; Seleukeia Pieria Ptolemaiosun əlinə keçdi", "04472253"], "d": ["II Ptolemaios e.ə. 246-cı il 28 yanvarda öldü; III Ptolemaios bacısı Berenikeni qorumaq üçün Selevki dövlətinə hücum etdi. Seleukeia Pieriada və Antakyada qarşılandı; Babil salnaməsi (BCHP 11) ordusunun e.ə. 246-cı il dekabrından etibarən Babilə dayandığını bildirir. Adulis kitabəsi Fəratın qərbini, Kilikiyanı, Pamfiliyanı və Frakiyanı fəth etdiyini iddia edir. Seleukeia Pieria uzun illər Ptolemaios əlində qaldı.", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["Ipsosdan sonra Ptolemaios Koile-Suriyanı işğal etdi; Seleukos etiraz etdi (Suriya müharibələrinin kökü)", "a109388f"], "d": ["Ipsos döyüşündən (e.ə. 301) sonra Seleukos, Lysimachos və Kassandros razılaşaraq Suriyanın hamısını Seleukosa verdi; Ptolemaios isə Koile-Suriyanı əsgərləri ilə işğal edib əlində saxladı. Bu anlaşılmazlıq sonrakı iki əsrdə altı Suriya müharibəsinə səbəb oldu. III Antiochos daha sonra bu iddianı Polybiosun nəql etdiyi kimi müdafiə etdi.", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["Ptolemaios özünü kral elan etdi; Ptolemaios sülaləsi rəsmən quruldu", "008c723a"], "d": ["Antigonos və Demetriosun kral titulu almasından (e.ə. 306) sonra Ptolemaios da kral titulunu aldı; Misir müstəqil Hellenistik krallıq kimi anılmağa başladı. Sülalənin Misirin fironu kimi təqdim edilməsi yerli kahin sinfi ilə razılaşmanı da sürətləndirdi.", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["Qəzzə döyüşü: Ptolemaios və Seleukos Demetriosu məğlub etdi (Suriya qısa müddət Ptolemaiosda)", "ea0d264f"], "d": ["Antigonosun oğlu Demetrios Qəzzə önündə Ptolemaios və Seleukosun birləşmiş ordusuna məğlub oldu; Ptolemaios Koile-Suriyaya girdi. Antigonosun əks-hücumu ilə bölgə qısa müddət sonra yenidən əldən çıxdı, sülh (e.ə. 311) bunu sabitləşdirdi.", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["Perdikkasın Misir yürüşü Nil keçidində uğursuz oldu; Perdikkas ordusunun əlində öldü", "c1792117"], "d": ["Diadoxlar müharibəsində İsgəndərin naibi Perdikkas İsgəndərin cənazə karvanını qaçıran Ptolemaiosa qarşı Misirə girdi, lakin Nili keçə bilmədi, çox sayda adam itirdi və zabitləri tərəfindən öldürüldü. Ptolemaios Misiri əlində saxladı.", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["Ptolemaios Kirenanı (Kyrenaika) Misirə birləşdirdi", "65316c50"], "d": ["Ptolemaios Kirenadakı daxili çəkişməyə müdaxilə edib Ophellasın komandanlığı ilə Liviyanın Kyrenaika bölgəsini Misirə bağladı. Beləliklə, Ptolemaios Misiri qərbə doğru da genişləndi; Kyrenaika sonrakı əsrlərdə Ptolemaios sülaləsinin bir qolunun əlində qaldı.", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["İsgəndər Siwa vahəsində Ammon kahininə müraciət etdi", "c437ced0"], "d": ["İsgəndər sahildən səhraya keçib Ammon məbədinin yerləşdiyi Siwa vahəsinə getdi və orakula müraciət etdi; Arrianos onun könlünü xoşlayacaq cavabı aldığını yazır. Bu ziyarət İsgəndərin Misirdəki məşruiyyətini və sonradan tanrının oğlu sayılması rəvayətlərini qidalandırdı.", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["İsgəndər Misirə girdi; Fars satrapı Mazakes təslim oldu, Misir Makedoniya idarəsinə keçdi", "c4a5f014"], "d": ["Qəzzədən yola çıxan İsgəndər yeddinci gün Pelusiuma çatdı, donanması da oraya gəlib çatmışdı. Issosdan sonra Fars dəstəyi qalmayan satrap Mazakes müqavimət göstərmədi, İsgəndəri şəhərlərdə dostcasına qəbul etdi. İsgəndər Pelusiuma qarnizon yerləşdirib Memphisə irəlilədi; idarəni iki yerli (Doloaspis, Petisis) qubernatora tapşırdı, Memphis və Pelusiuma Makedoniyalı komandanlar təyin etdi. Misir Fars hakimiyyətindən çıxıb İsgəndərin imperiyasına qatıldı.", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["III Artakserks Misiri yenidən fəth etdi; II Nektanebo Nubiyaya qaçdı", "55d78a8d"], "d": ["III Artakserksin Sidonu aldıqdan sonra Misirə yürüşündə Pelusium müdafiəsi çökdü; II Nektanebo Memphisdə mühasirəyə düşməyi gözləmədən Yuxarı Misirə və Nubiyaya qaçdı. Misir ikinci dəfə Fars satraplığı oldu; son yerli fironun aqibəti məlum deyil.", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["Takhos Suriya yürüşünə çıxdı; Nektanebo II çevrilişlə taxtı aldı, Agesilaos tərəf dəyişdi", "4e1e9804"], "d": ["Takhos Fars Suriyasına hücum etmək üçün yunan muzdlularını (Sparta kralı Agesilaos və afinalı Xabrias) topladı; yürüşdə ikən qardaşı oğlu Nektanebo II özünü kral elan etdi. Agesilaos Nektanebonun tərəfini tutdu; Plutarxos Agesilaosun qocalığında bir 'barbar üsyançı' üçün haqq müqabilində döyüşməsinin Yunanıstanda tənqid edildiyini yazır.", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["I Nektanebo Fars işğalını (Farnabazos-İfikrates) dəf etdi", "0a8bc67d"], "d": ["XXX sülalənin qurucusu I Nektanebo Farnabazosun komandanlığındakı Fars ordusunun və afinalı İfikratesin Deltaya çıxarmasını Nil daşqını və komandanlar arasındakı anlaşmazlıq sayəsində geri qaytardı. Bu uğur Misirin müstəqilliyini 30 il daha uzatdı.", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["İnarosun üsyanı: Afina dəstəkli Misir üsyanı Memphisdə Farsları sıxışdırdı, 454-cü ildə Prosopitisdə çökdü", "0cd93c33"], "d": ["Liviyalı İnaros Artakserksə qarşı Misirin demək olar ki, hamısını üsyana qaldırıb afinalılardan kömək istədi; Afina donanması Nilə girib Memphisin üçdə ikisini aldı, qalan 'Ağ Qala'nı mühasirəyə aldı. Fars komandanı Megabyzos afinalıları Prosopitis adasında bir il altı ay mühasirədə saxlayıb (kanalı qurudaraq) məhv etdi; İnaros əsir alınıb çarmıxa çəkildi. Delta bataqlıqlarındakı Amyrtaios isə tutula bilmədi.", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["Misir Fars hakimiyyətinə qarşı üsyan etdi; I Kserks üsyanı yatırıb Misiri daha ağır idarə etdi", "9d3d7462"], "d": ["I Dariusun ölümündən əvvəl başlayan Misir üsyanı I Kserksin ilk illərində yatırıldı; Kserks qardaşı Axaimenesi satrap təyin etdi və Misiri Darius dövründəkindən daha ağır idarə etməyə başladı.", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["Kambisin Kush yürüşü susuzluq və ərzaq çatışmazlığından uğursuz qaldı; Misirin cənub sərhədi Elefantində qaldı", "4ebbad8c"], "d": ["Kambis Misirdən sonra 'Uzunömürlü efiopiyalılara' (Kush) qarşı yürüş planlaşdırdı; Herodota görə Kush kralı Fars elçilərinə yayını göndərib 'yayı asanlıqla çəkə bildikdə' hücum etmələrini söylədi. Ordu səhrada ərzaqsız qalıb geri döndü. Strabon da Kambis ordusunun səhrada fırtınada məhv olduğu yeri xatırladır. Kush müstəqil qaldı; Farsların cənub sərhədi Elefantində dayandı.", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["Amasis Apriesi məğlub edib Misir taxtına çıxdı; yunan tacirlər Naukratisdə yerləşdirildi", "75a24b0b"], "d": ["Yunan muzdlularla Liviya yürüşündən qayıdan Apries ordudakı yerli birliklərin başına keçən Amasisə qarşı Momemphisdə məğlub oldu; Amasis Saisdən Misiri idarə etdi və yunanlara Naukratisi yeganə ticarət limanı kimi ayırdı. Hakimiyyətinin sonunda (e.ə. 526) Fars təhlükəsi böyüdü.", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["II Psamtik Nubiyaya yürüş etdi: Kushun Misir sərhədindəki təzyiqi qırıldı", "8f0aaf9d"], "d": ["II Psamtikin Nubiya yürüşü Herodotda 'Efiopiyaya yürüş' kimi xatırlanır; Misir ordusu və yunan/karyalı muzdlular Abu Simbelə yunanca yazılar qoydu. Fivadakı (Karnak) 3-cü il steləsi Kush krallığına ağır məğlubiyyət verildiyini bildirir və Kalabsha qələbə steləsi bunu xatırladır; yürüşün Üçüncü və ya Dördüncü şəlaləyə qədər irəlilədiyi sayılır. Mənbələrə görə, Kushun siyasi mərkəzi sonrakı dövrdə (Aspelta, təxminən e.ə. 591) cənuba, Meroeyə keçdi.", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["Nabukodonosor Misir sərhədinə hücum etdi; açıq döyüşdə iki tərəf ağır itki verdi, Babil geri çəkildi", "45655313"], "d": ["Babil kralı Nabukodonosor 4-cü ilində Misirə yürüdü; Misir kralı ordusunu toplayıb qarşılaşdı, açıq meydan döyüşündə iki tərəf bir-birini ağır şəkildə yıpratdı. Nabukodonosor Babilə dönüb ordusunu yenidən təchiz etməyə çəkildi. Misir sərhədini müdafiə etdi, lakin Suriya-Fələstin Babilə qalmışdı.", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["Karkamış döyüşü: Nabukodonosor Misir ordusunu məğlub etdi; Misir Suriyanı itirdi", "ba486ac1"], "d": ["Vəliəhd Nabukodonosor Babil ordusu ilə Karkamışda olan Misir ordusuna qarşı Fəratı keçib onu darmadağın etdi, qaçanları Hamat bölgəsində məhv etdi və bütün Hamat bölgəsini ələ keçirdi. Misir Suriyadan çəkilib Sinay sərhədinin gerisinə qayıtdı; Babil Suriya-Fələstinin sahibi oldu.", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["II Neko Suriya-Fələstinə girdi; Megiddoda Yosiyanı məğlub etdi və Fəratə doğru irəlilədi", "f887d6fd"], "d": ["Çöküşdə olan Assurinin qərb əyalətlərini ələ keçirməyə yönələn Neko II Suriyaya yürüdü; yolu üstündəki Yəhuda kralı Yosiyanı Megiddoda öldürtdü. Herodot 'Neko Magdolosda suriyalıları məğlub edib böyük Suriya şəhəri Kadytisi aldı' deyir. Beləliklə, Misir qısa müddət Suriya-Fələstini Fəratadək nəzarətdə saxladı.", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["Psamtik I qızı Nitokrisi Fivanın Tanrı Arvadına övladlığa verdirərək Yuxarı Misiri nəzarətə aldı", "bf768452"], "d": ["Psamtik I 9-cu ilində qızı Nitokrisin Kush kralı Taharkanın qızı Şepenwepetin (Fivanın Tanrı Arvadı) övladlığı kimi Fivaya göndərilməsini təmin etdi; Şepenwepet mülkünü Nitokrisə devr etdi və Fivanın məbəd sərvəti beləliklə Saislərin əlinə keçdi. Övladlığa götürmə steləsi Psamtikin 9-cu ilində Fivanın tam nəzarətini qazandığını və Tantamaninin Yuxarı Misiri həmin tarixədək itirdiyini göstərir.", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["Assur ordusu Fivanı talan etdi; Tantamani cənuba çəkildi, Kushun Misirdəki hakimiyyəti çökdü", "777fc1a5"], "d": ["Aşurbanipalın orduları Tantamanini Memphisdən qovub Fivaya qədər irəlilədi və şəhəri talan etdi; Fivanın məbəd xəzinələri Ninevaya daşındı. Tantamani Nubiyaya çəkildi; Yuxarı Misirdə Kush hakimiyyəti dağıldı. Bu talan Əhdi-Ətiqdə 'No-Amon' (Nahum 3:8) kimi xatırlanır.", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["XXVI sülalə başladı: I Psamtik Saisdə Assur vassalı kimi Aşağı Misirdə hakimiyyətə gəldi", "f270eac3"], "d": ["Assurinin Misirə yerləşdirdiyi Delta şahzadələri arasından Sais hökmdarı I Psamtik XXVI (Sais) sülaləsini başlatdı. Herodota görə Psamtik 'on iki kral' arasından seçilib bataqlığa sürgün edildi, Deltanı yenidən əldə etdi. Assur və Kushdan sonra Misir yenidən yerli sülalənin əlinə keçdi; Fiva və Yuxarı Misirin qazanılması bir neçə il çəkdi.", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["Tantamani Kushdan enib Fiva və Memphisi yenidən aldı; Assur vassallarını mühasirəyə aldı", "f84c87a4"], "d": ["Taharkanın varisi Tantamani Röya Steləsinə görə Napatada tac geyindikdən sonra çay boyu şimala endi: Elefantində Khnuma qurban gətirdi, Fivaya və Memphisə gəlib burada ona qarşı çıxanları qırğından keçirərək şəhəri aldı, Deltadakı bəylər isə gizləndi və ya itaət etdi. Bu cəhd Psamtik I və Assurinin Delta nizamını təhdid etdi və Assurinin cəza yürüşünü gətirdi.", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["Asarhaddon Misirə girib Memphisi aldı; Taharka cənuba çəkildi", "a138bcac"], "d": ["Assur kralı Asarhaddon 10-cu ilində Misirə yürüdü; Assur ordusu Misirdə böyük qırğın törətdi və Kush kralı Taharka cənuba qaçdı. Deltadakı knyazlıqlar Assur vassalı oldu, Memphis və Şimali Misir müvəqqəti olaraq Assurinin əlinə keçdi. Asarhaddon iki il sonra yeni yürüşə çıxarkən yolda öldü.", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["Sanxerib Yəhuda yürüşündə Kush-Misir ordusu ilə Eltekehdə qarşılaşdı", "7f423351"], "d": ["Assur kralı Sanxeribin Kənan yürüşündə Kushlu Misir ordusu Yəhudaya kömək üçün gəlib Eltekehdə Assurla vuruşdu; Assur ordusu Qüdsü ələ keçirə bilmədən geri çəkildi. Josephus Kush kralı Tirhakanın böyük orduyla gəldiyi xəbərini alan Sanxeribin Pelusiumdan ayrıldığını nəql edir. Bu, Kush-Misir ilə Assurinin ilk birbaşa toqquşmasıdır.", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["Piye (Pankhi) Misirə endi: Tefnaxt koalisiyasını məğlub edib Memphis və Delta hökmdarlarını itaətə gətirdi", "bb36f7c4"], "d": ["Saisli Tefnaxt Deltadan Memphisə və Orta Misirə uzanan ittifaq qurub Herakleopolisi mühasirəyə almışdı. Napatadan yürüş edən Piye 21-ci ilində şimala enib müttəfiq şəhərləri (Hermopolis, Memphis, Heliopolis) alaraq Delta şahzadələrinin təslimini qəbul etdi; ardınca Napataya qayıtdı. Beləliklə, Kush bütün Misirin başçısı oldu (25 sülalə).", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["Kush (Napata) kralı Kashta Yuxarı Misirə irəlilədi; Elefantin və Fivaya təsir göstərdi", "b0f5be7f"], "d": ["Napatadakı Kush kralları Misirin III Ara dövrdəki parçalanmasından istifadə edib şimala doğru güclənib. Kashtanın Elefantinə qədər Yuxarı Misirdə nüfuz qurduğu abidələrdən anlaşılır; Kush sülaləsindən Amenirdis I (Piyenin bacısı) Fivada Amonun 'Tanrı Arvadı' titulu ilə yerləşdirildi və bu vəzifə Kushun Fiva üzərindəki vasitəsi oldu. Beləliklə, 25 sülalənin qurulacağı zəmin hazırlandı.", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["Şoşenk Kənana yürüş etdi: Qüds və İsrail-Yəhuda şəhərləri Karnak siyahısına düşdü", "1607ae3a"], "d": ["Şoşenkin Kənan yürüşü Kral Rexabamın 5-ci ilində Qüdsdən xərac aldığını bildirən Tövrat rəvayəti ilə (1 Padşahlar 14:25) üst-üstə düşür; Karnakdakı Bubastit Qapısında təxminən 150 şəhər adı sıralanır (təxminən əlli-altmışı İsrailə, yüzü Yəhudaya aid). Josephus da Şişakın Qüdsü alıb xəzinəni apardığını nəql edir. Bu yürüş Misirin III Ara dövrdəki ən uzun xarici hərəkatıdır.", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["I Şoşenk (Meşveş/Liviya nəslindən) XXII sülaləni qurdu; paytaxt Bubastis", "dae122c7"], "d": ["Liviya mənşəli Meşveş generalları Yeni Krallıqdan sonra Deltada yerləşmişdi; bunlardan I Şoşenk Tanisdəki XXI sülalədən sonra Misiri yenidən birləşdirdi. Oğlunu Amon Baş kahini edərək Fivanı da sülaləyə bağladı. Bu dövr Misiri yenidən xarici siyasətə (Kənan yürüşü) yönəldən qısa bir dirçəliş təmin etdi.", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["Yeni Krallıq sona çatdı: XI Ramsesin son illərində Deltada Smendes (Tanis), Fivada Amon baş kahini faktiki müstəqil", "1828ceb0"], "d": ["XI Ramsesin son dövründə mərkəzi dövlət çökdü: Fivada Amon Baş kahini Herihor Yuxarı Misiri nəzarətdə saxlayır, Deltada Tanisdə Nesubenebded (Smendes) idarə edir; Wenamon Hekayəsi bu bölünməni (Wenamonun Herihordan Smendesə uzanan səyahəti) qeydə alır. Smendes sonda XXI sülaləni qurdu; Nubiya da bu qarışıqlıq içində Misirin nəzarətindən çıxdı.", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["III Ramses Dəniz Xalqlarını quruda (Djahy) və Deltada dənizdə məğlub etdi", "9068ae7b"], "d": ["III Ramsesin 8-ci ilində Peleset, Tjeker, Denyen, Şerden və digər Dəniz Xalqları quru və dənizdən Misir sərhədinə yönəldi; Misir ordusu əvvəl Kənan sərhədində, ardınca Delta ağızlarındakı dəniz döyüşündə onları dayandırdı. Medinet Habu barelyefləri bunu sənədləşdirir. Misir Kənanı yenidən əlində saxladı, lakin bu dövrdən sonra Şərqi Aralıq dənizindəki nüfuzu aşınmağa başladı.", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["Merneptah Liviya və Dəniz Xalqları ittifaqını qərbi Deltada məğlub etdi; Kənanda «İsrail» adı ilk dəfə xatırlandı", "e512311e"], "d": ["Merneptahın 5-ci ilində Libu rəhbərliyi ilə Meşveş və «Dənizdən Gələn Xalqlar» (Ekwesh, Teresh, Lukka, Şardana, Şekelesh) qərbi Deltanı işğal etdi; Misir ordusu Perirədə altı saatlıq döyüşdə onları dağıtdı. Eyni hadisələri nəql edən qələbə steləsi Kənanda Aşkelon, Gezer, Yenoam və «İsrail»i sadalayaraq adlandırır; bu, İsrail adının məlum ən qədim xatırlanmasıdır.", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["II Ramses ilə III Hattuşili arasında «Əbədi Müqavilə»: Misir-Xet müharibəsi sona çatdı", "100f2a75"], "d": ["II Ramsesin 21-ci ilində Xet elçiləri müqavilə lövhəsini Pi-Ramesseyə gətirdi. Müqavilə təxminən on beş illik Suriya müharibəsini bitirdi: iki tərəf Suriyada daha çox fəth planından əl çəkdi, müdafiə ittifaqı qurdu, qaçaqların təhvilini və qarşılıqlı yardımı qəbul etdi. Breastedin xülasəsinə görə, sərhəd mətndə göstərilmir; iki dövlətin təsir dairəsi faktiki vəziyyətdə (Kadeş-Amurru qurşağı Hattidə, Kənan Misirdə) qaldı.", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["II Ramses Kadeşdə II Muvatallinin xetlərini qarşıladı; nəticə bərabərliklə bitdi", "f5ad96db"], "d": ["II Ramses Orontes sahilindəki Kadeş önündə Xet ordusu ilə qarşılaşdı; Xet döyüş arabalarının pusqu qurması ilə Misir ordusu darmadağın olmaq həddinə gəldi, Ramses öz mühafizəçiləri ilə əks-hücum edib geri çevirdi. Döyüş qəti nəticə vermədi; Kadeş və Amurru Xet nəzarətində qaldı, Misirin şimal sərhədi yenə Kənan sahillərində qaldı.", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["I Seti Cənubi Kənandan Finikiya sahilinədək yürüş etdi: Misir Kənan və Livan sahili üzərində yenidən hakim oldu, Kadeşi aldı", "ad7bf1cd"], "d": ["Karnak barelyeflərinə görə I Setinin 1-ci il yürüşü əvvəl Şasu bədəvilərini, sonra Fələstin üzərindən şimala çıxıb Peher və Beth-Sheani, Yenoamı, Tiri və Livan bəylərini itaətə gətirdi. Barelyeflərin üst sırasında Kadeşin alınışı da göstərilir. Breasted daimi şimal sərhədinin Finikiya sahili boyunca şərq-qərb xəttinin o tərəfinə uzanmadığını və Xet gücünün qırılmadığını bildirir; bu, II Ramsesin Kadeş döyüşünün arxa planıdır.", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["Amarna dövründə Misirin Şimali Suriyadakı hakimiyyəti dağıldı; Amurru və Kadeş Xet təsir dairəsinə keçdi", "90d00c5a"], "d": ["Amarna məktubları (EA) Şimali Suriya vassallarının (Amurrudan Aziru, Kadeş hökmdarları) Misir, Mitanni və Hatti arasında manevr etdiyini və Misirin bölgəyə müdaxilə edə bilmədiyini göstərir. Xet kralı I Şuppiluliumanın Mitannini zəiflədən yürüşləri nəticəsində Amurru və Kadeş Xet təsirinə düşdü; beləliklə, Misirin Suriyadakı şimal sərhədi Kənana geri çəkildi.", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["IV Amenhotep (Axenaton) Misirin paytaxtını Axetatona (Amarna) köçürdü", "53cadac3"], "d": ["Axenaton Aton ibadətini dövlət dini edib Orta Misirdə səhraya açılan yeni bir şəhəri (Axetaton) paytaxt elan etdi; şəhər sərhədlərini müəyyənləşdirən «Sərhəd Steləri» 4-5-ci illərə tarixlənir. Amarna məktubları bu dövrdə Suriya vassallarının kömək istədiyini, lakin Misirin cavab vermədiyini göstərir.", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["II Amenhotep Nubiyada Napataya çatdı və cənub sərhəd steləsi dikdi: Misirin ən cənub nöqtəsi", "2f61f824"], "d": ["II Amenhotep Suriya yürüşündən qayıdarkən (iyul) Nubiyaya keçdi; Elefantin və Amadadakı məbəd yazılarına görə Suriyadan gətirilən yeddi şahzadədən altısını Fiva divarlarına, yeddincisini Napata divarlarına asdırdı. Breastedə görə kral Napatada və ya onun hələ yuxarısında cənub sərhədini göstərən stela dikdi: Misirin Nubiyadakı faktiki hakimiyyəti beləliklə Tombosun (Üçüncü şəlalə) o tərəfində Dördüncü şəlalə bölgəsinədək uzandı.", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["III Tutmos Fəratı keçib Mitanni torpaqlarına girdi; Naharində sərhəd steləsi dikdi", "ebdbeebe"], "d": ["33-cü ildə III Tutmos Retenudan irəliləyib Fəratı keçdi, Naharinin qəsəbələrini talan etdi və çayın şərqində sərhəd steləsi dikdi; atasının steləsinin yanına ikinci bir stela qoydu. Bu yürüş Misir təsirinin şimaldakı ən uzaq nöqtəsidir və Mitanni ilə birbaşa toqquşma astanasını göstərir.", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["III Tutmos Megiddoda Kadeş rəhbərliyindəki Kənan koalisiyasını məğlub etdi; Kənan-Suriya Misir hakimiyyətinə girdi", "439dc6e8"], "d": ["III Tutmosun 23-cü il, 1-ci Shemu ayının 21-ci günü Megiddo önündə Kadeş hökmdarının başında olduğu Kənan koalisiyasını məğlub etdi; düşmən şəhərə qaçdı və Megiddo uzun bir mühasirədən sonra təslim oldu. Karnak salnamələrində qeyd olunan bu yürüş Misirin Kənan və Cənubi Suriya üzərindəki asılılığını daimiləşdirdi və imperiyanın genişlənməsinin başlanğıcı oldu.", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["I Tutmos Fərat sahilinədək (Naharin) uzanan Asiya yürüşü etdi", "50ce0679"], "d": ["Ahmose-Pennekhbet və Ahmose-Ebana yazılarına görə I Tutmos Nubiya yürüşündən sonra Naharinə böyük bir yürüş təşkil etdi; III Tutmos daha sonra Fərat üzərində atasının dikdiyi sərhəd steləsinin yanına öz steləsini əlavə edir. Bu, Misir təsirinin Fəratadək uzandığı ilk qeydə alınmış dövrdür.", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["Ahmose Aşağı Nubiyaya yürüş edib Nubiya yaylaq sakinlərini yatırdı", "dbbd94b7"], "d": ["Ahmose asiyalıları məğlub etdikdən sonra çay boyu cənuba, Khent-hen-neferə çıxıb Nubiya yaylaq sakinlərini yatırdı. Bu yürüş Orta Krallıq qala xəttindən bəri Kermanın əlində olan Aşağı Nubiyanın Misirə qatılması prosesinin ilk addımıdır.", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["Ahmose Hiksosların paytaxtı Avarisi aldı və Şaruheni mühasirəyə alıb süquta uğratdı", "b7bb3099"], "d": ["Ahmose Şərqi Deltadakı Avarisi mühasirəyə alıb aldı; Hiksoslar Asiyaya qaçdı və onları Cənubi Kənandakı Şaruhenə qədər qovdu. Ebana oğlu Ahmosenin yazısı Şaruhenin 6 il mühasirədə saxlandığını bildirir. Beləliklə, Misirin Deltası Hiksos nəzarətindən çıxdı və Misir Kənana siyasi nüfuz göstərə biləcək vəziyyətə gəldi.", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["I Ahmose Fivada taxta çıxdı; XVIII sülalə və Yeni Krallıq dövrü başladı", "0798cfa3"], "d": ["Fivadakı XVII sülalənin son kralı Kamosenin qardaşı Ahmose uşaq yaşında taxta çıxdı; səltənəti boyu Hiksosu Misirdən qovub Nubiya və Kənana hakimiyyəti yenidən quracaq, XVIII sülalə və Yeni Krallıq dövrünü başlayacaqdı. Taxta çıxış Hiksosun sonu deyil, mübarizənin son mərhələsinin başlanğıcıdır.", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["Misir ikiyə bölündü: Hiksoslar (XV sülalə) Avarisdən Aşağı və Orta Misiri, Fivadakı XVII sülalə Yuxarı Misiri idarə etdi", "cd743737"], "d": ["Şərqi Deltadakı Avarisdə yerləşmiş Kənan mənşəli «əcnəbi hökmdarlar» (Hiksos) XV sülaləni qurub Aşağı Misiri və Orta Misiri Kusaeyə (Kusiyə) qədər idarə etdi; Fivadakı yerli XVII sülalə isə Yuxarı Misiri əlində saxladı. Fivanın cənubunda Kerma krallığı müstəqil güc kimi dayandı. Avarisin Hiksos paytaxtı olduğu Ahmosenin mühasirə rəvayəti ilə Breastedda təsdiqlənir.", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["III Sesostris Semnədə Misirin cənub sərhədini II şəlaləyə çəkdi; nubiyalıların keçidini qadağan etdi", "753ef5fd"], "d": ["III Sesostrisin 8-ci il tarixli Semne steləsi «cənub sərhədi»ni müəyyən edir: nubiyalıların ticarət üçün Ikenə gələnlər istisna olmaqla, quru və ya çay yolu ilə bu xətti keçməsi qadağandır. Kral Aşağı Nubiyada qala zənciri (Buhen, Semne, Kumme, Uronarti və s.) qurub Kermanın şimala açılmasını dayandırdı. Bu, Orta Krallığın Nubiyadakı ən cənub daimi sərhədidir.", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["I Amenemhat XII sülaləni qurdu; paytaxt Itj-tawyə köçürüldü", "26c43dad"], "d": ["Vəzir ikən kral olan I Amenemhat XII sülaləni qurdu və paytaxtı Fivadan Memphis ilə Fayum arasındakı yeni şəhərə (Itj-tawy) köçürdü. Bu sülalə Orta Krallığın ən sabit dövrünü və Nubiyaya yönəlik qala sistemini qurdu.", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["II Mentuhotep Herakleopolisi məğlub edib Misiri yenidən birləşdirdi (Sematawy)", "dbc6136f"], "d": ["Səltənətinin 39-cu ilinə doğru II Mentuhotep Herakleopolisi aradan qaldıraraq Yuxarı və Aşağı Misiri vahid idarəyə bağladı və titullarına «İki Torpağı birləşdirən» (Sematawy) adını əlavə etdi. Mərkəzi idarə Fivaya köçürüldü; nomarxların səlahiyyətləri azaldıldı.", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["II Mentuhotep Fivada taxta çıxdı; Orta Krallıq dövrü başladı və Herakleopolisə qarşı müharibə şiddətləndi", "edde038d"], "d": ["II Mentuhotepin uzun səltənəti (51 il) Orta Krallığın başlanğıcı sayılır. Səltənətinin ilk yarısında Fiva Herakleopolislə müharibə vəziyyətində idi; 14-cü ilində Herakleopolis qüvvələrinin Abydosdakı müqəddəs qəbiristanlığı pozması üzərinə kral şimala ordu göndərdi. Misirin faktiki birləşməsi isə çox sonra, səltənətinin 39-cu illərində baş verdi (aşağıdakı maddə).", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["Fivada XI sülalə başladı: Intef sülaləsi Yuxarı Misirdə müstəqil krallıq qurdu", "0e021743"], "d": ["Fiva nomarxları Intef nəslindən krallıq titulunu aldı və Yuxarı Misirin cənub ucunda (Elefantindən Abydosa) öz krallıqlarını qurdu. Sonrakı Intef Abydosun yerləşdiyi Tinis nomosunu ələ keçirdiyini və «bütün qalalarını açdığını» yazısında bildirir; beləliklə, Fiva-Herakleopolis sərhədi Abydos ətrafında çəkildi.", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["Herakleopolisdə (Henen-nesut) IX-X sülalə: Şimali Misiri Kheti sülaləsi idarə etdi", "9dde2d0c"], "d": ["I Ara dövrdə Memphisin boşluğunu Herakleopolisdəki sülalə doldurdu; Orta Misirdəki Siut qubernatoru Tefibi kimi sadiq nomarxlar cənuba (Fivaya) qarşı bu krallığın tərəfində vuruşdu. Siut məzar yazısı cənublularin Elefantindən şimala irəlilədiyini və «cənub sərhədi»nə qədər geri oturdulduğunu nəql edir. Misir beləliklə Herakleopolis (Şimal) və Fiva (Cənub) olmaqla iki əsas gücə bölündü.", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["Qədim Krallıq çökdü: II Pepidən sonra mərkəzi dövlət dağıldı, I Ara dövr başladı", "0339e96b"], "d": ["Çox uzun sürən II Pepi səltənətindən sonra VI sülalə sona çatdı; krallıq nomarxların (əyalət qubernatorlarının) faktiki müstəqil olduğu bölgələrə ayrıldı. Məzar yazıları (Siut, Elefantin və s.) yerli qubernatorların öz adlarına tarix verib öz əsgərlərini səfərbər etdiyini göstərir. Memphisdəki qısaömürlü VII-VIII sülalələr bütün ölkəyə nəzarət edə bilmədi.", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["Elefantin qubernatoru Harkhufun Yam diyarına yürüşləri: Nubiyanın o tərəfində diplomatik-ticari əlaqə", "705b9808"], "d": ["Elefantin qubernatoru Harkhuf Merenre və II Pepi üçün cənuba, Yam ölkəsinə bir neçə səfər etdi; yazısında hakim olduğu yol və gətirdiyi məhsullar təsvir olunur. Uşaq kral II Pepinin ona yazdığı məktub da məzar yazısında qorunub saxlanıb. Bu səfərlər Qədim Krallığın cənub sərhədində Kerma öncəsi/Qədim Kerma icmaları ilə təmasın qeydləridir.", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["VI sülalədə Weninin komandanlığı ilə Kənan sərhədinə və nubiyalı birliklərlə böyük yürüş", "69c94c55"], "d": ["Weninin tərcümeyi-halına görə kral «Asiyalı Qum Sakinləri»nə qarşı on minlərlə nəfərlik ordu topladı; ordu Cənubi Misirdən (Elefantinə qədər), Şimaldan və ayrıca Nubiya tayfalarından (Irtjet, Medja, Yam, Wawat, Kau) cəlb olunan birliklərdən ibarət idi. Mətn Qədim Krallığın Nubiyadan əsgər ehtiyatı kimi istifadə etdiyini və Cənubi Kənana qədər yürüş edə bildiyini göstərir.", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["Hufunun (Xeops) Gizadakı Böyük Piramidası inşa edildi", "282359fc"], "d": ["IV sülalə hökmdarı Hufunun Gizadakı piramidası Qədim Krallığın iş gücü və resurs səfərbərliyinin rəmzidir. Herodotun nəql etdiyi Misir kahin rəvayəti Hufunu məbədləri bağlayıb xalqı daş daşımağa məcbur edən zalım kimi təsvir edir; bu halı ilə sonrakı dövrün baxışıdır, müasir sənəd deyil.", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["Djoser (III sülalə) taxta çıxdı; Qədim Krallıq dövrü və Saqqara Pilləli Piramidası", "23e99ef4"], "d": ["Djoserin (Netcherikhet) hakimiyyəti ilə Memphis mərkəzli Qədim Krallıq başlayır; daş memarlığın ilk böyük nümunəsi olan Pilləli Piramida onun üçün tikildi. Bu dövrdə dövlət Nil vadisini və Deltanı mərkəzdən idarə edir; Sinay mədən ocaqları və Nubiya sərhədi (Elefantin) dövlətin nəzarətindədir.", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["Narmer (Menes) Yuxarı və Aşağı Misiri birləşdirdi; I sülalə və Memphis paytaxt oldu", "cd3fadb1"], "d": ["Yuxarı Misirin (Tinis/Abydos ətrafı) hökmdarı Narmer, əksər misirşünaslara görə Menesla eyni şəxsdir. Aşağı Misiri idarəsinə qatması ilə Nil vadisi və Delta ilk dəfə vahid dövlət oldu. Qədim rəvayətə görə Menes Nilin yatağını yönləndirərək Memphisin yerini saldı; birləşmə tək hadisə deyil, Naqada III-dən davam edən uzun prosesin nəticəsidir.", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["Vespasianus İskəndəriyyədə imperator elan edildi: Misirin taxıl mənbəyi vətəndaş müharibəsinin taleyini müəyyənləşdirdi", "02b78348"], "d": ["Misir prefekti Tiberius Alexander İskəndəriyyədəki legionlara Vespasianus adına sədaqət andı içdirdi; and 1 iyulda içildi və Vespasianus bu günü öz taxta çıxış günü saydı. Yəhudi ordusu iki gün sonra Vespasianusun hüzurunda and içdi. Misirin taxıl istehsalı bu təşəbbüsün strateji dayağı sayılır.", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["Misirdə, Kirenada və Kiprdə yəhudi üsyanı: Trayan hakimiyyətində Roma bölgəni çətinliklə yatırdı", "54787782"], "d": ["Trayanın Parfiya yürüşü davam edərkən Kirenada yəhudilər Andreasın rəhbərliyi ilə romalıları və yunanları qırdı; Dioya görə Misirdə və Kiprdə də oxşar hadisələr baş verdi və ölənlərin sayı yüz minlərlə ifadə edildi. Trayanın göndərdiyi Lusius Quietus üsyanı yatırdı; Kipr adasına yəhudilərin girişi qadağan edildi.", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["Bukoli üsyanı: Deltadakı bir üsyan İskəndəriyyəni təhdid etdi, Avidius Cassius yatırdı", "5f94e6bf"], "d": ["Deltanın Bukoli (çobanlar) adlandırılan əhalisi Isidorus adlı bir kahinin rəhbərliyi ilə üsyan etdi; Dioya görə üsyançılar bir Roma birliyini məğlub edib İskəndəriyyəni ələ keçirməyə az qalmışdı. Suriyadan göndərilən Cassius üsyançıların birliyini pozaraq qiyamı yatırdı.", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["Avidius Cassius Suriyada və Misirdə özünü imperator elan etdi; üç ay sonra öldürüldü", "ce33ca9d"], "d": ["Şərq əyalətlərinin komandanı Cassius Marcus Aureliusun ölümü xəbəri ilə imperatorluq elan etdi; üsyan Suriyaya və Misirə yayıldı (Misir qubernatoru Flavius Calvisiusun üsyanla əlaqəsi səbəbindən sonradan öldürülmədən bir adaya sürgün edildiyi Dioda keçir). Cassius Dioya görə üç ay altı gün davam edən bir 'imperatorluq röyasından' sonra öz zabitlərindən biri tərəfindən öldürüldü; Marcus Aurelius Misiri və Suriyanı ziyarət edib heç kimi cəzalandırmadı.", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["Palmira (Zenobia) Misiri işğal etdi; Roma generalı Probus məğlub oldu", "54568441"], "d": ["Zenobia adından hərəkət edən Palmira generalı Zabdas yetmiş minlik ordusu ilə Misirə girdi; Roma generalı Tenagino Probus İskəndəriyyəni bir müddət geri aldı, lakin məğlub olub Babylon qalasına çəkildi, əsir götürüləndə intihar etdi. Misir Zenobia adından bir-iki il Palmira dövlətinin tərkib hissəsi sayıldı.", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["Domitius Domitianus Misirdə imperator elan edildi; Diocletianus Fivanı və ardınca İskəndəriyyəni mühasirəyə alaraq üsyanı yatırdı", "3c765005"], "d": ["Vergi islahatına və Roma birliklərinin Parfiya cəbhəsinə çəkilməsinə reaksiya olaraq Misirdə Domitius Domitianus 297-ci ilin iyul-avqustunda Augustus elan edildi; İskəndəriyyə daxil olmaqla Misirin böyük hissəsi onu tanıdı. Diocletianus payızda Fiva üsyançılarını yatırıb İskəndəriyyəni mühasirəyə aldı; Domitianus 297-ci ilin dekabrında öldü, şəhərin müdafiəsini Aurelius Achilleus davam etdirdi və şəhər təxminən səkkiz ay davam edən mühasirədən sonra böyük ehtimalla 298-ci ilin martında təslim oldu.", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["Diocletianus Misirin cənub sərhədini Elefantin/Philae xəttinə çəkdi; Aşağı Nubiya Nobataeyə tərk edildi", "725574bb"], "d": ["Prokopios Diocletianusun Misirin ən cənubundakı geniş səhranı (Dodekaschoinos) əlində saxlamağın dəyərini görüb Elefantinin cənubunu Nobatae və Blemmyeslərə tərk etdiyini, sərhədi Elefantində sabitləşdirdiyini (müqabilində illik ödəniş bağlandığı da nəql edilir) təsvir edir. Roma idarəsi beləliklə Augustusun çəkdiyi Hiera Sykaminos sərhədindən geri çəkildi.", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["Aksum kralı Ezana Kushu məğlub etdi; Meroe krallığı sona çatdı (təxminən b.e. 350)", "7c9d95d7"], "d": ["Noba və Blemmyes təzyiqi ilə zəifləyən Kush krallığına Aksum kralı Ezana hücum etdi; Ezananın yazıları Noba və Kasu (Kush) xalqlarına qarşı yürüşünü nəql edir, Meroedə Aksum qələbəsinə aid parçalanmış iki yunan yazısı tapılmışdır. Meroedəki son piramidalar IV əsrin ortalarına tarixlənir; Kush dövləti dağılıb Nobatia, Makuria və Alodia krallıqlarına ayrıldı.", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["Teofil İskəndəriyyədəki Serapeumu dağıtdırdı: Misirdə bütpərəst ibadət mərkəzi bağlandı", "119a26c7"], "d": ["I Theodosiusun bütpərəst kultları qadağan edən fərmanlarından sonra İskəndəriyyə yepiskopu Theophilos Serapis məbədini (Serapeum) dağıtdırdı; şəhərdə xristianlarla bütpərəstlər arasındakı gərginlik bu hadisədə zirvəyə çatdı. Müqəddəs mətn və kitab kolleksiyalarının aqibəti mübahisəlidir.", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["I Theodosius öldü; imperiya daimi olaraq ikiyə bölündü, Misir Şərqi Romada (Arcadius) qaldı", "54a12472"], "d": ["Theodosiusun ölümü üzərinə oğulları Arcadius Şərqi, Honorius Qərbi aldı; Misir Roma taxıl ehtiyacının əsas təminatçısı olmasına baxmayaraq Şərq imperiyasının (Bizans) əyaləti qaldı və sonrakı əsrlərdə Konstantinopolun taxıl mənbəyi oldu.", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["Xalkedon Konsili: İskəndəriyyə patriarxı Dioskoros məhkum edildi; Misir kilsəsi imperiya kilsəsindən ayrıldı", "5d2d05c6"], "d": ["Xalkedon Konsili Misirin İskəndəriyyə patriarxı Dioskorosu məhkum edəndə Misir xristianlarının əksəriyyəti qərarları qəbul etmədi; beləliklə, Misirdə Qibti (Misir) kilsəsi ilə imperiya kilsəsi (Melkitlər) ayrıldı. Bu bölünmə sonrakı əsrlərdə Misirin Bizansdan siyasi uzaqlaşmasının zəminini hazırladı.", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["Augustus ilə IV Phraates arasında müqavilə: Crassusun Roma bayraqları qaytarıldı", "be5f8bda"], "d": ["Crassus və Antoniusun itmiş Roma bayraqları IV Phraates tərəfindən diplomatik jestlə Augustusa geri verildi. Müqavilə Fəratı Roma-Parfiya sərhədi kimi möhkəmləndirdi və Ermənistanı bufer olaraq qoydu.", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["Pakoros və Labienus Suriya və Fələstini işğal etdi", "68669aa1"], "d": ["Parfiya şahzadəsi Pakoros və Romadan qaçıb Parfiyaya sığınan Labienus Romanın Suriya əyalətlərini işğal edib Antakyanı və Fələstini aldı. Antoniusun generalı Ventidius 38-də Parfiyanı Gindarosda məğlub edib bölgəni geri aldı.", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["Carrhae (Hərran) döyüşü: Surena Crassusun Roma ordusunu məhv etdi", "3a91cd75"], "d": ["Crassusun Roma legionları Hərran yaxınlığında Parfiya süvarisi və atlı oxatanlarına məğlub oldu; Crassus öldürüldü. Döyüş Romanın Şərqdə ən ağır məğlubiyyətlərindən biridir və Fərat sərhədini Parfiya xeyrinə möhkəmləndirdi.", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["Sulla ilə Parfiya elçisi Orobazos Fəratda görüşdü; Roma-Parfiya ilk diplomatik təması", "f8913f2b"], "d": ["Kappadokiya qubernatoru Sulla Parfiya kralı II Mithradatesin elçisi Orobazosla Fərat sahilində görüşdü; Roma və Parfiya ilk dəfə rəsmi təmas qurdu. Fərat daha sonra iki dövlətin sərhədi olacaqdır.", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["VII Antiochos Sidetes Parfiyaya qarşı yürüşdə öldü; Selevki Mesopotamiyanı geri ala bilmədi", "e5897112"], "d": ["Antiochos VII Sidetes 130-129-da Parfiyadan Mesopotamiya və Mediyanı geri aldı, lakin qışlaq düşərgəsində üsyan və Parfiya hücumu ilə ordusunu və öz həyatını itirdi. Bu uğursuzluq Selevkilərin şərq iddiasına son qoydu.", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["Parfiya II Demetrios Nikatoru əsir aldı; Selevki Babil və Mesopotamiyanı qəti olaraq itirdi", "94a764ce"], "d": ["I Mithradatesin Parfiya ordusu Selevki kralı II Demetriosu tutdu və onu Parfiya sarayında saxladı. Mithradates Mesopotamiyanı Parfiya imperiyasına qatdı; Selevki dövləti sahilə sıxışıb Suriyaya çəkildi.", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["Makkabilər üsyanı: Yəhudiyyədə IV Antiochosun dini qadağalarına qarşı üsyan başladı", "41c25b76"], "d": ["IV Antiochos Epifanes Qüds məbədini Zeus Olympiosa həsr edib yəhudi dini ayinlərini qadağan edəndə Modeində Mattatiya və oğulları üsyan etdi. Yəhuda Makkabi 164-də məbədi geri alıb təmizlədi (Hanuka); Hasmonaylar dövləti doğuldu.", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["I Mithradates Parfiya taxtına çıxdı; Parfiya imperiyasının genişlənmə dövrü başladı", "cc77639b"], "d": ["Mithradates I Parfiyanı imperiyaya çevirdi: Mediyanı (147), Babil və Seleukeiyanı (141) aldı, Elymais və Persis üzərində hakimiyyət qurdu. Ktesifon sonradan qış paytaxtı olacaqdır.", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["Apameia müqaviləsi: Selevki Toros dağlarının qərbindən çəkildi, təzminat ödədi", "f5197a70"], "d": ["Roma ilə III Antiochos arasındakı müqavilə Torosun qərbindəki Anadolunu Roma müttəfiqlərinə (Pergamon, Rodos) verdi; Selevki donanması və fil sayı məhdudlaşdırıldı, 15.000 talant təzminat ödənildi. Selevki artıq Suriya-Mesopotamiya dövləti halına gəldi.", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["III Antiochosun şərq yürüşü (209-204): Parfiya və Baktriya kralları Selevki xərac vergisinə bağlandı", "5c81f302"], "d": ["Antiochos III Selevkilərin itmiş şərq torpaqlarını geri almaq üçün Mediya, Parfiya və Baktriyaya yürüdü: Arsakes II və Euthydemos xərac vergisinə bağlandı. Bu yürüşdən sonra Antiochos “Böyük” titulunu aldı.", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["Arsakes I və Tiridates Parthavanı alıb Parfiya (Arsakid) dövlətini qurdu", "2cd572ca"], "d": ["Parni köçəri tayfasının lideri Arsakes Selevki satrapı Andragorası devirib Parthavanı ələ keçirdi və Parfiya krallığının ilk kralı oldu; paytaxtı Hekatompylosdur. Parfiya dövləti sonrakı üç əsr Mesopotamiya və İranın hakimi olacaqdır.", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["Baktriya satrapı Diodotos Selevkidən ayrıldı; Greko-Baktriya krallığı doğuldu", "52faafa6"], "d": ["Baktriya və Soqdiana satrapı Diodotos II Antiochosun zəifliyindən istifadə edib müstəqilliyini elan etdi. Greko-Baktriya Selevki dövlətinin şərq sərhədini Parthava və Baktriyadan geri çəkilməyə məcbur etdi.", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["I Suriya müharibəsi (274-272): Selevki qüvvələri Dəməşqi geri aldı; sülh bağlandı", "0c17ee3d"], "d": ["Antiochos I qalatları “fil döyüşü” (275) ilə məğlub edib təhlükəsizliyi təmin edəndən sonra II Ptolemaiosla yenidən vuruşdu: Selevki generalı Dəməşqi geri aldı, Magas Misirə hücum etdi, sonda 272-də sülh bağlandı. Müharibə Koile-Suriya üzərində Ptolemaios-Selevki çəkişməsinin başlanğıcıdır.", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["Karia müharibəsi: II Ptolemaios İoniya, Karia, Likiya, Pamfiliya və Kilikiyanın bir hissəsini Antiochos I-dən aldı", "afe190ca"], "d": ["II Ptolemaios qısa və uğurlu yürüşlə Anadolunun cənub və qərb sahilini aldı, Dəməşqə çatdı; Antiochosun qüvvəsinin atasından aşağı olmadığını görüb atəşkəs bağladı. Antiochos itkini qəbul etdi, çünki Anadolu daxilindəki atasının fəthlərini nizama salmalı idi.", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["I Selevki Ptolemaios Keraunos tərəfindən öldürüldü; I Antiochos taxta çıxdı", "4703b674"], "d": ["Kuropedionda Lysimachosu məğlub edib Anadolunu alan Selevki Avropaya keçərkən Ptolemaios Keraunos tərəfindən xəncərlə öldürüldü. Oğlu I Antiochos dövləti təhvil aldı, lakin Qərbi Anadoluda çətinlik çəkəcəkdir.", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["I Selevki Antiokheyanı (Antakya) qurdu", "f4b98967"], "d": ["Selevki İpsosdan sonra Suriyada Orontes sahilində öz atasının adına Antiokheyanı qurdu; şəhər Selevki krallığının qərb paytaxtı və Qədim dövrün ən böyük şəhərlərindən biri oldu. Dəclə üzərindəki Seleukeia daha əvvəl şərq paytaxtı kimi qurulmuşdu.", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["İpsos döyüşü: Selevki və Lysimachos Antigonosu məğlub etdi; Suriya Selevkiyə keçdi", "93bf2aa9"], "d": ["Diadox müharibələrinin həlledici döyüşündə Selevki və Lysimachos Antigonosu məğlub etdi (Antigonos döyüşdə öldü). Şərqin hamısı və Suriya Selevkinin payına düşdü; Ptolemaios isə Koile-Suriyanı işğal edərək ilk Suriya müharibələrinin səbəbini yaratdı.", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["I Selevki Dəclə üzərində Seleukeiyanı qurdu", "032efabd"], "d": ["Selevki Babilin yaxınlığında Dəclə sahilində Seleukeiyanı qurub Babil əhalisini bura köçürməyə başladı. Seleukeia təxminən 300 min əhalisi ilə Şərqin ən böyük Hellenistik şəhəri və sonra Parfiya imperiyasının paytaxt qonşusu oldu.", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["I Selevki Hindistanda Çandragupta Maurya ilə müqavilə bağladı; Arakosiya, Gedrosiya və Paropamisadai Mauryaya verildi", "3ef3bdee"], "d": ["Selevki İsgəndərin Hind satraplıqlarını geri almaq üçün Hindistana yürüdü, lakin Çandragupta ilə razılaşıb şərq torpaqlarının bir hissəsini 500 döyüş fili ilə dəyişdi. Müqavilə Maurya imperiyasının qərb sərhədini Hindukuşa çatdırdı və Selevkiyə Qərb üçün fillər təmin etdi.", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0309-01-01:0":{"b": ["IV Aleksandros anası Roxane ilə öldürüldü; Argead sülaləsi sona çatdı", "3be9d974"], "d": ["311 sülhündən sonra Kassandrosun əmri ilə (Diodora görə cəllad Glaukias) on iki yaşlı IV Aleksandros və anası Roxane öldürüldü. İsgəndər imperiyasının nominal hökmdarı qalmadı; diadoxlar öz krallıqlarını elan etməyə (e.ə. 306-305) yönəldi.", "46aa8fb2"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["İsgəndər Persepolisə çatdı; şəhər və xəzinə Makedoniya əlinə keçdi", "c1dbaada"], "d": ["Susadan sonra Fars Qapılarını keçən İsgəndər 330-cu ilin yanvar sonunda Persepolisə çatdı; şəhər müqavimət göstərmədən təslim oldu. Persepolisin Həxamənişi mülkiyyəti bu il sona çatır (saray 330-cu ilin mayında yandırıldı).", "de8726c8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:1":{"b": ["Persepolis saraylarının yandırılması (aprel)", "6e6cdfe0"], "d": ["İsgəndər 330-cu ilin aprelində Persepolisdə bir neçə saray binasını yandırtdı; xəzinənin düşmən əlinə keçməməsi və hələ tək hökmdar olmaması əsaslandırması verilir. Kserks sarayının da yandığı arxeoloji olaraq görülür; şəhərin hamısı tərk edildi.", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-07-01:0":{"b": ["III Dara Baktriya satrapı Bessosun adamları tərəfindən öldürüldü; Həxamənişi sülaləsi sona çatdı", "bedcca87"], "d": ["Ekbatanadan qaçıb şərqə gedən III Dara 330-cu ilin iyulunda Parfiyada Bessos və tərəfdarları tərəfindən yaralanıb tərk edildi və öldü; İsgəndər cəsədi Persepolisə göndərdi. Həxamənişi imperiyasının faktiki sonu.", "dc8ceef3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["Qaugamela döyüşü: İsgəndər III Daranın ordusunu qəti şəkildə məğlub etdi", "a5b082d7"], "d": ["Qaugamelada Daranın çoxlu sayda döyüş arabası və süvarisindən ibarət ordusu İsgəndərin sol cinah müdafiəsini yarıb içəri girdiyi hücumda dağıldı; Dara yenə qaçdı. Döyüş Fars imperiyasının sonunu müəyyənləşdirdi; Babil və Susa qapılarını açdı.", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-22:0":{"b": ["İsgəndər Babilə girdi; Mazaios şəhəri təslim etdi və Babil satraplığı İsgəndərə keçdi", "c8d2afb3"], "d": ["Qaugameladan sonra Babil satrapı Mazaios qapıları İsgəndərə açdı; İsgəndər Marduk məbədinin təmirini əmr etdi və şəhərdən 34 gün istifadə etdi. Babil Fars idarəsindən Makedoniya idarəsinə keçdi.", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-12-15:0":{"b": ["İsgəndər Susanı aldı; Fars xəzinəsi ələ keçirildi", "fbf417db"], "d": ["Babildən ayrılan İsgəndər Susaya girdi; satrap Abulites şəhəri və böyük xəzinəni təslim etdi. Susa Makedoniyanın şərq yürüşü üçün maliyyə əsası oldu.", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["Sur mühasirəsi: İsgəndər adadakı şəhəri doldurma yolu ilə alıb dağıtdı", "89ede146"], "d": ["Fars donanmasının bazası Sur adasını İsgəndər yeddi ayda süni keçid tikərək aldı; şəhər talan edildi, əhalinin böyük hissəsi öldürüldü və ya qul edildi. Fars dəniz gücü beləliklə çökdü və Misirə gedən yol açıldı.", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["Issos döyüşü: İsgəndər III Daranı məğlub etdi; Dara ailəsini qoyub qaçdı", "3803fc30"], "d": ["Dar sahil düzənliyində III Daranın böyük ordusu İsgəndərə məğlub oldu; Fars kralı ailəsini və xəzinəsini qoyub qaçdı. Issos qələbəsi Suriya və Finikiya sahilinin, ardınca Misirin İsgəndərə keçməsini təmin etdi.", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["Qranikos döyüşü: İsgəndər Fars satraplarını məğlub etdi", "1aae30d4"], "d": ["Makedoniya kralı İsgəndər 334-cü ilin mayında Asiyaya keçdi, iyun əvvəlində Qranikosda Fars satraplarını məğlub etdi. Qərbi Anadolunun qapıları açıldı; Sardes və İoniya şəhərləri İsgəndərə təslim oldu.", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["III Dara Fars taxtına çıxdı (Arsesin öldürülməsi)", "706f8a9f"], "d": ["Saray məmuru Bagoas IV Artakserksi öldürdü; Ermənistan satrapı Artašata III Dara (Codomannus) adı ilə kral oldu. 336-cı ilin oktyabrında Makedoniyada Filipp öldürüldü və İsgəndər taxta keçdi.", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["III Artakserks öldü; IV Artakserks (Arses) taxta çıxdı", "d38e2edc"], "d": ["III Artakserks 338-ci ilin yayında təbii səbəblərdən (Diodorun zəhərləmə hekayəsinə baxmayaraq) öldü; Arses taxta çıxdı. Misir və Babil üsyanları, Makedoniya kralı Filippin Anadolu hazırlıqları eyni dövrə təsadüf edir.", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["III Artakserks Saydanı alıb dağıtdı; Tennes üsyanı yatırıldı", "d1b533cc"], "d": ["Sayda kralı Tennesin Misir dəstəkli Fars əleyhinə üsyanı zamanı III Artakserks şəhəri ələ keçirdi; Tennes farslara xəyanət etdi, şəhər özünü yandırdı və çox sayda adam öldü. Finikiya şəhərləri yenidən Fars nəzarətinə girdi və Misirin fəthinin yolu açıldı.", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["Kral sülhü (Antalkidas): Anadolu yunan şəhərləri və Kipr Farsa verildi", "17e871ad"], "d": ["Fars kralı II Artakserksin diktə etdirdiyi sülhlə Asiyadakı yunan şəhərləri və Kipr Farsa məxsus sayıldı, yunan şəhərlərinə muxtariyyət tanındı. Sparta Farsın sözçüsü olaraq sülhü tətbiq etdi.", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["Kunaksa döyüşü: Gənc Kyros böyük qardaşı II Artakserksə məğlub oldu və öldü", "90346087"], "d": ["Gənc Kyros yunan muzdlularından ibarət On Minliklə Babilə yürüyüb böyük qardaşı II Artakserksə Kunaksada məğlub oldu və döyüşdə öldü. On Minliklərin Qara dənizə qayıdış yürüşü Ksenofontun Anabasisində nəql edilir.", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["Kserks Hellespontu keçdi; Thermopylai və Afinanın alınışı", "9bf22df1"], "d": ["Kserks böyük ordusu ilə Thermopylaidə Leonidasın Sparta-müttəfiq birliyini məğlub edib Attikaya girdi; Afina boşaldılıb Akropolla birlikdə yandırıldı. Fars ordusu Yunanıstanın ortasınadək irəlilədi.", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["Salamis dəniz döyüşü: Yunan donanması Fars donanmasını darmadağın etdi", "010e3aab"], "d": ["Themistoklesin komandanlığındakı Yunan donanması Salamisdə Fars donanmasını dar boğazda məğlub edərək dəniz üstünlüyünü ələ keçirdi. Kserks quru ordusunun çoxu ilə Asiyaya qayıtdı, Mardonios Yunanıstanda qaldı.", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["Babildə Bêl-šimânni və Šamaš-eriba üsyanları I Kserks tərəfindən yatırıldı", "ebcef5a9"], "d": ["I Kserksin səltənətinin əvvəlində Babildə iki üsyan baş verdi (Bêl-šimânni, Šamaš-eriba). Kserks üsyanları yatırdı; Babil satraplığını bölüb şəhərin imtiyazlarını azaltdı.", "015c253c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0493-01-01:0":{"b": ["Lade dəniz döyüşü: Fars donanması İon donanmasını məğlub etdi; Miletos süqut etdi", "86396cf1"], "d": ["Farsların Finikiya ağırlıqlı donanması Ladedə İon donanmasını darmadağın etdi; Miletos mühasirəyə alınıb dağıdıldı, əhalisi Mesopotamiyaya sürgün edildi. İon üsyanı sona çatdı və İoniya yenidən Fars nəzarətinə girdi.", "b72ba00d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0497-01-01:0":{"b": ["İoniyalılar Sardesi yandırdı", "adf677bd"], "d": ["İoniyalılar və afinalı-eretriyalı birliklər Fars satraplıq mərkəzi Sardesə yürüyüb şəhəri yandırdı. Dara bundan sonra Afinanı cəzalandırmaq qərarı aldı; hadisə Marafon yürüşünün səbəbidir.", "32e33dce"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0498-01-01:0":{"b": ["İon üsyanı başladı: Aristagorasın Naksos yürüşü uğursuz olanda İoniya yunan şəhərləri Farsa qarşı qalxdı", "aab8ff2f"], "d": ["Miletos tirani Aristagorasın Naksos yürüşü çökəndə İoniya şəhərləri tiranlarını devirib Afina və Eretriyadan kömək istədi. Bu üsyan Fars-Yunan müharibələrinin fitilidir.", "7d70c2ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0512-01-01:0":{"b": ["Dara İstrosu (Tuna) keçib İskit yürüşünə çıxdı; Frakiya Fars satraplığına qatıldı", "a5891101"], "d": ["Dara Bosfor üzərindən körpü ilə Frakiyaya keçdi, getləri itaətə gətirib Tunanı keçdi və İskitlərə qarşı yürüşə çıxdı. İskitləri məğlub edə bilməsə də, Megabazos Frakiya və Makedoniya sahilini Fars hakimiyyətinə qatdı.", "f464fbf8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-05-08:0":{"b": ["Daranın ordusu Mediya üsyançısı Fravartişi (Phraortes) məğlub etdi", "4a9c4633"], "d": ["Mediyada özünü Kyaksaresin nəslindən kral elan edən Fravartişin ordusu məğlub oldu; Fravartiş qaçarkən Ragaidə (Tehran yaxınlığı) tutulub işgəncə ilə öldürüldü. Mediya yenidən Fars əyaləti oldu.", "efea5aea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-12-28:0":{"b": ["Daranın generalı Marqiana üsyançısı Fradanı məğlub etdi; son böyük qiyam yatırıldı", "76e0ea1c"], "d": ["Baktriya satrapı Dâdarši Qaraqum səhrasından 300 km yürüyüb Marqiana üsyançısı Fradanı 521-ci il dekabrın 28-də məğlub etdi. Daranın ilk səltənət ilində on doqquz döyüşlə bütün üsyanlar yatırılmış oldu.", "5c0c9cfa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-03-11:0":{"b": ["Qaumata (Bardiya) Fars taxtını ələ keçirdi; Kambis Misirdən qayıdarkən öldü", "1606d9c1"], "d": ["Bisütun yazısına görə kahin Qaumata özünü Kyrosun oğlu Bardiya (Smerdis) elan edib 522-ci ilin martında taxta çıxdı; Kambis Suriyada öldü. Dara və altı zadəgan 522-ci il sentyabrın 29-da Qaumatanı öldürdü.", "f143e726"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-09-29:0":{"b": ["Dara və altı zadəgan Qaumatanı öldürdü; I Dara Fars taxtına çıxdı", "08897d54"], "d": ["Dara altı zadəgan yoldaşı ilə Mediyadakı Sikayauvati qalasında saxta Bardiyanı öldürdü. Qaumatanın ölümü imperiyanın bir çox yerində üsyanları alovlandırdı; Dara bir il ərzində on doqquz döyüşlə bunları yatırdı.", "daebf974"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-12-18:0":{"b": ["Dara Babili geri aldı; Nidintu-Bêl (III Nabukodonosor) tutulub öldürüldü", "365cdd51"], "d": ["Qaumatanın ölümü üzərinə Nidintu-Bêl özünü Nabonidin oğlu və III Nabukodonosor elan edib Babili Fars hakimiyyətindən qopardı. Daranın ordusu dekabrın 13-də şişirdilmiş tuluqlarla Dəclədən keçib üsyan ordusunu darmadağın etdi, dekabrın 18-də Babil geri alındı və Nidintu-Bêl öldürüldü. Susadakı Elam qiyamı bu zaman yatırıldı.", "4bd29dc6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0529-01-01:0":{"b": ["Kyros öldü; oğlu Kambis taxta çıxdı", "de69f4d5"], "d": ["Kyros Herodota görə masagetlər ölkəsində döyüşdə öldü (Ksenofonta görə sarayında öldü); ölüm xəbəri 530-cu ilin dekabrında Babilə çatdı və sənədlər «Kambisin birinci ili» kimi tarixləndi. Kambis Misirin fəthi ilə imperiyanı genişləndirdi.", "9900a295"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:0":{"b": ["Kyrosun fərmanı: Babil sürgünündəki yəhudilər Qüdsə qayıda bildi, məbədin yenidən inşasına icazə verildi", "715eac6b"], "d": ["Babili alan Kyros sürgün xalqların tanrı heykəllərini geri göndərib yerlərinə qayıtmalarına icazə verdi (Kyros silindri). Tövrat (Ezra 1:1-4) bu fərmanı yəhudilər üçün ayrıca nəql edir: sürgündə olanlar Qüdsə qayıda və məbədi yenidən tikə bilər. Bölgə Fars satraplığı «Yehud» oldu.", "a8c7f81c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:1":{"b": ["Finikiya şəhər dövlətləri (Sur, Sayda, Cübeyl) Fars idarəsini qəbul etdi; Fars donanmasının nüvəsi oldular", "d9f7f277"], "d": ["Babilin süqutu ilə Finikiya sahili «Çayın o tayı» (Ebir-Nari) satraplığı daxilində Fars idarəsinə girdi. Finikiya donanmaları Fars dəniz gücünün onurğası oldu; Sidon və Sur imtiyazlı daxili idarə hüququnu qoruyub saxladı.", "bb0c17fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-01-01:0":{"b": ["Opis döyüşü: Kyros Dəclə sahilində Babil ordusunu məğlub etdi", "d91708c6"], "d": ["Kyrosun farsları Dəclə üzərində Opisdə Akkad ordusunu qarşılayıb məğlub etdi; Babil əhalisi geri çəkildi, talan və qırğın törədildi. Döyüş Babilin iki həftə sonra süqutunun yolunu açdı.", "20739fbd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-10:0":{"b": ["Sippar döyüşsüz farslara keçdi; Nabonid qaçdı", "47f6d3a5"], "d": ["Opis döyüşündən sonra 14 Tašrituda Sippar döyüşmədən Kyrosun əlinə keçdi, Nabonid qaçdı. Farslar iki gün sonra Babilə girəcəkdir.", "5a23a85c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-12:0":{"b": ["Qobryas (Ugbaru) komandanlığındakı Fars ordusu döyüşsüz Babilə girdi; Yeni Babil sona çatdı", "f67bf0e3"], "d": ["Qutium qubernatoru Ugbaru (Qobryas) və Kyrosun ordusu 16 Tašrituda toqquşmadan Babilə girdi; Nabonid tutuldu. Esaqilada ayinlər pozulmadı. Kyros 3 Arahsamnuda (29 oktyabr) şəhərə girdi və Babil imperiyası Fars hakimiyyətinə keçdi.", "891c267b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-29:0":{"b": ["Kyros Babilə girdi; Babilin nəzarəti Həxamənişilərə keçdi və Qobryas qubernator təyin edildi", "fd45fa83"], "d": ["Kyros 3 Arahsamnuda Babilə girdi; şəhər əhalisini salamladı və Gubarunu (Qobryas) şəhər qubernatoru etdi. Nabonidin şəhərə topladığı Akkad tanrı heykəlləri Kislîmu-Addaruda yerlərinə qaytarıldı. Oğlu Kambis vəliəhd kimi Nabû ayinində iştirak etdi.", "17d2bc46"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0546-01-01:0":{"b": ["Kroisos Halysi keçdi, Pteriyanı aldı; Kyrosla Pteria döyüşü həll olunmadan bitdi", "eee7aef1"], "d": ["Kroisos Delfi kahinliyinə güvənərək Halysi keçdi, Pteriyanı mühasirəyə alıb Kappadokiya suriyalılarını qovdu. Kyrosla edilən qanlı döyüş nəticəsiz qalınca Kroisos Sardesə qayıdıb müttəfiq orduları topladı; Kyros ani yürüşlə onu Thymbrada məğlub etdi və Sardes süqut etdi.", "419ac6ed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0551-01-01:0":{"b": ["Nabonid Teyma (Ərəbistan) vahəsinə yerləşdi, Babilə gəlmədi; Akitu bayramı keçirilə bilmədi", "2ce93701"], "d": ["Nabonid Teyma vahəsində qalarkən vəliəhd Belşazar ordusu ilə Akkadda gözlədi; aprel ayında kral gəlmədiyi üçün Marduk Babilə girmədi və Yeni il (Akitu) bayramı keçirilə bilmədi. Bu, məbəd kahinlərinin Nabonidə qarşı Kyrosu dəstəkləmə əsaslarından biri olmuşdur.", "d1e857db"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0555-01-01:0":{"b": ["Nabonid çevrilişlə Babil taxtına çıxdı", "b7ab73ce"], "d": ["Nabukodonosorun ölümündən (562) sonra Amel-Marduk, Neriglissar (559-556) və qısamüddətli Labaşi-Marduk gəlmişdi; Nabonid kral nəslindən olmadığı halda 556-da çevriliş etdi. Ay tanrısı Sinə xüsusi bağlılığı Marduk kahinlərini küsdürdü.", "6b2f9204"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0559-01-01:0":{"b": ["Kroisos Lidiya taxtına çıxdı; Efes və İoniya yunan şəhərlərini xərac vergisinə bağladı", "5544cfa4"], "d": ["Kroisos atası Alyattesin ölümündən sonra Efesi, ardınca digər İoniya, Aiolis və Karia yunan şəhərlərini xərac verən etdi. Lidiya Anadolunun qərbindən Halysadək tək siyasi birlikdir; Kroisosun xəzinəsi və Delfiyə hədiyyələri əfsanəyə çevrildi.", "88136bde"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0584-01-01:0":{"b": ["Halys (Qızılırmaq) döyüşü: günəş tutulması üzərinə Alyattes ilə Kyaksares sülh bağladı; Halys Lidiya-Mediya sərhədi oldu", "9ababdd3"], "d": ["Alyattes ilə Mediya kralı Kyaksaresin beş illik müharibəsi gündüz baş verən günəş tutulması üzərinə sülhlə nəticələndi; Kilikiya kralı Syennesis və Babil kralı «Labynetos» vasitəçilik etdi. Halys çayı iki krallığın sərhədi oldu və Mediya Anadolunun içinə qədər yayılmış sayıldı.", "ddab1c12"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:0":{"b": ["Nabukodonosor Suru mühasirəyə almağa başladı; mühasirə on üç il davam etdi", "5b753ca0"], "d": ["Josephusa (Apiona qarşı 1.156) görə Nabukodonosor kral Ithobaal zamanında Suru on üç il mühasirədə saxladı. Şəhər sonda sülh/vassallıq nizamı ilə sona çatdı; Sur Babil təsirinə girərkən adadakı şəhərin müstəqil idarəsi davam etdi.", "0975583d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:1":{"b": ["Qüds dağıdıldı, Süleyman məbədi yandı; Yəhuda krallığı sona çatdı, əhali Babilə sürgün edildi", "c9f78b2a"], "d": ["Sedekiyanın Babilə qarşı üsyanı üzərinə Nabukodonosor Qüdsü ikinci dəfə alıb yandırdı; məbəd dağıdıldı və əhalinin böyük hissəsi Babilə sürgün edildi (Babil əsarəti). Yəhudanın müstəqil dövlət kimi mövcudluğu sona çatdı.", "f53414ac"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0596-03-16:0":{"b": ["Nabukodonosor Qüdsü aldı; kral Yehoyakin əsir aparıldı, yerinə Sedekiya keçdi", "55b14c31"], "d": ["Babil ordusu «Yəhuda şəhəri»ni mühasirəyə alıb 2 Addaruda aldı; kral Yehoyakin əsir edilərək Babilə aparıldı və yerinə Babilin seçdiyi Sedekiya (Mattanya) qoyuldu. Şəhər ilk dəfə Babil hakimiyyətinə girdi.", "12a9d088"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0599-01-01:0":{"b": ["Urartu qalaları dağıdıldı və yandırıldı; dövlət çökdü", "6be90688"], "d": ["Karmir-blur kimi qalalarda görülən yanğın qatı e.ə. 600-dən əvvəl İskit/Kimmer axını, Midiyalılar və ya başqa bir düşmənin Urartunu dağıtdığını göstərir. Assur mənbələrinin kəsilməsi səbəbindən son kral III Rusadan sonrakı tarix qeyri-müəyyəndir; Urartu bir müddət sonra Həxamənişi satraplığı (Armina) oldu.", "1e7ff200"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0603-12-01:0":{"b": ["II Nabukodonosor Aşkelonu aldı, kralını əsir etdi və şəhəri xarabalığa çevirdi", "7429839d"], "d": ["Nabukodonosorun ilk ilində «Hatti ölkəsinin bütün kralları» ona xərac gətirdi; yalnız Aşkelon müqavimət göstərdi. Şəhər Kislîmu ayında alındı, kral əsir edildi və şəhər xarabalıq təpəsinə çevrildi.", "a455db32"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0604-09-07:0":{"b": ["Nabopolassar öldü, II Nabukodonosor Babil taxtına çıxdı", "bce88c5a"], "d": ["Babil kralı Nabopolassar 21 illik səltənətdən sonra 8 Abuda (15 avqust 605) öldü; Karkamışda qələbə qazanan Nabukodonosor ölkəyə qayıdıb 1 Ulûluda (7 sentyabr 605) taxta oturdu. Dörd illik yürüşlər Hatti ölkəsini (Suriya-Fələstin) Babilə bağladı.", "b519ffaa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:0":{"b": ["Hərran süqut etdi; Aššur-uballit II Misirə çəkildi", "b2d122c2"], "d": ["Ninevanın süqutundan sonra Assurinin son kralı Aššur-uballit II Hərrana çəkilmişdi; Midiyalılar və babillilər Hərrana yürüyəndə Assur və Misir birlikləri şəhəri buraxıb Fəratın o tayına çəkildi. Nabopolassar Hərranı alıb talan etdi.", "cb81464b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:1":{"b": ["Alyattes Lidiya taxtına çıxdı; Kimmerləri Anadoludan qovdu və krallığı genişləndirdi", "160e291d"], "d": ["Alyattes uzun səltənətində Kimmerləri Qərbi Anadoludan təmizləyib Miletosla vuruşdu; Mediya ilə Halys sərhədində qarşılaşanadək krallıq sərhədlərini Anadolunun ortasına çatdırdı.", "54aee50b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0613-01-01:0":{"b": ["Kyaksares ilə Nabopolassar Aşşur önündə ittifaq müqaviləsi bağladı", "650f0e5a"], "d": ["Midiyalılar Aşşuru alanda gecikən Babil kralı Nabopolassar şəhər yaxınlığında Mediya kralı ilə görüşüb ittifaq qurdu. Berossosa görə bu bağ Nabukodonosorun Kyaksaresin qızı Amytis ilə evliliyi ilə möhkəmləndi.", "450ae215"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0624-01-01:0":{"b": ["Kyaksares (Umakištar) Mediya taxtına çıxdı", "67896ea0"], "d": ["Herodot ənənəsinə görə Kyaksares qırx il hökm sürdü, Mediyanı birləşdirib Assura qarşı yürüşə çıxdı. Babillə ittifaq (614) və Ninevanın alınışı (612) onun səltənətindədir; Mediya bu illərdə ən geniş sərhədlərinə çatdı.", "4094aac8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0630-01-01:0":{"b": ["Aşurbanipal öldü; Assurda taxt çəkişməsi və Babil üsyanı başladı", "dbe19d8c"], "d": ["Aşurbanipalın ölümü Assuru iki vəliəhd arasında bölünmüş qoydu. Babil qubernatorları Sin-şum-lişir və Sin-şar-işkuna qarşı qalxdı; imperiyanın on il içində çöküşü başladı.", "9537e9f3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0644-01-01:0":{"b": ["Aşurbanipal Susanı dağıtdı; Yeni Elam krallığı çökdü", "cb341293"], "d": ["Elamın Babillə birlikdə Assura qarşı üsyan etməsinin cəzası olaraq Aşurbanipal Susanı alıb talan etdi, məbədləri dağıtdı və tanrı heykəllərini Ninevaya daşıdı. Elam yarımmüstəqil knyazlıqlar halında Fars/Anşan təsirinə girdi.", "327f1322"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0647-01-01:0":{"b": ["Babil Şamaş-şuma-ukin üsyanından sonra Aşurbanipala tabe oldu", "d6964932"], "d": ["Aşurbanipalın qardaşı, Babil kralı Şamaş-şuma-ukin 652-də Assura qarşı qalxdı; Elam və ərəb müttəfiqləri müvəqqəti dəstək verdi. Dörd il davam edən müharibə Babilin süqutu ilə bitdi və Şamaş-şuma-ukin öldü.", "b038173f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0651-01-01:0":{"b": ["Kimmerlər Sardesi talan etdi; Gyges öldü", "950e5f80"], "d": ["Kimmer axını Gordiondan (696/695) sonra Lidiyaya da uzandı və Sardesin aşağı şəhərini talan etdi. Assur mənbələri Lidiya kralı Gugunun (Gyges) Kimmerlərə qarşı Assur yardımı axtardığını bildirir; Gyges bu döyüşlər zamanı və ya sonrasında öldü.", "93736177"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0652-01-01:0":{"b": ["Til-Tuba/Ulay döyüşü: Aşurbanipal Elam kralı Teummanı məğlub edib öldürdü", "177e87cf"], "d": ["Aşurbanipal Elam kralı Teummanı Susa yaxınlığındakı Ulay (Karun/Karkheh) sahilində məğlub edib öldürdü; başı Ninevaya aparıldı. Döyüş Elamın Assur-Babil çəkişməsində oynadığı rolun sonunu hazırladı.", "3aa28a86"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0663-01-01:0":{"b": ["Aşurbanipal Fivanı (Thebes) talan etdi", "179269c7"], "d": ["Esarhaddonun ölümündən sonra Misirdə Kuş üsyanı Tanutamunla yenidən alovlanınca Aşurbanipal Yuxarı Misirə girdi və Fivanı talan etdi. Assur Misiri faktiki olaraq əlində saxlamaqda çətinlik çəkdi və qısa müddətdə çəkildi.", "c292bcf0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0676-01-01:0":{"b": ["Esarhaddon Saydanı dağıdıb Kar-Esarhaddon adı ilə yenidən qurdu", "bd713ae6"], "d": ["Sayda kralı Abdi-Milkutti Assura qarşı üsyan edəndə Esarhaddon şəhəri dağıtdı, kralı başı kəsilərək öldürdü və şəhərin yerində Kar-Esarhaddon («Esarhaddon limanı») adında Assur əyalət mərkəzi qurdu.", "2a506319"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0684-01-01:0":{"b": ["Gyges Kandaulesi devirib Mermnad sülaləsini qurdu", "37e46a38"], "d": ["Herodota görə Gyges saray mühafizəçisi ikən kral Kandaulesi devirib Lidiya taxtını ələ keçirdi və Mermnad sülaləsini qurdu. Frigiyanın Kimmer hücumu ilə çöküşündən sonra Lidiya Qərbi Anadolunun əsas gücü olmağa başladı.", "e477b6b5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0688-01-01:0":{"b": ["Sennacherib Babili dağıtdı, məbədləri talan etdi və Fəratı şəhərə axıtdı", "82265d98"], "d": ["Babilin təkrarlanan üsyanları üzərinə Sennacherib şəhəri alıb dağıtdı, Marduk heykəlini apardı və kanal sularını şəhərə axıtdı. Babil Esarhaddonun təmirinə qədər yarım əsr xarabalıq qaldı; dağıntı Assurinin Babil siyasətinin ən sərt addımıdır.", "e4312fee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:0":{"b": ["Sennacherib Yəhudanı işğal etdi; Lakişi aldı, Qüdsü mühasirəyə aldı", "dc11fa2d"], "d": ["Hizkiyanın Assura qarşı üsyanını yatıran Sennacherib Yəhudanın qırx altı şəhərini alıb Lakişi fəth etdi, Qüdsü mühasirəyə aldı. Hizkiya ağır xərac ödəyərək şəhəri xilas etdi; Ninevadakı Lakiş barelyefləri bu yürüşü göstərir.", "ebc2ce02"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:1":{"b": ["Sennacherib Saydanı aldı; kral Luli Kiprə qaçdı", "41bb1358"], "d": ["Sennacherib 701-də Finikiya şəhərlərini itaətə gətirdi: Sidon kralı Luli (Elulaios) Kiprə qaçdı, Sayda və Surun tabe şəhərləri Assura keçdi. Yəhuda yürüşünün öncəsində bu fəthlərlə qərb sahili təmin edildi.", "3b2c6518"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0704-01-01:0":{"b": ["II Sargon Tabalda döyüşdə öldü; Sennacherib taxta çıxdı", "2f6ae581"], "d": ["II Sargon Anadoluda Tabal kralı Gurdiyə qarşı yürüşdə öldü və cənazəsi xilas edilə bilmədi. Oğlu Sennacherib sarayı Ninevaya köçürdü; atasının Dur-Şarrukin şəhəri tərk edildi və bir çox əyalət üsyan etdi.", "21ee2771"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0711-01-01:0":{"b": ["II Sargon Malatyanı (Melid) aldı; Gunzinanu sürgün edildi", "3ef6a5c9"], "d": ["Melid (Malatya) kralı Gunzinanu Tabal və Urartu ilə əməkdaşlıq etdiyi üçün Sargon tərəfindən məğlub edildi və krallığı Assur əyaləti oldu. Anadolunun şərqində Yeni Xet hakimiyyəti beləliklə sona çatdı.", "281f75fd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0713-01-01:0":{"b": ["II Sargon Urartuya girdi: I Rusa məğlub oldu, Musasir talan edildi və Haldi heykəli alındı", "38992d24"], "d": ["Sargonun səkkizinci yürüşü Urartunu Urmiyə gölü ətrafından aşağı talan etdi; Musasirdəki Haldi məbədi soyuldu. Kral I Rusa ağır məğlubiyyət qarşısında özünü öldürdü (rəvayət). Urartu bir daha Assura qarşı böyük təşəbbüs göstərə bilmədi.", "7d05af4c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0716-01-01:0":{"b": ["II Sargon Karkamışı aldı; Pisirisin krallığı Assur əyaləti oldu", "cfcc3ee4"], "d": ["Karkamış kralı Pisiris Assura qarşı Midas (Mita) ilə ittifaq qurmağa cəhd etdi; Sargon şəhəri alıb sürgünlər həyata keçirdi. Karkamışın bir yarım əsrlik müstəqilliyi sona çatdı və Fərat sərhədi Assura keçdi.", "87f1f2e6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0719-01-01:0":{"b": ["II Sargon Həmanı (Hamat) məğlub etdi, Karkarda Yau-bidini öldürüb krallığı əyalət etdi", "aeca8edc"], "d": ["Hamat kralı Yau-bidi Sargona qarşı qurulan Suriya-Fələstin koalisiyasının başında idi; Sargon Karkarda onu məğlub edib şəhəri dağıtdı, Hamat Assur əyalətinə çevrildi.", "70e2d509"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0732-01-01:0":{"b": ["III Tiglat-Pileser Qalileya və Gileadı İsraildən alıb Assur əyalətləri etdi", "0b59ead2"], "d": ["Pekahın İsrailı Dəməşqlə birlikdə Assura qarşı çıxanda III Tiglat-Pileser şimali İsraili (Qalileya, Gilead, Megiddo ətrafı) Assur əyalətlərinə çevirib sürgünlər həyata keçirdi; Pekahın yerinə Hoşea keçdi. İsrail krallığı Samariya və ətrafındakı dağlıq bölgəyə endirildi.", "28d3a30e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0733-01-01:0":{"b": ["III Tiglat-Pileser Qəzzəni aldı; Fələstin sahili Assur nəzarətinə girdi", "1c89131f"], "d": ["Tiglat-Pileser Fələstin sahil zolağına yönəlib Qəzzə kralı Hanunuyu Misirə qaçırtdı və şəhəri hakimiyyətinə aldı. Fələstin şəhər dövlətləri sonrakı illərdə Assurinin vassal zolağına çevrildi.", "ff623a4d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0742-01-01:0":{"b": ["III Tiglat-Pileser Arpad yaxınlığında Urartu kralı II Sardurini məğlub etdi", "7478a232"], "d": ["II Sardurinin Suriya dövlətlərini müstəqilliyə yönəltmə cəhdi III Tiglat-Pileserin qələbəsi ilə nəticələndi. Urartu Suriyadakı nüfuzunu itirdi; Assur Anadolu və Suriya üçün heç bir rəqib qoymadı.", "b851f23b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0744-01-01:0":{"b": ["III Tiglat-Pileser taxta çıxdı; Assur əyalət sistemi quruldu", "b5889059"], "d": ["Kalhuda üsyanla taxta keçən III Tiglat-Pileser vassal krallıqların yerinə Assur qubernatorlarını qoyaraq əyalət sistemini oturtdu; Babili şəxsi birlik ilə bağladı və Dəməşq, Qəzzə, İsrail üzərinə yürüşlər təşkil etdi. Sonrakı imperiyaların (Babil, Fars, Selevki) istifadə etdiyi idarə nizamı buradan gəlir.", "7deb8187"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0795-01-01:0":{"b": ["III Adad-nirari Dəməşq kralı Marini məğlub etdi, xərac aldı", "3e01dbfa"], "d": ["III Adad-nirari Dəməşq kralı Marini (Bar-Hadad) məğlub edib böyük xərac aldı; Aram-Dəməşqin daxili gücü zəiflədi və İsrail bir müddət rahat nəfəs aldı.", "c5c0a66d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0809-01-01:0":{"b": ["Minua Urartunu Van gölündən Araz vadisinə, Urmiyə gölünə qədər genişləndirdi", "d77231e4"], "d": ["Minua və oğlu I Argişti dövründə Urartu Van gölü mərkəzindən Araz və Urmiyə gölü ətraflarınadək bütün yüksək ölkəni əhatə edən krallığa çevrildi. Tuşpa (Van) yeni yaşayış və suvarma işləri ilə genişləndirildi.", "289fc554"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0839-01-01:0":{"b": ["Moab kralı Meşa İsraildən müstəqilliyini elan etdi (Meşa steləsi)", "e9c264b2"], "d": ["Meşa steləsi Moab kralı Meşanın İsrail himayəsindən qurtuluşunu və Omri sülaləsinə qarşı qazandığı qələbələri nəql edir. Tövrat və stela birlikdə Omri sülaləsinin zəiflədiyi dövrü göstərir.", "ffefe5fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0840-01-01:0":{"b": ["III Şalmaneser Hazaeli məğlub etdi, Dəməşqi mühasirəyə aldı; İsrail kralı Yehu xərac ödədi", "93aacc56"], "d": ["III Şalmaneser Aram-Dəməşq kralı Hazaeli Şanir (Hermon) dağında məğlub edib Dəməşqi mühasirəyə aldı; İsrail kralı Yehu Qara Obeliskdə Assura xərac təqdim edərkən göstərilir. Karkar koalisiyası dağıldı və Assur qərbdə hakim güc oldu.", "2992ec0c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0852-01-01:0":{"b": ["Karkar döyüşü: III Şalmaneser Dəməşq-Hamat-İsrail koalisiyası ilə qarşılaşdı", "9a736e92"], "d": ["III Şalmaneser Dəməşq kralı Hadad-ezer (Adad-idri), Hamat kralı Irhuleni və İsrail kralı Axab daxil on iki kralın koalisiyası ilə Karkarda vuruşdu. Assur sənədləri qələbə iddia etsə də irəliləyişini dayandırmağa məcbur qaldı; koalisiya illərlə Assuru saxladı.", "524874c7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0857-01-01:0":{"b": ["III Şalmaneser Urartu (Arame) üzərinə yürüşlər başlatdı; Urartu ilk dəfə Assur mənbələrində göründü", "375ce993"], "d": ["III Şalmaneser səltənətinin ilk illərində kral Aramenin Urartu torpaqlarına yürüdü; Assur salnamələri bu yürüşlərdə Urartunu «Urartu ölkəsi» adı ilə ilk dəfə xatırlayır. Sonrakı əsrlərdə bu bölgədə Assurinin baş rəqibi olacaq dövlətin ilk tarixli qeydidir.", "759a75b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0876-01-01:0":{"b": ["II Aşşurnasirpal Fəratı keçib Karkamışdan və Yeni Xet/Arami dövlətlərindən xərac aldı", "5e385948"], "d": ["II Aşşurnasirpal qərb yürüşündə Fəratı keçib Karkamış, Patina və Finikiya sahilinə çatdı, xərac topladı. Bu yürüş Yeni Xet-Arami şəhər dövlətlərinin Assura bağlanma prosesinin başlanğıcıdır.", "8432c2ea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0878-01-01:0":{"b": ["II Aşşurnasirpal Kalhunu (Nimrud) Assurinin yeni paytaxtı etdi", "fbb17248"], "d": ["II Aşşurnasirpal kiçik bir qəsəbə olan Kalhunu 47 min işçi ilə böyük paytaxta çevirdi; Aşşurdan altı dəfə geniş şəhərdə şimal-qərb sarayı tikildi. Kalhu 706-ya qədər Assurinin paytaxtı qaldı.", "5a0f00b6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0879-01-01:0":{"b": ["Omri Samariyanı paytaxt etdi, Moabı aldı", "e060c4b7"], "d": ["Omri İsrailin ilk həqiqi dövlətini qurdu: Ürdünün şərqini (Moab daxil) fəth etdi, sərhəd qalalarını gücləndirdi və Samariyanı yeni paytaxt etdi. Oğlu Axab Sayda kralı Ethbaalın qızı İzebel ilə evlənərək İsraili Finikiya ticarətinə bağladı.", "14f7df9d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0910-01-01:0":{"b": ["II Adad-nirari taxta çıxdı; Neo-Assur dirçəlişi başladı", "e6887ba9"], "d": ["Təxminən bir yarım əsr davam edən geriləmədən sonra II Adad-nirari Assur torpaqlarını yenidən toplamağa başladı; aramilərə və Babil sərhədinə yürüşlər etdi. Varisləri Aşşurnasirpal II və III Şalmaneser dövründə Yeni Assur imperiyası doğuldu.", "beab377b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0929-01-01:0":{"b": ["Süleymanın krallığı bölündü; I Yeroboam şimalda İsrail krallığını qurdu", "cfbbc025"], "d": ["Tövrata görə Süleymanın ölümü üzərinə oğlu Rexabamın vergi artırması şimaldakı on qəbilənin ayrılmasına səbəb oldu; Yeroboam kral seçildi və Tirzanı paytaxt etdi. Cənubda Yəhuda Davud sülaləsi ilə davam etdi. İki dövlətin ayrı tarixi başlayır.", "7e2e066d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1099-01-01:0":{"b": ["I Tiglat-Pileser qərbə yürüyüb Aralıq dənizi sahilindəki Finikiya şəhərlərindən xərac aldı", "0b2822b7"], "d": ["I Tiglat-Pileser Livan meşələrinə və Arvad, Biblos (Cübeyl), Sayda kimi limanlara çatıb xərac topladı, Aralıq dənizində gəmi ilə səyahət etdi. Xet çöküşündən sonra qərbdə onu dayandıracaq güc olmadığından bu yürüşlər Assurinin qərb istiqamətini başladır.", "60dc7824"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1109-01-01:0":{"b": ["I Nabukodonosor (Isin II) Elama yürüyüb Marduk heykəlini geri aldı", "3c551c03"], "d": ["Isin II sülaləsindən I Nabukodonosor Elam üzərinə yürüyərək Kutir-Nahhuntenin apardığı Marduk heykəlini Babilə geri gətirdi. Qələbə Babil tarixində «Mardukun dönüşü» kimi xatırlanır və Marduk kultunu mərkəzi etdi.", "fdd1a6a4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1157-01-01:0":{"b": ["Şutruk-Nahhunte Babil ölkəsini talan etdi; Hammurabi və Naram-Sin steləsini Susaya apardı", "3d499fcc"], "d": ["Orta Elam kralı Şutruk-Nahhunte Babilə hücum edib Sippar kimi şəhərləri talan etdi; Hammurabi qanunları steləsi və Naram-Sin Qələbə steləsi kimi qənimətlər Susaya daşındı. Oğlu Kutir-Nahhunte isə e.ə. 1155-də Kassit sülaləsini bitirdi.", "2179c21e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1174-01-01:0":{"b": ["Karkamışda Kuzi-Teşub «Böyük Kral» titulu ilə Xet mirasını davam etdirdi", "0bda7a64"], "d": ["Hattuşanın dağılmasından sonra Karkamış krallığı Xet sülaləsinin bir qolunun əli ilə ayaqda qaldı; Kuzi-Teşub özünü «Böyük Kral» elan etdi. Karkamış, Malatya (Melid) və Həma kimi Luvi-Arami şəhər dövlətləri «Yeni Xet» dünyasını yaratdı.", "214de0bd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1179-01-01:0":{"b": ["Hattuşa yandı, tərk edildi; Xet imperiyası çökdü", "64d58b6b"], "d": ["Hattuşa şəhəri son Xet kralı II Şuppiluliumanın zamanında yandırılıb tərk edildi; qıtlıq, daxili toqquşma və Dəniz xalqları kontekstində yaşanan Son Tunc dövrü çöküşünün bir hissəsidir. Xet dövləti yerini Karkamış və Malatya kimi Yeni Xet şəhər dövlətlərinə verdi.", "34ee5436"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1224-01-01:0":{"b": ["Aşşur kralı I Tukulti-Ninurta Babili fəth etdi; Marduk heykəlini Aşşura apardı", "2cc39251"], "d": ["I Tukulti-Ninurta (təxminən 1243-1207) Kassit kralı IV Kaştiliaşı məğlub edərək Babili ələ keçirdi, divarları dağıtdırdı və Marduk heykəlini Aşşura daşıdı. Babil təxminən yeddi il Aşşurun nəzarətində qaldı; Assur orta əsrlərin ən güclü dövləti oldu.", "8abcb249"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1259-01-01:0":{"b": ["I Şalmaneser Kalhu (Nimrud) şəhərini qurdu", "e0bf279a"], "d": ["I Şalmaneser Dəclə sahilində Kalhunu qurdu; şəhər 883-də II Aşşurnasirpal tərəfindən yenidən qurulub Assurinin paytaxtı olacaqdır.", "8a213755"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1269-01-01:0":{"b": ["I Şalmaneser Hanigalbatı ilhaq etdi; Mitanni aradan qalxdı", "88620feb"], "d": ["Hanigalbat kralı II Şattuaranın üsyanını yatıran I Şalmaneser ölkəni birbaşa Assura qatdı, əhalini sürgün etdi. Mitanni dövləti xetlərin və assurlularin ardıcıl zərbələri ilə tarix səhnəsindən silindi.", "c6c8615e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1274-01-01:0":{"b": ["Untaş-Napiriša Dur-Untaş (Çoqa Zanbil) şəhərini və zigguratını qurdu", "117fbc13"], "d": ["Orta Elam kralı Untaş-Napiriša Susa yaxınlığında tanrı İnşuşinak üçün zigguratlı ibadət şəhəri qurdu; şəhər yarımçıq qalmasına baxmayaraq iki əsrdən çox istifadə edildi. Çoqa Zanbil İranın ən yaxşı qorunmuş zigguratıdır.", "fe8afd09"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1294-01-01:0":{"b": ["I Adad-nirari Hanigalbatı (Mitanni qalığını) məğlub etdi və vassal etdi", "1adb5969"], "d": ["Aşşur-uballit I-in nəvəsi I Adad-nirari xetlərin zərbə vurduğu Mitannidən qalan Hanigalbat krallığını məğlub edib vassallığa saldı; növbəti kral I Şalmaneser dövründə ölkə Assur əyalətinə çevrildi. Assur Fəratadək uzandı.", "24941786"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1317-01-01:0":{"b": ["II Mursili Arzavanı (Qərbi Anadolu) məğlub edib böldü", "4a204e42"], "d": ["II Mursili səltənətinin əvvəlində Qərbi Anadolunun güclü Arzava konfederasiyasını məğlub edərək alt krallıqlara böldü və Xet vassalı etdi. Qərbi Anadolunun Xet sərhədi Egey sahilinə yaxınlaşdı.", "c2f9977c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1327-01-01:0":{"b": ["Şuppiluliuma oğullarını Karkamış və Hələb krallıqlarının başına təyin etdi", "1c5bc8b3"], "d": ["Şuppiluliuma fəth etdiyi Suriyanı Xet sülaləsindən «krallar» vasitəsilə idarə etdi: Karkamış və Hələb oğullarına verildi. Karkamış kral-naibliyi Xet çöküşündən sonra belə 500 il qədər varlığını davam etdirəcəkdir.", "40eeaf84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1344-01-01:0":{"b": ["Şuppiluliuma I Mitannini (Tuşratta) məğlub edib Hələb və Karkamışı aldı; şimali Suriya Xetlərə keçdi", "52f9627a"], "d": ["Şuppiluliuma Mitanni kralı Tuşrattanı məğlub etdi, Karkamış və Hələb daxil Suriya şəhərlərini aldı; Mitanni torpaqlarının qərbi Xet imperiyasına qatıldı. Misirin Axenaton dövrü daxili problemləri bu genişlənməni asanlaşdırdı.", "c80de115"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:0":{"b": ["Kassit Babil Amarna diplomatiyasında Misirin bərabər böyük gücü kimi yer aldı", "5e7b31a2"], "d": ["Kassit kralları I Kadaşman-Enlil və Burna-Buriaş II Misir fironları ilə evlilik və hədiyyə diplomatiyası aparan «böyük krallar» liqasına daxil idi. Amarna məktubları bu liqanın üzvlərini Misir, Babil, Mitanni, Hatti və Aşşur olaraq sıralayır.", "8ecd665d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:1":{"b": ["Şuppiluliuma I Xet taxtına çıxdı; Yeni Krallıq dövrü başladı", "58b301b7"], "d": ["Şuppiluliuma I Xet Yeni Krallığının qurucusu və peşəkar döyüş arabası ordusunun yaradıcısıdır. Otuz beş illik səltənəti xetləri Anadoludan Suriyaya uzanan imperiyaya çevirdi.", "72c7f3af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1362-01-01:0":{"b": ["Aşşur-uballit I Mitanni himayəsindən qurtuldu; Assur müstəqil və «böyük kral» oldu", "5f280058"], "d": ["Mitanni vassalı olan Aşşur I Aşşur-uballit dövründə xetlərin Mitanniyə vurduğu zərbədən yararlanaraq müstəqillik qazandı. Kral Misir fironuna «böyük kral» titulu ilə məktub yazdı; bu, Orta Assur dövrünü başladır.", "690fb956"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1399-01-01:0":{"b": ["Mitanni-Misir ittifaqı: I Artatama və IV Tutmos sülhü, Mitanni şahzadəsi Misirə gəlin getdi", "017f13d2"], "d": ["Düşmənçilikdən sonra Mitanni kralı I Artatama Misir fironu ilə sülh bağladı və qızını Misirə göndərdi. İttifaq Xet təhlükəsinə qarşı şimali Suriyada Misir-Mitanni tarazlığını qurdu və Amarna dövrünün diplomatiyasını hazırladı.", "72df719d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1499-01-01:0":{"b": ["Mitanni (Hanigalbat) krallığı Xabur-Fərat bölgəsində quruldu", "04920d91"], "d": ["Hurri-Mitanni krallığı Qədim Babilin çöküşü və Xet geriləməsinin boşluğunda Yuxarı Mesopotamiyada yüksəldi. Paytaxt Vaşşukanni idi; krallıq bir neçə onillikdə Aşşuru və şimali Suriyanı vassal etdi.", "c6aa0237"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1524-01-01:0":{"b": ["Telepinu taxta çıxıb fərman yayımladı; Kizzuvatna ilə müqavilə ilə münasibətlər müəyyənləşdi", "e1f0895b"], "d": ["Telepinu varisliyə dair tənzimləmələr edən fərmanı ilə Xet hüququnu yenidən qurdu; Kizzuvatna ilə imzalanan müqavilə ölkəni asılı deyil, müstəqil tərəfdaş kimi tanıdı. Xet Qədim Krallığı bu fərmanla sona çatır.", "47b927f1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1569-01-01:0":{"b": ["Kassit sülaləsi Agum-kakrime dövründə Babili yenidən toparladı; Marduk heykəli Xet əsarətindən qayıtdı", "0d525e02"], "d": ["Xet kralı I Mursilinin Babil talanından (e.ə. 1595) sonra şəhərə Kassit sülaləsi hakim oldu. Rəvayət Agum-kakriməyə görə Marduk heykəlinin xetlərdən geri alındığını nəql edir; Kassitlər qısa müddətdə Babil mədəniyyətini mənimsədi və təxminən dörd əsr davam edəcək sülaləni qurdu.", "d91fcc1e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1589-01-01:0":{"b": ["I Mursili sui-qəsdlə öldürüldü; Xet krallığı daxili çəkişmələrlə zəiflədi", "fa5a6ea9"], "d": ["Babil dönüşündə I Mursili qayınatası Hantili və Zidanta tərəfindən öldürüldü. Taxt davaları və yeni Hurri/Mitanni gücü krallığı yarım əsr zəif qoydu; Telepinu ancaq təxminən e.ə. 1525-də nizamı qura bildi.", "90711b8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1599-01-01:0":{"b": ["I Mursili Hələbi (Yamhad) alıb dağıtdı", "78c81e82"], "d": ["Hattuşilinin nəvəsi və varisi I Mursili onilliklərlə müqavimət göstərən Hələb krallığını ələ keçirib dağıtdı. Yamhadın sona çatması şimali Suriyada Xet üstünlüyünü təmin etdi və Mursilinin Babil yürüşünün yolunu açdı.", "327a9d55"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1629-01-01:0":{"b": ["I Hattuşili Torosu keçib şimali Suriyaya yürüş etdi; Alalakh dağıdıldı, Hələb (Yamhad) krallığına hücum edildi", "92b0d44b"], "d": ["I Hattuşili (təxminən 1650-1620) Torosu keçib şimali Suriyaya yürüş etdi; Alalakh dağıdıldı və Hələb (Yamhad) krallığına hücum edildi, lakin Hələb alınmadı. Kizzuvatnanın (Kilikiya) ilhaqı bu yürüşlə olmadı: Kizzuwadna sonradan Hatti ilə Mitanni arasında gedib gəldi və Xet ilhaqı Yeni Krallığın əvvəlindədir.", "cf12effe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1749-01-01:0":{"b": ["Kuşşara kralı Anitta Kaneşi paytaxt etdi və Hattuşanı dağıtdı", "1eea344b"], "d": ["Anitta mətninə görə Kuşşara kralı Anitta Anadoluda bir çox şəhər dövlətini birləşdirdi, Neşanı (Kaneş) paytaxt etdi və Hattuşanı dağıdıb üzərinə lənət oxudu. Xetlərin ilk siyasi birləşmə cəhdi kimi xatırlanır.", "01d03ad4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1753-01-01:0":{"b": ["Hammurabi qanunları steləsi dikildi", "b4c80ab9"], "d": ["Hammurabinin 282 maddəlik hüquq külliyyatı bazalt steləyə yazılıb məbədlərdə dikildi. Stela Elam kralı Şutruk-Nahhunte tərəfindən e.ə. XII əsrdə Susaya aparılmış və 1901-də orada tapılmışdır; bu gün Luvrdadır.", "e37255ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1760-01-01:0":{"b": ["Hammurabi Marini aldı; iki il sonra divarlarını dağıtdırdı", "4f4114b4"], "d": ["Əvvəlki müttəfiqi Zimri-Limin Marisini ələ keçirən Hammurabi şəhər divarlarını da dağıtdırdı. Marinin dağıdılması Fərat vadisində Amorit krallığının sonudur; Babil şimalda Aşşur və Eşnunnayadək hakim güc oldu.", "5bbc9e99"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1762-01-01:0":{"b": ["Hammurabi Larsanı alıb Rim-Sin I-i məğlub etdi; cənubi Mesopotamiya Babilə bağlandı", "6f95399b"], "d": ["Hammurabi eyni il ərzində Elam və Eşnunna ilə vuruşub Larsaya yönəldi və Rim-Sin I-i məğlub etdi. Cənubi Mesopotamiya (Şumer) Babil krallığına qatıldı; bu bölgə həmin gündən «Akkad ölkəsi» (Babylonia) adlanır.", "4be6f89b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1793-01-01:0":{"b": ["Larsa kralı Rim-Sin I İsini fəth etdi; Isin sülaləsi sona çatdı", "88964ca6"], "d": ["Larsa kralı Rim-Sin I uzun müddətdir rəqibi olan Isini fəth edərək ələ keçirdi və Larsanı cənubi Mesopotamiyanın yeganə böyük gücü etdi. Beləliklə, Isin sülaləsi 223 illik hakimiyyətdən sonra sona çatdı.", "f1928082"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1794-01-01:0":{"b": ["Şamşi-Adad Marini aldı və oğlu Yasmah-Adadı Mariyə kral təyin etdi", "a428b4eb"], "d": ["Aşşur və Ekallatum kralı Şamşi-Adad Fəratdakı Mari krallığını ələ keçirib Yahdun-Lim sülaləsini aradan qaldırdı və kiçik oğlu Yasmah-Adadı Mariyə təyin etdi. «Yuxarı Mesopotamiya krallığı» beləliklə Zaqrosdan Fəratadək uzanan Amorit imperiyası halına gəldi.", "8d0ec094"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1799-01-01:0":{"b": ["Hələb Yamhad krallığının paytaxtı kimi xatırlanır", "9ad40400"], "d": ["Hələb Yamhad krallığının paytaxtı kimi e.ə. XVIII əsrdə görünür; krallığın dəqiq qurulma ili mənbədə verilmir.", "f9ad9832"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1821-01-01:0":{"b": ["Rim-Sin I Larsa taxtına çıxdı", "a24e891e"], "d": ["Rim-Sin I (təxminən 1822-1763) 60 illik səltənəti boyunca Uruk, Isin və Nippuru Larsaya bağlayıb Elam mənşəli sülaləni cənubun yeganə hakimi etdi. Səltənəti Hammurabi tərəfindən Larsanın fəthi ilə (e.ə. 1763) sona çatdı.", "dcc872e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1835-01-01:0":{"b": ["Kaneş (Kültepe) karumunun II qatı dağıdıldı; Anadolu şəhər dövlətləri arasında Anitta ayağa qalxdı", "084f9472"], "d": ["Kültepe II qatının dağılması Aşşurlu tacir karumlarının ilk böyük dövrünün sonudur. Ardınca Kuşşara kralı Anitta Kaneşi paytaxt etdi və xetlərin siyasi qurulmasının yolunu açdı.", "c3514f06"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1899-01-01:0":{"b": ["Aşşurlu taciərlər Kaneş (Kültepe) karumunu qurdu; Qədim Assur ticarət şəbəkəsi Anadoluya uzandı", "b81b0cb9"], "d": ["Aşşur şəhərinin taciərləri mis, qalay və parça ticarəti üçün Anadoluda Kaneş mərkəzli karumlar (ticarət koloniyaları) qurdu. Kültepədə tapılan on minlərlə mixi yazılı lövhə Anadoluda yazının və yazılı tarixin başlanğıcıdır.", "2311e7a7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1924-01-01:0":{"b": ["Larsa kralı Gungunum Uru Isindən aldı", "6c857c01"], "d": ["Gungunum (təxminən 1932-1906) Larsanı ilk dəfə böyük güc halına gətirdi: il adlarında Urun alınması və Elama yönəlik uğur elan edilir. Urun keçməsi ilə Isinin şimalla məhdud qalması başladı.", "0108b079"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1960-01-01:0":{"b": ["Naplânum Larsada müstəqil Amorit sülaləsini qurdu", "86a820f8"], "d": ["Amorit başçı Naplânum Larsada hakimiyyətini elan edərək III Ur sonrası cənubun ikinci böyük sülaləsini qurdu. Larsa Isinlə əsrlər boyu davam edən rəqabətdə əvvəl Uru, sonra Uruku və Isini özünə bağlayacaqdır.", "ab808712"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2001-01-01:0":{"b": ["İşbi-Erra Urdakı Elam qarnizonunu çıxardı; Isin, Ur və Nippuru hakimiyyətinə aldı", "a68018b2"], "d": ["Urun Elam tərəfindən alınmasından (təxminən 2004) sonra İşbi-Erra Urdakı Elam qarnizonunu çıxardı və Ur ilə Nippuru Isinə bağladı. Isin Urun siyasi varisi olaraq əsrlər boyu Şumer-Akkad kralı titulunu daşıdı.", "77884c9c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2016-01-01:0":{"b": ["İşbi-Erra Isində III Urdan ayrıldı; Isin sülaləsi quruldu", "8d9e3116"], "d": ["İbbi-Sinin generalı İşbi-Erra III Ur dövləti çökərkən Isində müstəqil sülalə qurdu. Isin Urun mədəni irsini davam etdirən «Şumer və Akkad kralı» titullu sülalə olaraq təxminən 220 il cənubi Mesopotamiyanın baş güclərindən biri oldu.", "b28db4ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2025-01-01:0":{"b": ["İbbi-Sin III Urun son kralı kimi taxta çıxdı", "0afa3ef5"], "d": ["İbbi-Sin (təxminən 2028-2004) Şu-Sinin varisi olaraq dövlətin çözülmə prosesini idarə etdi: Amorit təzyiqi, qıtlıq, Susa və şərq əyalətlərinin itirilməsi, İşbi-Errənin Isində müstəqilliyi. Səltənəti Elam/Simaşki hücumu ilə Urun talanında sona çatdı.", "19e45ed0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2031-01-01:0":{"b": ["Şu-Sin amoritlərə qarşı «Muriq-tidnim» divarını tikdi", "a09bfd57"], "d": ["III Ur kralı Şu-Sin qərbdən gələn Amorit köçərilərini (Martu) dayandırmaq üçün Dəclə ilə Fərat arasında uzun divar xətti (Muriq-tidnim, «Qərblilərini uzaq tutan») qurdu. Divar Amorit təzyiqinin dövləti zorladığını göstərir; III Ur qısa müddət sonra bu təzyiq və Elam hücumu ilə çökdü.", "e5ec4e9a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2091-01-01:0":{"b": ["Şulgi III Ur taxtına çıxdı; dövlətin mərkəzi inzibati sistemini qurdu", "06ea0c7b"], "d": ["Ur-Nammunun oğlu Şulgi (təxminən 2094-2047) 48 illik səltənətində III Ur dövlətini mərkəzləşdirdi: vergi və heyvan təhvil sistemi (Puzriş-Dagan), ordu islahatı, şəhər qubernatorluqları və yeni təqvim. III Ur Mesopotamiya tarixinin bürokratik baxımdan ən inkişaf etmiş erkən dövləti sayılır.", "d6f42381"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2099-01-01:0":{"b": ["Puzur-İnşuşinak Elamda (Susa) son Awan kralı olaraq Akkad himayəsindən qurtuldu", "cd91f4a2"], "d": ["Awan sülaləsinin son kralı Puzur-İnşuşinak Akkad dövlətinin çöküşündə Susa və Elam yaylasını birləşdirib Akkad himayəsindən çıxdı və mixi yazı ilə yanaşı «Xətti Elam» yazısı ilə kitabələr qoydu. Ur-Nammunun yüksəlişi ilə Elam yenidən Mesopotamiya nəzarətinə girdi.", "d16fe5e9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2110-01-01:0":{"b": ["Uruk kralı Utu-hegal Gutium kralı Tiriqanı məğlub edərək Gutium hakimiyyətinə son verdi", "aa67620c"], "d": ["Urukun kralı Utu-hegal Şumeri idarə edən Gutium kralı Tiriqanı Dəclə sahilində məğlub edib tutdu; Gutilər Şumerdən çəkildi və cənubda Urukun rəhbərliyi ilə Şumer hakimiyyəti yenidən quruldu. Utu-hegalın generalı Ur-Nammu qısa müddətdə III Ur sülaləsini quracaqdır.", "45b2db48"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2152-01-01:0":{"b": ["Gutium: Şumer Kral Siyahısına görə Gutilər Akkaddan sonra Şumerdə krallıq etdi", "506ad1cb"], "d": ["Zaqrosdan enən Gutilər Akkad dövlətinin çöküşündən sonra Mesopotamiyanın böyük hissəsində hakim oldu. Şumer Kral Siyahısı Gutiumu Akkad ilə V Uruk və III Ur arasındakı sülalə olaraq (21 kral, təxminən 91-124 il) sayır; mənbə təhrif olunsa da Gutilərin idarəsi güclü xarici təhlükə yerinə zəif varislik kimi sənədləşdirilir.", "8ee58415"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2229-01-01:0":{"b": ["Naram-Sin Zaqrosda Lullubi dağlılarını məğlub etdi (Qələbə steləsi)", "de84161d"], "d": ["Naram-Sinin Lullubi (Zaqros) xalqı üzərindəki qələbəsini göstərən barelyefli stela Akkad sənətinin ən tanınmış əsəridir. Stela sonradan Elam kralı Şutruk-Nahhunte tərəfindən Susaya aparıldı və 1898-də orada tapıldı.", "5e6a3ff7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2249-01-01:0":{"b": ["Naram-Sin «Böyük üsyanı» yatırdı: Kiş və Urukun rəhbərlik etdiyi şəhər dövlətləri koalisiyası məğlub oldu", "6e9373e8"], "d": ["Naram-Sinin səltənətinin əvvəlində Kiş kralı İphur-Kişin rəhbərliyi ilə cənubdakı şəhərlər Akkada qarşı qalxdı. Naram-Sin doqquz döyüşdə üsyançıları məğlub edərək Akkad hakimiyyətini yenidən qurdu; qələbəsini şəhər məbədlərinə həsr etdiyi kitabədə nəql etdi.", "c9f67d8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2260-01-01:0":{"b": ["Naram-Sin Akkad taxtına çıxdı; «dünyanın dörd bucağının kralı» titulunu aldı", "e9e5261d"], "d": ["Sarqonun nəvəsi Naram-Sin (təxminən 2254-2218) Akkad dövlətinin zirvəsini idarə etdi. Özü üçün ilk dəfə ilahiləşdirilmiş kral titulunu və «dörd bucağın kralı» sifətini istifadə edən Mesopotamiya hökmdarı oldu.", "b56983fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:0":{"b": ["Sarqon Elamı (Awan, Susa, Parahşum) əsarət altına aldı", "1b7806f5"], "d": ["Sarqonun il adları və kitabələri Elamın (Awan, Parahşum) məğlub edildiyini bildirir; Susa Akkad qubernatorları və akkadca sənədlərlə idarə olunan Akkad şəhəri oldu. Bu, Elamın ilk dəfə Mesopotamiya mərkəzli imperiyaya bağlanmasıdır.", "7214e566"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:1":{"b": ["Sarqon Uruk kralı Lugalzagesini məğlub edib Şumerin şəhər dövlətlərini Akkada bağladı", "aad96bc9"], "d": ["Agade (Akkad) kralı Sarqon Uruk kralı Lugalzagesini məğlub edərək Şumer şəhərlərini (Uruk, Ur, Laqaş, Umma, Kiş ətrafı) tək əldə topladı. Akkad cənubi Mesopotamiyanın hamısını idarə edən ilk imperiya halına gəldi.", "4ff76ffe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0231-01-01:0":{"b": ["I Ərdəşir Roma Mesopotamiyasına hücum etdi; Roma-Sasani müharibələri başladı", "576ebb06"], "d": ["Parfiyanı devirən I Ərdəşir 230-231-də Nusaybin və Carrhae ətrafına hücum edərək Romayla əsrlərlə davam edəcək mübarizəni başlatdı; Severus Alexanderin 232 yürüşü nəticəsiz qaldı.", "7040e38b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0240-01-01:0":{"b": ["Hatra Sasaninin əlinə keçdi (240-241)", "4f8a58ad"], "d": ["Səhra ticarət şəhəri və qalası Hatra uzun Parfiya-Roma çəkişməsindən sonra Ərdəşir I və Şapur I tərəfindən 240-241-də alındı və dağıdıldı. Hatranın süqutu Romanın Mesopotamiyadakı mühüm müttəfiqini aradan qaldırdı.", "12f25195"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0244-01-01:0":{"b": ["III Gordianus Ktesifon yaxınlığında öldü; Philippus Arabs Şapurla ağır sülh bağladı", "25d270ee"], "d": ["III Gordianus əvvəlcə uğurlu Mesopotamiya yürüşündən sonra Şapura qarşı məğlub oldu və öldü. Varisi Philippus Arabs farslarla sülh bağladı; Şapur öz kitabəsində (ŠKZ) Philippusun taxta çıxışını öz əsəri sayır və xərac aldığını bildirir.", "d975e0ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:0":{"b": ["I Şapur Suriyanı işğal edib Antiokheyanı talan etdi", "6f938d07"], "d": ["I Şapur Romanın Suriya əyalətinə böyük yürüş edib Antiokheya daxil onlarla şəhəri talan etdi və əsirləri İrana yerləşdirdi. Bu yürüşün qeydi Nəqş-i Rüstəmdəki ŠKZ kitabəsindədir.", "17b20275"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:1":{"b": ["Dura-Europos Sasanilər tərəfindən alındı", "c7f39e98"], "d": ["Fərat sahilindəki Roma sərhəd qarnizonu Dura-Europos uzun mühasirədən sonra süqut etdi və tərk edildi; Sasani mühasirə tunelləri və Roma əks tunelləri arxeoloji olaraq sənədləşdirilmişdir. Şəhər bir daha məskunlaşmadı.", "889d9ece"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0260-01-01:0":{"b": ["Edessa döyüşü: I Şapur Roma imperatoru Valerianusu tutub əsir aldı", "654d57e3"], "d": ["I Şapur Edessa yaxınlığında imperator Valerianusun ordusunu darmadağın etdi və imperatoru şəxsən əsir aldı. Bişapur və Nəqş-i Rüstəm barelyefləri bu qələbəni təsvir edir; Valerianusun Sasani əsarətində ölümü Roma tarixinin ən böyük alçalmasıdır.", "2da6ab5d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0298-01-01:0":{"b": ["Nisibis (Nusaybin) müqaviləsi: Galerius Narsehi məğlub etdi; Dəclənin o tayındakı torpaq Romaya keçdi", "3046c0f4"], "d": ["Narsehin Roma Mesopotamiyasına hücumu Galeriusun qələbəsi ilə bitdi; 298 sülhü ilə Dəclənin o tayındakı beş bölgə (Transtigritania) və Nisibis Romaya verildi. Müqavilə yarım əsr Roma-Sasani sərhədini müəyyənləşdirdi.", "4c01c338"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0309-01-01:0":{"b": ["II Şapur doğuşundan etibarən Sasani taxtına çıxdı (309-379)", "aeed05eb"], "d": ["II Hörmüzdün ölümündən sonra taxt çəkişməsi içində hamilə qalmış kraliçanın doğduğu II Şapur doğulmadan tac geyindirildi və 70 il hökm sürdü. Səltənəti Romayla yenidən mübarizənin və Kuşanların Sasani idarəsinə girməsinin dövrüdür.", "a2b5cb22"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0359-01-01:0":{"b": ["II Şapur Amidanı mühasirəyə alıb aldı (avqust-oktyabr 359)", "0b812592"], "d": ["II Şapur Kuşan-Kionit müttəfiqləri ilə Amidanı 73 günlük mühasirə ilə aldı, ardınca Singara və Bezabdeni ələ keçirdi. Ammianus Marcellinus mühasirədə hazır idi və təfərrüatlı nəql edir.", "a86e216d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-01-01:0":{"b": ["Jovianus müqaviləsi: Nisibis və Dəclənin o tayındakı beş bölgə Sasaniyə verildi", "6e619831"], "d": ["Jovianus mühasirəyə alınmış ordusunu xilas etmək üçün Nisibis, Singara və Dəclənin o tayındakı beş bölgənin Sasaniyə verilməsini qəbul etdi; Roma yarım əsrlik 298 qazanclarını itirdi. Nusaybin əhalisi Romaya çəkildi.", "21055f84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-06-26:0":{"b": ["Julianus Samarra yaxınlığında öldü; Sasani müharibəsi sona doğru getdi", "86970a50"], "d": ["Julianusun Ktesifon yürüşü su basqınları ilə dayandıqdan sonra geri çəkilən Roma ordusu Marangada Sasani hücumunda yaralanan imperator öldü. Ordunun seçdiyi Jovianus II Şapurla müqavilə bağlamağa məcbur oldu.", "9de62fd5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0387-01-01:0":{"b": ["Roma-Sasani Ermənistanı bölüşdürmə müqaviləsi (I Theodosius - III Şapur)", "228f4d6b"], "d": ["Armeniyanın böyük hissəsi (şərq) Sasani təsirinə, kiçik qərb hissəsi Roma təsirinə verildi; Erməni Arşakuni krallığı faktiki olaraq sona çatma yoluna girdi. Bölgü təxminən iki əsr Roma-İran sərhədini müəyyənləşdirir.", "d65941ae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0451-01-01:0":{"b": ["Avarayr döyüşü: II Yəzdgird Erməni üsyanını yatırdı", "1bf1df2d"], "d": ["Vardan Mamikonyanın başçılığındakı Erməni zadəganları Sasaninin zərdüştlüyü məcburi qəbul etdirməsinə qarşı üsyan etdi; Avarayrda ordu məğlub oldu və Vardan öldü. Ermənilər siyasi məğlubiyyətə baxmayaraq xristianlıqlarını qoruya bildi.", "453512fe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0484-01-01:0":{"b": ["I Peroz Eftalitlərlə döyüşdə öldü; Sasani Hunlara xərac ödəməyə başladı", "a418d8ae"], "d": ["Peroz Axşunvarın rəhbərliyindəki Eftalitlərin (Ağ Hunlar) qarşısında ordusu ilə birlikdə məhv oldu. Sasani dövləti böyük xəracı və oğlu Kavadın Eftalit sarayında girov qalmasına boyun əydi; şərq sərhədi daimi olaraq zəiflədi.", "0e4bc9f8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0496-01-01:0":{"b": ["I Kavad Məzdək tərəfdarı siyasəti üzündən taxtdan salındı; 498-499-da Eftalit köməyi ilə geri gəldi", "9101bfe7"], "d": ["Kavad I (488-dən bəri kral) zadəgan və ruhani təbəqənin etirazı ilə devrildi, sığınaraq Eftalitlərə getdi və 498-499-da onların hərbi dəstəyi ilə Ktesifona dönüb taxtı geri aldı. Eftalit dəstəyi ona ödənilməsi lazım olan xərac yaratdı; Romayla 502 müharibəsi bu ehtiyacdan çıxdı.", "06883ad8"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["İlk Osmanlı axçasının kəsilməsi", "38d2d638"], "d": ["Orxan Qazi adına kəsilən ilk gümüş axça bəyliyin müstəqil suverenliyinin pul elanıdır; axça beş əsr boyunca əsas pul vahidi qaldı.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Rumeli Bəylərbəyiliyi quruldu", "ffa16089"], "d": ["Avropa yakasındakı fəthlər vahid hərbi-inzibati çətir altında toplandı; bəylərbəyilik qaydası imperiya əyalət təşkilatının onurğası oldu.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Yıldırım Bəyazid – Despina Xatun evliliyi", "4b10dc6c"], "d": ["Kosovo sonrası Serb despotluğu ilə qurulan vassallıq Lazarın qızı Oliveranın Bəyazidlə evliliyi ilə möhürləndi — erkən dövr evlilik diplomatiyasının tipik nümunəsi.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Anadolu Bəylərbəyiliyi quruldu", "5ef8d3a7"], "d": ["İlhaq edilən bəylik torpaqlarının idarəsi üçün Anadolu Bəylərbəyiliyi təşkil edildi; Rumeli-Anadolu cüt qanadlı idarə qaydası tamamlandı.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Bursa Ulu Məscidi tamamlandı", "27bcc4a5"], "d": ["Nikopol qənimətiylə tikdirilən iyirmi günbəzli ulu məscid erkən Osmanlı memarlığının abidəvi nümunəsi və xəttatlıq sənətinin açıq muzeyidir.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Çandarlı Xəlil Paşanın vəzifədən alınması və edamı", "5e19438f"], "d": ["Fəthdən sonra mühasirəyə məsafəli duran köklü Çandarlı ailəsindən sədrəzəm edam edildi; ilk dəfə bir sədrəzəm padşah əmri ilə öldürülür, devşirmə mənşəli vəzirlər dövrü açılırdı.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Boğdanın xərac altına alınması", "25bd3693"], "d": ["Boğdan voyvodalığı xərac ödəməyi qəbul etdi; Eflak və Erdellə birlikdə Dunay şimalındakı üçlü vassal qurşaq imperiyanın şimal tamponu oldu. Eyni tarixdə qatılan digər yerlər: Yaş.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Dubrovnik (Raquza) xərac", "d127c78a"], "d": ["Tacir respublikası Raquza xərac müqabilində muxtariyyətini və ticarət imtiyazlarını təmin etdi; Osmanlının Adriatikdəki pəncərəsi olaraq zənginləşdi. Respublikanın torpağı olan Mljet adası da bu statusu bölüşdü.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Eflak yürüşü: Qazıqlı Voyvoda", "fd4530bb"], "d": ["Xərac ödəməyi rədd edib səfirləri öldürən Vlad Tepeş üzərinə təşkil edilən yürüşlə Eflak vassallığa qaytarıldı; gecə basqını və qazıq dəhşəti səhnələri Avropada əfsanələşdi. Eyni tarixdə qatılan digər yerlər: Bükreş.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Fatih Külliyəsi açıldı", "a150ea55"], "d": ["Səkkiz mədrəsəsi ilə (Səhni-Səman) külliyə İstanbulun İslam dünyasının elm mərkəzinə çevrilməsi proqramının ilk böyük addımı idi.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Əli Qüşçu İstanbulda", "8508229d"], "d": ["Səmərqənd rəsədxanasının son böyük nümayəndəsi Əli Qüşçu Fatihin dəvəti ilə Ayasofya Mədrəsəsinə müdərris oldu; İstanbulda riyaziyyat-astronomiya ənənəsini qurdu.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Fatih Qanunnaməsi", "b08944c9"], "d": ["Dövlət təşkilatını, protokolu və cəzaları toplayan ilk əhatəli örfi qanunnamə; 'nizami-aləm üçün' qardaş qətlinə icazə verən məşhur maddəsi ilə müzakirə olunur.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["İlk Osmanlı qızılı (sultani) kəsildi", "2fd5c0dd"], "d": ["Venesiya dukatına bərabər ilk Osmanlı qızıl sikkəsi kəsildi; imperiya maliyyəsi beynəlxalq pul qaydasına qatıldı.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Topqapı Sarayına köçüldü", "b9cd6a5e"], "d": ["Yeni Sarayın (Topqapı) tamamlanması ilə dövlət idarəçiliyinin mərkəzi bura köçürüldü; saray dörd əsr boyunca imperiyanın beyni olaraq qaldı.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Florensiya Respublikası hersoqluğa çevrildi — Alessandro de' Medici", "c08764e1"], "d": ["Papa VII Klemensin təzyiqi ilə Florensiyanın idarəedici komissiyası (Balìa) yeni konstitusiya qəbul etdi; beş əsrlik respublika rejimi qaldırılıb Alessandro de' Medici irsi hersoq elan edildi və 1 Mayda faktiki olaraq taxta çıxdı. Florensiya beləliklə müstəqil bir şəhər respublikasından Medici sülaləsinin irsi hersoqluğuna çevrildi.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Qanuni – Xürrəm Sultan nikahı", "abc05f26"], "d": ["Qanuninin Xürrəmlə rəsmi nikah qıyması saray ənənəsini kökündən dəyişdi; 'Xəsəki Sultan' institutu doğuldu və sülalə siyasətində qadınlar dövrünün qapısı açıldı.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Fransaya ilk əhatəli kapitulyasiyalar", "e2264e48"], "d": ["Habsburq sıxışdırmasına qarşı Fransa ittifaqının bir hissəsi olaraq Jean de la Forest ilə Məqbul İbrahim Paşa arasında ticarət imtiyazları imzalandı; o gün diplomatik vasitə olan kapitulyasiyalar əsrlər içində maliyyə asılılığının qapısına çevriləcəkdi.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Hind okeanı yürüşü: Diu mühasirəsi", "fcd1217a"], "d": ["Süveyşdən yola düşən donanma Qırmızı dənizi keçib Qucaratdakı Diunu mühasirəyə aldı; qala alınmasa da Osmanlı gücü ilk dəfə Hind okeanına uzandı, Portuqal inhisarı sarsıldı.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Seydi Əli Reisin Hind səyahəti", "e5da3b2c"], "d": ["Bəsrədəki donanmanı Misirə gətirməklə vəzifələndirilən Seydi Əli Reis fırtınalarla Hindistana sürüklənərək düşdü; qayıdış macərasını izah etdiyi Mirat-ül-məmalik ilk Osmanlı səyahətnamələrindəndir.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Piri Reisin edamı", "63026444"], "d": ["Hörmüz yürüşündən donanmanı Bəsrədə qoyub qayıdan böyük dənizçi-xəritəçəkən 84 yaşında edam edildi — elm tariximizin ən mübahisəli qərarlarından.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Süleymaniyyə Külliyəsi açıldı", "1c6458b2"], "d": ["Memar Sinanın 'kalfalıq əsərim' dediyi külliyə; mədrəsələri, darüşşifası və kitabxanası ilə klassik dövrün ən böyük təhsil-xeyriyyə kompleksi oldu.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Malta mühasirəsi", "f57f6a85"], "d": ["Aralıq dənizinin kilidi Malta dörd ay mühasirəyə alındı; Turqut Reis şəhid düşdü, mühasirə qaldırıldı. Qanuni dövrü dənizçiliyinin ilk böyük geri addımı oldu.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Səlimiyyə Məscidi tamamlandı", "3b0484e1"], "d": ["Sinanın 'ustalıq əsərim' dediyi, tək günbəzin məkana hakim olduğu Səlimiyyə Osmanlı klassik memarlığının zirvəsi sayılır (UNESCO Dünya İrsi).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["İstanbul Rəsədxanası quruldu", "169bdf5d"], "d": ["Təqiyyüddinin dövrün ən təchiz olunmuş müşahidə mərkəzlərindən olan rəsədxanası 1577 komet hadisəsindən sonra yaranan mübahisələrlə 1580-də dağıtdırıldı; institusional astronomiya üç əsr gecikdi.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Çıldır Qələbəsi — şərq müharibəsi başladı", "13125a54"], "d": ["Səfəvi ordusunun Çıldırda məğlub olması ilə Qafqazın qapıları açıldı; Tiflis alındı və Gürcüstan Osmanlı hakimiyyətinə girdi.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Məşəllər Döyüşü — Şirvan qəti olaraq Osmanlıda", "3bbc23bc"], "d": ["Gecə məşəl işığında da davam etdiyi üçün bu adla anılan döyüşdə Səfəvilər qəti məğlubiyyətə uğradıldı; Şirvan və Bakıdakı Osmanlı hakimiyyəti möhkəmləndirildi.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Böyük təğşiş — axça böhranı", "9205c3d4"], "d": ["Uzun müharibələrin və Amerika gümüşünün təzyiqi ilə axçanın gümüş tərkibi yarıya endirildi; qiymət inqilabı sipahi nizamının dağılmasını və Cəlali qarışıqlığını bəslədi.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Təbrizin fəthi", "6506bdb9"], "d": ["Sərdar Özdəmiroğlu Osman Paşa Təbrizə girdi; Səfəvilərin köhnə paytaxtı Osmanlı idarəsinə alındı. Osman Paşa bir neçə həftə sonra ordugahda vəfat etdi.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Fərhad Paşa Müqaviləsi — şərqdə ən geniş sərhədlər", "c429972f"], "d": ["Şah Abbasın səfiri Heydər Mirzənin İstanbula gəlişindən (18 Yanvar 1590) sonra fəth edilən yerlərin Osmanlıda qalması şərti ilə edilən və 12 illik müharibəni bitirən müqavilə ilə Təbriz, Qarabağ, Şirvan, Gürcüstan və Luristan Osmanlıda qaldı; imperiya şərqdə tarixinin ən geniş sərhədlərinə çatdı.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Osmanlı-Səfəvi müharibəsi (1603-1612) başladı — Şah Abbasın əks-hücumu, Təbrizin itirilməsi", "abf27dd8"], "d": ["Ordusunu yenidən təşkil edən Şah Abbas Cəlali qarışıqlıqlarından istifadə edərək hücuma keçdi; Təbriz süqut etdi, Qafqaz qazancları bir neçə il içində əldən çıxdı. Eyni yürüş və ardınca əldən çıxan digər yaşayış məntəqələri: Naxçıvan, Xoy, Mərənd, Səlmas; Qaradağ (Ahar) və Mukri bəyləri də Səfəvi tərəfinə döndü.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Övliya Çələbi doğuldu", "2b6051ff"], "d": ["Əlli ildən çox səyahətlərini on cildlik Səyahətnamədə toplayan Övliya Çələbi 17-ci əsr Osmanlı dünyasının misilsiz panoramasını buraxdı.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Nəsuh Paşa Müqaviləsi", "bb69e388"], "d": ["1603-dən bəri davam edən müharibəni bitirən müqavilə ilə 1590 qazanclarından imtina edildi və 1555 Amasya sərhədinə dönüldü; şərq cəbhəsində tarazlıq yenidən quruldu.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Sultan Əhməd Məscidi açıldı", "e39dfd43"], "d": ["Altı minarəsi və mavi İznik çinriləri ilə 'Mavi Məscid' klassik dövrün son böyük səlatin külliyəsidir.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Sultan İbrahimin qətli", "bc4eb452"], "d": ["İsrafçılıq və idarəetmə böhranı əsas gətirilərək ocaq-ülema ittifaqı İbrahimi taxtdan endirdi; on gün sonra fətva ilə boğdurulub öldürüldü. Taxta yeddi yaşlı IV Mehmed keçdi; hakimiyyət faktiki olaraq böyük valide Kösəm Sultanın əlinə keçdi.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Katib Çələbinin ölümü", "e167e89d"], "d": ["Kəşfüz-zünun biblioqrafiyası və Cihannüma coğrafiyası ilə Osmanlı elm tarixinin zirvə adı; Avropa mənbələrindən istifadə edən öncül yanaşması ilə tanınır.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Ədirnə Hadisəsi — II Mustafanın taxtdan endirilməsi", "0291c1cd"], "d": ["Padşahın Ədirnədə oturması və Feyzullah Əfəndinin nüfuzuna duyulan qəzəb böyük bir ordu-esnaf üsyanına çevrildi; şeyxülislam linç edildi, padşah taxtdan endirildi, saray İstanbula qayıtdı.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Parisə səfir: Yirmi səkkiz Mehmed Çələbi", "26312a3f"], "d": ["Fransaya göndərilən böyük səfirlik Qərbi yerində araşdıran ilk sistemli müşahidə oldu; Səfarətnaməsi Lalə Dövrü yenilənməsinə ilham verdi.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["İlk Osmanlı mətbəəsi quruldu", "4943f7e5"], "d": ["Türkcə kitab çap etmək icazəsi verildi; ilk əsər Vankulu Lüğəti 1729-da çap edildi. Mətbəə Lalə Dövrü yenilənməsinin ən daimi irsidir.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Kapitulyasiyalar daimi hala gətirildi", "d044a79e"], "d": ["Fransaya verilən imtiyazlar padşahla məhdud olmaqdan çıxarılıb daimi müqaviləyə bağlandı; birtərəfli ləğv edilə bilməz hala gələn kapitulyasiya rejimi ancaq Lozannada ləğv edilə bildi.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Mühəndisxanəyi-Bəhri-Hümayun quruldu", "9bf3f439"], "d": ["Çeşmə fəlakətindən sonra müasir dəniz zabiti yetişdirmək üçün qurulan mühəndisxana Qərb tipli texniki təhsilin ilk daimi qurumudur; quru mühəndisxanası 1795-də izlədi.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Londonda ilk daimi səfirlik", "6b5630eb"], "d": ["Nizami-Cədid proqramının bir hissəsi olaraq Avropa paytaxtlarında daimi səfirliklər açıldı; Osmanlı diplomatiyası qarşılıqlılıq əsasına keçdi.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Alemdar Mustafa Paşanın ölümü", "4426534e"], "d": ["15 Noyabr 1808 gecəsi başlayan yeniçəri üsyanında Babıalidə mühasirəyə alınan islahatçı sədrəzəm gözlədiyi kömək gəlmədikdə ertəsi gün sursat anbarını alovlandıraraq yüzlərlə hücumçu ilə birlikdə öldü; Sənədi-İttifaq qaydası və ilk islahat cəhdi onunla birlikdə dəfn edildi.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["İlk rəsmi qəzet: Təqvimi-Vəqayi", "c637f623"], "d": ["Dövlətin rəsmi qəzeti nəşr olunmağa başladı; müasir ictimai rəy və rəsmi elan ənənəsinin başlanğıcıdır.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Balta Limanı Ticarət Müqaviləsi", "e790b383"], "d": ["İngiltərəyə daxili ticarətdə belə ən imtiyazlı mövqe tanındı, yədi-vahid (inhisar) üsulu ləğv edildi; yerli istehsal müdafiəsiz qalarkən müqavilə Osmanlı bazarının sərbəst ticarətə tam açılışının sənədi oldu.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Livan Əmirliyinin sonu — III Bəşir Şihabın vəzifədən alınması", "f85ae454"], "d": ["Xristian-Druz çəkişməsini və Şuf bölgəsindəki daxili tarazlıqları nəzarət edə bilməyən Əmir II (III) Bəşir Yanvar 1842-də vəzifədən alındı; 1516-dan bəri (Maanoğulları və ardınca Şihaboğulları əli ilə) davam edən yerli əmirlik qaydası sona çatdı və bölgə birbaşa Osmanlı idarəsinə, ardınca ikili qaymaqamlıq sisteminə keçdi.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Təshihi-sikkə: Məcidiyyə qaydası", "c77be809"], "d": ["Pul islahatı ilə əyarı pozulmuş sikkələr toplatdırıldı; qızıl lirə (Məcidiyyə) əsaslı sabit iki metal qaydası quruldu.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Baalbəkdə Xərfuş ailəsinin yerli hakimiyyətinin sonu", "8438f4ae"], "d": ["1521-dən bəri (Canbirdi Qəzali üsyanından sonra) Baalbəkdə kiçik bir yerli sülalə olaraq hökm sürən Xərfuş ailəsinin nüfuzu Babialinin yeni inzibati nizamlanması ilə sona çatdı; şəhər Şam vilayətinə bağlı adi bir qəza mərkəzi halına gətirildi.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Şirkəti-Xeyriyyə quruldu", "462830e7"], "d": ["Boğaziçində paroxod işlətmək üçün qurulan şirkət ilk Osmanlı səhmdar cəmiyyəti sayılır; şəhər həyatına paroxod körpüləri möhür vurdu.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["İlk xarici borc müqaviləsi", "9017c579"], "d": ["Krım müharibəsinin maliyyələşdirilməsi üçün London bazarından ilk xarici istiqraz alındı; 21 ildə 15 borclanma ilə gəlinən nöqtə 1875 moratoriumu və Düyuni-Ümumiyyə oldu.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Teleqraf xətti İstanbulda", "d320f39f"], "d": ["Krım müharibəsinin ehtiyacları ilə qurulan ilk teleqraf xətti istismara açıldı; imperiya bir neçə onillikdə dünyanın ən geniş teleqraf şəbəkələrindən birinə qovuşdu.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Torpaq Qanunnaməsi", "6bae243a"], "d": ["Torpaq hüququnu müasirləşdirən qanunnamə miri torpaqda faktiki istifadəni tapuya bağladı; bugünkü Yaxın Şərqin mülkiyyət qaydasının əsas sənədlərindəndir.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Darülfünunda ilk dərslər", "08f74066"], "d": ["Universitet səviyyəsində təhsil verəcək Darülfünun ictimaiyyətə açıq dərslərlə fəaliyyətə başladı; fasilələrlə davam edən qurum 1900-də daimi olaraq açıldı və İstanbul Universitetinin nüvəsi oldu.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Vilayət Nizamnaməsi", "ad20853b"], "d": ["Əyalət qaydası yerinə Fransız modelində vilayət təşkilatı quruldu; Midhat Paşanın Tuna Vilayəti tətbiqi nümunə götürülərək bütün ölkəyə yayıldı.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Əbdüləzizin Avropa səyahəti", "9ff0fa1e"], "d": ["Bir Osmanlı padşahının sülh məqsədli ilk Avropa səyahəti; Paris sərgisi və London ziyarətləri həm diplomatiya, həm modernləşmə vitrini funksiyası gördü.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Qalatasaray Məktəbi-Sultanisi açıldı", "f9688524"], "d": ["Fransızca təhsil verən lisey din və millət ayrımı gözləməyən şagird tərkibi ilə Tənzimatın təhsildə bərabərlik idealının rəmzi oldu.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Məcəllənin ilk kitabı qüvvədə", "6475461c"], "d": ["İslam hüququnun öhdəliklər-əşya sahəsini müasir qanun texnikası ilə toplayan Məcəllə ilk İslam mülki qanunu sayılır; Cövdət Paşanın başçılıq etdiyi heyət 16 kitabı 1876-da tamamladı.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Əbdüləzizin taxtdan endirilməsi", "eb7397ea"], "d": ["Məşrutiyyətçi dövlət adamları və hərbi rəhbərlik Əbdüləzizi səssiz bir çevrilişlə endirdi; beş gün sonra şübhəli ölümü, ardınca gələn Çırağan hadisələri illərlə davam edəcək hesablaşmalar doğurdu.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Çırağan basqını (Əli Suavi hadisəsi)", "d2a9ac87"], "d": ["Jurnalist Əli Suavi V Muradı yenidən taxta çıxarmaq üçün Çırağanı basdı; basqın qanlı şəkildə yatırıldı, Əbdülhəmid rejimi təhlükəsizlik çevrəsini daimi olaraq sıxlaşdırdı.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Reji İdarəsi quruldu (tütün inhisarı)", "bad9b030"], "d": ["Tütün gəlirləri Düyuni-Ümumiyyə tərkibindəki xarici kapitallı Reji şirkətinə verildi; kəndli ilə qolçular arasındakı 'Reji qaçaqmalçılığı' toqquşmaları onilliklərlə davam etdi. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Zeyla.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["İmperator II Vilhelmin İstanbul və Qüds ziyarəti", "2988cd06"], "d": ["Alman imperatorunun ikinci ziyarəti Osmanlı-Alman yaxınlaşmasını möhkəmləndirdi; Bağdad dəmir yolu imtiyazının yolu açıldı, Şamda 'üç yüz milyon müsəlmanın dostu' nitqi söylənildi.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Hicaz Dəmir Yolu Mədinədə", "95009b9c"], "d": ["Yalnız müsəlman ianələri və yerli mühəndislik ilə tikilən 1464 km-lik xətt Mədinəyə çatdı; həcc səyahəti həftələrdən günlərə endi. II Əbdülhəmid dövrünün ən böyük infrastruktur əsəridir.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["31 Mart Hadisəsi", "1d7c2bb2"], "d": ["Məşrutiyyət əleyhdarı böyük üsyan İstanbulu ələ keçirdi; Salonikdən gələn Hərəkat Ordusu üsyanı yatırdı və II Əbdülhəmid taxtdan endirildi.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Ədirnə mühasirəsi başladı", "234d9b28"], "d": ["Şükrü Paşanın beş ay davam edən müdafiəsi Balkan fəlakəti içindəki müqavimət dastanı oldu; şəhər aclıqla süqut etdi, İyul 1913-də geri alındı.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Babıali basqını", "b304d02d"], "d": ["Ədirnənin təslimə hazırlaşan hökumət İttihadçıların silahlı basqını ilə devrildi; Hərbiyyə Naziri Nazım Paşa öldürüldü. İttihad və Tərəqqinin tam hakimiyyət dövrü başladı.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Cəbəl Livan Mütəsərrifliyinin ləğvi", "b5639051"], "d": ["1861 Reglement Organique ilə qurulan və 1864-də yenilənən beynəlxalq protokola əsaslanan muxtar mütəsərriflik qaydası I Dünya müharibəsi zamanı Osmanlı Dövləti tərəfindən birtərəfli şəkildə ləğv edildi; Daxiliyyə Nəzarəti bölgəyə birbaşa müsəlman mütəsərriflər təyin etməyə başladı. 1861-1915 arası səkkiz mütəsərrifin vəzifə apardığı muxtariyyət dövrü beləliklə bağlandı.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Şahzadələr arasında ölkənin bölünməsi", "82f26bfb"], "d": ["Ankara məğlubiyyətindən sonra Süleyman Çələbi Rumeliyə keçdi və Ədirnədə səltənət elan etdi; İsa Çələbi Bursanı, Çələbi Mehmed isə Amasya-Tokat-Sivas bölgəsini əlində saxladı. Xəritədə bu üç pay ayrı rənglərlə göstərilir.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Gəlibolu Müqaviləsi: Misivriyə qədər Qara dəniz sahili Bizansa buraxıldı", "a4164eca"], "d": ["Ankara məğlubiyyətindən sonra Rumelidə tutunmaq istəyən Əmir Süleyman Gəliboluda Bizans İmperatoru Manuel ilə müqavilə imzaladı. Kartal, Pendik və Gebze ilə bəzi adaları, Rumelidə Saloniki və Teselyanı, Qara dənizdə də Misivriyə qədər uzanan sahil zolağını Bizansa buraxdı; Bizansın Osmanlılara ödədiyi vergi də ləğv edildi. İstranca sahilindəki Axtopol, İyneada və Rezve beləliklə iyirmi bir il Bizans idarəsində qaldı; II Murad 1424 sülhü ilə bu yerlərin çoxunu geri aldı.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Yıldırım Bəyazidin əsirlikdə ölümü", "7e968d83"], "d": ["Teymurun əlində əsir olan padşah Akşehirdə vəfat etdi; cənazəsi Bursaya gətirilərək dəfn edildi. Ölümü şahzadələr arasındakı taxt mübarizəsini geri dönməz hala gətirdi.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Gəlibolu Müqaviləsi — Bizansa güzəştlər", "dfacbd00"], "d": ["Rumelidəki mövqeyini təmin etmək istəyən Süleyman Çələbi Bizans və Latın dövlətləri ilə razılaşaraq Saloniki, Mərmərə sahillərini və bəzi adaları qaytardı; xərac ödəməyi belə qəbul etdi.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Ulubat toqquşması — İsa Çələbinin məğlubiyyəti", "500c5d24"], "d": ["Bursanı əlində saxlayan İsa Çələbi qardaşı Mehmed qarşısında Ulubatda məğlub oldu; bir neçə dəfə toparlanma cəhdi də nəticəsiz qaldı.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["İsa Çələbinin aradan qalxması", "0effa11e"], "d": ["Süleyman Çələbinin dəstəyi ilə bir neçə dəfə Anadoluya qayıdan İsa Çələbi son məğlubiyyətindən sonra yoxa çıxdı; payı Çələbi Mehmedə keçdi və xəritədə Mehmedin sahəsi qərbə doğru genişləndi.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çələbi Eflaka keçdi", "8441267a"], "d": ["Süleyman Çələbi qarşısında Bursa və Ankaranı itirib Tokat-Amasyaya çəkilən Çələbi Mehmed qardaşı Musanı Rumeliyə getməyə təşviq etdi. Musa Eflak Voyvodası Mirçeanın dəvətini qəbul edərək dəniz yolu ilə Eflaka çatdı; buradan Süleymanı iki cəbhə arasında buraxacaq mübarizəyə girişəcəkdi.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çələbi Mehmed Bursa və Ankaranı yenidən aldı — Anadolu payı Süleyman Çələbidən çıxdı", "bfb69f12"], "d": ["Musa Çələbinin Rumelidəki uğurları (Yanbolu, 13 Fevral 1410) üzərinə Anadoluda olan Əmir Süleyman Çələbi Rumeliyə keçdi. Süleymanın Anadoludan ayrılmasından sonra Mehmed Çələbi Ankara daxil Bursa ətrafını yenidən ələ keçirdi və taxta keçdiyinin işarəsi olaraq 813 tarixli sikkə kəsdirdi. Xəritədə Mərmərənin Anadolu yakası Əmir Süleymanın payından Çələbi Mehmedin rənginə keçir.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Kosmidion döyüşü", "0efc2caa"], "d": ["Bizans dəstəyi ilə İstanbul divarları önündə aparılan döyüşdə Süleyman Çələbi qardaşı Musanı məğlub etdi; lakin Rumelidəki dəstəyi sürətlə əriməyə başlamışdı.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Musa Çələbinin İstanbul mühasirəsi", "4932f586"], "d": ["Süleymanı dəstəkləyən Bizansı cəzalandırmaq istəyən Musa Çələbi İstanbulu mühasirəyə aldı; bu mühasirə Bizansı Çələbi Mehmedlə ittifaqa itələdi.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Əmir Süleymanın ölümü — Musa Rumeliyə hakim", "325c1549"], "d": ["Ədirnədən qaçarkən yaxalanan Süleyman Çələbi öldürüldü; Rumelinin hamısı Musa Çələbinin əlinə keçdi. Xəritədə Rumeli mavi rəngdən bənövşəyi rənginə dönür.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Çamurlu döyüşü — birliyin yenidən qurulması", "0b23173e"], "d": ["Bizans, Serb despotluğu və Rumeli bəylərinin dəstəyini alan Çələbi Mehmed qardaşı Musanı Çamurluda qəti məğlubiyyətə uğratdı; Musa qaçarkən öldürüldü. Musanın əlindəki Rumeli Ədirnə ilə birlikdə Mehmedə keçdi və Mehmed Çələbi Ədirnədə özünü Osmanlı Dövlətinin yeganə hökmdarı elan etdi. On bir illik Fətrət Dövrü sona çatdı, xəritədəki şahzadə payları tək gövdədə birləşdi.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Vyana yürüşü qərarı — Vasvár sülhü yenilənmədi, hədəf Yanıqqaladan Vyanaya çevrildi", "1bf278f2"], "d": ["İmperator I Leopold müddəti hələ dolmamış Vasvár Müqaviləsinin yenilənməsini istəyir, IV Mehmed də sülhdən yana görünürdü. Sədrəzəm Mərzifonlu Qara Mustafa Paşa isə Orta Macar kralı elan etdirdiyi İmre Tökölinin şikayətlərini əsas gətirərək sülhü yenilətmədi; Vani Mehmed Əfəndi başda olmaqla vaizləri hərəkətə keçirib padşahı müharibəyə razı saldı. Edilən məşvərətdə padşahın Belqradda qalması, sərdari-əkrəmin Yanıqqalanı almaq üçün irəliləməsi qərara alındı; lakin İstolni Belqraddakı məşvərətdə Krım xanı Murad Giray ilə Budin valisi Uzun İbrahim Paşanın etirazına baxmayaraq hədəf Vyananın mühasirəyə alınması olaraq dəyişdirildi.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["II Vyana mühasirəsi başladı — ordu Vyana önlərində", "bb542e49"], "d": ["Vəzirəzəm Qara Mustafa Paşanın komandanlığındakı Osmanlı ordusu 14 İyul 1683-də Vyana önlərinə gəldi. İmperator I Leopold şəhərin mühafizəsini Starhembergə buraxaraq Avstriya içlərinə çəkildi. Birincidən fərqli olaraq birbaşa Vyana hədəf alınaraq hazırlanan bu ikinci mühasirə 12 Sentyabra qədər davam edəcəkdi.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Parkan məğlubiyyəti və Estergonun itirilməsi", "a7366740"], "d": ["Vyanadan çəkilən ordu Parkanda ikinci dəfə məğlub oldu; ardınca Macarıstanın açar qalalarından Estergon süqut etdi. Geri çəkilmə çöküşə çevrilməyə başladı.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Mərzifonlu Qara Mustafa Paşanın edamı", "ce8b10ac"], "d": ["Vyana məğlubiyyətinin məsuliyyətli sayılan sədrəzəm Belqradda boğdurulub öldürüldü; lakin edamı nə cəbhəni düzəltdi, nə də dövlətin sarsılan nüfuzunu geri gətirdi.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Müqəddəs İttifaq quruldu", "060280d0"], "d": ["Papalığın başçılığı ilə Avstriya, Polşa və Venesiya arasında Osmanlıya qarşı Müqəddəs İttifaq (Müqəddəs İttifaq) quruldu; 1686-da Rusiya da qatıldı. Beləliklə imperiya on altı il davam edəcək çoxcəbhəli müharibəyə girdi.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Birinci Budin müdafiəsi", "ccc43630"], "d": ["Müqəddəs İttifaq ordusunun ilk Budin mühasirəsi qalanın dörd ay davam edən inadkar müdafiəsi ilə dəf edildi; lakin Macarıstandakı qalalar tək-tək süqut etməyə davam edirdi.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Uyvarın itirilməsi", "689ab78c"], "d": ["İyirmi iki il Osmanlı əlində qalan və Avropada atalar sözü olan Uyvar qalası süqut etdi; Yuxarı Macarıstandakı Osmanlı mövcudluğu dağıldı.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Tökölinin Varadda həbs edilməsi — Orta Macar Krallığı dağıldı, Yuxarı Macarıstan qalaları təslim oldu", "1741aaaf"], "d": ["Vyana məğlubiyyətindən sonra Osmanlılar Tökölini də müharibəyə və məğlubiyyətə yol açanlar arasında görməyə başlamışdı. 15 Oktyabr 1685-də Sərdar Məlik İbrahim Paşanın əmri ilə Varad bəylərbəyi Əhməd Paşa köməyə gələn Tökölini yaxalatdı; onu Habsburqlara təslim edərək daha yaxşı sülh şərtləri əldə etmək ümid edilirdi. Həbs xəbəri yayıldıqda həyat yoldaşı Ilona Zrínyinin müdafiə etdiyi Munkács istisna olmaqla Orta Macar Krallığının bütün qala və şəhərləri Habsburqlara təslim oldu; Kuruc əsgərlərinin çoxu Habsburq ordusuna keçdi. Tököli 2 Yanvar 1686-da Belqradda sərbəst buraxıldıqda krallıq artıq aradan qalxmışdı.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Budinin itirilməsi — 145 illik Macar paytaxtı", "70800e2b"], "d": ["Yetmiş səkkiz gün davam edən mühasirənin sonunda Budin süqut etdi; son bəylərbəyi Əbdürrəhman Abdi Paşa divarlarda şəhid oldu. 1541-dən bəri Osmanlı idarəsində olan şəhərin itirilməsi Macarıstanın əldən çıxmasının rəmzi sayılır. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Peşt.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["İkinci Mohaç (Harşan) məğlubiyyəti — Erdelin və Mohaçın itirilməsi", "a7922681"], "d": ["1526-da böyük qələbənin qazanıldığı düzdə bu dəfə ağır məğlubiyyət alındı; ordu dağıldı, üsyan edən əsgərlər sədrəzəmi vəzifədən saldırdı. Məğlubiyyət Erdelin də itirilməsinə yol açdı.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Afinanın itirilməsi və Parthenon partlayışı", "b6691730"], "d": ["Venesiya topçusunun atdığı bir bomba Osmanlıların sursat anbarı olaraq istifadə etdiyi Parthenonu havaya uçurdu; iki min illik məbəd xarabalığa döndü. Şəhər Venesiya əlinə keçdi (1688-də geri alınacaqdır).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["IV Mehmedin taxtdan endirilməsi və II Süleymanın cülusu", "9f53037c"], "d": ["Cəbhədəki fəlakətlər və ordunun üsyanı üzərinə 39 illik səltənətindən sonra IV Mehmed taxtdan endirildi; yerinə qırx ildir qəfəsdə saxlanılan qardaşı II Süleyman gətirildi.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Belqradın ilk dəfə itirilməsi — Müqəddəs İttifaq mühasirəsi", "c6b9b19a"], "d": ["1521-dən bəri Osmanlı əlində olan Belqrad Müqəddəs İttifaq ordusuna təslim oldu; Serbiyanın qapıları düşmənə açıldı və təhlükə Niş-Sofiya xəttinə dayandı. Eyni tarixdə atlasda Osmanlıdan Habsburqa keçən digər yaşayış məntəqəsi: Hisarcıq (Grocka) — Belqradın abi-mərkəz zəncirini izləyir (TDV belgrad; bəyanlı təqribilik).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden Pasarofça önündə Moravanı keçdi — Pasarofça Avstriyaya düşdü", "bcf3fc59"], "d": ["Markqraf Ludwig von Baden Avqust 1689-da Moravanı Pasarofçada keçərək Niş istiqamətinə irəlilədi; şəhər 1690-cı ilin yayına qədər Avstriya əlində qaldı (TDV suleyman-ii 1690-da Pasarofçanın geri alındığını deyir). Gün və Röder oxunuşu bu sessiyada yenidən doğrulanmadı.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Nişin itirilməsi — Habsburq (Macarıstan Krallığı tacı) irəliləyişi, ən kritik il", "c5e27b3f"], "d": ["Habsburq (Macarıstan Krallığı tacı) irəliləyişi Nişi Osmanlı idarəsindən də aldı; basqınlar Üsküp və Priştinəyə qədər uzandı. Vidin isə bundan sonra, Oktyabr 1689-da süqut etdi (ayrı maddə). Müharibənin ən qaranlıq ilində dövlət paytaxtını belə təhdid altında hiss etdi.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova və Fəthülislam Avstriya qarnizonuna alındı", "ee8dd875"], "d": ["Vidinin döyüşsüz alınmasından (Oktyabr 1689, TDV vidin) sonra Baden 25 Oktyabr 1689-da Orsova və Fəthülislamı təmir edib qarnizonlaşdırdı; Orsova 1690-cı ilin payızına qədər Avstriyada qaldı. Gün Bánlaky/Röderə əsaslanır, bu sessiyada yenidən doğrulanmadı.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niş yenidən Osmanlıda", "0c4f44eb"], "d": ["Fazıl Mustafa Paşa İyul 1690-da yürüşə çıxdı; Şəhərköy, Pasarofça və Göyərçinlik alındıqdan sonra mühasirəyə alınan Niş 27 Sentyabr 1690-da Osmanlıların əlinə keçdi (TDV semendire). Eyni zamanda Vidin də geri alınmışdı. Eyni tarixdə atlasda Habsburqdan Osmanlıya dönən digər yaşayış məntəqələri: Yaqodina (Jagodina) və Ürküp (Prokuplje) — yer səviyyəsində gün tapılmadığından Niş günü götürülmüşdür (TDV semendire; bəyanlı təqribilik; Röder 1842 vəzirin Yaqodinadan 8-24 Sentyabrda keçdiyini yazır, ziddiyyət həll edilmədi).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Smederevoda Avstriya birlikləri təslim oldu", "90da20c4"], "d": ["Nişin 27 Sentyabr 1690-da alınmasından sonra dörd günlük mühasirə ilə Smederevodakı Avstriya birlikləri təslim oldu (TDV semendire). Bánlaky/Röder 24 Sentyabr deyir; mənbələr ziddiyyətlidir, TDV əsas götürüldü.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belqrad geri alındı", "ab435838"], "d": ["Sədrəzəm Köprülüzadə Fazıl Mustafa Paşa 8 Oktyabr 1690-da Belqradı Avstriyadan geri aldı; 1688-də itirilən şəhər beləliklə Osmanlıya döndü (TDV suleyman-ii). Eyni tarixdə atlasda Habsburqdan Osmanlıya dönən digər yaşayış məntəqəsi: Hisarcıq (Grocka) — Belqradın abi-mərkəz zəncirini izləyir (TDV suleyman-ii; bəyanlı təqribilik).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Salankamen məğlubiyyəti — Fazıl Mustafa Paşa şəhid", "10d626f1"], "d": ["Əsrin ən qanlı meydan döyüşlərindən birində sədrəzəm alnından vurularaq şəhid düşdü; ordu dağıldı. Toparlanma ümidi bu döyüşlə birlikdə söndü.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Xios adasının itirilməsi", "07c084f8"], "d": ["Venesiya donanması Xiosu işğal etdi; Egeydəki Osmanlı hakimiyyəti təhdid altına girdi. Ada ertəsi il geri alınacaqdır.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["II Mustafanın yürüşə şəxsən çıxma qərarı", "61c3ba9c"], "d": ["Yeni padşah ataların yolu ilə gedərək ordunun başında yürüşə çıxacağını elan etdi; bu qərar ordu içində mənəviyyat yaratdı və iki il davam edəcək şəxsi yürüşlər dövrünü başlatdı.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Xiosun geri alınması", "6b496fca"], "d": ["Quzu Adaları dəniz döyüşlərində Venesiya donanmasını məğlub edən Mezomorto Hüseyn Paşa Xiosu geri aldı; Osmanlı dənizçiliyində qısa bir dirçəlişin əlaməti oldu.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Lugoş qələbəsi — II Mustafanın birinci Avstriya yürüşü", "d5ee9b34"], "d": ["Padşahın şəxsən qatıldığı ilk yürüşdə Lipova geri alındı və Lugoşda Avstriya qüvvələri məğlub oldu; illərdir davam edən məğlubiyyət zəncirində ilk qırılma yaşandı. Atlas Karánşebeşi (Caransebeş) də bu yürüşdə Habsburqdan Osmanlıya dönmüş sayır; mənbə yalnız Sentyabr 1695-i verir (TDV mustafa-ii), atlas günü Lugoş qeydindən götürülmüşdür (bəyanlı təqribilik).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Azak qalasının itirilməsi", "2b78b5cd"], "d": ["Qara dənizə çıxmağı hədəfləyən I Pyotr ikinci mühasirəsində Azakı aldı; Rusiya ilk dəfə bir Osmanlı qalasına daimi olaraq yerləşdi və dəniz gücü olma yolunda ilk addımını atdı.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Ulaş (Olaşin) qələbəsi", "02ac9ca8"], "d": ["Padşahın ikinci yürüşündə Dunay sahilində qazanılan qələbə Avstriyanın Temeşvarı alma planını pozdu; lakin müharibənin ümumi tarazlığını dəyişdirmədi.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Zenta məğlubiyyəti — müharibənin taleyi müəyyən edildi", "475c4a7b"], "d": ["Ordu Tisa çayını keçərkən Şahzadə Evgeninin qəfil basqınına uğradı; çayın iki yakasında bölünən qüvvələr bir neçə saatda məhv edildi, sədrəzəm Almas Mehmed Paşa daxil minlərlə əsgər və dövlət adamı öldü. Osmanlı tarixinin ən ağır məğlubiyyətlərindən biri olan Zenta sülh masasını qaçılmaz etdi.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Karlovits sülh danışıqları başladı", "1f395cf3"], "d": ["İngiltərə və Hollandiyanın vasitəçiliyi ilə başlayan danışıqlarda Osmanlı heyəti ilk dəfə 'uti possidetis' (əldə olanın qalması) prinsipini qəbul etməyə məcbur qaldı; yetmiş iki iclas davam edən danışıqlar müasir Osmanlı diplomatiyasının doğuşu sayılır.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Qavalalı Məhəmməd Əli Misirə çıxdı", "514c943f"], "d": ["Fransız işğalındakı Misiri geri almaq üçün göndərilən Osmanlı ordusunun içində Qavaladan toplanan könüllü birlik də var idi. Otuzlu yaşlarındakı Məhəmməd Əli bu birliyin ikinci komandanı idi; Misirə bir canişin deyil, bir bölük zabiti olaraq ayaq basdı.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Alban əsgərləri Misir canişinini devirdi", "c76a0ec2"], "d": ["Maaşları ödənilməyən Alban birlikləri üsyan edib canişin Xosrov Paşanı qaladan qaçmağa məcbur etdi. Fransızların çəkilməsi ilə yaranan boşluqda Kölə bəyləri, Alban ocağı və Babialinin təyin etdiyi canişinlər üçbucaqlı mübarizəyə girdi; Məhəmməd Əli bu üçbucaqda tarazlıqlar quraraq önə çıxdı. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Taif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Qahirə ülaması Məhəmməd Əlini canişin elan etdi", "a16752f2"], "d": ["Vergi təzyiqindən bezən Qahirə əsnafı və ülaması nəqibüləşrəf Ömər Məkrəmin rəhbərliyi ilə üsyan edib canişin Xurşid Paşanı tanımadıqlarını bildirdi və Məhəmməd Əlini canişinlik məqamına oturtdu. Osmanlı tarixində bir canişinin xalq tərəfindən seçilməsi nadir rast gəlinən bir hadisədir.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Babıali oldubittini qəbul etdi: Misir canişinliyi fərmanı", "b86736a3"], "d": ["Misirdə öz namizədini saxlamaq gücü olmayan Babıali Məhəmməd Əliyə vəzirlik rütbəsi ilə Misir canişinliyi fərmanı göndərdi. Xəritədə Misir bu tarixdən etibarən vassal (açıq ton) qatına keçir: hüquqən Osmanlı torpağı, faktiki olaraq Qavalalı sülaləsinin ölkəsidir. Eyni tarixdə vassal qata keçən digər yaşayış məntəqələri: Qahirə, İskəndəriyyə, Dəmyat, Asyut, Asvan, İbrim, Süveyş, Rəşid (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Britaniya Fraser yürüşü İskəndəriyyəyə çıxdı", "4d6c31be"], "d": ["Osmanlının Fransaya yaxınlaşmasına qarşılıq İngiltərə Misirə bir desant qüvvəsi göndərdi. Məhəmməd Əli o zaman Yuxarı Misirdə Kölələrlə məşğul idi; sürətlə qayıdaraq müdafiəni təşkil etdi.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Rəşid (Rosetta) məğlubiyyəti — İngilislər geri oturdu", "3636004c"], "d": ["Rəşid qəsəbəsinə girən İngilis qolu küçə döyüşlərində ağır itki verdi; Sentyabrda qüvvələr Misiri tamamilə boşaltdı. Bu qələbə Məhəmməd Əlinin həm Misirdəki, həm İstanbuldakı nüfuzunu möhkəmləndirdi.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Qala Hadisəsi: Kölə bəylərinin ləğvi", "84030b97"], "d": ["Hicaz yürüşü üçün təşkil edilən mərasim yürüşünə dəvət olunan Kölə bəyləri Qahirə Qalasının dar keçidində tələyə salınaraq aradan qaldırıldı. Beş əsrlik Kölə nüfuzu beləliklə sona çatdı və Misirdə Məhəmməd Əlinin qarşısında rəqib qalmadı.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Hicaz yürüşü başladı — ordu Süveyşdən dənizlə və həcc yolundan quru ilə Yənbuya yürüdü", "1c05c159"], "d": ["1803-dən bəri Süudi-Vəhhabi idarəsindəki Hərəməyni geri almaq II Mahmudun ən böyük legitimlik məsələsi idi; Babialinin gücü çatmadıqda vəzifə Misir canişininə verildi. Məhəmməd Əli on altı yaşlı oğlu Tosunu ordunun başında göndərdi.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yənbu təslim alındı — Hicaz yürüşünün ilk sahil bazası", "179bc78d"], "d": ["Süveyşdən yeni tikilmiş gəmilərlə yola çıxan iki min qədər Alban piyadası Oktyabr 1811-də Yənbu yaxınlığında quruya çıxdı; qəsəbə iki günlük zəif müqavimətdən sonra təslim oldu. Tosunun komandanlığındakı süvarilər həcc yolunu quru ilə izləyib Əqəbə və Vəcx üzərindən ancaq iki həftə sonra Yənbuya çatdı. Yənbu Mədinə və Məkkə üzərinə yürüyəcək Misir ordusunun Hicazdakı ilk bazası oldu.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Səfra-Cədidə boğazında ilk məğlubiyyət", "99ef804d"], "d": ["Dar dağ keçidlərində pusquya düşürülən Misir öncül qüvvəsi dağıldı. Məğlubiyyət yürüşün taktiki dərsi oldu: bədəvi qəbilələrin dəstəyi alınmadan Hicazda yürümənin mümkün olmadığı anlaşıldı.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Mədinə geri alındı", "6f6a5d55"], "d": ["Uzun bir mühasirədən sonra Mədinə təslim oldu. Həzrət Peyğəmbərin şəhərinin geri alınması İstanbulda top şənlikləri ilə qeyd edildi; Məhəmməd Əliyə mükafat olaraq Cidda canişinliyi də verildi.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Məkkə geri alındı — həcc yolu açıldı", "3d6d66a0"], "d": ["Məkkəyə girən Misir qüvvələri Kəbədə yenidən Osmanlı padşahı adına xütbə oxutdu. On ildir kəsintiyə uğrayan həcc karvanları yenidən yola çıxa bildi. Xəritədə Hicaz Osmanlı hakimiyyətinə dönür, lakin idarəsi Qahirədə olduğu üçün vassal tonda göstərilir. Eyni tarixdə vassal idarəyə keçən digər yer: Cidda.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Taifin geri alınması — Hicaz yürüşünün tamamlanması", "6315fb31"], "d": ["Mədinə (Dekabr 1812) və Məkkənin (Yanvar 1813) ardınca Tosun Paşanın komandanlığındakı Misir ordusu son olaraq Taifi Vəhhabilərdən geri aldı. On il davam edən Süud hakimiyyəti sona çatdı, Hicazın üç müqəddəs mərkəzi də yenidən Osmanlı-Misir nəzarətinə girmiş oldu.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Məhəmməd Əli şəxsən Hicaza keçdi", "fda0ea2d"], "d": ["Yürüşün ağır getdiyini görən canişin idarəni birbaşa öz əlinə aldı; qəbilə başçıları ilə sövdələşərək Süudi cəbhəsini içəridən həll etməyə çalışdı. Misirin Qırmızı dəniz ticarətindəki payı da bu yürüşlə böyüdü.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Bisel döyüşü: Süudi qüvvələri məğlub oldu", "9c9ab91f"], "d": ["Meydan döyüşündə ağır məğlubiyyət alan Süudilər daxili bölgələrə çəkildi. Edilən barışıq daimi olmadı; iki il sonra əməliyyat Nəcdin ürəyinə daşınacaqdı. Atlas bu qələbədən sonra Taif şərqindəki Türabə və Hurməni Süudi əlindən çıxmış sayır (hadisə mənbəyi Lorimer, Gazetteer; yaşayış məntəqələrinə məxsus şəhadət və 13 Yanvar günü bəyanlı təqribilikdir).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["İbrahim Paşa Nəcd yürüşünə çıxdı", "d5ed80d1"], "d": ["Qardaşı Tosunun ölümü üzərinə komandanlığı devralan İbrahim Paşa səhrada iki il davam edən ağır yürüşə girişdi. Quyu-quyu irəliləyən ordu qəbilələri tək-tək bertaraf edərək Süudi paytaxtına dayandı.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Diriyyə süqut etdi — ilk Süudi Dövləti sona çatdı", "aa96206d"], "d": ["Altı ay davam edən mühasirədən sonra Diriyyə təslim oldu və dağıdıldı. Əmir Abdullah b. Süud İstanbula göndərilərək edam edildi. Osmanlı bayrağı Ərəbistanın içlərinə ilk dəfə bu qədər dərin çatdı; Nəcd qarnizonu 1824-ə qədər qaldı. Eyni tarixdə qatılan digər yerlər: Diriyyə (Nəcd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Sudan yürüşü başladı", "b1fc6905"], "d": ["Məhəmməd Əlinin məqsədi üç qatlı idi: ordusuna əsgər toplamaq, Sənnar qızılına çatmaq və qaçan Kölə qalıqlarını məhv etmək. Oğlu İsmayıl Paşanın komandanlığındakı qüvvə Nili izləyərək cənuba endi.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola alındı — Kölə qalıqları dağıdıldı", "ba6bc24b"], "d": ["Nilin böyük əyrisindəki Dongolaya girən ordu buraya sığınmış son Kölə qrupunu ləğv etdi. Xəritədə Sudan bu tarixdən etibarən vassal qatda görünür: fəth edən Qahirədir, idarə edən də Qahirə olacaqdır.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Sənnar (Func) Sultanlığı təslim oldu", "3cac7dd2"], "d": ["Üç əsrlik Func sülaləsi döyüşsüz təslim oldu. Eyni il Nilin iki qolunun birləşdiyi nöqtədə qurulan ordugah qısa müddətdə Sudanın idarə mərkəzi Xartuma çevrildi. Eyni tarixdə qatılan digər yerlər: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan ələ keçirildi", "06440602"], "d": ["Qərbə göndərilən ikinci qol Barədə (Bara) Darfur qüvvələrini məğlub edərək Nühud ətrafı ilə birlikdə Kordofanı aldı. Misirin Sudan hakimiyyəti beləliklə Nil vadisindən qərb bozqırlarına genişləndi.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Giritə Misir qüvvələri çıxdı", "835aee90"], "d": ["Rum üsyanı Giritə sıçradıqda Babıali adaya Misir qüvvəsi göndərilməsini istədi. Məhəmməd Əlinin adadakı nüfuzu bu müdaxilə ilə başladı və səkkiz il sonra Girit canişinliyinin ona verilməsi ilə nəticələndi.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Şəndidə İsmayıl Paşanın öldürülməsi", "223860c9"], "d": ["Ağır vergi və əsgər tələbinə qəzəblənən yerli əmir Nəmir qaldığı evi odlayıb İsmayıl Paşanı və yanındakıları yandırdı. Qisas yürüşü bölgəni qan gölünə çevirdi; Sudan idarəsi bundan sonra sərtlik üzərində quruldu.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["II Mahmud Moreya üçün Məhəmməd Əlidən kömək istədi", "03594a42"], "d": ["Yeniçəri ordusu ilə üç ildə yatırıla bilməyən Moreya üsyanı üçün padşah Avropa üsulu ilə təlim görmüş Misir ordusuna müraciət etdi. Müqabilində Moreya canişinliyi və Girit vəd edildi. Bu istək imperiyanın öz vilayətinə möhtac hala gəldiyinin ilk açıq etirafı idi.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["İbrahim Paşa Modona çıxdı", "9c993dba"], "d": ["Misir donanmasının qoruduğu desant qüvvəsi Moreyanın cənub-qərb ucuna ayaq basdı. Nizami piyada və səhra topçusu ilə təchiz edilmiş bu ordu üsyançı dəstələrə qarşı qısa müddətdə üstünlük təmin etdi.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa geri alındı — Moreyanın mərkəzi süqut etdi", "8a478c11"], "d": ["Üsyanın idarə mərkəzi Tripolitsanın süqutu ilə Moreyanın böyük hissəsi yenidən nəzarət altına girdi. Xəritədə yarımada Misir qüvvələrinin əlində olduğu üçün vassal tonla görünür.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonqi (Mesolonqi) süqut etdi", "07257f87"], "d": ["Bir il davam edən mühasirədən sonra şəhər alındı. Lakin müdafiənin Avropa mətbuatında yaratdığı əks-səda Yunan davasına duyulan simpatiyanı zirvəyə çıxardı və böyük dövlətlərin müdaxiləsinin zəminini hazırladı.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Afina Akropolu təslim alındı", "3b19f946"], "d": ["Akropolun süqutu ilə Yunan üsyanı hərbi olaraq demək olar ki, bitmişdi. Məhz bu nöqtədə məsələ daxili üsyan olmaqdan çıxıb Avropa diplomatiyasının mövzusuna çevrildi.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["London Müqaviləsi: üç dövlət Yunan muxtariyyətini diktə etdi", "7ce46fd8"], "d": ["İngiltərə, Fransa və Rusiya Osmanlı ilə Yunanlar arasında atəşkəs və muxtariyyət şərtini qəbul etdirmək üçün birgə hərəkət qərarı aldı; rədd edilərsə donanmalarının müdaxilə edəcəyi bildirildi. Babıali təklifi rədd etdi.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["İskəndəriyyə Sazişi: Misirin Moreyadan çəkilmə qərarı", "cc978f37"], "d": ["Navarində donanmasını itirən Məhəmməd Əli İstanbulla məsləhətləşmədən Britaniya admiralı ilə birbaşa razılaşaraq qüvvələrini Moreyadan çəkməyi qəbul etdi. Bir canişinin böyük dövlətlərlə müstəqil müqavilə bağlaması gələcək böhranın xəbərçisi idi.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Misir qüvvələri Moreyanı boşaltdı", "8fb742dd"], "d": ["Son birliklər gəmilərə mindirildi; yarımada faktiki olaraq əldən çıxdı və 1830 London Protokolu ilə müstəqil Yunanıstanın nüvəsi oldu. Məhəmməd Əli isə vəd edilən Moreya canişinliyini ala bilməmiş, müqabilində böyük bir donanma və ordu itirmişdi. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Giritin idarəsi Məhəmməd Əliyə buraxıldı", "7f76396d"], "d": ["Moreya itkisinin əvəzi olaraq Girit canişinliyi Məhəmməd Əliyə verildi. Ada on il boyunca Qahirədən idarə edildi; xəritədə bu müddət ərzində vassal tonda görünür. Eyni tarixdə qatılan digər yerlər: Kandiya (Girit).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["İbrahim Paşa Suriyaya girdi — birinci böhran başladı", "1a5cc386"], "d": ["Bəhanə Misirdən qaçan fellahları qaytarmayan Əkka canişini idi; əsl səbəb Məhəmməd Əlinin Suriyanın şam ağacına, limanlarına və insan resursuna ehtiyacı idi. Ordu Sinanı keçib Fələstin sahilini sürətlə ələ keçirdi.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Əkka mühasirəsi başladı", "b211d96d"], "d": ["Napoleonu 1799-da dayandıran qala altı ay müqavimət göstərdi. Mühasirə Misir ordusunun müasir topçusunun ilk böyük imtahanı idi.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Əkka süqut etdi", "0f47917b"], "d": ["Divarları döyən batareyalar yarıq açdıqda qala alındı. Suriyanın qapısı açılmışdı; Babıali eyni günlərdə Məhəmməd Əlini üsyançı elan etdi və canişinliyini ləğv etdi.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Şam təslim oldu", "48da3b62"], "d": ["Şəhər toqquşmadan təslim oldu. İbrahim Paşa vergi nizamını və qeyri-müsəlmanlara tanınan bərabərliyi elan edərək yerli dəstəyi qazanmağa çalışdı; eyni siyasətlər bir neçə il sonra ona qarşı üsyanların da səbəbi olacaqdı. Eyni günlərdə qatılan digər yerlər: Beyrut, Tripoli, Sayda.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Hims döyüşü", "867810ee"], "d": ["Suriyanı xilas etmək üçün göndərilən Osmanlı ordusu açıq ərazidə məğlub oldu. Yeniçəriliyin ləğvindən altı il sonra qurulan yeni ordunun hələ hazır olmadığı görüldü.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Hələb ələ keçirildi", "9c0ead76"], "d": ["Şimali Suriyanın ticarət və idarə mərkəzi də süqut etdi. Beləliklə Misir ordusu Toros dağlarının ətəklərinə dayandı və Anadolunun qapısındakı keçidlərə yönəldi.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Belen (Beylan) keçidi məğlubiyyəti — Çukurova açıldı", "4bae872b"], "d": ["Amanos dağlarındakı dar keçiddə müdafiə xətti yarıldı. Antakya, Adana və Tarsus Misir qüvvələrinə keçdi (Maraşın işğalı TDV-yə görə 1833-dür, ayrı maddə); xəritədə Çukurova vassal tona dönür. Anadolu içlərinə gedən yol artıq müdafiəsiz idi.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Gülək boğazı süqut etdi — İçil sahili (Mersin, Silifkə) Misir nəzarətinə girdi", "d9049b5b"], "d": ["Torosların Çukurova qapısı Gülək boğazı Misir ordusunun əlinə keçdi. İbrahim Paşa İçil Sancağına öz mütəsəllimini təyin etdi və sahildəki bütün körpülər Misir nəzarətinə girdi. Xəritədə Mersin və Silifkə bu gündən etibarən (alt hədd; təyinat günü mənbədə yoxdur) Misirə bağlı göstərilir; Kütahya qərarında yalnız Adana muhassilliyi keçdiyi üçün bu nəzarət Anadolu təxliyəsi ilə sona çatır.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğlisi Misir işğalında — Konya–Adana yolunun Toros ağzı", "fb908900"], "d": ["Gülək boğazını aşan Misir ordusunun Konyaya gedən yolu üstündəki Ereğli 1832-də İbrahim Paşanın işğalına girdi və 1833 Kütahya nizamlanması ilə boşaldıldıqda yenidən Qaraman vilayətinə bağlandı. Xəritədə Adana ilə Konya arasındakı işğal xəttinin mənbəli ara nöqtəsidir; Ulukışla və Karapınar üçün şəhər səviyyəsində şəhadət tapılmadı.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Misir ordusu Konyaya girdi", "13952a2d"], "d": ["Toroslari aşan ordu Mərkəzi Anadoluya çatdı. Bir Osmanlı canişininin qüvvələri ilk dəfə imperiyanın nüvə torpaqlarında irəliləyirdi. Eyni tarixdə qatılan digər yerlər: Qaraman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Konya Meydan Döyüşü: sədrəzəm əsir düşdü", "ec82cc9a"], "d": ["Dumanlı havada dağılan Osmanlı ordusu ağır məğlubiyyət aldı və sədrəzəm Rəşid Mehmed Paşa əsir alındı. Dövlətin mərkəz ordusu artıq yox idi; İstanbul ilə Misir qüvvələri arasında dayanacaq bir güc qalmamışdı.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş Misir işğalına uğradı", "f558e383"], "d": ["TDV-yə görə Maraş 1833-də Qavalalı İbrahim Paşanın işğalına uğradı və on doqquz aya yaxın onun idarəsində qaldı. Maraş Kütahya nizamlanmasının əyalət sərhədləri xaricində qaldığı üçün bu idarə hüquqi deyil, faktikidir.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Qarahisari-Sahib (Afyon) Misir işğalına uğradı — Konya–Kütahya yolu", "ae0c2c78"], "d": ["Konya Meydan Döyüşündən sonra Kütahyaya irəliləyən Misir ordusunun yolu üstündəki Qarahisari-Sahib 1833-də bir müddət İbrahim Paşanın əlində qaldı. Xəritədə Konya ilə Kütahya arasındakı işğal xəttinin mənbəli ara nöqtəsidir; Akşehir, Ilgın və İshaklı üçün şəhər səviyyəsində şəhadət tapılmadı, onlar Osmanlı rəngindədir.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Misir ordusu Kütahyaya çatdı", "214f8df6"], "d": ["İbrahim Paşa İstanbula üç mənzil məsafədəki Kütahyada dayandı. İrəli getməməsi hərbi deyil, siyasi idi: Rus müdaxiləsi və Avropanın reaksiyası nəzərə alınmışdı.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Rus donanması Böyükdərə önlərində", "6f836d61"], "d": ["İngiltərə və Fransadan kömək ala bilməyən II Mahmud dünənki düşməni Rusiyaya müraciət etdi. Padşahın \"dənizdə batan ilana sarılar\" sözü ilə anılan bu qərar Rus əsgərinin boğazlara çıxması ilə nəticələndi və Avropada həyəcan zənglərini çaldırdı.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Kütahya Razılaşması (şifahi) — Suriya və Adana Qavalalıya", "25fe9985"], "d": ["Babıali Misir, Girit və Hicazın yanı sıra Şam, Hələb, Tripoli və Sayda canişinliklərini Məhəmməd Əliyə; Adana muhassilliyini İbrahim Paşaya buraxdı. Müqabilində ordu Toroslarin cənubuna çəkildi. Bu bir müqavilə deyil, padşahın bir canişinə verdiyi fərmanlar şəklində idi — məsələ həll edilməmiş, təxirə salınmışdı.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Misir ordusunun Anadoludan çəkilməsi Güləkdən tamamlandı", "a53ac2a3"], "d": ["Kütahya nizamlanmasından sonra Misir qüvvələri Anadolunu boşaltdı; İyun ortalarına doğru ordunun hamısı Gülək boğazından Çukurovaya keçdi. İçil sahili (Mersin, Silifkə) yenidən Osmanlı idarəsinə dönür; Adana muhassilliyi və Suriya Misirdə qalır.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Hünkar İskələsi Müqaviləsi", "da741d5c"], "d": ["Rusiya ilə səkkiz illik qarşılıqlı müdafiə ittifaqı imzalandı. Gizli maddəyə görə Osmanlı Rusiya hücuma məruz qalarsa boğazları hərbi gəmilərə bağlayacaqdı. Bu, Osmanlı diplomatiyasının ən mübahisəli qərarlarından biri oldu və İngiltərəni Misir məsələsində aktiv hala gətirdi.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Fələstin-Nablus üsyanı Misir idarəsinə qarşı", "4fe43e27"], "d": ["Məcburi hərbi xidmət, silah toplama və yeni vergilər Fələstində geniş üsyana yol açdı. Üsyan sərt şəkildə yatırıldı; Misir idarəsinin yerli əhali yanındakı dəstəyi sürətlə əridi.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Maraşın Misir idarəsinin sonu (təqribən)", "bb46ca42"], "d": ["TDV-nin 'on doqquz aya yaxın' müddət cümləsi 1833 işğalından etibarən sayılsa Misir idarəsi 1834-cü ilin yayı ətrafında sona çatır. Küçükəlioğullarından Mustafa bəyin 1834-də Misir ordusuna qarşı dura bilməyib Maraş tərəfinə çəkilməsi də Maraşın o zaman Misir nəzarəti xaricində bir sığınacaq olduğunu göstərir.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Cəbəl Druz üsyanı", "12e74626"], "d": ["Druz bölgəsində çıxan müqavimət iki il davam etdi. Suriyada yığılan narazılıq 1840-da müttəfiq donanmalar sahilə çıxdıqda Misir ordusunun arxasını boşaldacaqdı.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Məhəmməd Əli müstəqillik niyyətini bildirdi", "48633bbd"], "d": ["Canişin böyük dövlətlərin konsullarına Misir və Suriyanın müstəqilliyini elan etməyi düşündüyünü açıqladı. İngiltərə buna qəti şəkildə qarşı çıxdı: Aralıq dənizində güclü və Fransaya yaxın bir dövlətin yaranması Hindistan yolunu təhdid edərdi.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Osmanlı ordusu Fəratı keçdi", "9af1ea69"], "d": ["II Mahmud Kütahyada itirdiklərini geri almaq üçün ordusunu Suriya sərhədinə sürdü. Ordudakı müşavir Prussiyalı zabit Moltke mövqe seçiminə və erkən hücuma etiraz etdi; etirazları dinlənilmədi.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Nizip döyüşü — Osmanlı ordusu dağıldı", "156b3cdf"], "d": ["Pis yerləşdirilmiş Osmanlı ordusu bir neçə saat içində məğlub oldu. Məğlubiyyət xəbəri İstanbula çatmadan padşah öldü; dövlət bir neçə gün içində ordusunu, hökmdarını və ardınca donanmasını itirəcəkdi.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["II Mahmudun ölümü", "07eccfff"], "d": ["Otuz bir illik səltənəti boyunca yeniçəriliyi ləğv edən, mərkəzi idarəni yenidən quran padşah ən böyük rəqibini məğlub edə bilmədən vəfat etdi. Xəstəliyinə dəqiq diaqnoz qoyulmamışdı. Ölümü yeniçəri zehniyyətinin hərəkətə keçəcəyi qorxusu ilə şəhərdə hərbi tədbirlər görülənə qədər 30 İyuna qədər gizlədildi.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Əbdülməcidin cülusu və II Mahmudun cənazəsi", "d0f3d2cc"], "d": ["Atasının ölümü üzərinə on altı yaşlı Əbdülməcid taxta keçdi. Eyni gün II Mahmudun cənazəsi Topqapı Sarayına gətirildi; qorxulan qarışıqlıq çıxmadı, müsəlman və qeyri-müsəlman geniş xalq kütlələri cənazə yürüşünə qatıldı.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Donanmanın İskəndəriyyəyə təslimi", "a53e6103"], "d": ["Kapudan-i dərya Əhməd Fövzi Paşa sədrəzəm Koca Xosrov Paşanın donanmanı Rusiyaya verəcəyi şübhəsi ilə donanmanı İskəndəriyyəyə aparıb Məhəmməd Əliyə təslim etdi. Osmanlı Dövləti eyni ay içində ordusuz, padşahsız və donanmasız qaldı.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Böyük dövlətlərin ortaq notası", "2a3b8316"], "d": ["Beş dövlət Babialiyə nota verərək Misir məsələsində təkbaşına razılaşma etməməsini istədi. Daxili məsələ beləliklə rəsmən \"Avropa məsələsi\" halına gəldi; Osmanlı dövləti öz vilayəti haqqında qərar vermə səlahiyyətini faktiki olaraq itirdi.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["London Müqaviləsi: dörd dövlət Osmanlının yanında", "a517f775"], "d": ["Fransa kənarda buraxılaraq imzalanan müqavilə Məhəmməd Əliyə ultimatum verdi: on gün içində qəbul edərsə Misir irsi canişinliyi və ömürlük şərti ilə Əkka; iyirmi gün içində qəbul edərsə yalnız Misir; rədd edərsə heç nə. Canişin rədd etdi.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Beyrut bombardmanı və müttəfiq desantı", "0905ce92"], "d": ["Britaniya-Avstriya donanması Beyruta top atəşi açdı; Livan dağlarında Misir idarəsinə qarşı üsyan edən xalqa silah paylandı. İbrahim Paşanın Suriyadakı nəzarəti daxili üsyan və xarici müdaxilə arasında çökdü.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beyrut və sahil şəhərləri əldən çıxdı", "09bdaf23"], "d": ["Baalbək istiqamətindəki döyüşlərdən sonra Misir qüvvələri sahildən çəkildi. Xəritədə Livan sahili vassal tondan çıxıb birbaşa Osmanlı idarəsinə dönür.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Əkka iki saatda süqut etdi", "5aec21f0"], "d": ["Müttəfiq donanmasının bombardmanında qalanın sursat anbarı partladı və Əkka bir neçə saat içində təslim oldu. Səkkiz il əvvəl İbrahim Paşanın altı ayda ala bildiyi qala dəniz topçusunun üstünlüyünü göstərdi.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["İskəndəriyyə Konvensiyası", "85cb47b0"], "d": ["Məhəmməd Əli Suriya, Adana, Girit və Hicazdan imtina etməyi, Osmanlı donanmasını qaytarmağı və padşahın hakimiyyətini tanımağı qəbul etdi; müqabilində Misirin irsi canişinliyi təmin edildi.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Misir ordusu Suriya və Çukurovanı boşaltdı", "719a28dc"], "d": ["Doqquz illik işğal sona çatdı; İbrahim Paşanın ordusu Sina üzərindən Misirə qayıtdı. Xəritədə Hələbdən Qəzzəyə, Adanadan Giritə uzanan geniş qurşaq yenidən birbaşa Osmanlı idarəsinə keçir. Eyni tarixdə əldən çıxan digər yaşayış məntəqələri: Urfa, Maraş, Tarsus, Antakya, Kandiya (Girit), Həma, Şam, Qüds, Yafa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Fərman: Misir canişinliyi Qavalalı ailəsinə irsi buraxıldı", "87b89ff8"], "d": ["Padşah fərmanı canişinliyi sülalə daxilində atadan oğula keçəcək şəkildə tanıdı; buna qarşılıq ordu sayı on səkkiz minə endirildi, vergi İstanbula bağlandı, sikkə kəsmək və müqavilə bağlamaq səlahiyyəti ləğv edildi. Misir vilayət olaraq qaldı, lakin artıq ayrı bir sülalənin ölkəsi idi. Hicaz və Hərəməyn idarəsi Babialiyə geri döndü. Eyni tarixdə vassal qatdan birbaşa qata dönən digər yaşayış məntəqələri: Məkkə, Mədinə, Cidda, Yənbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["London Boğazlar Konvensiyası", "0e95a1ea"], "d": ["Hünkar İskələsinin yerini alan konvensiya sülh zamanında boğazların bütün hərbi gəmilərə bağlı olmasını hökmə bağladı. Rusiyanın təkbaşına qazandığı imtiyaz beləliklə Avropanın ortaq təminatına çevrildi; boğazlar məsələsi beynəlxalq statusa qovuşdu.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrahim Paşa faktiki Misir canişini oldu", "9e14f5d9"], "d": ["Qocalan və əqli qabiliyyətlərini itirən Məhəmməd Əlinin yerinə oğlu İbrahim Paşa canişinliyə gətirildi. Lakin bir neçə ay sonra, Noyabr 1848-də atasından əvvəl öldü.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Qavalalı Məhəmməd Əli Paşanın ölümü", "871310e0"], "d": ["Qavalada doğulub Misirdə sülalə quran, imperiyanı iki dəfə uçurumun kənarına gətirən canişin səksən yaşında öldü. Qurduğu sülalə 1953-ə qədər Misirdə hökm sürdü; dövlət isə onun açdığı yaranı Avropa müdaxiləsi ilə bağlaya bildiyini görərək Tənzimat yolunda irəlilədi.", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Ərtoğrul Qazinin ölümü və Osman bəyin bəyliyə keçişi — Söyüd və Domaniç mirası", "395fb9fa"], "d": ["TDV-yə görə Ərtoğrul Qazi 680 (1281-82) ilində vəfat etdi; maddə 1288 və 1289 tarixlərinin də verildiyini qeyd edir. Osman bəy atasından fəth edilmiş bir şəhər deyil, Səlcuq sultanının sərhəd bölgəsinin ən irəli xəttinə yerləşdirdiyi Ərtoğrula verdiyi iki təxsisatı devraldı: Söyüddə yurtluq (qışlaq) və Domaniçdə yaylaq. Yəni bəylik fəth mirası ilə deyil, iki otlaq təxsisatı ilə işə başlamışdır; xəritədə bu iki yer 'fəth' deyil, 'miras' olaraq göstərilir.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Siciliya Axşamı — Anjou sülaləsi Siciliya adasını itirdi", "547db635"], "d": ["Palermoda Pasxa bazar ertəsi axşam duası vaxtı Anjulu I Karlın idarəsinə qarşı başlayan üsyan Siciliya adasını Anjou sülaləsindən qopardı. Siciliya Krallığı ikiyə ayrıldı: ada Araqona yönəldi, Anjou sülaləsi isə Neapol mərkəzli qitə krallığında tutundu. Sülalənin Adriatik və Aralıq dənizindəki xarici mülkləri də bu krallığa bağlı qaldı: 1267-dən bəri əllərində olan Korfu ilə 1270-lərdən bəri tutduqları Draç Neapol Krallığının hissəsi olaraq davam etdi; Albaniya sahilindəki Avlonya, Kanina və Himara qalaları da Neapol mərkəzli krallıqda qaldı (Avlonya komandanı John of Taxis 1282 boyunca Bizanslılara qarşı müqavimət göstərdi; Draç, Avlonya və Kanina böyük ehtimalla 1285-in əvvəlində Bizansa keçdi). Malta isə ancaq 1284-də Araqonluların əlinə keçdi.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Kulacahisar basqını — Osman bəyin ilk hərbi əməliyyatı", "79b00b14"], "d": ["TDV Osman I maddəsi: 'İnegöl yaxınlığında kiçik Kulaca Hisarını talayıb odlamışdır (684/1285).' Bu, Osman bəyin mənbələrdə tarixləndirilə bilən ilk hərbi hərəkətidir. Daimi bir yaşayış məntəqəsi ələ keçirilməmiş, hisar talanıb yandırılmışdır; deməli fəthdən çox klassik bir sərhəd basqınıdır. Bəyliyin hərbi fəaliyyətinin başlanğıc nöqtəsi sayılır.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Qarahisarın fəthi — ilk şəhər qazancı və Əskişəhərə hakimiyyət", "178ae619"], "d": ["TDV Osman I maddəsi: Osman bəy 687 (1288) ilində 'Qarahisarı fəth edib Əskişəhərə malik oldu'. Bu, bəyliyin ilk həqiqi şəhər qazancıdır və rəvayətə görə Osman bəy bu uğurla sərhəddə sancaq bəyliyinə yüksəlmişdir; adına ilk cümə xütbəsinin Qarahisarda oxunduğu və buraya ilk qazının təyin edildiyi nəql olunur. TDV Əskişəhər maddəsi Osmanlı ənənəsinin 1291 tarixini verdiyini, lakin bunun doğruluğunun şübhəli olduğunu bildirir.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Əkkanın Məmlüklərə süqutu — Səlibçilərin Suriya sahilindən ləğvi: Sayda və Beyrut", "3ca7a464"], "d": ["Uzun müddət Qüds Səlib Krallığının mərkəzi olan Əkka Məmlük Sultanı əl-Məlikül-Əşrəf Xəlil tərəfindən fəth edildi və Səlibçilərin Fələstindəki hakimiyyəti sona çatdı. Əkkadan çəkilən Templier cəngavərləri Saydaya sığındı; Məmlük ordusu yaxınlaşdıqda dəniz qalasını buraxıb Kiprə qaçdılar və şəhər eyni yay Məmlüklərə keçdi. 1197-dən bəri Səlibçilərin əlində olan Beyrut da 1291-də Şam canişini Sənçər əş-Şücai tərəfindən alındı. Beləliklə iki əsrlik Səlib mövcudluğu Suriya-Fələstin sahilindən silindi.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Bilecik və Yarhisarın gecə basqını ilə fəthi", "f461b0af"], "d": ["TDV Bilecik maddəsi: 'Bilecik təkfurunun da aralarında olduğu bölgədəki digər təkfurlar Osman Qaziyə sui-qəsd hazırlasalar da bu tələnin xəbər alınması üzərinə Osmanlı qüvvələri qəfil basqınla Yarhisar və Bileciki fəth etdilər (1299).' İki qala tək əməliyyatda, eyni gecə basqınında alınmışdır. Bu tarix Osmanlı Dövlətinin qurulma ili sayılan dönüş nöqtəsidir. Eyni tarixdə qatılan digər yerlər: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Koyunhisar (Bapheus) döyüşü — Bizans ordusuna qarşı ilk böyük qələbə", "584a9512"], "d": ["TDV Osman I maddəsi: Osman bəy 27 İyul 1302-də Bapheusda (Koyunhisar) Bizans ordusu ilə döyüşüb onu məğlub etdi. Bu qələbə Osman bəyi bölgəsel sərhəd bəyi olmaqdan çıxarıb sülalə qurucusu statusuna yüksəldən dönüş nöqtəsidir. Döyüşdən sonra Bursa düzənliyi Osmanlı nəzarətinə girmiş, İznikin blokadası başlamışdır.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Dimbos qələbəsi və ardınca Kite ilə Ulubatın alınması", "e168ab64"], "d": ["TDV Osman I maddəsi: 702 (1303) ilində Bursa, Kestel, Kite və Adranos təkfurlarının qurduğu ittifaq Dimbos Boğazında məğlub edildi; düşmən döyüşə-döyüşə dar boğaza qədər çəkildi və Kestel təkfuru döyüş meydanında öldü. Qələbənin dərhal ardınca Kite və Ulubat qalaları ələ keçirilərək Bursanın quru bağlantısı kəsildi və blokadası sıxlaşdırıldı. Gənc Orxan da bu döyüşə qatılmışdır.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Sakarya yürüşü: Leblebicihisar, Lefke, Mekece və Geyvənin alınması", "a51ba4d3"], "d": ["TDV Osman I maddəsi 704 (1304) Sakarya yürüşünün ardıcıllığını verir: 'Leblebici Hisarına gəldikdə təkfur itaət etdi... Lefkəyə vardı... Mekeceyə çatdı... Geyvəyə gedib boş tapdığı hisarı aldı.' Lefkə Sakarya vadisinin Bilecikə açılan qapısıdır. Bu tək yürüş vadi boyunca uzanan qala zəncirini Osmanlı nəzarətinə keçirərək İznik hövzəsinin şərq cinahını bağlamışdır.", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Geyvə Boğazı qalalarının fəthi: Qaraçöpüş, Qaratiqin və Absu", "76907c78"], "d": ["TDV Orxan maddəsi: Orxan 705 (1305) Sakarya yürüşündə 'Qaraçöpüş (Katoikia), İznik önündə Qaratiqin, Absu (Hypsu: Geyvə Boğazında) qalalarını fəth etdi'. Bu üç qala Sakarya vadisi ilə İznik hövzəsi arasındakı keçidi bağlayaraq İznikin quru köməyini tamamilə kəsmişdir. Geyvə boğazındakı Qaraçöpüş və Absuya Qazi Əbdürrəhman yerləşdirilmişdir; şəhər artıq yalnız aclıqla süquta uğradıla bilərdi.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Adranos (Orxaneli) yürüşü — Osman bəyin son yürüşü", "4811546c"], "d": ["TDV Orxan maddəsi 1323 payızındakı Adranos qalası yürüşünü Osman bəyin son yürüşü kimi qeyd edir. Adranos təkfuru iyirmi il əvvəl Dimbosda Osmanlılara qarşı qurulan təkfurlar ittifaqının üzvü idi; bu yürüş o hesabın bağlanması mənasına gəlirdi. Qalanın qəti fəth günü məlum deyil; əməliyyat Orxan bəy tərəfindən davam etdirilmişdir.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Osman Qazinin vəfatı və Orxan bəyin bəyliyə keçişi", "021487cd"], "d": ["Bəyliyə adını verən Osman Qazi Asporça Xatun və Mekece vəqfnamələrinin şəhadəti ilə 724 (1324) ilində vəfat etdi. 1305-dən bəri yürüşlərdə ordunun başında olan oğlu Orxan atasının ölümü üzərinə heç bir taxt çəkişməsi yaşanmadan bəyliyin başına oturdu. Qurucu nəslin sancağı sarsıntısız devr etməsi sərhəd bəyliyindən dövlətə uzanan yolda sülalənin ilk böyük imtahanını sakitliklə keçdiyini göstərir.", "6f95e64a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Pelekanon (Maltepe) döyüşü və Kocaelinin hamısının alınması", "389e7bd4"], "d": ["TDV Orxan maddəsi: döyüşün ilk günü Orxan Qazi Bizans ordusunu özünə çəkmək üçün üç yüz nəfərlik qüvvə göndərdi; ikinci gün Pazarlu komandanlığındakı birliklərin düzənliyə enməsi ilə döyüş böyüdü və imperator oxla yaralanınca Bizans ordusunda çaxnaşma çıxdı. Nəticə qətidir: 'Orxan bütün Kocaelini ələ keçirdi; qələbədən sonra İznikliləryn heç bir ümidi qalmadı.' Herekədən Üsküdara qədər sahil qəsəbələri Osmanlı hökmünə girdi, Gebze bölgənin mərkəzi edildi. Bu, İstanbulu xilas etmək üçün gələn son Bizans imperiya ordusu idi.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["İznikdə ilk Osmanlı mədrəsəsinin qurulması", "c85fb625"], "d": ["Orxan bəy İzniki aldıqdan dərhal sonra Çandarlı Qara Xəlili buraya qazı təyin etdi, bir bazilikanı məscidə çevirdi və yanına bir imarət ilə bir mədrəsə tikdirərək şəhərin abadlığına başladı. TDV-nin Davud-i Qeysəri maddəsinə görə mədrəsənin inşaatı 1336-da tamamlandı və Orxan Qazi müdərrisliyə gündə 30 axça ilə Davud-i Qeysərini gətirdi. Bu mədrəsə Osmanlı elm həyatının ilk institusional addımıdır; bəylik fəth gücünün yanına bir elm ənənəsi də əlavə etmiş oldu. Fəthlə alınan bir Bizans paytaxtının İslam elm mərkəzinə çevrilməsi Osmanlının oturaq dövlət olma iddiasının ilk konkret işarəsi idi.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizansın xərac altına alınması — İzmit mühasirəsi və müqavilə", "0c1ec8d3"], "d": ["TDV Orxan maddəsi: Orxan 733 (1333) yayında İzmiti böyük ordu və mancınıqlarla mühasirəyə aldı, imperator müqaviləyə razı oldu. Mühasirədən əl çəkməsi müqabilində Bizans Orxana ildə 12.000 qızıl (hyperper) ödəməyi qəbul etdi; 'beləliklə Osmanlı əmiri gözündə Bizans xəraçgüzar bir ölkə vəziyyətinə düşmüşdür'. Müqabilində Orxan imperatorun dostu olacaq və Bizansa bağlı şəhərlərə hücum etməyəcəkdi. Bir sərhəd bəyliyinin Şərqi Romanı vergiyə bağlaması güc tarazlığının nə qədər dönmüş olduğunun elanı idi.", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Karası Bəyliyinin ilhaqı: Balıkəsir, Bərqama, Biqa, Ədrəmit və Ərdək", "c7cb0511"], "d": ["TDV Orxan maddəsi (İnalcık) ilhaqı 735 (1334-35) tarixinə qoyur: Dəmirxan bəyin ölümü üzərinə Karası qazıları və Hacı İlbey Dursun bəyi taxta dəvət edib Orxandan kömək istədilər. Orxan əvvəl Balıkəsir üzərinə yürüdü; sülh danışıqlarına gedən Dursun bəy Bərqama qalasından atılan oxla ölüncə bəylik bütövlükdə Osmanlı ölkəsinə qatıldı. Eyni əməliyyatda Kirmasti və Mihaliç itaət etdi, Gölyazı alındı və daha əvvəl aman ilə buraxılmış Ulubat qəti olaraq zəbt edildi. Orxan Karası sancağına Süleyman Paşanı təyin edib Biqanı sərhəd mərkəzi etdi — Rumeliyə keçidin dənizçi kadrosu beləliklə qazanıldı. Qeyd: TDV-nin Karasıoğulları maddəsi eyni hadisə üçün 746 (1345) tarixini verir; ansiklopediya öz daxilində ziddiyyətlidir. Eyni tarixdə qatılan digər yerlər: Çanaqqala.", "f5ed82c2"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Orxan Qazinin Cenovalılarla ilk kapitulyasiyası", "e64cb196"], "d": ["Venesiya-Cenova müharibəsi zamanı Cenovalılarla razılaşan Orxan Qazi Fevral 1352-dəki Boğaz döyüşündən sonra Peranın müdafiəsinə 1000 oxatan göndərdi və əsgər daşınması üçün 60.000 qızıl təmin etdi; müqabilində Cenovalılara ilk kapitulyasiyanı bağışladı. Müqavilənin tam mətni günümüzə çatmamışdır. Bu, Osmanlının bir Avropa dəniz gücü ilə etdiyi ilk rəsmi sazişdir və otuz beş il sonra 1387-də yenilənəcəkdi.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Gəlibolunun alınması — Rumelidə daimi körpübaşı", "ba51a160"], "d": ["1349-1352 illəri arasında Kantakuzenosun müttəfiqi sifəti ilə ətrafını tanıdıqları Gəlibolunu Osmanlılar 1354-də ələ keçirdilər; şəhərin divarlarını dağıdan böyük zəlzələ fürsət doğurmuşdu. Çimpedəki dar körpübaşı beləliklə Boğazın Rumeli yakasında həqiqi bir bazaya çevrildi və Frakiyaya açılan qapı taybatay aralandı. Gəlibolu 1366-da Savoya Səlib yürüşü ilə əldən çıxacaq, lakin 1376-dakı ikinci fəthlə qəti olaraq Osmanlı hakimiyyətinə girəcəkdi. Eyni tarixdə qatılan digər yerlər: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Rumeli fatehi Süleyman Paşanın ölümü", "2dc98228"], "d": ["Orxan bəyin böyük oğlu və Rumeli fəthlərinin memarı Süleyman Paşa mənbələrdə 758 (1357), 759 və 760 (1359) olaraq verilən tarixlərdən ən çox qəbul göreni olan 1357-nin payızında ov zamanı atdan yıxılaraq öldü. 1352-1354 illəri arasındakı keçidləri ilə Rumelidə daimi Osmanlı mövcudluğunu quran şahzadənin ölümü vəliəhdlik sırasını qardaşı Murada buraxdı. Bolayıra dəfn edilən Süleyman Paşanın türbəsi Osmanlının Avropadakı ən qədim sülalə abidəsi olaraq qaldı.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Pəncik Qanunu — Yeniçəri Ocağının təməlinin atılması", "e5877c2d"], "d": ["Rumeli fəthlərindən sonra ülamadan Qaramanlı Qara Rüstəmin tövsiyəsi ilə müharibə əsirlərinin beşdə birinin və ya bunun pul müqabilinin dövlətə ayrılmasını nəzərdə tutan pəncik sistemi qüvvəyə qoyuldu. Bu əsirlərdən seçilənlərin Türk ailələrinin yanında yetişdirilib əsgərliyə alınması ilə birbaşa padşaha bağlı daimi bir piyada gücünün — Yeniçəri Ocağının — nüvəsi yarandı. Tayfa süvarisinə əsaslanan bir sərhəd bəyliyinin mərkəzi ordusu olan bir dövlətə çevrilməsi bu nizamlamayla başladı.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Qərbi Frakiyaya enmə: Gümülcinənin fəthi", "9ef69221"], "d": ["Ədirnənin alınmasından sonra Meriçin qərbinə yönələn sərhəd qüvvələri Qazi Evrenos bəyin komandanlığı ilə Qərbi Frakiyanın mərkəzi Gümülcinəni ələ keçirdi. Şəhər Evrenos bəyin basqınlarını Makedoniyaya daşıyacağı irəli qərargah halına gəldi. Beləliklə Frakiyanın Egey sahilinə uzanan hissəsi Osmanlı nəzarətinə girdi və Salonik yolu açıldı.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna Dobruca Knyazlığına keçdi və paytaxt oldu", "2bfe73f9"], "d": ["Bolqar Çarlığının dağılma prosesində Qara dəniz sahilindəki Varna Dobrotiçin qurduğu Dobruca Knyazlığına qatıldı və bu kiçik dövlətin paytaxtı edildi.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Filibənin qərbi: Tatarpazarcığı və İxtimanın qatılması", "1664d0e1"], "d": ["Filibənin 1372-də alınmasından sonra Meriç vadisinin yuxarı ucundakı Tatarpazarcığı ilə Sofiyaya açılan keçidi tutan İxtiman Osmanlı idarəsinə bağlandı. Çirmən döyüşü sonrası vassallaşan yerli bəylərin əlindəki bu xətt birbaşa idarəyə keçirilərək Filibə-Sofiya marşrutu fasiləsiz hala gətirildi. Bu irəliləyiş on iki il sonra Sofiyanın fəthinə gedən yolun hazırlığıdır.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Savcı bəy üsyanı — şahzadə ilə Bizans vəliəhdinin ortaq qiyamı", "75198c33"], "d": ["I Muradın oğlu Savcı bəy ilə Bizans İmperatoru V Ioannesin oğlu Andronikos Palaiologos 1373 Mayının əvvəlində Bursa və İstanbulda eyni vaxtda atalarına qarşı qiyam etdilər. İki sülalənin vəliəhdlərini birləşdirən bu ittifaq sürətlə yatırıldı; Savcı bəy yaxalanaraq gözlərinə mil çəkildi və edam edildi. Osmanlı rəvayətinin üsyan üçün verdiyi 787 (1385) tarixi yanlışdır; hadisə Bizansın Osmanlı vassallığına girdiyi illərin dərhal ardına düşür və iki sarayın nə qədər bir-birinə qarışdığını göstərir.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Struma və Mesta vadiləri: Köstendil, Petriç, Nevrokop və Dramanın qatılması", "8c0980c4"], "d": ["Çirmən qələbəsindən sonra Osmanlıya xərac ödəməyə başlayan Serb və Bolqar yerli bəylərinin əlindəki Struma və Mesta vadiləri sərhəd bəylərinin irəliləyişi ilə birbaşa Osmanlı idarəsinə alındı. Köstendil, Petriç, Nevrokop və Dramanın qatılması ilə Makedoniyanın şərq yarısı açıldı və Salonik ilə Serez mühasirə çevrəsinə girdi. Xəritədə Rumelinin cənub-qərbə doğru genişlənməsi bu əməliyyatın nəticəsidir.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Teymur Heratı aldı: Kert sülaləsinin sonu və Xorasanın Teymurilərə keçməsi", "15f6019e"], "d": ["Xorasan 1380-də Sərbədarlar, Kertlər və Müzəffərilər arasındakı mübarizə ilə parçalanmış halda idi. Teymur oğlu Miranşahı bölgəyə göndərdikdən sonra özü Herat üzərinə yürüdü və bir müddət mühasirəyə aldıqdan sonra şəhəri Kert Məliki Qiyasəddin Pir Əlidən təslim aldı. Ayrılışının ardınca çıxan üsyan Miranşah tərəfindən qanla yatırıldı və 1255-dən bəri Heratda hökm sürən Kert sülaləsinə son verildi. Məşhəddən Nişapura bütün Xorasan bu tarixdə Teymuri idarəsinə girdi.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Eretna Bəyliyinin sona çatması və Qazi Bürhanəddin Dövlətinin qurulması", "60dcaf57"], "d": ["1335-də Elxanlı canişinliyindən doğan və Sivas ilə Qeysəri mərkəzli Mərkəzi Anadolunu qırx altı il idarə edən Eretnaoğulları saray daxili çəkişmələrlə dağıldı. May 1378-də vəzir olan Qazi Bürhanəddin rəqibləri Qılıcarslan və Hacı Şadgəldini bertaraf etdikdən sonra 1381-in payızında sultanlığını elan edərək bəyliyə son verdi və öz adı ilə anılan dövləti qurdu. Beləliklə Osmanlının şərq qonşusu əldən-ələ keçdi; Sivas-Qeysəri xətti bundan sonra on yeddi il Qazi Bürhanəddinin əlində qalacaqdı.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Makedoniyanın içinə irəliləyiş: Manastır və Ohrinin fəthi", "63bb7838"], "d": ["Via Egnatia üzərindəki Manastır ilə göl sahilindəki Ohri Albaniya istiqamətindəki basqınlar zamanı Osmanlı idarəsinə girdi. İkisi də Adriatikə uzanan yolun açar nöqtələri idi; Ohri ayrıca Balkanların ən qədim Pravoslav arxiyepiskopluq mərkəzi idi. TDV Ohrinin fəth tarixi üçün qəti məlumat olmadığını, 787 (1385) ilə Kralyeviç Markonun ölümündən sonrakı 797 (1395) tarixlərinin irəli sürüldüyünü qeyd edir; burada 1385 əsas götürülmüşdür. Manastır irəliləyən əsrlərdə Rumelinin ən mühüm hərbi mərkəzlərindən biri olacaqdı.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Savra döyüşü — Albaniya qapılarının açılması", "dda6671b"], "d": ["Balşa sülaləsinə qarşı sıxışan Alban bəyi Karlo Topyanın kömək çağırışı üzərinə Osmanlı qüvvələri Savra düzündə II Balşanın ordusunu məğlub etdi; Balşa döyüş meydanında həyatını itirdi. Bir yerli bəyin dəvəti üzərinə girilən bu döyüş Osmanlılara Adriatik sahillərinə qədər uzanan Alban torpaqlarında ilk daimi nüfuz qazandırdı. Bölgədəki bəylərin bir-birinə düşməsini fürsətə çevirən bu siyasət önümüzdəki əsr boyunca Balkan fəthlərinin dəyişməz üsulu olacaqdı.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["Teymurun 'üç illik yürüşü': Azərbaycan və Şimali İranın alınması", "2a98ec51"], "d": ["Xorasan yürüşləri zamanı İranın dağınıq halını yaxından görən Teymur 788-də (1386) qərbə yürüdü. 'Üç illik yürüş' deyə anılan 1386-1388 əməliyyatında Mazandaran, Luristan və Gürcüstan üzərindən Azərbaycana keçib Qarabağa çatdı; Təbriz, Ərdəbil, Urmiya və Naxçıvan Teymuri idarəsinə girdi. Şimali İran və Azərbaycanı ələ keçirməsi, vaxtilə Cuci ulusu ilə Elxanlılar arasında olduğu kimi, Qızıl Orda ilə uzun bir çəkişmənin də başlanğıcı oldu.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Frenkyazısı döyüşü və Konya mühasirəsi — ilk Qaraman yürüşü", "af4e5d77"], "d": ["Kürəkəni olmasına baxmayaraq Osmanlının Qərbi Anadoludakı genişlənməsindən narahat olan Qaramanoğlu Əlaəddin Əli bəyə qarşı I Murad şəxsən yürüşə çıxdı; Frenk Yazısı adlanan məvqedə aparılan döyüşdə təlim görmüş və təcrübəli Osmanlı ordusu Qaramanlı qüvvələrini məğlub etdi. Ardınca Konya qalası mühasirəyə alındı, lakin Əlaəddin bəyin əfv edilməsi ilə bəylik tamamilə aradan qaldırılmadı. Bu yürüş Osmanlı ilə Qaraman arasında bir əsr davam edəcək və ancaq 1468-də qəti ilhaqla bitəcək uzun hesablaşmanın açılış pərdəsidir.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Gəlibolu Tərsanəsinin qurulması — Osmanlı donanmasının doğuşu", "47546241"], "d": ["Osmanlı Dövlətinin ilk təşəkkül tapmış tərsanəsi 1390-da Yıldırım Bəyazid tərəfindən Gəliboluda, Bizansdan qalan tərsanənin yerində quruldu. Qərbi Anadolu bəyliklərinin dənizçi irsini devralan Osmanlı beləliklə ilk dəfə öz gəmisini özü yapan dəniz gücü halına gəldi. Çanaqqala Boğazının açar nöqtəsində yerləşən tərsanə İstanbulun mühasirəsindən Egey yürüşlərinə qədər bir yarım əsr boyunca Osmanlı donanmasının əsas bazası olaraq xidmət etdi.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Hamid-ili Osmanlıya qatıldı: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Qaramanoğlu Əlaəddin bəyin Hamid-ilinə hücum etməsi və xalqın şikayəti üzərinə yürüşə çıxan Yıldırım Bəyazid Hamidoğullarının qalan torpaqlarının hamısını ələ keçirdi və idarəsini oğlu İsa Çələbiyə verdi.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Müzəffəri sülaləsinin sonu: Şah Mənsurun Şiraz önündə məğlub olması", "5fd14eb8"], "d": ["1318-dən bəri Yezd, Fars, İsfahan və Kirmanda hökm sürən Müzəffərilərin son güclü hökmdarı Şah Mənsur qohumları ilə birləşərək Teymura qarşı hərəkətə keçdi. Şiraz yaxınlığındakı döyüşdə əmirlərindən birinin qarşı tərəfə keçməsi ilə qüvvələrinin çoxunu itirdi, məğlub olub öldürüldü. Teymurun ardınca bütün sülalə üzvlərini də öldürtməsi ilə Müzəffəri hakimiyyəti sona çatdı və Fars ilə Kirman Teymuri idarəsinə qatıldı.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Amasyanın Osmanlı torpaqlarına qatılması", "fe2860cf"], "d": ["Yıldırım Bəyazidin Mərkəzi Anadolu əməliyyatı zamanı mühasirəyə alınan Amasya əmiri şəhəri Osmanlılara təslim etdi və Bəyazid 1393-də şəhərə girdi. Sultan buranın idarəsini oğlu Mehmed Çələbiyə buraxdı; şahzadə sancağı olaraq Amasya bundan sonra Osmanlı sülaləsinin ən mühüm təhsil ocaqlarından biri halına gəldi. Bu seçim irəlidəki Fətrət Dövründə həlledici olacaq, Çələbi Mehmed dövləti yenidən birləşdirmə mübarizəsini məhz bu Amasya bazasından aparacaqdı.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Teymur Bağdadı zəbt etdi — Cəlayirlilər Anadoluya qaçdı", "4d5602b3"], "d": ["Teymur uzun bir mühasirədən sonra Bağdadı ələ keçirdi; şəhərin hakimi Cəlayirli Sultan Əhməd qərbə qaçaraq əvvəl Məmlüklərə, sonra Osmanlı sarayına sığındı. Teymurun qərbə doğru genişlənməsi beləliklə ilk dəfə Osmanlı nüfuz sahəsi ilə birbaşa təmasa girdi. İki hökmdar arasındakı ədavətin ilk halqası buradan başlayır.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Qara dəniz sahilində Varnanın alınması", "a84b2abf"], "d": ["Bolqar Çarlığının Dunay ilə Qara dəniz arasındakı torpaqlarının sıxışdırılması zamanı sahildəki ən böyük liman olan Varna Osmanlı idarəsinə keçdi. Limanın alınması Dobruca istiqamətindəki irəliləyişin önünü açdı və Qara dənizin qərb sahilində Osmanlıya ilk böyük körpünü qazandırdı. Varna əlli bir il sonra Səlib ordusunun məhv ediləcəyi 1444 qələbəsinin də səhnəsi olacaqdı.", "2e425501"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Qazi Bürhanəddin Dövlətinin yıxılması", "b13391e3"], "d": ["Ağqoyunlu hökmdarı Qarayülük Osman bəyə əsir düşən Qazi Bürhanəddin Sivasın təslimi müqabilində azad olunmağı təklif etsə də şəhər əhalisi müqavimət göstərdi və sultan divarların önündə edam edildi. Sivas əyanları oğlu Əlaəddin Əli Çələbini başa keçirsələr də Ağqoyunlu təzyiqi qarşısında Yıldırım Bəyaziddən kömək istədilər; Süleyman Çələbinin komandanlığındakı Osmanlı qüvvələri Qarayülükü məğlub edərək şəhərə hakim oldu. Beləliklə Qazi Bürhanəddin Dövləti tarixə qarışdı və Sivas, Tokat, Niksar ilə Qeysəri Osmanlı torpaqlarına qatıldı. Eyni tarixdə qatılan digər yerlər: Kırşəhir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Teymurun ultimatumu: qaçaqların qaytarılması rədd edildi", "33790bc8"], "d": ["Teymurun təzyiqi üzərinə Cəlayirli Sultan Əhməd ilə Qaraqoyunlu lideri Qara Yusif Osmanlı torpaqlarına sığındı; Teymur bu iki qaçağın qaytarılmasını istədi, Yıldırım Bəyazid rədd etdi. Bunun üzərinə iki hökmdar arasında qarşılıqlı ağır təhqirlər ehtiva edən məktublar mübadiləsinə başlandı. Müharibənin ideoloji zəmini hələ bir əsgər hərəkət etmədən bu yazışmalarla quruldu.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Bursada Yıldırım Darüşşifası — ilk Osmanlı xəstəxanası", "5f0dc59a"], "d": ["Yıldırım Bəyazid Bursada möhtəşəm Ulu Məscidi tikdirdiyi illərdə şəhərə bir də darüşşifa qazandırdı; imarət, mədrəsə, xan və körpüdən ibarət geniş xeyriyyə proqramının təbabətə ayrılan halqası bu idi. Dövlətin qurduğu ilk xəstəxana olan bu tikili həkim yetişdirən bir təbabət məktəbi funksiyasını da görərək Osmanlı səhiyyə qurumlarının modelini müəyyən etdi. Ankara fəlakətindən yalnız iki il əvvəl tamamlanan əsər Yıldırımın Bursanı bir imperiya paytaxtına çevirmə təsəvvürünün son halqalarındandır.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Teymur Sivası yerlə bir etdi", "f4d79de6"], "d": ["Ağqoyunlu Qarayülük Osman bəy ilə Ərzincan əmiri Mütəhhərtənin bələdçiliyi ilə Sivasa yürüyən Teymur şəhəri on səkkiz gün mühasirəyə aldı və heç kimin qanının tökülməyəcəyi vədi ilə təslim aldıqdan sonra böyük qətliam etdi; müdafiəçiləri xəndəklərə doldurub diri-diri üzərlərini örtdürdü. Divarlar başda olmaqla şəhərin mühüm əsərləri dağıdıldı, Sivas demoqrafik olaraq çökdü. Bu, Ankara döyüşündən iki il əvvəl Teymurun Osmanlı torpaqlarına endirdiyi ilk böyük zərbədir.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bəyazid Ərzincan və Kəmahı geri aldı", "7047ca08"], "d": ["Teymurun Suriya yürüşünə çıxmasını fürsət bilən Yıldırım Bəyazid Teymura vassal olan Ərzincan əmiri Mütəhhərtənin əlindən Ərzincan və Kəmahı aldı. Sivasın dağıdılmasına müdaxilə etməməsinə baxmayaraq bu hərəkət Teymurun Şərqi Anadoludakı nüfuz sahəsinə birbaşa meydan oxumaq mənasına gəlirdi. İki hökmdarın arası bundan sonra düzəldilməz hala gəldi.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Teymurun Təbrizdən göndərdiyi ultimatum — dörd şərt", "3e1ac50e"], "d": ["Teymur Təbrizdən göndərdiyi səfirlə dörd şərt bildirdi: Kəmahın Mütəhhərtənə qaytarılması, Anadolu bəylərindən alınan torpaqların sahiblərinə geri verilməsi, bir Osmanlı şahzadəsinin girov göndərilməsi və külah ilə kəmərin itaət əlaməti olaraq qəbul edilməsi və Qara Yusifin təslimi. Bəyazid bunların heç birini qəbul etmədi; dövlət adamlarının israrına və Mütəhhərtənin vasitəçiliyinə baxmayaraq danışıqlar çökdü. Teymur Çin yürüşünə çıxmazdan əvvəl Anadolu məsələsini qəti şəkildə bağlamağa qərarlı idi.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Saruxanoğulları yenidən quruldu — Manisa Osmanlıdan çıxdı", "ac747b05"], "d": ["Ankara məğlubiyyətindən üç həftə sonra Teymurun dəstəyi ilə Orxan bəy bəyliyin başına keçdi və Saruxan ili yenidən müstəqil oldu. Manisa mərkəzli bölgə 1390-dakı Osmanlı ilhaqından on iki il sonra xəritədən çıxdı. Bu, Teymurun bəylikləri dirçəltmə siyasətinin tarixi qəti məlum ilk tətbiqlərindəndir.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Əmir Süleyman dövlət xəzinəsi ilə Rumeliyə qaçdı", "0a2b7363"], "d": ["Bursadakı dövlət xəzinəsini, arxivləri, ailəsini və qardaşlarını yanına alan Əmir Süleyman Gəmlikdən gəmi ilə Güzəlcəhisara (Anadoluhisarı) keçdi, oradan Gəliboluya çatıb Ədirnədə hökmdarlığını elan etdi. Dövlət arxivinin və xəzinənin Rumeliyə daşınması Osmanlı ağırlıq mərkəzinin bir nəsil boyunca Balkanlara sürüşməsinin başlanğıcıdır. Xəritədə Rumeli bu tarixdən etibarən Əmir Süleymanın öz rəngi ilə çəkilir.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Teymur Anadolu bəyliklərini yenidən qurdu — Türk birliyi dağıldı", "15187774"], "d": ["Teymur Ankara qələbəsindən sonra yanında olan bəyləri köhnə torpaqlarına qaytardı. Qaramanoğlu Mehmed və Əli bəylərə Qaraman ili ilə Qeysəri, Kırşəhir, Sivrihisar və Beyşəhir; Germiyanoğlu II Yaqub bəyə Kütahya və Germiyan ili; Candaroğlu İsfəndiyar bəyə Kastamonu-Sinop xəttinə əlavə olaraq Çankırı və Kalecik verildi. Aydın, Menteşə və Təkə illəri də köhnə sülalələrinə döndü. Yıldırım Bəyazidin on ildə qurduğu Anadolu Türk birliyi tək bir yay içində dağıldı; xəritədə bu bəyliklər yenidən öz rənglərində görünür.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Teymur İzmiri Sent-Jan cəngavərlərindən aldı", "66dd1dd4"], "d": ["Kütahya, Denizli, Aydın, Ayasuluk və Tire üzərindən qərbə enən Teymur 1344-dən bəri Xristianların əlində olan sahil İzmirini mühasirəyə alıb aldı. Yıldırım Bəyazidin illərlə ala bilmədiyi bu qalanı qısa müddətdə zəbt edən Teymur ətrafdakı qalaları da ələ keçirdikdən sonra Aydın ilini köhnə sahiblərinə buraxaraq şərqə döndü. Şəhər bundan sonra Aydınoğlu Cüneyd bəyin idarəsinə girdi.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["İsa Çələbi Bursanı ələ keçirdi — Anadolu payı doğuldu", "955128c1"], "d": ["Ankara məğlubiyyətindən sonra Karası tərəflərinə çəkilən İsa Çələbi Teymur İzmirdə ikən Bursanı ələ keçirdi. Teymurun əsgərləri tərəfindən talanıb yandırılmış köhnə paytaxtda hökmdarlığını elan etdi və öz adına sikkə kəsdirdi; Yanvar 1403-də Anadoluda 'Türklərin' hökmdarı sifəti ilə tanınırdı. Xəritədə Mərmərənin Asiya sahili boyunca uzanan bu pay İsa Çələbinin öz rəngi ilə görünür.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Teymurun Anadoludan çəkilməsi", "93a98839"], "d": ["Yıldırım Bəyazidin Akşehirdə vəfat etdiyi xəbərini alan Teymur Anadoludakı işini bitmiş sayaraq şərqə yönəldi. Geridə ona bağlılıq bildirən bəyliklər ilə bir-birinə düşmüş Osmanlı şahzadələri qaldı; Sivas kimi bəzi şəhərlər Teymura vassal Mezid bəy kimi əmirlərin əlində buraxıldı. Teymur bir daha Anadoluya qayıtmadı, lakin qurduğu bu parçalı nizam on il davam etdi.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Əmir Süleyman Anadoluya keçdi: Bursa onun əlinə keçdi", "9b27aa5f"], "d": ["İsa Çələbinin məğlubiyyətini eşidən Əmir Süleyman Çandarlı Əli Paşa ilə birlikdə güclü ordu ilə Anadoluya keçərək Bursanı ələ keçirdi; Mart 1404 qeydləri Qara dəniz Ereğlisinin də onun idarəsində olduğunu göstərir. Qısa müddətdə həm Rumeliyə, həm Anadolunun böyük hissəsinə hakim olan Süleyman qarşısında Çələbi Mehmed müqavimət göstərə bilmədi. Xəritədə bu tarixdən Çələbi Mehmedin Bursanı yenidən almasına (1410) qədər iki yaka tək rəngdə, Əmir Süleymanın payında görünür.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Yenişəhər düzü döyüşü — Çələbi Mehmed Amasyaya çəkildi", "f1568288"], "d": ["Bursa və Ankaranı itirən Çələbi Mehmed Yenişəhər düzündə Əmir Süleymana məğlub olaraq Qərbi Anadoludakı bütün qazanclarını itirdi və Tokat-Amasya bazasına çəkildi. Bu məğlubiyyətdən sonra birbaşa toqquşmadan qaçaraq Anadolunun içlərində hakimiyyətini möhkəmləndirməyə yönəldi. Fətrətin ən uzun səssiz mərhələsi belə başladı.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Əmir Süleyman Ankaranı Çələbi Mehmeddən aldı", "d6a2acd6"], "d": ["Teymurun Anadoludan çəkilməsindən sonra Çələbi Mehmedin əlində qalan Ankaranı 1406-da Əmir Süleyman mühasirəyə aldı. Qala mühafizəçisi Yaqub bəy bir müddət dayandı, lakin Vəzirəzəm Çandarlı Əli Paşanın bir hiyləsi ilə qalanı Süleymana təslim etdi. Bunun üzərinə Çələbi Mehmed Qaramanoğlu Mehmed bəylə razılaşaraq Süleymana qarşı hərəkətə keçdi.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çələbi Mehmed Sivası Teymuri Mezid bəydən geri aldı", "90079b0c"], "d": ["Teymur istilasından sonra Sivasın idarəsi Teymura vassal Mezid bəyə buraxılmışdı. Amasyadakı Çələbi Mehmed komandanı Bəyazid Paşanı şəhəri almaq üçün göndərdi və şiddətli müqavimətdən sonra Sivas ikinci dəfə Osmanlı sülaləsinin əlinə keçdi. Beləliklə Mehmedin payı Ankara döyüşündən altı il sonra şərqdə köhnə sərhədinə çatdı.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Artuqlu sülaləsinin sonu: Mardinin Qaraqoyunlulara təslimi", "15b06f33"], "d": ["1106-dan bəri Mardində hökm sürən və sülalənin ən uzunömürlü qolu olan Artuqlular Ağqoyunlu təzyiqi qarşısında tutuna bilmədi. Şəhəri müdafiə edə bilməyəcəyini anlayan Məlik Əhməd Qaraqoyunlu hökmdarı Qara Yusiflə razılaşaraq Mardini ona təslim etdi. Üç əsri aşan Artuqlu hakimiyyəti beləliklə sona çatdı; Mardin və ətrafı bir əsr sonra Osmanlıya keçənə qədər Qaraqoyunlu-Ağqoyunlu mübarizəsinin səhnəsi oldu.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Yanbolu döyüşü — Musa Çələbi Ədirnəyə girdi", "8f978408"], "d": ["Eflak üzərindən Rumeliyə keçən Musa Çələbi Eflak və Serb dəstəyi ilə Yanbolu-da Əmir Süleymanın qüvvələrini məğlub etdi və Ədirnəyə girdi. Fətrət Dövründə Rumeli ilk dəfə Əmir Süleymanın əlindən çıxmış oldu. Lakin hakimiyyəti daimi olmadı; dörd ay sonra Kosmidionda məğlub olaraq Balkan içlərinə çəkiləcəkdi.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["İnceğiz döyüşü — Çələbi Mehmedin ilk Rumeli məğlubiyyəti", "3c35cd43"], "d": ["Bizansın gəmiləri ilə Rumeliyə keçən Çələbi Mehmed İnceğizdə Musa Çələbi ilə döyüşə girişdi; Musa əmrindəki yeddi min yeniçəri ilə Mehmedi məğlub etdi və Mehmed Anadoluya qayıtmağa məcbur qaldı. Bu məğlubiyyət Mehmedi birbaşa döyüş yerinə Rumeli sərhəd bəylərini və Serb despotluğunu öz tərəfinə çəkmək strategiyasına yönəltdi. Doqquz ay sonrakı Çamurlu qələbəsinin zəmini bu diplomatiya ilə hazırlandı.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Konya mühasirəsi və Qaramanoğulları ilə müqavilə — Hamid-ili, Said-ili, Beyşəhir, Seydişəhir və Akşehir geri alındı", "0996257e"], "d": ["Fətrət Dövründə Osmanlı torpaqlarına hücum edən və Bursanı mühasirəyə alıb yandıran Qaramanoğullarına qarşı Çələbi Mehmed böyük bir yürüş təşkil edərək Məhərrəm 818-də Konyanı mühasirəyə aldı. Qaramanoğlu II Mehmed bəy sülh istəməyə məcbur qaldı; müqavilə nəticəsində Hamid-ili (Isparta ətrafı) və Said-ili yenidən Osmanlı torpaqlarına qatıldı, Beyşəhir, Seydişəhir və Akşehir də geri verildi; Teymurun 1402-də Qaramanoğullarına verdiyi Sivrihisar da Osmanlılara döndü. Ankara döyüşü ilə dağılan Anadolu birliyinin yamanmağa başladığı bu yürüş Çələbi Mehmedin 'ikinci qurucu' sayılmasının konkret əsaslarındandır.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["İzmirin Aydınoğlu Cüneyd bəydən alınması", "2377ca51"], "d": ["Fətrət boyunca şahzadələr arasında davamlı tərəf dəyişən Aydınoğlu Cüneyd bəyin mərkəzi İzmir on günlük mühasirədən sonra Çələbi Mehmed tərəfindən alındı; Cüneyd əfv edilərək Nikopol sancaq bəyliyinə göndərildi. Teymurun 1402-də Aydınoğullarına qaytardığı şəhər beləliklə on üç il sonra Osmanlıya döndü. Cüneyd 1422-də şəhəri yenidən ələ keçirəcək, məsələ ancaq 1424-1426-da II Murad tərəfindən bağlanacaqdır.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Torlak Kamalın edamı — Saruxan qəti olaraq Osmanlının", "8a09dbf1"], "d": ["Şeyx Bədrəddin hərəkatının Qərbi Anadolu ayağını idarə edən Torlak Kamal Manisa ətrafında məğlub edilərək edam olundu. Bu tarixdən sonra Saruxan bölgəsi qəti olaraq Osmanlı nəzarətinə girdi və 1402-də Teymurun dirçəltdiyi bəylik tarixə qarışdı. Fətrət Dövrünün Qərbi Anadoludakı son siyasi qalıqları beləliklə təmizləndi.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Avlonya, Berat və Kaninanın fəthi", "1e1949b8"], "d": ["Osmanlılar 1417-də Adriatik sahilindəki Avlonyanı, ölkənin daxili hissəsindəki Berat şəhəri və Kanina qalası ilə birlikdə hakimiyyətləri altına aldılar. Bir il sonra Venesiyanın şəhəri geri alma təşəbbüsü uğursuzluğa uğradı və burada bir sancaq təşkilatı quraraq Osmanlı hakimiyyəti daimiləşdi. Avlonyanın alınması Osmanlını ilk dəfə Adriatikdə birbaşa liman sahibi edərək İtaliya qarşısında dənizaşırı sıçrayış platforması qazandırdı.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Mərkəzi Anadolunun geri alınması: Qeysəri və Kırşəhir", "204eacb3"], "d": ["Fətrət Dövründə Qaramanoğullarının əlinə keçən Mərkəzi Anadolu şəhərləri Çələbi Mehmedin dövləti yenidən toparlama yürüşləri zamanı Osmanlı idarəsinə döndü. Qeysəri və Kırşəhirin qatılması ilə Ankara döyüşündə itirilən Qızılırmaq hövzəsi böyük ölçüdə geri alındı. Bu irəliləyiş dörd il əvvəlki Konya mühasirəsi ilə başlayan şərqə yönəlmə siyasətinin davamıdır.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Məmlüklər Qeysərini Dulqadirli Nasirəddin Məhəmmədə verdi", "aad4b00c"], "d": ["Qaramanoğlu Mehmed bəyə qarşı yürüşə çıxan Məmlük ordusu Qeysərini işğal etdi; Məmlük komandanı şəhəri və ətrafını Dulqadirli Nasirəddin Məhəmmədə buraxaraq ölkəsinə qayıtdı.", "8cd84dc4"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Təkəoğullarının qəti ləğvi: Antalyanın alınması", "e65565b2"], "d": ["Ankara döyüşündən sonra Teymurun dirçəltməsi ilə yenidən qurulan Təkəoğulları Bəyliyi Həmzə bəyin komandanlığındakı Osmanlı qüvvələrinin Antalyanı mühasirəyə alması ilə sona çatdı; bəyliyin son mühüm adamı Osman Çələbi aradan götürüldü. Beləliklə Aralıq dənizi sahilindəki Təkə ili iyirmi bir illik ayrılıqdan sonra qəti olaraq Osmanlıya qatıldı. Bəylik Hamidoğullarından ayrılan qol olaraq 1321-dən bəri Antalyada hökm sürürdü.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Turaxan bəyin Moreya yürüşü və Heksamilion Divarının yıxılması", "c6c2706d"], "d": ["Bizansın rəqib taxt iddiaçısı Mustafa Çələbini dəstəkləməsi üzərinə II Murad Turaxan bəyi Moreya üzərinə göndərdi. Turaxan bəy Korinf Berzəxini başdan-başa bağlayan Heksamilion divarını yıxıb yarımadaya girdi və böyük dağıntılara yol açdı. Sülh divarın bir daha tikilməməsi və illik vergi ödənilməsi şərti ilə təmin edildi; Moreya despotluğu beləliklə hərbi olaraq müdafiəsiz buraxılaraq 1460-dakı son fəthin zəmini otuz yeddi il əvvəldən hazırlandı.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Aynaroz (Athos) monastırlarının Osmanlı himayəsinə girməsi", "562de5ea"], "d": ["Salonikin mühasirə altına alındığı illərdə Xalkidikinin şərq barmağındakı Aynaroz monastır respublikası II Murada müraciət edərək himayə istədi və Osmanlı hakimiyyətini qəbul etdi. Rahiblərin mülkiyyət və ibadət hüquqları təmin edildi; monastırlar vergi müqabilində daxili işlərdə sərbəst buraxıldı. Bu qayda Osmanlının Pravoslav qurumlarla qurduğu himayə münasibətinin ən uzunömürlü nümunəsi oldu və beş əsr davam etdi.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Tacəddinoğulları Bəyliyinin ilhaqı: Niksar", "370ffd47"], "d": ["Amasya bəylərbəyi Yörgüç Paşanın təzyiqi üzərinə Tacəddinoğlu Hüsaməddin Həsən bəy mərkəzi Niksar olan ölkəsinin açarlarını 830 (1427) ilində təslim etdi; ona Rumelidə bir sancaq verildi. XIV əsrin ikinci yarısında qurulan və sərhədləri zaman-zaman Kelkit, Amasya, Samsun, Ordu və Giresuna qədər uzanan bəylik beləliklə sona çatdı. Eyni il Hacıəmiroğullarına aid torpaqlar da təhrir edilərək Canik sancağına bağlandı; Orta Qara dəniz bəylikləri dövrü bağlandı.", "06fa8222"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin Qaraqoyunlu mühafizəçisindən Ağqoyunlu Qarayülük Osman bəyə keçdi", "d82bc97f"], "d": ["Qara Yusifin 1409-da aldığı Mardini Qaraqoyunlular canişinlərlə idarə etdi; mühafizəçi buraxılan Əmir Nasir şəhəri 835-də (1432) Ağqoyunlu Qarayülük Osman bəyə təslim etdi. Ağqoyunlu idarəsi XVI əsrin əvvəlinə qədər davam etdi.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Qaramanoğulları Qeysərini Dulqadirlilərdən aldı", "2b09e8e8"], "d": ["Qaraman bəyi Dulqadirlilərə qarşı qazandığı qələbə ilə Qeysəri, Ürgüp, Develi Qarahisarı və Uçhisarı ölkəsinə qatdı.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Buçuktəpə Hadisəsi — ilk yeniçəri üsyanı və II Muradın taxta qayıdışı", "6388dda1"], "d": ["Ədirnədə baş verən və tarixin bildiyi ilk yeniçəri üsyanı olan Buçuktəpə Hadisəsi ulufələrinin yarım axça artırılması tələbi ilə başladı və gənc II Mehmedin taxtdan endirilməsi ilə nəticələndi. II Murad 8 Səfər 850-də Manisadan təcili yola çıxaraq ikinci səltənətinə başladı. Hadisə qapıqulu ocağının artıq taxt üzərində söz sahibi bir güc halına gəldiyini göstərən ilk işarə oldu və Fatihin yeniçəriyə qarşı ömür boyu davam edəcək ehtiyatını formalaşdırdı.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Epir sahilinin qatılması: Arta və Preveze", "796f7ecf"], "d": ["Yanyanın 1430-da təslim olmasından on doqquz il sonra Epir despotluğunun sahil hissəsindəki Arta və Preveze də Osmanlı idarəsinə girdi. Beləliklə İon dənizinə açılan Ambrakiya körfəzi nəzarət altına alındı və Yanyanın dəniz bağlantısı tamamlandı. Preveze doxsan il sonra Barbarosun tarixə keçəcək qələbəsinə adını verəcək körfəzin açar nöqtəsidir.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["II Muradın vəfatı və II Mehmedin ikinci cülusu", "8f8256ad"], "d": ["Oğlunun toyundan sonra xəstələnən II Murad 1 Məhərrəm 855-də (3 Fevral 1451) Ədirnədə vəfat etdi. On doqquz yaşlı II Mehmed 16 Məhərrəm 855-də (18 Fevral 1451) ikinci dəfə Osmanlı taxtına çıxdı — bu dəfə daimi olaraq. Beş il əvvəl Buçuktəpədə taxtından endirilən gənc hökmdarın qayıdışı iki il sonra İstanbulun fəthi ilə taclanacaq və Osmanlı Bəyliyini dünya imperiyasına çevirəcək səltənətin başlanğıcıdır.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Osmanlı-Krım müştərək qüvvələrinin ilk Kəfə mühasirəsi", "e346d163"], "d": ["İyun 1454-də Fatih Sultan Mehmedlə razılaşan Krım Xanı Hacı Giray 7000 atlısı ilə Kəfəni quru ilə mühasirəyə aldı; əlli-altmış kadırğalıq bir Osmanlı donanması da açıqda mövqe tutdu. Cenovalı Kəfə mühasirəni xərac ödəyərək qaldırtdı və qəti fəth iyirmi bir il sonraya, 1475-ə qaldı. Bu ilk ortaq əməliyyat Osmanlı-Krım hərbi əməkdaşlığının irəlidə Kəfənin qəti fəthində təkrarlanacaq ilk nümunəsi idi.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Şimali Egey adalarının alınması: Bozcaada, İmroz və Taşoz", "76575895"], "d": ["İstanbulun fəthindən dərhal sonra Fatih Sultan Mehmed yeni paytaxtın dəniz yolunu təmin etmək üçün Çanaqqala Boğazının Egey ağzındakı adalara yönəldi; Bozcaada ilə İmroz Bizansdan, Taşoz isə Cenova əsilli Gattilusio ailəsindən alındı. Boğazın iki yakasını kilidləyən bu adalar bundan sonra İstanbulun ərzaq və müdafiə xəttinin ilk halqası oldu. Papalıq və Venesiya donanmalarının müdaxilələri ilə hakimiyyət bir müddət gedib-gəldi və ancaq 1459-da qətiləşdi.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Kosovonun fəthi: Priştinə və Yenipazarın alınması", "d7ed2345"], "d": ["Serb Despotluğu üzərinə yürüyən Osmanlı ordusu Kosovo düzündəki Priştinə ilə Raşka bölgəsinin mərkəzi Yenipazarı ələ keçirdi; eyni əməliyyatda gümüş mədənləri ilə məşhur Novoberda da alındı. Beləliklə Serbiyanın cənub yarısı birbaşa Osmanlı idarəsinə bağlandı və Smederevodakı despotluq mərkəzi torpaqlarından qoparıldı. Bu fəth dörd il sonra Serbiyanın tamamilə ilhaqına gedən yolun həlledici addımı idi.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["İpək (Peç) Osmanlı idarəsinə girdi — Dukakin sancağının mərkəzlərindən", "19511588"], "d": ["1455-də Fatih Sultan Mehmedin Serbiya yürüşündən dərhal sonra Serb patriarxlığının mərkəzi İpək Osmanlı idarəsinə keçdi; Osmanlı mənbələrində bu keçidə dair qeyd yoxdur. Qəsəbə zamanla kiçik bir müsəlman qəsəbəsi halına gəldi və Dukakin sancağında sancaq bəyinin iqamətgahlarından biri oldu.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Enezin və Semadirekin fəthi — Qərbi Frakiya sahilinin tamamlanması", "106e723b"], "d": ["Meriç çayının dənizə töküldüyü yerdəki Enez səksən ildir burada hakim olan Cenova əsilli Gattilusio ailəsindən alındı; buraya bağlı Semadirek adası da eyni əməliyyatda ələ keçirildi. Enezin süqutu ilə Qərbi Frakiya sahil zolağı Saloniklə Gəlibolu arasında fasiləsiz Osmanlı torpağı halına gəldi. Gattilusio ailəsinin əlində yalnız Midilli qaldı; o da altı il sonra alınacaqdı.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Belqrad mühasirəsinin uğursuzluğu", "3d53a604"], "d": ["Fatih Sultan Mehmed İstanbulun fəthindən sonra Mərkəzi Avropanın kilidi sayılan Belqradı mühasirəyə aldı; lakin Yan Hunyadinin Dunaydan gətirdiyi təchizat və səlibçi vaizi Kapistranonun topladığı könüllülər qalanın süqutunun qarşısını aldı. Padşah mühasirə önündə göstərdiyi şəxsi qəhrəmanlığa baxmayaraq yaralanaraq çəkilməyə məcbur qaldı. Bu uğursuzluq Macarıstan sərhədini altmış beş il boyunca Osmanlı irəliləyişinə bağlayacaq; Belqrad ancaq 1521-də Qanuni tərəfindən alına bildi.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Şimali Moreyanın fəthi: Balyabadra (Patras)", "c08a8509"], "d": ["Serbiyanın ilhaqı ilə eyni illərdə Moreya despotluğuna yönələn Fatih Sultan Mehmedin qüvvələri yarımadanın şimal-qərbindəki Balyabadranı ələ keçirdi. Korinf körfəzinin ağzını tutan bu liman Moreyaya quru ilə girişin kilididir; alınması iki il sonrakı son fəthin zəminini hazırladı. Şəhər Bizans despotlarının Latın dünyası ilə əlaqə qurduğu son böyük körpü idi.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Qərbi Qara dəniz sahilinin alınması: Amasra", "f43608fc"], "d": ["Cenovanın Qərbi Qara dənizdəki istehkamlı koloniyası Amasra Fatih Sultan Mehmedin donanma və quru qüvvələrinin ortaq təzyiqi ilə müqavimət göstərmədən təslim oldu. Bartın-Zonquldak sahilindəki bu liman Candaroğulları ilə Osmanlı torpaqları arasında bir Latın cibi olaraq dururdu; alınması ilə sahil bütövləşdi. Amasranın süqutu iki il sonra (1461) Sinop və Trabzona yönələcək böyük Qara dəniz yürüşünün ilk addımıdır.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Midilli adasının fəthi", "fe17aeba"], "d": ["Fatih Sultan Mehmedin komandanlığındakı Osmanlı ordusu Zilhiccə 866-da Midillini qısa, lakin şiddətli bir mühasirədən sonra Cenova əsilli Gattilusio ailəsinin əlindən alaraq ilhaq etdi. Şimali Egeyin ən böyük adasının süqutu Cenovalıların bölgədəki son mühüm bazasını da ləğv etdi. Ada Anadolu sahilinə yaxınlığı sayəsində bundan sonra Osmanlı donanması üçün irəli post funksiyasını görəcək, eyni zamanda Barbaros qardaşlarının yetişdiyi yer olaraq dənizçilik tarixinə keçəcəkdi.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["On altı illik Osmanlı-Venesiya müharibəsinin başlaması", "563ddb68"], "d": ["Venesiyalılar Osmanlının Moreya və Egeydəki irəliləyişini dayandırmaq üçün Qaraman və Ağqoyunlu idarəçiləri ilə ittifaq edərək 1463-də müharibəni başlatdılar. Şərqdə Uzun Həsən, qərbdə Venesiya və arada Qaramanla qurulan bu mühasirə strategiyası Fatihi eyni anda birdən çox cəbhədə döyüşməyə məcbur etdi. On altı il davam edən mübarizə Otluqbelidən Albaniya yürüşlərinə qədər dövrün bütün böyük əməliyyatlarını əhatə edəcək və ancaq 1479 İstanbul Müqaviləsi ilə sona çatacaqdı.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Herseqin böyük hissəsinin fəthi: Trebinye və Mostar", "f54c0100"], "d": ["Bosniyadan ayrı idarə quran Herseq Hersoqu Stjepan Vukčić-Kosačanın torpaqları Bosniya Krallığının yıxılmasından üç il sonra böyük ölçüdə Osmanlı idarəsinə keçdi: cənubda Trebinye 1466-da \"demək olar ki, bütün Herseq bölgəsi ilə birlikdə\" ələ keçirildi. Neretva körpüsünün iki kiçik qalası ətrafında qurulan Mostar da Herseqin mərkəzi Blagajın 1466-1468-dəki fəthindən az əvvəl alınmış olmalıdır; 1468-1469 tarixli Bosna icmal təhririndədə \"Köprülü Hisar\" adı ilə qeydə alınıb. Hersoqluğun qalan qalaları ilə Herseqin fəthi 1483-də tamamlandı.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["II Albaniya yürüşü — Fatihin İsgəndər bəy üzərinə şəxsən yürüşü", "9cdd2bfa"], "d": ["İsgəndər bəyin çərək əsri aşan müqavimətini qırmaq üçün Fatih Sultan Mehmed 1466-1467 illərində şəxsən komandanlıq etdiyi böyük yürüşlər təşkil etdi. Osmanlı ordusu Akçahisarı mühasirəyə aldı və bölgəni nəzarət altına almaq üçün İlbasan (Elbasan) qalasını inşa etdi. Yürüş Alban müqavimətinin belini qırmaqla birlikdə qalanı süquta uğrada bilmədi; bölgənin tam itaəti İsgəndər bəyin ölümündən sonrakı on ili tapacaqdı.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Qaraqoyunlu Dövlətinin çöküşü: Cahan Şahın öldürülməsi", "30bc6358"], "d": ["Uzun Həsən üzərinə çıxdığı yürüşdən qışın basması üzündən qayıdarkən basqına uğrayan Qaraqoyunlu hökmdarı Cahan Şah Bingöl ilə Kığı arasında qaçarkən öldürüldü. Bu zərbədən sonra dövlət toparlana bilmədi; son hökmdar Həsən Əli 1469-da Uzun Həsənin oğlu Uğurlu Mehmed tərəfindən əsir alınıb öldürüldü. Şərqi Anadolu, Azərbaycan və İraqda bir əsrə yaxın hökm sürən Qaraqoyunlu hakimiyyəti beləliklə Ağqoyunlulara keçdi.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["İsgəndər bəyin ölümü — Alban müqavimətinin sönməsi", "9158c35f"], "d": ["Osmanlı sarayında yetişmişkən 1444-də İzladi məğlubiyyətindən sonra üsyan edən və çərək əsri aşan müddət Albaniyada müqavimət göstərən İsgəndər bəy sığındığı Ləşdə öldü. II Murad və Fatih dövrlərində Osmanlı orduların dəfələrlə məşğul edən bu müqavimət onun ölümü ilə mərkəzi rəhbərliyini itirdi. Papalıq və Venesiyanın bəslədiyi Alban cəbhəsinin çökməsi ilə Osmanlılar on il içində Akçahisar və İşkodranı alaraq bölgəni qəti olaraq torpaqlarına qatdılar.", "5c7cffad"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Boğdanda Rakova (Vaslui) məğlubiyyəti", "a1a74bf7"], "d": ["Boğdan voyvodası Stefan cel Mare Rumeli Bəylərbəyi Xədim Süleyman Paşanın komandanlığındakı Osmanlı qüvvələrini bataqlıq əraziyə çəkərək ağır məğlubiyyətə uğratdı. Fatih dövrünün ən ağır quru məğlubiyyətlərindən biri olan bu məğlubiyyət Avropada böyük əks-səda doğurdu və Stefana səlibçi aləmində ad qazandırdı. Padşah ertəsi il qisas üçün şəxsən yürüşə çıxacaqdı.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Akdərə (Valea Albă) qələbəsi — Boğdan yürüşü", "45a66791"], "d": ["Bir il əvvəlki Rakova məğlubiyyətinin qisasını almaq üçün şəxsən yürüşə çıxan Fatih Sultan Mehmed Osmanlı ordusu ilə Boğdan birliklərini Akdərə məvqeyində böyük hezimətə uğratdı və bəyliyin mərkəzi Suceavaya girdi. Lakin qalalar ələ keçirilə bilmədi; ərzaq çətinliyi, yeniçərilər arasında baş qaldıran taun və Macar hazırlıqları üzündən ordu geri çəkilməyə məcbur qaldı. Boğdanın qəti bağlılığı ancaq sonrakı illərdə və Kili ilə Akkermanın 1484-də alınması ilə təmin edilə bilərdi.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Akçahisarın (Kruja) fəthi və Albaniyanın tamamlanması", "559a79b4"], "d": ["İsgəndər bəyin ölümündən on il sonra, 1478-də Akçahisar, Drivasto, Ləş və Jabyakın ələ keçirilməsi ilə Albaniyanın fəthi böyük ölçüdə tamamlandı. İllərlə Osmanlı ordularına müqavimət göstərən və İsgəndər bəy müqavimətinin rəmzi olan Kruja qalasının süqutu bölgədəki Venesiya-Alban ittifaqının sonu mənasına gəlirdi. Geriyə qalan İşkodra isə ertəsi il imzalanacaq İstanbul Müqaviləsi ilə Osmanlıya buraxılacaqdı.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Taman yarımadasının qatılması", "4ef917b8"], "d": ["Kəfə və Kerçin 1475-də alınmasından sonra Fatih Sultan Mehmedin Qafqaz sahillərinə göndərdiyi donanma Anapa və Kopa ilə birlikdə Taman yarımadasındakı Cenova Matreqasını (Tamatarxan) zəbt etdi. Beləliklə boğazın iki yakası da nəzarət altına alındı və Azak dənizinə giriş tamamilə nəzarət edilə bilən hala gəldi. Taman Şimali Qafqaza açılan qapı olaraq Kəfə sancağına bağlandı.", "74a0de9f"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Rodos mühasirəsinin uğursuzluğu", "35a85c28"], "d": ["Fatih Sultan Mehmedin əmri ilə Məsih Paşanın komandanlığındakı 160 parçalıq donanma 885 (1480) baharında Rodosu mühasirəyə aldı və ada üç ay boyunca blokadada qaldı. Böyük ustad Pierre d'Aubussonun başçılıq etdiyi Sent-Jan cəngavərləri ağır itkilərə baxmayaraq şiddətlə müqavimət göstərdi; 20 Cəmadiyəlevvəl 885-də edilən son böyük hücumun da dəf edilməsi üzərinə donanma 3 Avqustda çəkildi. Bu uğursuzluqdan sonra şəhərin divarları baştan yenilənərək Avropanın ən güclü istehkamı halına gətirildi və ada ancaq 1522-də Qanuni tərəfindən alına bildi.", "23334bd0"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Yenişəhər döyüşü — Cem Sultanın məğlubiyyəti", "c35abee2"], "d": ["Fatihin ölümündən sonra taxt üçün hərəkətə keçən iki qardaş Yenişəhər düzündə qarşı-qarşıya gəldi və Cem Sultan qəti məğlubiyyətə uğradı. Bursada on səkkiz gün hökm sürüb adına xütbə oxudan şahzadə məğlubiyyətdən sonra əvvəl Konyaya, oradan Məmlük torpaqlarına sığınmağa məcbur qaldı. Yenişəhər Osmanlı tarixinin ən uzunmüddətli sülalə böhranını başlatdı: Cem məsələsi on dörd il boyunca Osmanlı xarici siyasətini Avropa qarşısında iflic edəcəkdi.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Herseqin ilhaqı", "bf247891"], "d": ["Bosniyanın 1463-də fəthindən sonra ayaqda qalan Herseq Hersoqluğunun torpaqları mərhələ-mərhələ Osmanlı idarəsinə keçdi: Trebinye və Mostar 1466-da alınmış, Herseq sancağı 1470-də təşkil edilmiş, hersoqluğun Adriatik sahilindəki son torpaqları da Herseqnovi (Herceg Novi) ilə birlikdə 1482-nin əvvəllərində fəth edilərək sancağa qatılmışdı. Beləliklə Adriatikin arxasındakı dağlıq bölgə bütövlükdə Osmanlının oldu və Bosniya ilə Herseq tək bir inzibati coğrafiya halına gəldi. Son hersoqun Osmanlı sarayına girən oğlu irəlidə sədrəzəmliyə qədər yüksələcək Herseqzadə Əhməd Paşadır.", "0522e47f"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Cem Sultanın Rodosa sığınması", "2228d6da"], "d": ["Konyanı mühasirəyə alma təşəbbüsü də nəticəsiz qalan Cem Sultan otuz qədər adamı ilə Anadoludan qaçaraq Rodosa çatdı və Sent-Jan cəngavərləri tərəfindən mərasimlə qarşılandı. Lakin qonaqlıq qısa müddətdə əsirliyə çevrildi; şahzadə əvvəl Fransaya, ardınca Papalığa verilərək Avropa siyasətinin əlində bir kartı halına gəldi. II Bəyazid qardaşının saxlanılması müqabilində illik ödəniş etməyə məcbur qaldı və Osmanlının Qərbə yönəlik hərbi addımları Cemin ölümünə qədər dayandırıldı.", "05ca0dd6"]}
});
